/* ÇEVİRİ bs · olay — arac/ceviri.py ile YAZILDI, elle düzenleme: py arac/ceviri.py uygula.
   Kayıt: id → [metin, kaynak_ozet] (olayda alan başına). Tasarım: denetim/CEVIRI-1103/TASARIM.md */
Ceviri.ekle("bs","olay",{
"OLAYLAR_EK5:1672-06-04:0":{"b": ["Počeo poljski pohod — Mehmed IV i Fazil Ahmed-paša na čelu vojske", "75e15a39"], "d": ["Kako su se nastavljali poljski napadi na ukrajinskog hetmana Petra Dorošenka, koji je stupio pod osmansko pokroviteljstvo, Istanbul je od poljskog kralja zatražio da od napada odustane; kad potvrdan odgovor nije stigao, odlučeno je o pohodu na Poljsku. Veliki vezir Fazil Ahmed-paša s vojskom u kojoj je bio i sultan krenuo je 4. juna 1672. na Poljsku. Pohod će se završiti osvajanjem Kamenice i Bučačkim mirom.", "7340721a"]},
"OLAYLAR_EK5:1672-08-27:0":{"b": ["Osvajanje Kamenice i osnivanje Podoljskog ejaleta", "c3f4f6d0"], "d": ["Nakon devetodnevne opsade zauzeta je Kamenica, smatrana najjačom poljskom tvrđavom na istoku; Mehmed IV 2. septembra klanjao je prvu džumu u džamiji pretvorenoj iz katedrale. Tvrđava je postala središte novoosnovanog Podoljskog ejaleta, a osmanska zastava dosegla je najsjeverniju tačku u današnjim ukrajinskim krajevima. Kamenica će do Karlovačkog mira 1699. ostati sjeverozapadni kraj carstva.", "d89c513a"]},
"OLAYLAR_EK5:1674-08-03:0":{"b": ["Kara Mustafa-paša preuzeo Uman od Poljske", "0d3543a0"], "d": ["Kara Mustafa-paša, poslan protiv Poljske, preuzeo je Uman, jednu od tvrđava u poljskim rukama; grad je do Karlovačkog mira ostao pod osmanskom upravom.", "bdb8e553"]},
"OLAYLAR_EK5:1678-08-21:0":{"b": ["Osvajanje tvrđave Čigirin", "a17cedd0"], "d": ["Nakon akcije Melek Ibrahim-paše prethodne godine koja nije donijela rezultat, veliki vezir Kara Mustafa-paša Merzifonlu lično je zapovijedao opsadom utvrđene tvrđave Čigirin (19/21. jula) i zauzeo je 21. augusta. Pad tvrđave, simbola osmansko-ruskog suparništva oko kozačkog hetmanata u Ukrajini, primorao je Rusiju na mir. Taj uspjeh bio je i jedan od izvora samopouzdanja Merzifonlua koje će ga okrenuti prema Beču.", "aee53ec4"]},
"OLAYLAR_EK5:1681-02-13:0":{"b": ["Bahčisarajski mir — prvi zvanični mir s Rusijom", "df82bc0b"], "d": ["Nakon pohoda na Čigirin, pregovorima vođenim uz posredovanje krimskog hana potpisan je dvadesetogodišnji mir između Osmanske države i Rusije, kojim je rijeka Dnjepar (Özü) prihvaćena kao granica. Kao prvi sveobuhvatni ugovor između dviju država, smatra se početnim dokumentom osmansko-ruskih odnosa. Zahvaljujući miru osiguran je istočni front, pa se vojska mogla usmjeriti prema Srednjoj Evropi.", "56f57388"]},
"OLAYLAR_EK5:1682-09-16:0":{"b": ["Dodjela berata o kraljevstvu Srednje Ugarske Imri Thökölyju", "3cd8d51d"], "d": ["Protestantski ugarski plemić Imre Thököly, koji se pobunio protiv habsburškog pritiska, od aprila 1682. smatran je 'izabranim kraljem Srednje Ugarske', a 16. septembra budimski beglerbeg Ibrahim-paša uručio mu je znamenja kneževskog dostojanstva. Tako je pod osmanskim pokroviteljstvom stvorena nova vazalna ugarska država. Ta intervencija učinila je rat s Austrijom neizbježnim i pokrenula lanac koji je doveo do Druge opsade Beča iduće godine.", "6f7f5236"]},
"OLAYLAR_EK5:1684-08-06:0":{"b": ["Gubitak Lefkade (Aja Mavra) u korist Venecije", "e6905fee"], "d": ["Flota Venecije, koja je pristupila Svetoj ligi, nakon što je grad izložila topovskoj vatri, zauzela je otok Lefkadu u Jonskom moru. Padom Preveze iste godine slomljen je osmanski nadzor na ulazu u Jadran. Ti gubici bili su početni koraci akcije kojom će Morosini za tri godine zauzeti cijelu Moreju.", "8fe34c55"]},
"OLAYLAR_EK5:1685-08-11:0":{"b": ["Gubitak Korona u korist Venecije", "2ed762bc"], "d": ["Venecijanske snage pod zapovjedništvom Morosinija zauzele su tvrđavu Koron na jugozapadnom kraju poluotoka Moreje; grad će od tada trideset godina ostati pod venecijanskom upravom. Pad Korona bio je prvi veliki uspjeh venecijanske akcije osvajanja Moreje. Tvrđavu je tek 1715. povratila osmanska vojska pod zapovjedništvom Silahdar Ali-paše.", "506cf83e"]},
"OLAYLAR_EK5:1688-04-08:0":{"b": ["Povratak Atine — povlačenje Venecije", "03393b46"], "d": ["Morosini, koji je u septembru 1687. bombardirao Akropolu i digao Partenon u zrak, nakon zimovanja u Atini shvatio je da se u gradu ne može održati. Zbog kuge, teškoća opskrbe i okupljanja osmanskih snaga venecijanska posada ispraznila je grad i povukla se u Moreju. Tako se Atina bez borbe vratila pod osmansku upravu, ali se razaranje koje je pretrpio Partenon nije moglo popraviti.", "79c8586a"]},
"OLAYLAR_EK5:1688-06-22:0":{"b": ["Lipova (Lippa) predala se Caraffi — prešla u austrijske ruke", "7f0a8d38"], "d": ["Nakon trodnevne opsade Antonija Caraffe Lipova se predala između 12. i 22. juna 1688. i prešla u austrijske ruke. Osmanlije su kasnije povratile grad, Austrija ga je 1691. ponovo zauzela; u pohodu 1695. Osmanlije su ponovo uspostavile kontrolu. Ostala naselja koja su istog datuma u atlasu prešla od Osmanlija Habsburgovcima: Arad i Világos (Şiria). Za Arad izvor daje samo godinu (MKL, Arad: u osmanskim rukama 1551–1688); dan je preuzet od Lipove, a Világos slijedi lanac Arada (deklarirana približnost). Tvrđave Lugoj (Lugos) i Caransebeş (Karánsebes) također su krajem juna prešle Austriji (Bánlaky 0016/1302 'Jenővel elveszett Lugos és Karánsebes'; 0017/1443 'június végén').", "2c8131d4"]},
"OLAYLAR_EK5:1688-10-20:0":{"b": ["Odbijanje venecijanske opsade Negroponta", "aae7e6a0"], "d": ["Nakon zauzimanja Moreje Morosini se okrenuo Egeju i opsadom dužom od tri mjeseca pokušao zauzeti Negropont; međutim, pred utvrđenjima ojačanim u zimu 1687–1688. i otporom posade morao se povući uz teške gubitke. Taj neuspjeh zaustavio je venecijansko napredovanje na Egeju i uzdrmao Morosinijev vojni ugled. Negropont će i u Karlovačkom miru ostati u osmanskim rukama.", "ea8430a3"]},
"OLAYLAR_EK5:1690-04-23:0":{"b": ["Gubitak tvrđave Kaniže u korist Austrije", "553b45f3"], "d": ["Kaniža, koju je od januara 1690. u strogoj blokadi držala habsburška vojska od 60.000 ljudi, mjesecima se opirala ne dobijajući pomoć, a zatim je izgubljena sporazumom o predaji koji je potpisao posljednji zapovjednik Mustafa-paša. Tako je završena devedesetogodišnja osmanska vlast u tvrđavi koja se pamti po legendarnoj odbrani Tirjaki Hasan-paše. Gubitak Kaniže bio je slom posljednjeg velikog osmanskog uporišta u zapadnoj Ugarskoj.", "dc630d57"]},
"OLAYLAR_EK5:1691-06-22:0":{"b": ["Smrt Sulejmana II", "d2478080"], "d": ["Sulejman II, doveden na prijestolje 1687. nakon gotovo četrdeset godina u kafezu, umro je bolestan, prateći pripreme vojske, u petak 22. juna 1691. oko podne u Edirnama; vladao je tri godine, osam mjeseci i dva dana. Veliki vezir unaprijed je dao potrebna uputstva da u slučaju sultanove smrti na prijestolje bude doveden njegov brat Ahmed. Dženaza je klanjana istog dana u Alaj-köšku; tijelo je preneseno u Istanbul i sahranjeno u turbetu sultana Sulejmana Zakonodavca, s njegove desne strane.", "3cf4fcb1"]},
"OLAYLAR_EK5:1691-06-23:0":{"b": ["Stupanje na prijestolje Ahmeda II", "52947b14"], "d": ["Nakon smrti Sulejmana II na prijestolje je u Edirnama stupio njegov četrdesetdevetogodišnji brat Ahmed II. Njegova vladavina pala je u najteže godine ratova sa Svetom ligom; dva mjeseca nakon stupanja na prijestolje, kod Slankamena je poginuo kao šehid veliki vezir Fazil Mustafa-paša. Nasuprot tome, sistem malikane, uveden u njegovo doba, postao je jedna od najvažnijih uredbi koja je dugoročno promijenila strukturu osmanskih finansija.", "d3441b14"]},
"OLAYLAR_EK5:1693-01-06:0":{"b": ["Smrt Mehmeda IV u Edirnama", "17388b7e"], "d": ["Mehmed Lovac (Avdži), svrgnut 1687, doveden je u Edirne za vrijeme ugarskog pohoda Sulejmana II 1689. i bio je svjedok i vladavine drugog brata Ahmeda II. Umro je u tom gradu koji je veoma volio. Tijelo mu je preneseno u Istanbul i sahranjeno u turbetu njegove majke Turhan-sultanije kraj Nove džamije.", "fd0f3d8c"]},
"OLAYLAR_EK5:1695-02-06:0":{"b": ["Smrt Ahmeda II u Edirnama", "c6306c08"], "d": ["Ahmed II, čija je četverogodišnja vladavina protekla u ratu, umro je u Edirnama u pedeset drugoj godini od istiske (edema). Tijelo mu je preneseno u Istanbul i sahranjeno u turbetu sultana Sulejmana Zakonodavca. Na njegovo mjesto došao je njegov bratić Mustafa II.", "a61e819c"]},
"OLAYLAR_EK5:1696-01-01:0":{"b": ["Iranci zauzimaju Basru", "a9cdf3a3"], "d": ["Dok se Osmanska država na zapadu bavila ratovima sa Svetom ligom, Basra je nakon kuge 1690. bila izložena pljački najprije šejha plemena Muntefik Mania, a zatim huvejzanskog kana Feredžulaha. Koristeći tu pometnju, Iranci su 1696. zauzeli grad i u Basri ostavili zapovjednika posade.", "2db76d27"]},
"OLAYLAR_EK5:1700-07-14:0":{"b": ["Istanbulski mir — prepuštanje Azova Rusiji", "79db4724"], "d": ["U Karlovcima je s Rusijom bilo moguće sklopiti samo dvogodišnje primirje; trajni mir potpisan je u Istanbulu nakon mukotrpnih pregovora od godinu i po. Osmanska država zvanično je Rusiji prepustila tvrđavu Azov, izgubljenu 1696, i okolne zemlje, a krimski han odrekao se godišnjeg danka koji je primao od Moskve. Zauzvrat je Rusija stekla pravo na stalnog poslanika u Istanbulu; time je rusko prisustvo na sjevernoj obali Crnog mora i pravno potvrđeno.", "a3a5a803"]},
"OLAYLAR_EK5:1701-01-01:0":{"b": ["Daltaban Mustafa-paša povratio Kurnu i Basru", "7adb777d"], "d": ["Daltaban Mustafa-paša, nakon Karlovačkog mira postavljen za bagdadskog valiju i basranskog seraskera, krenuo je na jug sa snagama iz Alepa, Rake, Sivasa i Karamana i s riječnom flotom koja je sišla iz Biredžika. Šejhovi okolnih plemena jedan po jedan iskazali su pokornost, iranski zapovjednik Basre Davud-kan napustio je grad, a Kurna i Basra ponovo su ušle pod osmansku upravu.", "60abbe06"]},
"OLAYLAR_EK5:1703-12-29:0":{"b": ["Smrt Mustafe II", "626c394d"], "d": ["Mustafa II, koji je nakon Edirnskog događaja prepustio prijestolje bratu Ahmedu III, umro je oko pet mjeseci nakon svrgavanja u Edirnama, koje je veoma volio. Bolesti se pridružila i tuga zbog posljednjih zbivanja. Neki zapadni izvori pišu da je u narodu bilo rašireno uvjerenje da je otrovan.", "8ce146e8"]},
"OLAYLAR_EK5:1704-01-01:0":{"b": ["Početak kolemenske (memlučke) uprave u Bagdadu", "abe52618"], "d": ["Postavljanjem Hasan-paše, gruzijskog porijekla, za bagdadskog valiju počelo je u Iraku razdoblje u kojem je umjesto valija imenovanih iz centra vladao sloj upravljača odgojenih iz vlastitih robova. Sistem se potpuno ukorijenio s valijstvom Sulejman-paše 1749, pa Visoka porta više nije mogla imenovati koga želi, nego je morala imenovati jednog od kolemena koji je preuzeo uticaj. Ta poluautonomna struktura, iako je bila korisna u odbrani iranske granice, vijek i po slabila je nadzor središnje vlasti nad Irakom.", "7cf655d4"]},
"OLAYLAR_EK5:1705-07-12:0":{"b": ["Uspostava dinastije Huseinida u Tunisu", "cb1a98f9"], "d": ["U praznini vlasti nastaloj nakon što su alžirske snage upale u Tunis, spahijski aga turskog porijekla Husein b. Ali preuzeo je vlast nad bejlukom i stekao legitimitet iskazavši odanost osmanskom sultanu. Dinastija koju je osnovao vladala je Tunisom 1705–1735. i 1756–1957; upravu odžaka zamijenio je bejlučki poredak nasljedan s oca na sina. Tako je nastao prvi primjer dinastijskih struktura u sjevernoafričkim odžacima, vezanih za centar, ali faktički autonomnih.", "941c7858"]},
"OLAYLAR_EK5:1708-04-04:0":{"b": ["Oduzimanje Orana i Mers el-Kebira od Španaca", "b67ce06a"], "d": ["Snage beglerbega alžirskog odžaka nakon duge opsade zauzele su Oran i njegovu luku Mers el-Kebir, koji su dva stoljeća bili u rukama španskog garnizona. Bio je to najveći uspjeh koji su sjevernoafrički odžaci pod osmanskim pokroviteljstvom ostvarili protiv Španije u zapadnom Sredozemlju, a njime je osigurano zapadno krilo Alžira. Grad će 1732. ponovo pasti pod špansku okupaciju, ali će 1792. biti konačno vraćen.", "33d9da74"]},
"OLAYLAR_EK5:1711-07-21:0":{"b": ["Prutski mir — povratak Azova i Taganroga", "bac5d2a1"], "d": ["Ugovor od sedam tačaka, potpisan predajom ruske vojske opkoljene na Prutu, predvidio je povratak tvrđave Azov s njenim zemljištem i municijom Osmanlijama. Utvrđenja Taganrog, Kamenka i Jenikale trebala su biti srušena, a strane u toj oblasti neće graditi nove tvrđave. Urušio se sistem flote i baza koji je Petar I šesnaest godina gradio u Voronježu i Azovu; ruski izlazak na Crno more odgođen je za otprilike pedeset godina.", "657d45ff"]},
"OLAYLAR_EK5:1711-07-29:0":{"b": ["Uspostava dinastije Karamanli u Tripoliju", "e1105d4a"], "d": ["U Tripoliju, iscrpljenom sukobima aga odžaka, konjički oficir Ahmed Karamanli preuzeo je vlast i svoj položaj ozvaničio beratom o beglerbeglučkom zvanju dobijenim iz Istanbula. Preko Ahmed-paše, njegovog sina Mehmed-paše i unuka Jusuf-paše nastala je dinastija koja je trajala od 1711. do 1835; pojavila se poluneovisna struktura koja je stvorila vlastitu flotu i neposredno potpisivala ugovore s evropskim državama. To razdoblje završilo se tek 1835, kad je ejalet neposredno vezan za centar.", "b1c3dd0a"]},
"OLAYLAR_EK5:1713-06-24:0":{"b": ["Edirnski mir s Rusijom", "14901a70"], "d": ["Kako obećanja data na Prutu nisu ispunjena, rat je još dva puta objavljivan, a napokon, kad su Rusi prihvatili obaveze, u Edirnama je potpisan trajni mir. Ugovor je potvrdio prutske uslove; Rusija se neće miješati u poljske poslove, povući će se s kozačkih zemalja i neće sprečavati švedskog kralja Karla XII (Demirbaš Šarla) da se vrati u svoju zemlju. Tako zatvaranje sjevernog fronta omogućilo je Osmanskoj državi da se okrene prema Moreji i venecijanskom frontu. Ostala mjesta pripojena istog datuma: Hotin.", "34010e06"]},
"OLAYLAR_EK5:1714-12-08:0":{"b": ["Objava rata Veneciji — priprema pohoda na Moreju", "d970b122"], "d": ["Uz obrazloženje da Venecija pomaže crnogorske pobunjenike, da otima osmanske trgovačke brodove i da teškim porezima ugnjetava Moreju koju je stekla Karlovačkim mirom, u divanu je donesena odluka o ratu. Pohod koji je pripremio veliki vezir Silahdar damat Ali-paša iduće godine će se, za manje od sto dana, završiti povratkom cijelog poluotoka Moreje. Međutim, taj uspjeh pokrenut će Austriju i 1716. otvoriti vrata znatno težeg rata.", "ef2edb5f"]},
"OLAYLAR_EK5:1715-06-05:0":{"b": ["Tinos (Istendil): predaja posljednjeg venecijanskog otoka u Egeju", "4abec891"], "d": ["Flota koja je krenula na morejski pohod usput se usidrila pred Tinosom, jedinim otokom koji je Veneciji ostao u Egeju. Otok, koji je zahvaljujući latinskom stanovništvu nosio venecijansku zastavu još stotinu pedeset godina iako je Naksoski dukat pao 1566, predao se bez krvi nakon kratke opsade. Tako je izbrisan posljednji venecijanski trag u Egejskom moru i more je u cijelosti postalo osmansko unutrašnje more.", "7b191aca"]},
"OLAYLAR_EK5:1715-07-20:0":{"b": ["Osvajanje Nauplije (Anabolu) — ključna tvrđava Moreje", "62a5808a"], "d": ["Anabolu, venecijanska prijestolnica u Moreji i najjače utvrđenje, pala je zauzimanjem tabije Palamidi nakon devetodnevnog bombardovanja. Tako brzo zauzimanje tvrđave slomilo je otpor na ostatku poluotoka. Povratak Moreje, izgubljene u Karlovcima, faktički je ovdje dovršen. Ostalo naselje koje je istog datuma u atlasu prešlo od Venecije Osmanlijama: Argos — slijedi lanac matičnog središta Nauplije (TDV anabolu; deklarirana približnost).", "8467e05c"]},
"OLAYLAR_EK5:1715-08-01:0":{"b": ["Predaja Modona", "43faa909"], "d": ["Nakon pada Nauplije tvrđava Modon na jugozapadnom kraju Moreje opsjednuta je s kopna vojskom, a s mora flotom i ubrzo se predala. Ta luka, koju je Venecija dvjesto godina koristila na svojim pohodima po istočnom Sredozemlju, bila je obavezna usputna tačka gdje su brodovi uzimali vodu i namirnice. Njen gubitak okončao je manevarsku sposobnost venecijanske flote u Egeju.", "0d2c6d1a"]},
"OLAYLAR_EK5:1715-08-16:0":{"b": ["Predaja Korona — dovršetak morejskog pohoda", "e4b9c8a4"], "d": ["Predajom tvrđave Koron, koja drži ulaz u Mesenijski zaljev, venecijanska uprava na poluotoku Moreja potpuno je okončana. Poluotok izgubljen u Karlovcima u cijelosti je vraćen samo tri mjeseca nakon početka pohoda. U nastavku istog pohoda, u septembru 1715, od Venecije je oduzet i otok Lefkada (Aja Mavra) u Jonskom moru. Ta brzina primorala je Veneciju da uvuče Austriju u rat i tri godine kasnije otvorila put koji je vodio u Požarevac.", "d3173b05"]},
"OLAYLAR_EK5:1715-09-07:0":{"b": ["Zauzimanje otoka Kitere (Čuha)", "494de6c6"], "d": ["Otok Kiteru na južnom kraju Moreje flota je preuzela nakon dovršetka osvajanja poluotoka. Otok koji nadzire prolaz između Jonskog i Egejskog mora bio je isturena stražarnica kojom je Venecija nadzirala te vode. Ali nije ostao jedini zadržani osmanski otok: tri godine kasnije Požarevačkim mirom vraćen je Veneciji.", "42162c0d"]},
"OLAYLAR_EK5:1716-04-13:0":{"b": ["Austrija i Venecija sklopile savez — vrata osmansko-austrijskog rata 1716–1718.", "99511ca2"], "d": ["Nakon što su Osmanlije povratile Moreju od Venecije, Austrija je, tvrdeći da je prekršen Karlovački mir, potpisala savez s Venecijom; princ Eugen u pismu velikom veziru zatražio je povrat mjesta oduzetih Veneciji. Na vijećanju u logoru Davutpaša, pod pritiskom velikog vezira Ali-paše, objavljen je rat Austriji, a za to je od šejhul-islama uzeta fetva.", "4a2089d7"]},
"OLAYLAR_EK5:1716-04-24:0":{"b": ["Veliki vezir Ali-paša krenuo u pohod na Austriju", "2fbdce42"], "d": ["Nakon objave rata Austriji serdar-ekrem Ali-paša krenuo je s vojskom većom od 100.000 ljudi u pohod na Austriju; flota se istog ljeta usmjerila prema Krfu. Vojska će iz Beograda krenuti na Petrovaradin, a u porazu početkom augusta veliki vezir poginut će kao šehid.", "02a5590b"]},
"OLAYLAR_EK5:1716-08-05:0":{"b": ["Poraz kod Petrovaradina — pogibija damat Ali-paše", "265c1d81"], "d": ["Osmanska vojska, koja je preko Beograda prešla Dunav, sukobila se pred Petrovaradinom s austrijskim snagama pod zapovjedništvom princa Eugena; iako je u prvom naletu janjičarski juriš ugrozio neprijateljske rovove, slomom konjičkog krila redovi su se raspali. Veliki vezir Silahdar damat Ali-paša pogođen je u čelo i poginuo kao šehid, a logor i artiljerija potpuno su pali u neprijateljske ruke. Ovaj poraz, koji osmanske kronike nazivaju 'godinom Petrovaradina', bio je prva karika lanca koji je vodio do gubitka Temišvara i, iduće godine, Beograda.", "ad21a2c3"]},
"OLAYLAR_EK5:1716-08-20:0":{"b": ["Neuspjeh opsade Krfa", "b2aa7011"], "d": ["Morejski serasker Kara Mustafa-paša napadao je Krf s kopna, a kapudan-paša Džanim Hodža Mehmed-paša flotom s mora; otok je bio ključna venecijanska baza na Jadranu. Međutim, izuzetno snažna utvrđenja tvrđave, pojačanja koja je dovela venecijanska flota i vijesti o porazu s dunavskog fronta doveli su do dizanja opsade. Neuspjeh u zauzimanju Krfa ugasio je polet stvoren ponovnim osvajanjem Moreje i težište rata pomjerio u Ugarsku.", "4589579c"]},
"OLAYLAR_EK5:1716-10-13:0":{"b": ["Gubitak Temišvara u korist Austrije", "27fe1365"], "d": ["Nakon poraza kod Petrovaradina princ Eugen krenuo je izravno na Temišvar, a tvrđava je nakon opsade duže od četrdeset dana predana uz pogodbu. Grad osvojen 1552. u doba Sulejmana Zakonodavca, koji se 164 godine kao sjedište beglerbegluka smatrao istočnim stubom odbrane Ugarske, tako je izgubljen. Padom Temišvara cijeli Banat prešao je Austriji, a osmanska granica potisnuta je južno od Dunava. Ostala naselja koja su istog datuma u atlasu prešla od Osmanlija Habsburgovcima: Csákóvár, Facset i Karánsebes (Caransebeş) — uz predaju Temišvarskog ejaleta (TDV timisvar; dan na nivou mjesta nije naveden u izvoru, lanac matičnog središta, deklarirana približnost).", "a1408ad1"]},
"OLAYLAR_EK5:1716-11-16:0":{"b": ["Predaja tvrđave Haram (Nova Palanka) Austriji — izgubljena dunavska obala Banata", "38ee4c6d"], "d": ["Austrijski konjički general Mercy, zadužen da nakon pada Temišvara zauzme preostali Banat, krenuo je 14. novembra na Haram (Nova Palanka) na obali Dunava; kad je 16. novembra stigao do tvrđave, osmanska posada od 200 ljudi istakla je bijelu zastavu i predala se uz uslov slobodnog povlačenja. Tako je i dunavska linija Južnog Banata, u osmanskim rukama od 1552, prešla Austriji. Ostalo naselje koje je istog datuma u atlasu prešlo od Osmanlija Habsburgovcima: Vršac — slijedi lanac matičnog središta Harama (Bánlaky 0019/1703; deklarirana približnost).", "5b54ecb0"]},
"OLAYLAR_EK5:1718-07-21:0":{"b": ["Požarevački mir — Moreja dobivena, Beograd i Banat izgubljeni", "d46aa216"], "d": ["Moreja je vraćena od Venecije, ali je Austrija, koja je stupila u rat, pobjedama kod Petrovaradina i Beograda sjela za pregovarački sto u nadmoćnom položaju. Ugovor potpisan uz posredovanje Engleske i Holandije ostavio je Moreju Osmanlijama, a zauzvrat je Austriji prepušten Beograd zajedno sa Sjevernom Srbijom, Banatom i Malom Vlaškom; po riječima TDV-a 'Sjeverna Bosna potpuno je prepuštena Austriji' — tvrđave uz Savu, kao što su Bosanska Dubica i Bosanski Brod, od tog dana na karti prelaze Austriji (tačnu granicu komesari su povlačili jednu po jednu, TDV te tvrđave ne navodi po imenu); Venecija je, pak, zadržala položaje na jonskoj obali kao što su Preveza i Kitera. Trgovačkom ahdnamom potpisanom istog dana carina na austrijsku robu smanjena je s pet na tri posto. Ugovor je, potvrđujući povlačenje Osmanske države iz Srednje Evrope, otvorio dvadesetsedmogodišnji mir, koji je postavio temelje Doba tulipana (1718–1730): pod upravom damat Ibrahim-paše Nevšehirlija prva osmanska štamparija (1727, Ibrahim Muteferrika), prevodilački odbori, zapažanja o vakcini protiv boginja i novi dvorsko-kulturni život plod su tih mirnih godina. Ostala naselja koja su istog dana u atlasu promijenila gospodara: Krajova (Craiova), Rimnik (Râmnicu Vâlcea) i Turnu Severin (Mala Vlaška/Oltenija, od Osmanlija Austriji) te Lefkada (Aja Mavra) (od Osmanlija Veneciji; TDV ayamavra: 1718. Požarevačkim mirom otok je prepušten Veneciji). U Maloj Vlaškoj Austriji prelazi i Târgu Jiu; Veneciji prelaze Vonitsa (Voniče, TDV pasarofca-antlasmasi) i otok Kitera (TDV cuka-adasi: 3. član požarevačkog ugovora).", "ec4430bf"]},
"OLAYLAR_EK5:1723-06-15:0":{"b": ["Istočni pohod: zauzimanje Tbilisija i početak rata s Iranom", "78343dc2"], "d": ["Kako se safavidska država raspadala pod afganistanskom invazijom, a Rusija silazila na obale Kaspijskog jezera, Osmanska država poslala je vojsku na istok da praznina ne bi u potpunosti ostala pod ruskim uticajem. Zauzimanjem Tbilisija Gruzija je pripojena osmanskoj upravi; zatim je nastavljeno napredovanje prema Gandži, Erivanu i Nahičevanu. Taj pohod, vođen iza miroljubivog lica Doba tulipana, bio je početak duge istočne pustolovine koja će trajati trinaest godina i završiti vraćanjem svih osvojenih mjesta.", "5c412d91"]},
"OLAYLAR_EK5:1723-08-01:0":{"b": ["Iranski pohod 1723: ulazak u Širvan i Gruziju", "c81189fc"], "d": ["Kad se safavidska država urušila pod afganistanskom invazijom, pod obrazloženjem da treba spriječiti silazak Rusije na obale Kaspijskog jezera pokrenut je pohod na istok. Erzurumska vojska preko Gruzije ušla je u Tbilisi, a širvanska kolona u Šamahi, te su vraćene zemlje izgubljene sto trideset godina ranije. Taj pohod bio je posljednje veliko osmansko napredovanje na Kavkazu.", "9f84acd9"]},
"OLAYLAR_EK5:1723-10-01:0":{"b": ["Zauzimanje Kermanšaha — vrata Zagrosa", "ad14799f"], "d": ["Bagdadska vojska, prešavši zagroske prolaze, zauzela je Kermanšah, smatran zapadnim vratima Irana. Grad je ležao na karavanskom i vojnom putu od Bagdada do Isfahana, a njegovo zauzimanje osiguravalo je istočnu sigurnost iračkog ejaleta. To napredovanje pokrenulo je utrku Osmanlija i Rusije za podjelu raspadajuće safavidske zemlje.", "65dba49c"]},
"OLAYLAR_EK5:1724-06-24:0":{"b": ["Istanbulska mukasemenama — podjela Irana s Rusijom", "fce8eec2"], "d": ["Da bi se spriječio sukob Osmanlija i Rusije oko raspadajuće safavidske zemlje, uz posredovanje francuskog poslanika potpisan je ugovor o podjeli. Zapadne i južne obale Kaspijskog jezera pripale su Rusiji, a Gruzija, Širvan, Azerbejdžan i gradovi zapadnog Irana Osmanskoj državi. Ta podjela, koja je na papiru izgledala kao veliki dobitak, ubrzo će usponom Nadir-šaha faktički postati ništavna. Prema ugovoru, plodne zemlje Širvana, kao što su Šabran i Muškur, ostale su na ruskoj strani (Çaycıoğlu, DergiPark).", "7b0b411b"]},
"OLAYLAR_EK5:1724-08-11:0":{"b": ["Zauzimanje Nahičevana", "bdf14d0a"], "d": ["Osmanske snage koje su napredovale duž Araksa zauzele su Nahičevan i Ordubad; i Džulfa je pripojena Nahičevanskom sandžaku. Grad je, kao sjeverozapadna vrata Irana, pripojen novoosnovanom Erivanskom ejaletu. Tako je osmanska granica ponovo dosegla najistočniju liniju iz doba Sulejmana Zakonodavca.", "9e602879"]},
"OLAYLAR_EK5:1724-08-31:0":{"b": ["Osvajanje Hamadana", "e1339a97"], "d": ["Vojska koja je od Kermanšaha krenula na istok nakon duge opsade zauzela je Hamadan, na zapadnom pragu iranske visoravni. Grad je bio posljednja velika stanica na putu prema Isfahanu, najistočnijoj tački koju su osmanske vojske mogle dosegnuti od pohoda na dva Iraka. Iste godine s Rusijom potpisana Istanbulska mukavelenama stavila je na papir podjelu raspadajućeg Irana između Osmanlija i Rusije.", "81552031"]},
"OLAYLAR_EK5:1724-10-03:0":{"b": ["Ponovno osvajanje Erivana", "88acabef"], "d": ["Nakon teške opsade od devedeset dana Erivan, ključna tvrđava doline Araksa, ponovo je ušao pod osmansku upravu. Tvrđava sagrađena 1583. i izgubljena 1604. ovaj put je utvrđena jačom posadom. Dužina opsade pokazivala je da osmanska vojska više ne napreduje lako. Nahije Karpi (Üçkilise, tj. Ečmijadzin), Šerur, Maku i Šuregel također su pripojene Erivanskom ejaletu.", "a989b1eb"]},
"OLAYLAR_EK5:1725-07-28:0":{"b": ["Zauzimanje Tabriza — osvajanje Azerbejdžana", "e502a4f7"], "d": ["Tabriz, ponovo opsjednut nakon neuspjelog pokušaja prethodne godine, predao se osmanskoj vojsci nakon žestokih borbi od ulice do ulice. Pod osmansku upravu ušli su i Marand, Maraga i Sovukbulak (Mahabad), pripadajući Tabriskom ejaletu. Iste godine zauzeti su i Lori, Gandža, Ardabil i Horamabad, čime su faktički zaposjednuta područja koja su po Istanbulskoj mukasemenami pripala Osmanlijama. Taj obim dostignut na istoku bio je najdalja granica od doba Ferhad-pašinog mira; ali njeno zadržavanje teško je opteretilo vojsku i riznicu.", "e0953563"]},
"OLAYLAR_EK5:1725-09-04:0":{"b": ["Osvajanje Gandže — kraj kavkaskog pohoda", "875bca7a"], "d": ["Gandža, posljednji cilj kavkaske akcije, preuzeta je kao središte Karabaha između Kure i Araksa. Dovršetkom linije Širvan–Erivan–Nahičevan–Gandža Osmanska država na Kavkazu je dosegla obim iz 1590. Ali taj dobitak bio je kratkog vijeka: usponom Nadir-šaha cijela oblast bit će za deset godina vraćena.", "265db7e0"]},
"OLAYLAR_EK5:1727-10-04:0":{"b": ["Hamadanski mir — pripajanje zapadnog Irana Osmanlijama", "94a29dc3"], "d": ["Ugovorom potpisanim s afganistanskim vladarom Ešref-šahom završen je četverogodišnji rat i pravno priznate zapadnoiranske zemlje koje je zaposjela Osmanska država. Ešref-šah je zauzvrat priznao hilafet osmanskog sultana i obavezao se da se hutba u Iranu uči u sultanovo ime. Ta diplomatska pobjeda bila je kratkog vijeka; protunapad koji je Nadir-šah pokrenuo 1730. u nekoliko godina izbrisat će dobitke ugovora.", "fd0174b9"]},
"OLAYLAR_EK5:1731-01-01:0":{"b": ["Hećimoglu Ali-paša zauzeo Urmiju", "eac7f64d"], "d": ["U iranskom pohodu Hećimoglu Ali-paša najprije je zauzeo Urmiju (Rumiju), a zatim 15. novembra 1731. Tabriz, ispražnjen za Osmanlije. TDV ne navodi dan zauzimanja Urmije; poznata je samo godina i to da je zauzeta prije Tabriza.", "f99d74f9"]},
"OLAYLAR_EK5:1732-01-08:0":{"b": ["Ahmed-pašin mir — povrat većeg dijela zapadnog Irana", "590d839f"], "d": ["Nakon pobjede Nadir-šaha kod Malajera i uzastopnih iranskih napada, bagdadski valija Ahmed-paša potpisao je tekst o miru ne savjetujući se s centrom. Prema ugovoru rijeka Araks prihvaćena je kao granica; zapadnoiranski gradovi kao što su Hamadan, Kermanšah, Ardalan, Ardabil i Tabriz vraćeni su Iranu, a Gandža i Tbilisi ostali su Osmanlijama. Taj tekst, dočekan s negodovanjem u Istanbulu, ni Nadir-šah nije smatrao dovoljnim, pa se rat ponovo rasplamsao još prije isteka 1732. Atlas i Kotur, koji slijedi lanac Hoja, smatra da je tog dana prešao od Osmanlija Safavidima (TDV hoy; dan specifičan za Kotur nije naveden u izvoru — deklarirana približnost).", "fdaa1e6f"]},
"OLAYLAR_EK5:1732-07-01:0":{"b": ["Ponovni gubitak Orana u korist Španije", "20485027"], "d": ["Velika desantna flota koju je poslao španski kralj Filip V stigla je pod zapovjedništvom grofa Montemara pred Oran, porazila snage alžirskog odžaka i povratila grad. Luka osvojena dvadeset četiri godine ranije ostat će šezdeset godina ponovo u rukama španskog garnizona. Ovaj gubitak, koji je pokazao granice snage sjevernoafričkih odžaka u zapadnom Sredozemlju, mogao se nadoknaditi tek konačnim osvajanjem Orana 1792.", "b255a8da"]},
"OLAYLAR_EK5:1733-05-01:0":{"b": ["Reforma humbaradžijskog odžaka po evropskom uzoru i osnivanje Humbarahane", "d980cf2a"], "d": ["Humbaradži Ahmed-paša, Francuz porijeklom koji je stupio u osmansku službu, uz podršku velikog vezira Hećimoglu Ali-paše pretvorio je humbaradžijski odžak u plaćenu jedinicu uređenu po evropskom uzoru. Tri stotine vojnika regrutiranih iz Bosne dobilo je redovnu obuku zasnovanu na računu i geometriji; pripremljeni su novi propisi za ustrojstvo, opremu i penzionisanje, a savremenom tehnikom proizvedeno je sto merzera i pedeset hiljada bombi. Humbarahana, u kojoj se predavala geometrija, smatra se prvom klicom modernog vojnoinženjerskog obrazovanja kod Osmanlija.", "181b7161"]},
"OLAYLAR_EK5:1736-06-24:0":{"b": ["Smrt Ahmeda III", "455f7fba"], "d": ["Ahmed III, svrgnut ustankom Patrone Halila 1730, posljednjih šest godina života proveo je u odajama Topkapi saraja namijenjenim svrgnutim sultanima i umro u šezdeset trećoj godini. Sahranjen je u Bahčekapiju, u turbetu svoje bake Turhan-sultanije kraj Nove džamije.", "00cc8767"]},
"OLAYLAR_EK5:1736-09-01:0":{"b": ["Istanbulski mir — prepuštanje Južnog Kavkaza Iranu", "8c205aab"], "d": ["Drugi iranski rat, koji je trajao četiri godine, nakon poraza na Arpačaju i gubitka Gandže i Tbilisija završen je ugovorom. Osmanska država povukla se sa svih zemalja Južnog Kavkaza i zapadnog Irana koje je zauzela od 1723, a granica se vratila na liniju Kasr-i Širina iz 1639. Od trinaestogodišnjih istočnih pohoda ostali su teško finansijsko breme i ispražnjena riznica; s druge strane, zatvaranje istočnog fronta zbog novog rata s Rusijom bio je životni dobitak.", "bcb0cbe8"]},
"OLAYLAR_EK5:1737-07-11:0":{"b": ["Pad tvrđave Očakov (Özi) u ruske ruke", "f93e61f3"], "d": ["Ruska vojska pod zapovjedništvom maršala Münnicha opsjela je tvrđavu Očakov na ušću Dnjepra; eksplozijom barutane odbrana se urušila, a tvrđava je pala uz velike ljudske gubitke. Gubitak Očakova, smatranog ključem sjeverozapadne obale Crnog mora, otvorio je Rusima put na Krim i izazvao veliku paniku u Istanbulu. Tvrđavu će iduće godine Rusi isprazniti zbog epidemije i teškoća opskrbe, pa će se vratiti Osmanlijama.", "479e0090"]},
"OLAYLAR_EK5:1737-08-04:0":{"b": ["Pobjeda kod Banje Luke — spas Bosne", "f603865a"], "d": ["Kad su austrijske snage ušle u Bosnu i opsjele Banju Luku, bosanski valija Hećimoglu Ali-paša pritekao je u pomoć snagama okupljenim od domaćeg stanovništva i teško porazio brojčano nadmoćnog neprijatelja. Ta pobjeda srušila je austrijski plan zauzimanja Bosne već na prvom koraku, a sjever ejaleta potpuno je povraćen. Banja Luka postala je jedna od prekretnica koje su popravile moral osmanske vojske, koja se poslije 1683. stalno povlačila pred Austrijom.", "81c1850e"]},
"OLAYLAR_EK5:1739-07-22:0":{"b": ["Pobjeda kod Grocke (Hisardžik) — otvaranje puta prema Beogradu", "2101cdff"], "d": ["Austrijska vojska, koja je napredovala da zaštiti Beograd, upala je u zasjedu u tjesnacu na obali Dunava i u bitki koja je trajala cijeli dan pretrpjela teške gubitke. Dok su se snage maršala Wallisa neuredno povlačile prema Beogradu, osmanska vojska stigla je pred tvrđavu i započela opsadu. Grocka je bila najodlučnija pobjeda na otvorenom polju nad Austrijom od Karlovaca i neposredno je omogućila povratak Beograda.", "5811893a"]},
"OLAYLAR_EK5:1739-10-03:0":{"b": ["Niški mir — mir s Rusijom, neutralizacija Azova i zaustavljanje krimskih prepada", "674f974e"], "d": ["Rusija, ostavši sama kad je Austrija u Beogradu pristala na mir, morala je uz posredovanje francuskog poslanika Villeneuvea okončati rat. Utvrđenja tvrđave Azov srušena su, a područje je proglašeno neutralnom zemljom između dviju država; Rusija je prihvatila uslov da ne drži ratne ni trgovačke brodove na Crnom moru. Tako je ruski cilj izlaska na more odgođen za još jednu generaciju, a Osmanska država posljednji put u XVIII stoljeću ustala je od stola s dobitkom.", "7ca0d614"]},
"OLAYLAR_EK5:1739-12-12:0":{"b": ["Očakov se vratio nakon ruske okupacije: po miru 1739. tvrđava predata nakon rušenja", "7ecc2bef"], "d": ["Rusi su Očakov zauzeli 11. jula 1737. Prema miru sklopljenom s Rusijom 1739, utvrđenja tvrđave srušena su, a zatim je ponovo predata Osmanlijama; Osmanlije su Očakov držale do 1788, prije Jaškog mira.", "39ee6708"]},
"OLAYLAR_EK5:1743-10-23:0":{"b": ["Odbrana Mosula — odbijanje Nadir-šaha", "c03ffbc1"], "d": ["Nadir-šah, koji je zauzeo Kirkuk i Erbil i stigao pred Mosul, četrdeset dana tukao je grad topovima i uzastopno izvodio opće juriše. Odbrana koju je valija Husein-paša el-Dželili vodio naoružavši i gradsko stanovništvo primorala je iransku vojsku da uz teške gubitke digne opsadu. Opstanak Mosula spriječio je gubitak cijelog Iraka i za stoljeće učvrstio uticaj porodice Dželili u gradu.", "b9f67e29"]},
"OLAYLAR_EK5:1744-01-01:0":{"b": ["Dirijski savez — uspostava prvog Saudijskog emirata u Nedždu", "188751bf"], "d": ["Emir Muhammed b. Saud, primivši pod zaštitu u Diriji učenjaka Muhammeda b. Abdulvehhaba, protjeranog iz Ujejne, s njim je sklopio savez kojim je politički autoritet stavio u službu vjerskog poziva. Taj sporazum otvorio je novu historiju porodice Saud i ujedinio raštrkane oazne emirate Nedžda oko jednog pokreta. Ta snaga, koja će se za pola stoljeća protegnuti do Kerbele, Meke i Medine, primorat će Osmansku državu da brani svoju vlast u Hidžazu.", "6843c874"]},
"OLAYLAR_EK5:1746-09-04:0":{"b": ["Kerdenski mir — kraj osmansko-iranskih ratova", "1d3a919e"], "d": ["Ugovorom potpisanim nakon posljednjeg četverogodišnjeg rata u cijelosti je obnovljena granica Kasr-i Širina iz 1639; nijedna strana nije stekla teritorij. Uporni zahtjev Nadir-šaha da se džaferijski pravac prizna kao peti mezheb ostao je bez odgovora, a zauzvrat je dogovoreno da iranski hadžije slobodno obavljaju hadž i da se razmjenjuju poslanici. Tako su faktički završeni osmansko-iranski ratovi, duži od dva stoljeća; ta granica uglavnom se održala do danas.", "2a089331"]},
"OLAYLAR_EK5:1754-12-13:0":{"b": ["Smrt Mahmuda I i stupanje na prijestolje Osmana III", "30203700"], "d": ["Mahmud I, koji je tokom dvadeset četiri godine vladavine Beogradskim mirom povratio izgubljene zemlje i podržavao reformu humbaradžijskog odžaka, umro je na povratku sa svečanog odlaska na džumu. Na njegovo mjesto došao je brat Osman III, koji je do pedeset osme godine živio u kafezu. Počela je kratka i nemirna vladavina; u doba Osmana III, koji je za tri godine promijenio šest velikih vezira, u državnim poslovima vladao je izražen zastoj.", "8bdf7c4e"]},
"OLAYLAR_EK5:1757-10-30:0":{"b": ["Smrt Osmana III i stupanje na prijestolje Mustafe III", "3ac10f85"], "d": ["Smrću Osmana III nakon trogodišnje vladavine na prijestolje je stupio Mustafa III, otvoren za reformske ideje i veoma zainteresiran za državne poslove. Novi sultan, oslanjajući se na iskustvo velikog vezira Kodža Ragib-paše, nastojao je srediti finansije i obnoviti vojsku; u to doba osnovani su brzometni topnici barona de Totta. Međutim, rat s Rusijom u koji se ušlo 1768. bacit će sjenu na sve dobitke sedamnaestogodišnje vladavine.", "2d13aff2"]},
"OLAYLAR_EK5:1768-10-08:0":{"b": ["Objava rata Rusiji — incident u Balti i početak rata 1768–1774.", "9c6aabe0"], "d": ["Kad su ruske i kozačke jedinice, progoneći Barsku konfederaciju u Poljskoj, napale i spalile gradić Baltu na osmanskoj granici, divan je donio odluku o ratu, a ruski poslanik zatvoren je u Jedikulu. Rat u koji se ušlo bez ozbiljnih vojnih priprema i s objavom šest mjeseci unaprijed od početka je išao loše. Ta borba, koja će trajati šest godina, pretvorit će se u jedan od najtežih nizova poraza u osmanskoj historiji: napad kod Češme, poraz na Kagulu i okupacija Krima.", "18bfa4d5"]},
"OLAYLAR_EK5:1769-09-20:0":{"b": ["Gubitak tvrđave Hotin u korist Rusa", "66d43ea4"], "d": ["Iako su dva pokušaja ruske vojske pod zapovjedništvom kneza Golicina bila odbijena, nakon poraza velikog vezira između Kamenice i Hotina vojska se povukla, a branioci su ispraznili tvrđavu. Gubitak najjačeg osmanskog utvrđenja sjeverno od Dunava bez otpora otvorio je Rusima vrata Vlaške i Moldavije. Obje kneževine okupirane su iste godine; Hotin se mogao vratiti tek 1774. mirom u Küčük Kajnardži.", "1d0b219f"]},
"OLAYLAR_EK5:1770-08-01:0":{"b": ["Poraz na Kagulskom polju", "6f408eaf"], "d": ["Tri sedmice nakon spaljivanja flote kod Češme, glavna osmanska vojska na Dunavu raspala se na Kagulskom polju pred brojčano znatno manjim, ali disciplinovanim jedinicama maršala Rumjanceva. Logor, komora i stotine topova pali su u neprijateljske ruke; jedinice u bijegu pretrpjele su velike gubitke prelazeći Dunav. Uništenje i flote i kopnene vojske istog ljeta dovelo je do uzastopnog pada Kilije, Akermana, Izmaila i Bendera te do okupacije Krima.", "0fd97052"]},
"OLAYLAR_EK5:1771-07-01:0":{"b": ["Ruska okupacija poluotoka Krima", "217837b0"], "d": ["Ruske vojske, koje su godinu ranije zauzele Budžak, pod zapovjedništvom kneza Dolgorukova prešle su Perekop i preplavile cijeli poluotok Krim. Kan je zbačen, a doveden je proruski Sahib Giraj, čime je učinjen prvi korak ka odvajanju kanata od Osmanlija. Gubitak Krima, koji je tri stoljeća bio sjeverni štit Osmanlija, bio je početak procesa koji je 1774. doveo do nezavisnosti, a 1783. do neposredne aneksije.", "952270d8"]},
"OLAYLAR_EK5:1774-01-21:0":{"b": ["Smrt Mustafe III i stupanje na prijestolje Abdul-Hamida I", "42cba8e2"], "d": ["Na mjesto Mustafe III, umrlog u najkritičnijem trenutku ruskog rata, u četrdeset devetoj godini na prijestolje je stupio njegov brat Abdul-Hamid I, koji je četrdeset tri godine proveo u dvorskom kafezu. Novi sultan, preuzevši državu u jednom od najtežih razdoblja, morao se suočiti s teškim uslovima mira u Küčük Kajnardži, koji će se potpisati iste godine. Petnaestogodišnja vladavina proći će u gubitku Krima i novom ratu s Rusijom, a završit će 1789. moždanim udarom koji ga je zadesio dok je čitao vijest o padu Očakova.", "05963836"]},
"OLAYLAR_EK5:1774-06-25:0":{"b": ["Poraz kod Kozludže — poraz koji je vodio u Küčük Kajnardžu", "8e0542f9"], "d": ["Osmanske snage okupljene pred Šumnom poražene su kod Kozludže od združenih kolona Suvorova i Kamenskog, a veći dio vojske se raspao. Ovim porazom na Balkanu nije ostalo snaga za otpor; ruske prethodnice opsjele su Šumnu, a štab velikog vezira našao se pod prijetnjom. To što se za manje od mjesec dana sjelo za sto u Küčük Kajnardži i prihvatili izuzetno teški uslovi neposredna je posljedica tog poraza.", "6721d6e3"]},
"OLAYLAR_EK5:1775-05-07:0":{"b": ["Ustupanje Bukovine (Sjeverne Moldavije) Austriji", "190f9caa"], "d": ["Koristeći slabost nastalu nakon mira u Küčük Kajnardži, Austrija je zatražila oblast Bukovine, koja je spajala Moldaviju i Erdelj, i bez rata, prijetnjom i podmićivanjem, dobila tu zemlju. Gubitak te plodne i strateške oblasti jugozapadno od Hotina faktički je prepolovio Moldavsko vojvodstvo. To ustupanje bez ijednog ispaljenog metka smatralo se jednim od najjasnijih pokazatelja da je Osmanska država izgubila moć odvraćanja. Ustupanjem Bukovine 1775. Sučava i Černovci prešli su Austriji (dan nepotvrđen).", "93bbc1f7"]},
"OLAYLAR_EK5:1776-04-16:0":{"b": ["Iranska okupacija Basre", "0161e709"], "d": ["Sadik-han, brat zendskog vladara Kerim-hana, nakon jednogodišnje opsade zauzeo je Basru, pa je Osmanska država izgubila svoju najvažniju luku u Basranskom zaljevu. Okupacija je neposredno pogodila indijski trgovački put, prihode od datula i bisera i južnu odbranu Iraka. Grad se mogao vratiti tek 1779, tokom borbi za prijestolje koje su izbile u Iranu nakon smrti Kerim-hana.", "838306ba"]},
"OLAYLAR_EK5:1779-03-21:0":{"b": ["Ajnalikavačka konvencija (tenkihnama) — privremeni sporazum o Krimu", "9b3b0468"], "d": ["Dvije države, koje su zbog pitanja ko će doći na čelo Krimskog kanata stigle na ivicu rata, uz francusko posredovanje potpisale su u paviljonu Ajnali Kavak objašnjavajući tekst. Rusija je pristala povući vojsku s Krima, a Osmanska država priznati kanstvo proruskog Šahin Giraja; potvrđeno je sultanovo vjersko pravo hilafeta nad Krimom. Ta krhka ravnoteža, koja će trajati četiri godine, potpuno će se urušiti 1783. kada Rusija neposredno anektira poluotok.", "8a428802"]},
"OLAYLAR_EK5:1781-01-01:0":{"b": ["Gradnja tvrđave Anapa — kavkaska odbrambena linija", "be92a80f"], "d": ["Kad je Küčük Kajnardžom izgubljen Krim, radi očuvanja osmanskog uticaja na Kavkazu pristupilo se gradnji nove tvrđave na ušću rijeke Kuban. Anapa, sagrađena na ostacima đenoveške kolonije, sa čaršijom, hamamima i više od dvjesto pedeset dućana ubrzo je postala grad koji je održavao vezu sa čerkeskim plemenima. Tvrđava je četrdeset osam godina ostala najisturenija osmanska stražarnica protiv ruskog silaska na Kavkaz.", "334a40cb"]},
"OLAYLAR_EK5:1785-04-27:0":{"b": ["Smjena i pogubljenje velikog vezira Halil Hamid-paše", "c44001ca"], "d": ["Reformatorski veliki vezir Halil Hamid-paša, zadovoljstvo čijom je službom Abdul-Hamid I pokazivao u raznim prilikama, iznenada je pred jutro 31. marta 1785. smijenjen i prognan u Gelibolu, a sva imovina mu je zaplijenjena. Najprije su mu dodijeljeni Habeški ejalet, Džedanski sandžak i dužnost šejhul-harema Meke; dok je april 1785. provodio na Tenedosu pripremajući se za put, smijenjen je i s tog valijstva, a po izdatom fermanu o pogubljenju ubio ga je Karaćethudazade Ali, jedan od ljudi Džezairli Gazi Hasan-paše. Odsječena glava poslana je u Istanbul i izložena kod Ortakapije. Prema TDV-u, iako je taj nagli pad tumačen optužbom za zavjeru da se zbaci sultan i na njegovo mjesto dovede šehzada Selim, pravi razlozi mora da su bili ogorčenje zbog njegove šutnje o aneksiji Krima, neprijateljstvo krugova kojima su štetile njegove reforme i protivljenje Gazi Hasan-paše.", "6f73b0a5"]},
"OLAYLAR_EK5:1787-08-16:0":{"b": ["Objava rata Rusiji — počeo osmansko-ruski rat 1787–1792.", "3bfb870c"], "d": ["Zbog raskošnog putovanja Katarine II na Krim i njenog uzimanja Gruzije pod zaštitu, divan je donio odluku o ratu s ciljem poništavanja aneksije, a ruski poslanik ponovo je zatvoren u Jedikulu. Međutim, vojska nije bila spremna, riznica je bila prazna, a traganje za saveznicima ostalo je bez rezultata. Petogodišnji rat završit će se padom Očakova uz pokolj, gubitkom Izmaila i teškim uslovima Jaškog mira.", "80a26d8f"]},
"OLAYLAR_EK5:1788-02-09:0":{"b": ["Ulazak Austrije u rat — borba na dva fronta", "ae912290"], "d": ["Na osnovu tajnog saveza koji je s Rusijom sklopio 1781, austrijski car Josip II objavio je rat Osmanskoj državi i krenuo prema Beogradu i Bosni. Osmanska vojska odjednom je morala ratovati na dva fronta: na sjeveru protiv Rusije, na zapadu protiv Austrije. Uprkos pobjedama nad Austrijancima kod Lazaretane, Mehadije i Šebeša, gubitkom Beograda 1789. urušit će se i zapadni front.", "402d5acd"]},
"OLAYLAR_EK5:1790-01-31:0":{"b": ["Osmansko-pruski savez", "03b88e51"], "d": ["Selim III, koji je čim je stupio na prijestolje tražio saveznike u Evropi, potpisao je s Pruskom ugovor o savezu koji je predviđao uzajamnu pomoć; Pruska se obavezala da objavi rat Rusiji i Austriji, a Osmanska država da ne sklopi mir dok se ne povrati Krim. Bio je to prvi pravi tekst uzajamnog saveza koji su Osmanlije u svojoj historiji potpisale s nekom evropskom državom i pokazivao je da je napušteno klasično shvatanje 'ne može biti saveza s nevjernicima'. Pruska nije ušla u rat, ali je primoravši Austriju na mir otvorila put Svištovskom miru.", "de29f327"]},
"OLAYLAR_EK5:1790-12-22:0":{"b": ["Pad tvrđave Izmail i pokolj", "6a296b0c"], "d": ["Tvrđava Izmail, smatrana najjačim utvrđenjem delte Dunava, zauzeta je za jedan dan krvavim općim jurišem koji je organizirao general Suvorov; garnizon i stanovništvo grada u velikoj su mjeri posječeni sabljom. Taj pokolj, koji je imao širok odjek u Evropi, izazvao je dubok šok u osmanskoj javnosti i slomio kičmu dunavske odbrambene linije. Tvrđava će godinu kasnije biti vraćena Jaškim mirom, ali je sudbina rata tada već bila odavno odlučena.", "225351fb"]},
"OLAYLAR_EK5:1791-08-04:0":{"b": ["Svištovski mir — zatvaranje austrijskog fronta", "58741f1d"], "d": ["Zahvaljujući pritisku Pruske i tome što je Francuska revolucija zaokupila Austriju na zapadu, dvije države postigle su mir na osnovu predratnih granica. Austrija je vratila sva zauzeta mjesta, uključujući Beograd; Osmanska država prihvatila je samo male ispravke na hrvatskoj granici. Zatvaranje zapadnog fronta pod tim uslovima omogućilo je Osmanskoj državi da svu snagu usmjeri protiv Rusije i ograničilo gubitak u Jaškom miru. Ovim ispravkama na hrvatskoj granici Cetin (Cetingrad) i Drežnik Grad prelaze od Osmanlija Habsburgovcima (TDV zistovi-antlasmasi; Korić 2016, br. 118, 4. član). Oršova (Stara Oršova) jedino je mjesto koje nije vraćeno (Bánlaky 0019/1796); atlas pravni prijenos bilježi pod ovim datumom (faktička okupacija 16. aprila 1790).", "83845e51"]},
"OLAYLAR_EK5:1792-01-10:0":{"b": ["Jaški mir — konačni gubitak Krima i granica na Dnjestru", "a56fd194"], "d": ["Ugovorom potpisanim na kraju petogodišnjeg rata rijeka Turla (Dnjestar) prihvaćena je kao granica; lijeva obala rijeke ostala je Rusiji, desna Osmanlijama, a Očakov s okolinom konačno je izgubljen. Osmanska država potpuno je napustila nadu u povratak Krima i pravno priznala aneksiju iz 1783; Vlaška i Moldavija vraćene su uz dvogodišnje oslobođenje od poreza. Prihvaćena je i obaveza ratne odštete od dvanaest miliona guruša, čime je sjever Crnog mora trajno prepušten Rusiji. Ostala mjesta pripojena istog datuma: Izmail.", "277ee99d"]},
"OLAYLAR_EK5:1792-02-12:0":{"b": ["Španci evakuiraju Oran i predaju ga Alžiru", "9f95cee6"], "d": ["Kad su u zemljotresu 1790. tvrđava i grad uglavnom razoreni, Španija, koja više nije mogla nositi skupu posadu koju je držala tri stoljeća, sporazumjela se s alžirskim odžakom i bez borbe predala Oran i Mers el-Kebir. Tako je likvidiran i posljednji evropski položaj na sjevernoafričkoj obali. Osmanski Alžir vladao je cijelom obalom trideset osam godina, sve do francuske okupacije.", "c73636aa"]},
"OLAYLAR_EK5:1795-03-01:0":{"b": ["Faktička vladavina Pazvandoglu Osmana u Vidinu", "0ce70361"], "d": ["Pazvandoglu Osman, koji se pobunio protiv uredbi Nizam-i džedida, natjerao je vidinskog valiju u bijeg, zauzeo grad i utvrdio ga dubokim opkopima duž Dunava. Na vrhuncu moći 1797. okupio je gotovo osamdeset hiljada ljudi i pod kontrolu stavio Nikopolj, Svištov, Ruse, Sofiju i Niš; sebe je predstavljao ne kao pobunjenika, nego kao reformatora. Višemjesečna opsada Visoke porte 1798–1799. ostala je bez rezultata, a on je do smrti 1807. poluneovisno vladao Sjevernom Bugarskom.", "b0acf80b"]},
"OLAYLAR_EK5:1795-09-01:0":{"b": ["Otvaranje Mühendishane-i Berri-i Humajun", "e9a3a34b"], "d": ["Radi obrazovanja topničkih, inžinjerijskih i kartografskih oficira za vojsku Nizam-i džedida, u Hasköyu je otvorena kopnena inžinjerska škola; bila je kopneni pandan Pomorske inžinjerske škole osnovane 1773. U programu su se predavali algebra, geometrija, mehanika, fortifikacija i balistika, a s evropskih jezika prevođene su knjige iz matematike i artiljerije. Ta škola, smatrana korijenom modernog inžinjerskog obrazovanja u Turskoj, priznaje se kao početak današnjeg Istanbulskog tehničkog univerziteta.", "ff1a8344"]},
"OLAYLAR_EK5:1798-09-09:0":{"b": ["Objava rata Francuskoj i savez s Rusijom i Engleskom", "80e95bd7"], "d": ["Nakon Napoleonove okupacije Egipta, Osmanska država, prekinuvši dva i po stoljeća staro tradicionalno prijateljstvo s Francuskom, objavila joj je rat. U istom procesu prvi put u historiji sklopila je savez s Rusijom i dozvolila ruskoj floti da kroz moreuze izađe u Sredozemno more; zatim je potpisan savez i s Engleskom. Zahvaljujući tim savezima Jonski otoci oduzeti su Francuzima, ali je otvaranje moreuza stranoj floti stvorilo presedan koji će kasnije imati tešku cijenu.", "7d8a9e45"]},
"OLAYLAR_EK5:1798-10-23:0":{"b": ["Oduzimanje Preveze od Francuza — bitka kod Nikopolisa", "d8e5e892"], "d": ["Kad je 1797. pala Venecijanska Republika, Jonski otoci i na kopnu Preveza, Parga i Vonitsa prešli su u francuske ruke. Janjinski valija Ali-paša Tepelenski, koristeći rat objavljen zbog francuske okupacije Egipta, krenuo je na Prevezu i kod ruševina Nikopolisa izvan grada teško porazio francusku posadu. Tako je ta luka, ostavljena Veneciji u Požarevcu, osamdeset godina kasnije ušla pod osmansku upravu. Butrint (Butrinto) pao je 25. oktobra nakon što je francuska posada digla utvrđenja u zrak i povukla se na Krf (Curlin, Preveza B, 2010; atlas dan preuzima od Preveze) i ušao pod osmansku upravu.", "f32e8843"]},
"OLAYLAR_EK5:1799-05-20:0":{"b": ["Odbrana Akke — odbijanje Napoleona", "56b5c45b"], "d": ["Napoleon, koji je napredovao iz Egipta prema Siriji, opsjeo je Akku i dva mjeseca uzastopno jurišao; Džezar Ahmed-paša branio je grad uz podršku engleske flote i jedinica Nizam-i džedida poslanih iz Istanbula. Napoleon, prisiljen da digne opsadu i povuče se u Egipat, pred tim je zidinama sahranio san o širenju na istok. Vijest je u Istanbulu dočekana s velikom radošću i smatrana dokazom da je novoosnovana obučena vojska položila prvi ozbiljni ispit.", "78b85f0c"]},
"OLAYLAR_EK5:1801-04-01:0":{"b": ["Vehabijski prepad na Kerbelu", "522341ed"], "d": ["Vehabijske snage koje su krenule iz Nedžda ušle su u Kerbelu, opljačkale grad, razorile turbe hazreti Husejna i ubile više od tri hiljade ljudi. Kolemenski valije Osmanske države u Iraku nisu mogli spriječiti prepad; događaj je izazvao veliku reakciju i u Iranu i u Istanbulu. Taj napad bio je objava da je saudijski pokret prestao biti oazni emirat i pretvorio se u regionalnu silu koja prijeti osmanskim svetim gradovima.", "f571ab30"]},
"OLAYLAR_EK5:1801-09-24:0":{"b": ["Kartli-Kahetija (Istočna Gruzija) anektirana Rusiji", "3b650c5e"], "d": ["Kartlijsko-kahetinsko carstvo, koje je 1783. prihvatilo rusko pokroviteljstvo i 1795. pretrpjelo razorni iranski pohod, ukinuto je; naredbom od 12. septembra 1801. proglašeno je ruskom pokrajinom i počeo se uvoditi ruski upravni sistem. Gruzija je od tada izgubila nezavisnost; za nekoliko godina pod rusku vlast dospjele su i Megrelija (1803), Imeretija i Gurija (1804), a Rusija se naslonila na osmansku kavkasku granicu. Ovim događajem Gori, Dušeti (Kartli) i Telavi (Kahetija) prešli su Rusiji.", "f5e0d5d5"]},
"OLAYLAR_EK5:1801-10-09:0":{"b": ["Evakuacija Francuza iz Egipta", "00cfdc8c"], "d": ["Kao rezultat združene akcije osmanskih i engleskih snaga s kopna i mora, najprije je preuzet Kairo, zatim Aleksandrija, a francuske snage brodovima su poslane u domovinu. Dok se završavala trogodišnja okupacija, Egipat se na papiru vratio pod osmansku upravu, ali je borba za vlast između kolemenskih begova i albanskih jedinica gurnula zemlju u haos. Ta će praznina za nekoliko godina pripremiti tlo za uspon Mehmed Alije Kavalalija.", "acaf7e40"]},
"OLAYLAR_EK5:1802-06-25:0":{"b": ["Pariški mir — ponovna uspostava mira s Francuskom", "1b76991f"], "d": ["Ugovorom potpisanim nakon evakuacije Egipta ratno stanje između Osmanske države i Francuske zvanično je okončano i obnovljene su stare kapitulacije. Francuskim trgovačkim brodovima dozvoljen je ulazak u Crno more; zauzvrat je Francuska priznala osmanski teritorijalni integritet. Uspostava mira vratila je manevarski prostor vanjskoj politici Selima III, koja se bila stisnula uz Rusiju i Englesku.", "367c616e"]},
"OLAYLAR_EK5:1803-02-01:0":{"b": ["Vehabije zauzimaju Taif", "7b791359"], "d": ["Vehabijske snage pod zapovjedništvom Sauda b. Abdulaziza u prvom potezu prema Hidžazu opsjele su i opljačkale Taif; grad je pao kao prva kapija ka svetim zemljama. Za osmanskog sultana, koji je nosio naslov zaštitnika Haremejna, to je bio udarac koji je neposredno uzdrmao legitimitet vlasti. Dva i po mjeseca kasnije ista vojska krenut će na Meku.", "289d52ef"]},
"OLAYLAR_EK5:1803-04-30:0":{"b": ["Vehabije prvi put zauzimaju Meku", "21157c05"], "d": ["Dva i po mjeseca nakon pada Taifa vehabijske snage ušle su u Meku, srušile turbeta i uspostavile poredak po svom shvatanju; šerif Galib morao se povući u Džedu. Zatvaranje hadžijskih puteva odjeknulo je u cijelom islamskom svijetu i primoralo Istanbul da od egipatskog valije Mehmed Alije zatraži vojnu pomoć. Ta prva vlast trajat će samo tri mjeseca.", "7194e460"]},
"OLAYLAR_EK5:1803-08-06:0":{"b": ["Šerif Galib povratio Meku", "83d08dff"], "d": ["Šerif Galib, koji se povukao u Džedu, sa sakupljenim snagama opsjeo je Meku i nakon dvadesetpetodnevne opsade povratio grad od vehabija; hutba se ponovo učila u ime Osmanlija. Ni ta druga vlast neće biti trajna: saudijske snage ponovo će zauzeti grad 1806.", "8c15c19e"]},
"OLAYLAR_EK5:1804-02-14:0":{"b": ["Početak Prvog srpskog ustanka", "0f6e8767"], "d": ["Kad su pobunjeni janjičarski dahije, koji su preuzeli upravu u Beogradu, masovno pogubili srpske prvake, pod vodstvom Karađorđa počeo je oružani otpor. Pokret, koji se u početku vodio samo protiv dahija uz odanost sultanu, ubrzo se pretvorio u nacionalni ustanak koji je tražio autonomiju i nezavisnost. Srpske snage zauzele su Beograd 1806; ovaj ustanak bio je prva karika nacionalističkih pokreta za nezavisnost na Balkanu.", "07d5d6c6"]},
"OLAYLAR_EK5:1805-06-01:0":{"b": ["Vehabijska okupacija Medine", "84e310d7"], "d": ["Nakon Meke i Medina je pala u ruke vehabijskih snaga; riznica Ravzai-mutahhare razdijeljena je, a turbeta s kupolama u gradu srušena. Tako su oba sveta grada istovremeno izašla ispod osmanskog nadzora, a hadžijski karavani iz Damaska i Egipta godinama nisu mogli krenuti na put. Medinu je tek sedam godina kasnije, 1812, povratila egipatska vojska pod zapovjedništvom Tosun-paše, sina Mehmed Ali-paše.", "b8d034e6"]},
"OLAYLAR_EK5:1806-12-22:0":{"b": ["Početak rata s Rusijom (osmansko-ruski rat 1806–1812) i zatvaranje moreuza", "ea170804"], "d": ["Kad je Selim III, koji se nakon Napoleonove pobjede kod Austerlitza približio Francuskoj, uprkos ruskom pritisku smijenio vojvode Vlaške i Moldavije, ruske vojske okupirale su obje kneževine i rat je počeo. Osmanska država zatvorila je moreuze ruskoj floti; zauzvrat je i Engleska stala na stranu Rusije i poslala flotu u Istanbul. Taj šestogodišnji rat, isprepleten s Kabakčijevim ustankom i svrgavanjem Selima III, završit će gubitkom Besarabije u Bukureštanskom miru 1812.", "901537a4"]},
"OLAYLAR_EK5:1807-02-20:0":{"b": ["Dolazak engleske flote pred Istanbul (Duckworthova akcija)", "195bb58f"], "d": ["Engleska, želeći primorati Osmansku državu da prekine vezu s Francuskom, provela je flotu pod zapovjedništvom admirala Duckwortha kroz Dardanele i usidrila je pred Istanbulom. I uz usmjeravanje francuskog poslanika Sébastianija stanovništvo Istanbula se mobiliziralo, obalne baterije pojačane su u nekoliko dana, a flota se morala povući ne mogavši bombardirati grad; pri povratku je u Dardanelima pretrpjela teške gubitke. To što je prijestolnicu prvi put tako izbliza ugrozila strana flota postavilo je pitanje moreuza u središte evropske diplomacije.", "bf71116c"]},
"OLAYLAR_EK5:1808-11-17:0":{"b": ["Ubistvo Mustafe IV davljenjem", "eeb75c20"], "d": ["Kad je Alemdar Mustafa-paša doživio prepad i poginuo, a pobunjenici htjeli krenuti na saraj, svrgnuti Mustafa IV zadavljen je po naredbi svog brata Mahmuda II. Tijelo je sahranjeno u Bahčekapiju, u turbetu njegovog oca Abdul-Hamida I; među pobunjenicima proširila se glasina da je tabut prazan.", "8a944508"]},
"OLAYLAR_EK5:1809-01-05:0":{"b": ["Sultanijski mir (Kal'a-i Sultanije) — mir s Engleskom i pravilo o moreuzima", "fe282117"], "d": ["Ugovorom potpisanim s Engleskom nakon neuspjeha Duckworthove akcije okončan je rat između dviju država i engleskim trgovcima vraćene su stare povlastice. Odredba u tekstu, poznata kao 'drevno pravilo', zapisala je da u mirno doba nijedan strani ratni brod ne smije proći kroz moreuze. To načelo postalo je pravni temelj svih međunarodnih uredbi koje će tokom XIX stoljeća oblikovati režim moreuza.", "7ef33a02"]},
"OLAYLAR_EK5:1811-10-14:0":{"b": ["Poraz kod Slobozije — opkoljavanje dunavske vojske", "54b60fd1"], "d": ["Veći dio osmanske vojske koja je prešla Dunav kod Ruščuka bio je stisnut kod Slobozije manevrom opkoljavanja koji je Kutuzov izveo s druge obale rijeke i prepušten gladi. Hiljade vojnika morale su se predati; snaga u rukama velikog vezira faktički se istopila, a Visoka porta morala je mjesec dana kasnije zatražiti primirje. Taj poraz neposredan je uzrok pristanka na ustupanje Besarabije u Bukureštanskom miru 1812.", "d9da91c7"]},
"OLAYLAR_EK5:1813-10-05:0":{"b": ["Povratak Beograda i gušenje Prvog srpskog ustanka", "06f56f52"], "d": ["Srpski ustanici, lišeni ruske podrške Bukureštanskim mirom, nisu mogli izdržati zajedničku akciju snaga iz Bosne i Rumelije; Huršid Ahmed-paša ušao je u Beograd i devetogodišnji ustanak potpuno je ugušen. Karađorđe je pobjegao u Austriju, a Smederevski sandžak ponovo je neposredno vezan za osmansku upravu. Međutim, primijenjene oštre mjere dvije godine kasnije pokrenut će drugi i trajni ustanak pod vodstvom Miloša Obrenovića.", "1f0a751b"]},
"OLAYLAR_EK5:1815-04-23:0":{"b": ["Drugi srpski ustanak i vrhovno kneštvo Miloša Obrenovića", "e6e82ad2"], "d": ["Protiv teških mjera primijenjenih nakon gušenja prvog ustanka izbio je novi ustanak pod vodstvom Miloša Obrenovića; ovaj put je Visoka porta umjesto sile izabrala nagodbu. Sklopljenim sporazumom Miloš je priznat kao 'vrhovni knez', a ovlaštenje za ubiranje poreza i vođenje unutrašnjih poslova prepušteno je srpskim knezovima. Ta prva klica faktičke autonomije bila je polazište procesa koji je vodio do fermana 1830. i nezavisnosti 1878.", "bf6041bb"]},
"OLAYLAR_EK5:1821-02-22:0":{"b": ["Vlaški ustanak — Ipsilantijev prelazak Pruta i ustanak Vladimireskua", "67d46a98"], "d": ["Aleksandar Ipsilanti, general u ruskoj vojsci, u ime Filiki Eterije prešao je Prut i pokušao pokrenuti opći grčki ustanak u Vlaškoj i Moldaviji; istih dana Tudor Vladimirescu pokrenuo je i domaće seljake. Dva pokreta nisu se mogla ujediniti: na Ipsilantijev poziv na zajedničku borbu protiv Turaka Vladimirescu je odgovorio 'Ja sam ustao ne protiv Turaka nego protiv Grka' i ubrzo su ga ubili Ipsilantijevi ljudi. Ustanak su osmanske snage ugušile u maju, ali je fanariotski sistem vojvodstva okončan, a plamen ustanka prenio se na Moreju.", "64b96ac8"]},
"OLAYLAR_EK5:1824-06-01:0":{"b": ["Uspostava Druge saudijske države u Rijadu", "34dad3bd"], "d": ["Šest godina nakon pada Dirije 1818. i rušenja prve saudijske države, Turki b. Abdullah istjerao je egipatske garnizone iz Nedžda i uspostavio novi saudijski emirat sa središtem u Rijadu. Nova struktura, izbjegavajući širenje na Hidžaz, radije je ostala u Nedždu i držala se podalje od neposrednog sukoba s osmansko-egipatskim snagama. Ta druga država trajat će do kraja stoljeća i činit će drugu kariku lanca koji vodi do osnivanja današnje Saudijske Arabije. Ostala naselja izgubljena istog datuma: Dirija (Nedžd).", "72b5fd29"]},
"OLAYLAR_EK5:1826-10-07:0":{"b": ["Akermanski ugovor — ustupci Srbiji i kneževinama", "c75f15d0"], "d": ["Odmah nakon ukidanja janjičarskog odžaka Osmanska država, ostavši bez vojske, morala je pred ruskim ultimatumom prihvatiti ugovor s teškim uslovima. Potvrđena je autonomija obećana Srbiji, prihvaćeno je da vojvode Vlaške i Moldavije ne mogu biti smijenjene bez ruske saglasnosti, a ruskim trgovačkim brodovima priznata je potpuna sloboda u moreuzima. Kad je Visoka porta dvije godine kasnije zbog grčkog pitanja objavila da ne priznaje ugovor, Rusija će to uzeti kao povod za rat.", "a7de6cda"]},
"OLAYLAR_EK5:1827-02-01:0":{"b": ["Ukidanje timarskog sistema", "84d5d1d6"], "d": ["Godinu dana nakon ukidanja janjičarskog odžaka, oko 5.200 timarskih spahija u pedeset tri sandžaka Rumelije i Anadolije, zajedno s timarskim prihodima, pretvoreno je u konjicu Asakir-i Mansure. Tako je faktički završen timarski režim, četiri stoljeća stara okosnica osmanskog zemljišnog, poreskog i vojnog poretka. Oslobođeni timari preneseni su u državnu riznicu i otvoren je put prelasku na centralno plaćenu vojsku i novčani porez.", "077ea4ea"]},
"OLAYLAR_EK5:1827-03-14:0":{"b": ["Osnivanje Tiphane-i Amire — početak modernog medicinskog obrazovanja", "ac3e57c0"], "d": ["Da bi se za novoosnovanu vojsku Asakir-i Mansure obrazovali liječnici i hirurzi, na prijedlog glavnog liječnika Mustafa Behčet-efendije u Šehzadebašiju otvorena je Tiphane-i Amire. Predavanja su uređena po evropskom programu, a nastava se u početku izvodila na francuskom jeziku; nekoliko godina kasnije osnovana je i Džerahhane-i Amire, pa su dvije ustanove spojene. Ta škola, smatrana početkom modernog medicinskog obrazovanja u Turskoj, priznaje se kao korijen današnjeg Istanbulskog medicinskog fakulteta.", "54a2ed54"]},
"OLAYLAR_EK5:1828-04-26:0":{"b": ["Početak osmansko-ruskog rata 1828–1829.", "9dff4e05"], "d": ["Nakon spaljivanja flote kod Navarina i objave Visoke porte da ne priznaje Akermanski ugovor, Rusija je objavila rat na dva fronta. Budući da je janjičarski odžak tek bio ukinut, a nova vojska bila u fazi formiranja, osmanska odbrana bila je od početka slaba; Rusi su, prešavši Dunav, na istoku zauzeli Kars i Ahalcihe. Ruska vojska, koja je za godinu dana napredovala do Edirna, nametnut će teške uslove Jedrenskog mira 1829. i nezavisnost Grčke.", "9491c932"]},
"OLAYLAR_EK5:1830-05-07:0":{"b": ["Prvi ugovor sa Sjedinjenim Američkim Državama", "d737516f"], "d": ["Ugovorom o trgovini i plovidbi, potpisanim nakon višegodišnjih kontakata, SAD su stekle status najpovlaštenije nacije u osmanskoj zemlji i pravo trgovačkog prolaza kroz moreuze. Posebna tajna klauzula predviđala je da Osmanlije po želji mogu graditi brodove u američkim brodogradilištima i kupovati gotove brodove i drvenu građu; američki Senat ratificirao je ugovor, ali je tu tajnu klauzulu odbacio s 27 glasova protiv 18. Put prema brodovima ipak se nije zatvorio: Henry Eckford prodao je 1831. Osmanlijama brod koji je dovezao, a američki majstori koji su radili u Ajnali Kavaku donijeli su floti brodove novog tipa. Ovaj ugovor postao je dokument prvog sveobuhvatnog odnosa koji je Osmanska država uspostavila s nekom neevropskom državom.", "c87615ca"]},
"OLAYLAR_EK5:1831-09-14:0":{"b": ["Okončanje kolemenske uprave u Bagdadu", "7e1d38a3"], "d": ["Mahmud II, koji je vodio politiku centralizacije, proglasio je pobunjenikom bagdadskog valiju Davud-pašu, koji nije slao traženi novac i koji je dao ubiti činovnika poslanog iz centra. Snaga pod zapovjedništvom Ali Riza-paše nakon opsade od devedeset dana zauzela je grad, a gotovo svi kolemeni su uklonjeni. Tako je okončana poluneovisna kolemenska uprava koja je trajala od 1704, a Irak ponovo neposredno vezan za centar.", "676f3744"]},
"OLAYLAR_EK5:1834-07-01:0":{"b": ["Osnivanje Mekteb-i Harbije u kasarni Mačka", "bf31c7d9"], "d": ["Da bi se Asakir-i Mansure-i Muhammedijje obezbijedili oficiri obrazovani po evropskom uzoru, u kasarni Mačka otvoren je Mekteb-i Funun-i Harbije. Učenicima su se predavali matematika, kartografija, fortifikacija i strani jezici; ubrzo su učenici poslani u Beč i Pariz radi jačanja kadra. Ta škola postala je mjesto rođenja tradicije školovanih oficira u osmanskoj vojsci, a time i nove generacije vojnika-intelektualaca koja će se pojaviti krajem XIX stoljeća.", "1d64a30c"]},
"OLAYLAR_EK5:1835-05-26:0":{"b": ["Neposredno pripajanje Tripolija centru — kraj dinastije Karamanli", "faabcb96"], "d": ["Zbog borbi za prijestolje u porodici Karamanli i sve većeg evropskog pritiska nakon francuske okupacije Alžira 1830, Visoka porta neposredno je intervenirala u Tripoliju. Flota poslana iz Istanbula ušla je u grad, posljednji karamanlijski beg smijenjen je i doveden u Istanbul, a ejalet predat valiji imenovanom iz centra. Dok se završavalo 124 godine dugo dinastijsko razdoblje, učvršćen je posljednji dio teritorija u Sjevernoj Africi kojim je Osmanska država neposredno upravljala.", "71104846"]},
"OLAYLAR_EK5:1838-02-28:0":{"b": ["Ukidanje defterdarstva i osnivanje Ministarstva finansija", "89f8125e"], "d": ["Ukinut je položaj defterdara, glave klasičnog osmanskog finansijskog poretka, i osnovano Ministarstvo finansija, ministarstvo po evropskom uzoru, a raspršene riznice objedinjene su pod jednom rukom. Iste godine i druge jedinice Visoke porte preuređene su pod nazivom ministarstava, čime se prešlo na moderno ustrojstvo vijeća ministara. Ta uredba bila je jedan od najvažnijih koraka koji su pripremili upravnu infrastrukturu Tanzimatskog fermana, proglašenog godinu kasnije.", "46962eda"]},
"OLAYLAR_EK5:1839-01-19:0":{"b": ["Englezi se nastanjuju u Adenu", "ddbd556b"], "d": ["Engleska je, pozivajući se na sporazum o trgovini i prijateljstvu koji je 1802. potpisala sa sultanom Lehedža Ahmedom b. Abdulkerimom, iskrcala vojsku u adenskoj luci i preuzela nadzor nad gradom. Ta luka, koja je držala ušće Crvenog mora, postala je ključna tačka britanske imperijalne strategije kao stanica za opskrbu ugljem na putu za Indiju. Iako se osmanska pretenzija na Jemen na papiru nastavljala, faktička vlast na južnoj obali nakon ovog datuma više se nikada nije vratila.", "731b896d"]},
"OLAYLAR_EK5:1849-01-01:0":{"b": ["Povratak na obalu Tihame: zauzimanje Hodeide, Zebida i Moke", "353982d2"], "d": ["Na obalu Jemena, ostalu bez gospodara povlačenjem egipatske vojske 1840, iskrcale su se snage pod zapovjedništvom Tevfik-paše uz nadzor mekanskog šerifa i pripojile luke Hodeidu, Zebid i Moku osmanskoj upravi. Iako se željelo napredovati do Sane, zbog otpora stanovništva vratilo se u Hodeidu; tako su visoravni ostale zejdijskim imamima, a osmanska vlast dvadeset tri godine trajala je samo u pojasu Tihame. Unutrašnji Jemen vraćen je tek 1872. pohodom Ahmed Muhtar-paše.", "7a30c1f9"]},
"OLAYLAR_EK5:1849-05-01:0":{"b": ["Baltalimanska konvencija: zajedničko osmansko-rusko pokroviteljstvo u Vlaškoj i Moldaviji", "d3bb22e9"], "d": ["Kad su se revolucije 1848. proširile na Vlašku i Moldaviju, osmanske i ruske snage zajedno su okupirale kneževine. Konvencijom potpisanom u Baltalimanu dogovoreno je da vojvode neće birati nego ih postavljati sultan na sedam godina te da dvije države uspostave zajednički nadzor nad oblašću. Sporazum je čuvao osmanski suverenitet na papiru, ali je Rusiji priznao faktičko pravo partnerstva i ubrzao odvajanje dunavskih kneževina od Osmanlija.", "b343f446"]},
"OLAYLAR_EK5:1849-08-16:0":{"b": ["Pitanje mađarskih izbjeglica: Kossuth i njegovi drugovi sklanjaju se kod Osmanlija", "1c7d7ef4"], "d": ["Nakon gušenja mađarske revolucije 1848–1849. rusko-austrijskom intervencijom, Lajos Kossuth i hiljade mađarskih i poljskih izbjeglica sklonili su se na osmanske zemlje. Austrija i Rusija oštro su tražile izručenje izbjeglica; Visoka porta, uz podršku Engleske i Francuske, odbila je izručenje i nastanila grupu u Kutahji. Kossuthov krug tu je ostao oko osamnaest mjeseci, a stotine izbjeglica primile su islam i stupile u osmansku službu. Događaj se smatra jednom od rijetkih diplomatskih pobjeda koje su uzdigle ugled tanzimatskih Osmanlija u evropskoj javnosti.", "07b6d020"]},
"OLAYLAR_EK5:1851-02-11:0":{"b": ["Osnivanje Endžumen-i Daniša: prva osmanska akademija u Istanbulu", "6fda1365"], "d": ["Endžumen-i Daniš, osnovan odlukom Medžlis-i Maarif-i Umumijje, prva je osmanska naučna akademija ustanovljena radi pripremanja naučnih i školskih knjiga na turskom. Svečano je otvoren 18. jula 1851. u zgradi Darulmaarifa; među domaćim i stranim članovima bio je i Ahmed Dževdet-paša. Iako kratkog vijeka, djela kao što su Dževdet-pašina Historija i Kavaid-i Osmanijje bila su plod te ustanove, i ona se smatrala kamenom temeljcem za to da turski postane jezik nauke.", "7eebb193"]},
"OLAYLAR_EK5:1853-11-11:0":{"b": ["Pobjeda kod Oltenice: prvi osmanski uspjeh na dunavskom frontu", "a660ad2f"], "d": ["U početnoj fazi Krimskog rata serdar-ekrem Omer Lutfi-paša prešao je Dunav i kod Oltenice uz teške gubitke odbio ruske snage. Pobjeda je zaustavila rusko napredovanje na samom početku rata i pokazala Evropi snagu koju je osmanska vojska stekla obukom nakon Tanzimata. Taj uspjeh pripremio je psihološku podlogu koja je olakšala odluku Engleske i Francuske da uđu u rat na strani Osmanlija.", "a0e5e8fb"]},
"OLAYLAR_EK5:1854-03-12:0":{"b": ["Ugovor o savezu s Engleskom i Francuskom u Istanbulu", "04809278"], "d": ["Ugovorom o savezu potpisanim u Krimskom ratu protiv Rusije između Osmanske države, Engleske i Francuske utvrđeno je da tri države vode zajedničke operacije i da saveznici prije kraja rata neće sklopiti zaseban mir. Tako je Osmanska država prvi put u historiji stupila u vojni savez s velikim evropskim državama kao ravnopravna strana. Taj ugovor stvorio je i pravnu osnovu za zvanično primanje Osmanlija u evropski sistem država u Parizu dvije godine kasnije.", "1899331b"]},
"OLAYLAR_EK5:1855-08-16:0":{"b": ["Osnivanje Istanbulskog šehremaneta: prvo moderno gradsko ustrojstvo", "be4af27f"], "d": ["Kriza infrastrukture nastala zbog savezničkih vojnika nagomilanih u Istanbulu tokom Krimskog rata i rasta stanovništva razotkrila je nedostatnost klasične gradske uprave sa središtem u kadijstvu. Osnivanjem Šehremaneta po evropskim uzorima poslovi čistoće, narha, nadzora čaršije i izgradnje objedinjeni su pod jednom rukom; iduće godine u Bejoglu-Galati ustanovljena je kao pilot-područje Šesta općinska uprava. Taj korak smatra se početkom moderne komunalne uprave kod Osmanlija.", "23959c70"]},
"OLAYLAR_EK5:1856-03-30:0":{"b": ["Pariški mir: kraj Krimskog rata i primanje Osmanlija u evropski sistem država", "4aee0e2a"], "d": ["Pariškim mirom, kojim je okončan Krimski rat, Osmanska država proglašena je ravnopravnim članom evropskog međunarodnog prava, a njen teritorijalni integritet stavljen pod zajedničku garanciju velikih sila. Crno more je neutralizirano, poništena je ruska pretenzija na pokroviteljstvo nad pravoslavnim podanicima, stečena od mira u Küčük Kajnardži, a južna Besarabija (kadiluci Kilija, Kagul, Izmail i Bolgrad) pripala je Moldaviji. Međutim, isti ugovor pretvorio je Islahat-ferman u međunarodnu obavezu i time odškrinuo vrata miješanju u unutrašnje poslove.", "42c5d63d"]},
"OLAYLAR_EK5:1856-06-07:0":{"b": ["Otvaranje saraja Dolmabahče: preseljenje sjedišta uprave iz Topkapija", "71ad26d0"], "d": ["Saraj, koji je Abdul-Medžid 1842. naručio od porodice Baljan, otvoren je nakon četrnaest godina gradnje, a sjedište državne uprave preseljeno je iz četiri stoljeća starog Topkapija na obalu Bosfora. Sa svojim evropskim stilom, kristalnim stepeništem i Dvoranom za bajramske čestitke saraj je postao kameni izraz zapadnjačke pretenzije Tanzimata. Njegova golema cijena postala je jedna od najkritikovanijih stavki godina u kojima su osmanske finansije ušle u spiralu vanjskog zaduživanja.", "bb3cd1c8"]},
"OLAYLAR_EK5:1859-02-05:0":{"b": ["Ujedinjenje Vlaške i Moldavije pod Cuzom: rođenje Rumunije", "baef4da5"], "d": ["Na izborima organiziranim nakon Pariškog mira obje kneževine izabrale su pukovnika Alexandrua Ioana Cuzu za vojvodu i time ostvarile faktičko ujedinjenje. Iako su se Visoka porta i Austrija tome protivile, morao se prihvatiti svršeni čin koji je podržavala Francuska. Taj savez, na papiru i dalje vezan za Osmanlije, 1862. uzet će ime Rumunija, a 1877. jednostrano proglasiti nezavisnost; on je prekretnica u raspadanju osmanske vlasti na Dunavu.", "83e52b52"]},
"OLAYLAR_EK5:1859-09-14:0":{"b": ["Incident u Kuleliju: prvi pokušaj državnog udara protiv Abdul-Medžida u Istanbulu", "e3653b21"], "d": ["Tajno društvo sastavljeno od vojnika i civila, koje je reagovalo na tanzimatsku politiku i na jednakost koju je Islahat-ferman priznao nemuslimanima, planirajući zbacivanje sultana, zatečeno je prepadom na sastanku u džamiji Kilič Ali-paše. Budući da su optuženici suđeni u kasarni Kuleli, događaj se tako zove; smrtne kazne preinačene su u progonstvo. Smatra se prvim pokušajem dvorskog udara u osmanskoj historiji koji je preduzela organizacija osnovana iz ideoloških pobuda.", "4e9e2296"]},
"OLAYLAR_EK5:1860-05-30:0":{"b": ["Druzsko-maronitski građanski rat u Džebel-i Libanu i događaji u Damasku", "5595fdd6"], "d": ["Sukobi koji su izbili u maju 1860. nakon ubistva dvojice Druza u blizini Sidona pretvorili su se u najkrvaviji druzsko-maronitski građanski rat u planini, a u julu su se prenijeli na Damask i završili smrću hiljada kršćana. Kad je Francuska iskrcala vojsku, Visoka porta poslala je u tu oblast Fuad-pašu s izvanrednim ovlaštenjima; provedena je oštra kaznena akcija. Događaji su postali povod za evropsku intervenciju i neposredan uzrok tome što je Liban dobio poseban status.", "511709b3"]},
"OLAYLAR_EK5:1860-10-22:0":{"b": ["Početak izlaženja lista Terdžuman-i Ahval: prve privatne turske novine u Istanbulu", "24792957"], "d": ["Terdžuman-i Ahval, koji je izdavao Agah-efendija, a uredništvo preuzeo Šinasi, prve su turske novine koje su izlazile bez državne potpore. U uvodniku prvog broja branjeno je pravo naroda da kaže svoju riječ o vlastitim poslovima, a novine su, objavljujući u nastavcima Šinasijevu 'Ženidbu pjesnika', otvorile vrata i modernoj turskoj književnosti. Rođenje pojma javnog mnijenja i opozicione štampe kod Osmanlija veže se za ovaj datum.", "cc4ba4a5"]},
"OLAYLAR_EK5:1861-06-09:0":{"b": ["Nizamnama o Džebel-i Libanu: povlašteni status mutasarifluka za Liban", "bf375603"], "d": ["Nizamnama, pripremljena pod pritiskom velikih sila nakon pokolja 1860, pretvorila je Džebel-i Liban u povlašteni mutasarifluk neposredno vezan za Visoku portu, kojim je upravljao upravni savjet sastavljen po ravnoteži među vjerskim zajednicama. Propisano je da mutasarif mora biti katolički kršćanin i osmanski podanik, a njegovo imenovanje podneseno na odobrenje velikim silama; prvi mutasarif bio je Davud-paša. Taj poredak trajat će do 1915. i činiti jezgro moderne libanske države.", "1b56a9d5"]},
"OLAYLAR_EK5:1861-06-25:0":{"b": ["Smrt Abdul-Medžida i stupanje na prijestolje sultana Abdul-Aziza", "27204d7c"], "d": ["Kad je Abdul-Medžid, koji je u dvadeset dvije godine vladavine potpisao Tanzimatski i Islahat ferman, podlegao tuberkulozi, na prijestolje je stupio njegov brat Abdul-Aziz. Novi sultan u prvim je godinama mjerama štednje i jednostavnim životom ulijevao nadu; flotu je pretvorio u jednu od rijetkih velikih snaga svijeta. Ali pri kraju njegove vladavine nagomilaju se teški vanjski dug, bankrot 1875. i balkanski ustanci, što će pripremiti tlo za njegovo svrgavanje 1876.", "1c2db3f9"]},
"OLAYLAR_EK5:1862-02-21:0":{"b": ["Ujedinjene kneževine dobivaju ime Rumunija", "d960e3fc"], "d": ["Vlaška i Moldavija, faktički ujedinjene dvostrukim izborom Cuze 1859, objedinivši 1862. svoje skupštine i vlade pod jednim krovom u Bukureštu, zvanično su uzele ime Rumunija. Iako je Osmanska država pravno zadržala status suzerena i godišnji danak, faktički je izgubila nadzor nad kneževinom. Kraj četiristoljetnog osmanskog uticaja sjeverno od Dunava simbolizira ovaj datum.", "1693f20f"]},
"OLAYLAR_EK5:1865-01-01:0":{"b": ["Pripajanje Suakina, Masawe i Dahlaka Egiptu", "a0924860"], "d": ["Masawa, koju je sultan Abdul-Medžid 1846. zajedno sa Suakinom dao egipatskom hedivu Mehmed Ali-paši kao saljanu (dodjelu prihoda), za hediva Ismail-paše zajedno s Dahlakom i Suakinom uključena je u egipatske posjede i uređena kao kajmakamluk. Tako su te tri luke na afričkoj obali Crvenog mora, iako su pravno ostale osmanski teritorij, upravno iz neposredne nadležnosti Visoke porte prešle Kairu — ušle su u isti vazalni sloj kao susjedni Egipat i Sudan.", "782199b7"]},
"OLAYLAR_EK5:1866-08-21:0":{"b": ["Početak Kretskog ustanka (1866–1869)", "3679b861"], "d": ["Široki ustanak koji je izbio na otoku uz otvorenu podršku Grčke prvi put je zahtjev kretskih Grka za enosisom (pripajanjem Grčkoj) učinio međunarodnim pitanjem. Trogodišnji teški gorski rat nanio je osmanskoj vojsci velike gubitke i snažno odjeknuo u evropskoj javnosti. Ustanak se mogao ugasiti tek 1868, kad je Ali-paša otišao na otok i uveo nizamnamu koja je priznala široke povlastice.", "eba163ff"]},
"OLAYLAR_EK5:1867-04-18:0":{"b": ["Povlačenje posljednjih osmanskih posada iz Beograda i tvrđava Srbije", "b34217db"], "d": ["Pod pritiskom velikih sila i na uporan zahtjev kneza Mihaila, Visoka porta pristala je isprazniti posljednje vojne baze koje su joj ostale u Srbiji; 18. aprila 1867. osmanska zastava na Beogradskoj tvrđavi spuštena je, a ključevi predati knezu. Tako je okončano faktičko osmansko vojno prisustvo koje je trajalo od 1521. i uklonjena posljednja velika prepreka na putu Srbije k nezavisnosti. Sultanov suzerenitet sveo se samo na simbolično pitanje zastave i danka.", "875dbecb"]},
"OLAYLAR_EK5:1867-06-08:0":{"b": ["Dodjela titule hediva egipatskim valijama", "09e10c12"], "d": ["Zahvaljujući snažnom lobiranju Ismail-paše iz trećeg koljena dinastije Kavalali i novcu koji je slivao u Istanbul, egipatskom valiji dodijeljena je titula hediva, kojom se naglašavala njegova nadređenost drugim valijama. Istih godina i način nasljeđivanja izmijenjen je tako da prelazi s oca na sina, a Egiptu su priznata ovlaštenja suverenog karaktera, kao što su vanjsko zaduživanje, dodjela odlikovanja i držanje konzulata. Ti su koraci prva karika lanca koji je ubrzao pravno odvajanje Egipta od Osmanlija.", "38a9a00f"]},
"OLAYLAR_EK5:1868-01-04:0":{"b": ["Kretska nizamnama: široke upravne povlastice za otok", "12052262"], "d": ["Da bi se okončao trogodišnji ustanak, veliki vezir Ali-paša lično je prešao na otok, a nizamnamom objavljenom uz sultanovo odobrenje Krećanima su priznati mješoviti upravni savjeti, mjesni sudovi, upotreba grčkog jezika u službenim poslovima i poreske olakšice. Ta uredba održala je osmansku vlast na otoku još trideset godina. Međutim, povlastice priznate kršćanskom stanovništvu oslabile su položaj muslimanskih Krećana i posijale sjeme krize 1896–1898.", "9cce04af"]},
"OLAYLAR_EK5:1868-05-10:0":{"b": ["Otvaranje Šura-yi Devleta: osnivanje osmanskog Državnog vijeća", "70b16497"], "d": ["Iradom od 5. marta 1868. Medžlis-i Ahkam-i Adlijje podijeljen je na dvoje: upravno-zakonodavni poslovi prepušteni su Šura-yi Devletu, a sudski Divan-i Ahkam-i Adlijje; ustanova je svečano otvorena u Visokoj porti, a za prvog predsjednika doveden je Midhat-paša. Zadužena je da priprema nacrte zakona, rješava upravne sporove i vodi suđenja činovnicima. Sa svojim mješovitim muslimansko-nemuslimanskim članstvom smatra se prvom institucionalnom primjenom ideje podjele vlasti kod Osmanlija.", "c85741e0"]},
"OLAYLAR_EK5:1869-11-17:0":{"b": ["Otvaranje Sueskog kanala: skraćivanje puta za Indiju preko Egipta", "377ccd04"], "d": ["Gradnja započeta 1859. trajala je deset godina, a kanal od 163 kilometra, koji povezuje Sredozemno i Crveno more, uz veličanstvenu svečanost pušten je u upotrebu. Kad se put koji Evropu povezuje s Indijom skratio za hiljade milja, Egipat je odjednom postao ključna tačka svjetske trgovine. Ta geostrateška vrijednost bit će glavni razlog što će Engleska trinaest godina nakon otvaranja kanala okupirati Egipat; a dug koji je kanal natovario Egiptu odvest će hedivat u bankrot.", "ccff3d4b"]},
"OLAYLAR_EK5:1870-03-11:0":{"b": ["Osnivanje Bugarskog egzarhata: odvajanje bugarske crkve od Fenera", "33a8272c"], "d": ["Sultanovim fermanom osnovana je zasebna, samostalna bugarska crkva (egzarhat), odvojena od Grčke patrijaršije, a narodnom glasanju prepušteno je koji će kadiluci biti vezani za egzarhat. Iako je Visoka porta taj korak preduzela da slomi grčki uticaj, ishod je bio suprotan: crkva se pretvorila u organizirano središte bugarskog nacionalnog identiteta i bugarske pretenzije na Makedoniju. Tako je postavljena institucionalna podloga bugarsko-grčko-srpskog suparništva na Balkanu i ustanaka 1876.", "ce8f108b"]},
"OLAYLAR_EK5:1871-01-01:0":{"b": ["Stavljanje Asira pod neposrednu upravu", "4559e099"], "d": ["Kad je otvaranjem Sueskog kanala porasla strateška vrijednost Crvenog mora, uvidjelo se da se planine Asir na sredini kopnenog puta za Jemen ne mogu ostaviti bez nadzora. Snage Redif-paše, koji je krenuo u jemenski pohod, ušle su u Abhu, pripojile oblast neposrednoj osmanskoj upravi i osnovan je Asirski sandžak. Zbog brdovitog reljefa i uticaja Idrisija ta vlast nikada se nije potpuno učvrstila.", "eb2bbdad"]},
"OLAYLAR_EK5:1871-04-20:0":{"b": ["Nedžedski pohod Midhat-paše: ponovna uspostava osmanske vlasti u Lahsi", "7db51461"], "d": ["Bagdadski valija Midhat-paša, koristeći borbu za prijestolje u porodici Saud, uputio je vojsku na zapadnu obalu Perzijskog zaljeva i oblast Lahsa pod imenom Nedžedski sandžak pripojio Basranskom vilajetu. Abdullah b. Fejsal postavljen je za mutasarifa, čime je osmanska vlast uspostavljena na papiru. Pohod je imao cilj zaustaviti širenje engleskog uticaja u zaljevu i iste godine doveo je do toga da i Katar uđe pod osmanski nadzor.", "fbc6819e"]},
"OLAYLAR_EK5:1871-09-07:0":{"b": ["Smrt velikog vezira Ali-paše: kraj tanzimatskog kadra", "1cf0141c"], "d": ["Smrću Ali-paše, koji je nakon smrti Fuad-paše 1869. sam nosio tanzimatsku politiku, iscrpljena je generacija vještih diplomata koja je trideset godina vodila državnu vanjsku politiku. Proruska i samovoljna uprava Mahmud Nedim-paše, koji je došao na njegovo mjesto, učvrstila je ličnu vladavinu Abdul-Aziza. U pet godina nakon smrti Ali-paše finansije su bankrotirale, Balkan se digao na ustanak, a smjena na prijestolju postala je neizbježna.", "c4954cff"]},
"OLAYLAR_EK5:1871-09-20:0":{"b": ["Uspostava osmanske kontrole u Kataru", "3b453165"], "d": ["Na poziv šejha Kasima b. Sanija, koji je bio pod engleskim pritiskom, osmanske snage iskrcale su se na poluotok Katar i u jesen 1871. uspostavljena je osmanska kontrola u toj oblasti. Katar je ustrojen kao kadiluk Nedžedskog sandžaka, a šejh je postavljen za kajmakama. Taj potez bio je najopipljiviji dobitak ofanzivne politike koju je Midhat-paša u zaljevu vodio protiv Engleske; osmanska zastava na poluotoku vijorila se do 1913.", "823711c3"]},
"OLAYLAR_EK5:1871-10-24:0":{"b": ["Ferman o nasljeđivanju za Tunis — bejluk porodici Mehmed Sadik-paše", "1509ebb0"], "d": ["Fermanom donesenim zahvaljujući nastojanjima Hajreddin-paše, koga je tuniski beg Mehmed Sadik-paša, koristeći francuski poraz od Pruske, poslao u Istanbul, Tunis je, uz neposrednu vezanost za Istanbul, dat Mehmed Sadik-paši i njegovim potomcima uz pravo nasljeđivanja. Bez sultanove dozvole neće se voditi ni rat ni mirovni pregovori, nikakva zemlja neće se dati drugome, a osmanski zahtjev za vojnicima bit će ispunjen. Francuska nije priznala ferman; deset godina kasnije okupirala je Tunis.", "b72eabcc"]},
"OLAYLAR_EK5:1872-04-01:0":{"b": ["Zauzimanje Sane: ponovna uspostava osmanske vlasti u Jemenu", "978e20a0"], "d": ["Kad je otvaranjem Sueskog kanala porasla strateška vrijednost Crvenog mora, Visoka porta uputila je u Jemen pričuvnu vojsku pod zapovjedništvom Ahmed Muhtar-paše. Zauzimanjem Sane u unutrašnjem Jemenu, faktički izgubljenom dva stoljeća, ponovo je uspostavljen državni autoritet, a oblast je pretvorena u vilajet. Međutim, borba sa zejdijskim imamima nikada nije prestala; ustanci 1891, 1898. i 1904. činili su najskuplji i najdugotrajniji unutrašnji front Osmanlija. Ostala mjesta pripojena istog datuma: Sana, Taiz.", "2173d1a2"]},
"OLAYLAR_EK5:1875-06-19:0":{"b": ["Početak Hercegovačkog ustanka: ponovno rasplamsavanje Istočnog pitanja", "571b18ec"], "d": ["Ustanak kršćanskih seljaka oko Nevesinja zbog teških poreza i pritiska ajana ubrzo se proširio na cijelu Hercegovinu i hranio se dobrovoljcima iz Srbije i Crne Gore. Ustanak, koji je doveo do toga da Austrija i Rusija nametnu reforme, iduće godine pokrenuo je bugarske ustanke i srpsko-crnogorske objave rata. Tako je pukla prva karika velikog lanca koji je vodio do rata 1877–78. i gubitka Balkana Berlinskim ugovorom.", "b697eb06"]},
"OLAYLAR_EK5:1875-10-06:0":{"b": ["Bankrot osmanskih finansija: prepolovljene otplate vanjskog duga", "2cac2fa5"], "d": ["Zajmovi uzimani jedan za drugim od 1854, troškovi Krimskog rata, gradnja saraja i anadolska glad 1873–74. pretvorili su budžetski deficit u ponor veći od pet miliona lira. Vlada Mahmud Nedim-paše objavila je da će otplate kamata i glavnice duga na pet godina biti prepolovljene, čime je faktički proglasila moratorij. Ta odluka, koja je izazvala veliku reakciju na evropskim berzama, pokrenula je proces koji će šest godina kasnije rezultirati Muharemskom uredbom i osnivanjem Uprave Dujun-i Umumijje.", "a6706632"]},
"OLAYLAR_EK5:1876-08-31:0":{"b": ["Svrgavanje Murata V i stupanje na prijestolje Abdul-Hamida II", "cffb2271"], "d": ["Murat V, koji je stupio na prijestolje nakon svrgavanja Abdul-Aziza, zbog duševnog zdravlja uzdrmanog smrću strica i incidentom Čerkeza Hasana postao je nesposoban za obavljanje dužnosti; od devedeset tri dana vladavine samo je sedam dana bio pri zdravom razumu. Svrgnut je fetvom šejhul-islama, a na njegovo mjesto doveden je brat Abdul-Hamid II. Novi sultan stupio je na prijestolje dajući Midhat-paši obećanje da će proglasiti ustavnu monarhiju; počinjalo je doba koje će trajati trideset tri godine.", "9904ab70"]},
"OLAYLAR_EK5:1876-12-23:0":{"b": ["Konferencija u brodogradilištu (Tersane): velike sile nameću balkanske reforme", "b5006a2c"], "d": ["Konferencija koju su velike sile sazvale u Istanbulu radi rješavanja balkanske krize zahtijevala je da se Bugarska podijeli na dva autonomna vilajeta i da se u Bosni i Hercegovini provedu reforme pod međunarodnim nadzorom. Visoka porta, na dan otvaranja konferencije topovskim plotunima objavivši proglašenje Kanun-i Esasija, pokušala je na nametanja odgovoriti ustavnom reformom. Delegati su to smatrali odugovlačenjem i 20. januara 1877. razišli se; četiri mjeseca kasnije Rusija je objavila rat.", "8149c00f"]},
"OLAYLAR_EK5:1877-03-19:0":{"b": ["Otvaranje prvog Medžlis-i Mebusana u Dolmabahčeu", "429bb279"], "d": ["115 poslanika izabranih na osnovu Kanun-i Esasija prvi se put sastalo 19. marta 1877. na svečanosti u Dvorani za bajramske čestitke saraja Dolmabahče; tako je u osmanskoj historiji počelo doba predstavničke skupštine. Muslimanski i nemuslimanski poslanici oštro su ispitivali vladu i raspravljali o vođenju rata i odgovornosti ministara. Ta hrabra opozicija bit će glavni razlog što će skupštini biti skraćen vijek.", "df95fa07"]},
"OLAYLAR_EK5:1877-07-19:0":{"b": ["Početak odbrane Plevne: otpor Gazi Osman-paše", "0e04a878"], "d": ["Osman-paša, koji je iz Vidina krenuo na Plevnu da presiječe put prema Istanbulu ruskoj vojsci koja je u ratu 1877–78. prešla Dunav, utvrdio je gradić tabijama i rovovima i započeo petomjesečnu legendarnu odbranu. Uzastopna tri velika rusko-rumunska napada odbijena su uz teške gubitke, a vojska kojom je lično zapovijedao car Aleksandar II bila je prisiljena na opsadu. Plevna je ušla u historiju kao najblistaviji odbrambeni uspjeh osmanske vojske u 19. stoljeću.", "5a86466f"]},
"OLAYLAR_EK5:1877-12-10:0":{"b": ["Pad Plevne: slom dunavskog fronta", "185e7602"], "d": ["Osman-paša, kojem su u petomjesečnoj opsadi nestale zalihe, preduzeo je ispad preko rijeke Vit; kad je ranjen pao u zarobljeništvo, grad se predao. Ruski zapovjednici pozdravili su zarobljenog pašu vrativši mu sablju, a Osman-paša dobio je nadimak 'Gazi'. Padom Plevne ruskoj vojsci otvoren je put; u roku od dva mjeseca pali su Sofija, Plovdiv i Edirne, a ruske prethodnice stigle su do Ješilköya.", "fc075756"]},
"OLAYLAR_EK5:1878-01-04:0":{"b": ["Ruska okupacija Sofije", "ef369d22"], "d": ["Ruska vojska, koja je nakon pada Plevne prešla Balkan, ušla je u nezaštićenu Sofiju. Grad se više nikada neće vratiti pod osmansku upravu; postat će krajem 1878. dio autonomne Kneževine Bugarske, a 1879. faktički njen glavni grad. Na karti Sofija od tog datuma izlazi iz neposredne osmanske uprave i prelazi u privremenu rusku okupaciju, a zatim u autonomnu bugarsku upravu.", "66b1da91"]},
"OLAYLAR_EK5:1878-01-31:0":{"b": ["Jedrensko primirje: utihnulo oružje u ratu 1877–78.", "1f899180"], "d": ["Kad su Sofija, Plovdiv i Edirne pali jedno za drugim, a ruska vojska doprla do obala Mramornog mora, Visoka porta morala je tražiti primirje. Primirje potpisano u Edirnama primoralo je Osmanlije da prihvate preliminarne uslove mira kao što su autonomija Bugarske, nezavisnost Crne Gore, Srbije i Rumunije te teška ratna odšteta. Ti uslovi će mjesec dana kasnije u Svetom Stefanu postati tekst ugovora.", "49d61081"]},
"OLAYLAR_EK5:1878-02-13:0":{"b": ["Abdul-Hamid II raspušta Medžlis-i Mebusan na neodređeno vrijeme", "e770b540"], "d": ["Zbog oštrih kritika poslanika koji su vladu i saraj smatrali odgovornima za katastrofalan ishod rata, Abdul-Hamid II, pozivajući se na ovlaštenje koje mu je davao Kanun-i Esasi, raspustio je skupštinu na neodređeno vrijeme. Tako je zatvoren prvi osmanski parlament, koji je radio oko jedanaest mjeseci, i počelo je doba apsolutizma koje će trajati trideset godina. Skupština se mogla ponovo sastati tek nakon revolucije 1908.", "dd2e6d60"]},
"OLAYLAR_EK5:1878-03-03:0":{"b": ["Sanstefanski mir: projekt Velike Bugarske", "2c7cc611"], "d": ["Sanstefanski mir, kojim je završen rat 1877–78, stvarao je golemu autonomnu Bugarsku koja je dopirala do Egeja i obuhvatala Makedoniju; priznavao nezavisnost Srbije, Crne Gore i Rumunije; Kars, Ardahan, Batum i Doğubayazit ostavljao Rusiji, a uz to nametao ratnu odštetu koju je bilo nemoguće platiti. Taj tekst, koji je Rusiju spuštao na Sredozemno more, izazvao je žestoku reakciju Engleske i Austrije. Prije nego što je proveden, za četiri mjeseca ponovo je uređen na Berlinskom kongresu; ipak je ostao dokument koji je objavio kraj osmanske Rumelije.", "dfd3e7f4"]},
"OLAYLAR_EK5:1878-07-13:0":{"b": ["Kars, Ardahan i Batum prepušteni Rusiji — Elvije-i Selase", "99bdfad2"], "d": ["Berlinskim ugovorom Osmanska država prepustila je Rusiji Kars, Ardahan i Batum na ime dijela ratne odštete; Doğubayazit i dolina Eleškirta, dati Rusiji u Svetom Stefanu, ostali su Osmanlijama. Iako je Batum dat kao slobodna luka, taj status mogao je zadržati samo do 1886. Rusi su Kars učinili oblašću vezanom za zakavkasko generalno guvernerstvo sa sjedištem u Tbilisiju; stanovništvo iz Elvije-i Selase, čiji je broj dostizao 100.000, moralo je iseliti prema Erzurumu. Istim ugovorom Južna Besarabija (Kilija, Kagul, Bolgrad) vraćena je od Rumunije Rusiji.", "867dda58"]},
"OLAYLAR_EK5:1878-07-29:0":{"b": ["Austrougarska okupacija Bosne i Hercegovine i Novopazarskog sandžaka", "e5f901df"], "d": ["Na osnovu ovlaštenja datog Berlinskim ugovorom austrougarske vojske ušle su u Bosnu; iako je osmanska vlada pristala da se ne opire, domaće muslimansko i pravoslavno stanovništvo u Sarajevu i Mostaru latilo se oružja i tri mjeseca pružalo žilav otpor. Okupacija je mogla biti završena tek 20. oktobra 1878. Sultanov pravni suverenitet trajao je na papiru do 1908, ali je četiristoljetna osmanska Bosna faktički izgubljena i počeo je veliki val iseljavanja muslimana. Ostala naselja izgubljena istog datuma: Banja Luka.", "9d6a9e57"]},
"OLAYLAR_EK5:1881-12-20:0":{"b": ["Muharemska uredba i osnivanje Uprave Dujun-i Umumijje", "02b7cc03"], "d": ["Pregovori vođeni s predstavnicima država povjerilaca nakon bankrota 1875. okončani su uredbom od 28. muharema 1299 (20. decembra 1881): glavnica duga smanjena je za više od polovine, a zauzvrat su najplodnije stavke prihoda, kao što su takse na so, duhan, svilu, taksene marke i ribu, prenesene na Upravu Dujun-i Umumijje, kojom su neposredno upravljali povjerioci. Ta uprava, koja je zapošljavala hiljade činovnika, pretvorila se u zasebnu finansijsku organizaciju unutar države. Smatra se datumom faktičkog kraja osmanske finansijske nezavisnosti.", "3cb26eeb"]},
"OLAYLAR_EK5:1884-02-01:0":{"b": ["Suakin — jedina luka koja nije pala u Mahdijeve ruke", "5a37b198"], "d": ["Dok su od februara 1884. sve istočnosudanske oblasti osim Suakina prelazile pod vlast Muhammeda Ahmeda el-Mahdija, luka se održala zahvaljujući vojnoj zaštiti britanskih snaga od tri bataljona pod zapovjedništvom generala Grahama. Bio je to početak razdoblja u kojem su se faktičko i pravno stanje razdvojili: iako je obala faktički bila pod britanskim vojnim nadzorom, njena upravna veza 1885. oduzeta je Egiptu i neposredno vezana za Jemenski vilajet, odnosno za Visoku portu — taj poredak trajao je dok 1888. nije okončan francuskom okupacijom Zejle.", "343c16cf"]},
"OLAYLAR_EK5:1884-05-08:0":{"b": ["Ubistvo Midhat-paše u tamnici u Taifu", "f4562261"], "d": ["Midhat-paša, arhitekt Kanun-i Esasija i simbolično ime Prve ustavne monarhije, na Jildiskom sudu proglašen je krivim u vezi sa smrću Abdul-Aziza, smrtna kazna mu je preinačena u progonstvo i poslan je u Taif. Prema zapisu TDV-a, u noći 7–8. maja 1884. zadavljen je u ćeliji, a kao zvanični uzrok navedena je bolest 'šir-pendže' (karbunkul). Njegova smrt postala je simbol likvidacije ustavne opozicije u doba Abdul-Hamida II.", "06cc8d1c"]},
"OLAYLAR_EK5:1888-09-24:0":{"b": ["Dodjela koncesije za željeznicu Hajdarpaša–Ankara Nijemcima", "5705b163"], "d": ["Sultanovom iradom koncesija za izgradnju i eksploataciju linije Hajdarpaša–Ankara dodijeljena je bankaru Alfredu von Kaulli, predstavniku Deutsche Banka, i osnovano je Anadolsko željezničko društvo. Ta koncesija bila je prekretnica koja je u osmanskoj saobraćajnoj i vanjskoj politici slomila englesko-francuski monopol i učvrstila njemački uticaj. Uz koncesiju za bagdadsku liniju, koja će istom društvu biti data jedanaest godina kasnije, rodit će se san 'Berlin–Bagdad', koji će postati jedna od glavnih osa suparništva velikih sila prije Prvog svjetskog rata.", "9974f219"]},
"OLAYLAR_EK5:1889-06-02:0":{"b": ["Osnivanje Društva Ittihad-i Osmani u Istanbulu", "b7187939"], "d": ["Četvorica učenika Vojne medicinske škole osnovala su Društvo Ittihad-i Osmani kao tajnu organizaciju protiv apsolutističke uprave; ta struktura ubrzo se pretvorila u Komitet jedinstva i napretka, koji će pod svojim krovom okupiti sve opozicione elemente mladoturskog pokreta. Organizacija zasnovana na ćelijama spojila se s izgnanicima u Evropi i oficirima u Solunu. Kadar koji će 1908. natjerati na proglašenje Druge ustavne monarhije i od 1913. sam upravljati državom izrastao je iz te male studentske ćelije.", "f2417434"]},
"OLAYLAR_EK5:1896-08-26:0":{"b": ["Prepad na Osmansku banku: akcija dašnačkih aktivista u Galati", "08b3095f"], "d": ["Naoružana grupa armenske organizacije Dašnakcutjun, s ciljem da privuče pažnju Evrope na armensko pitanje, upala je u sjedište Osmanske banke u Galati, uzela taoce i prijetila da će zgradu dići u zrak. Kriza je okončana, uz posredovanje ambasadora, u zamjenu za to da akteri brodom napuste zemlju. Krvavi događaji u Istanbulu u danima nakon prepada bili su presudni za to da se armensko pitanje pretvori u polugu međunarodne intervencije.", "8fb5eb98"]},
"OLAYLAR_EK5:1897-04-17:0":{"b": ["Početak osmansko-grčkog rata 1897: tesalijsko bojište", "33e490ab"], "d": ["Zbog grčkog slanja flote i vojske na Kretu i napada četa na rumelijskoj granici, Osmanska država objavila je rat. Osmanska vojska, koju je obučavala njemačka reformska misija, brzo je napredovala u Tesaliji i za mjesec dana zauzela Larisu, Farsalu i Domokos; grčka vojska se raspala. Posredovanjem velikih sila osvojene zemlje vraćene su, ali je rat ostao jedina odlučna vojna pobjeda doba Abdul-Hamida II i nije mogao spriječiti faktički gubitak Krete.", "405fd8a7"]},
"OLAYLAR_EK5:1899-11-27:0":{"b": ["Dodjela koncesije za liniju Konja–Bagdad Nijemcima", "fd8b6cbd"], "d": ["Nakon posjeta cara Wilhelma II Istanbulu i Damasku 1898, Anadolskom željezničkom društvu dodijeljena je prethodna koncesija za liniju koja će se protezati od Konje do Bagdada i Basre. Projekt Bagdadske željeznice za Osmanlije je značio jačanje centralnog nadzora nad arapskim vilajetima, a za Njemačku dolazak do Perzijskog zaljeva. Taj projekt, kojem su se Engleska i Rusija žestoko protivile, postao je jedan od najspornijih predmeta imperijalističkog suparništva koje je vodilo u Prvi svjetski rat.", "0de9d1cf"]},
"OLAYLAR_EK5:1900-09-01:0":{"b": ["Početak gradnje Hidžaške željeznice u Damasku", "62f58f68"], "d": ["Linija koju je Abdul-Hamid II naredio iradom od 2. maja 1900. počela se graditi zvaničnom svečanošću u Damasku 1. septembra 1900. Projekt, izveden u potpunosti prilozima prikupljenim iz islamskog svijeta i radom osmanskih inžinjera i vojnika, skratio je put hadžija od Damaska do Medine s četrdeset dana na pet. Bio je i prestižno djelo koje je učvršćivalo duhovni autoritet hilafeta i strateško ulaganje koje je jačalo vojni nadzor nad Hidžazom.", "5dedd229"]},
"OLAYLAR_EK5:1903-10-02:0":{"b": ["Mürzsteški program: međunarodni nadzor nad reformama u Makedoniji", "4c7464da"], "d": ["Nakon Ilindenskog ustanka ruski i austrijski car sastali su se u Mürzstegu i pripremili novi reformski paket za Makedoniju. Program je predviđao da uz osmanskog generalnog inspektora budu postavljena dva strana civilna agenta, da evropski oficiri reorganizuju žandarmeriju i da se upravne granice promijene po nacionalnom načelu. Iako se Visoka porta opirala tvrdeći da su povrijeđena njena suverena prava, pred zajedničkim pritiskom morala je pristati; program je postao jedan od glavnih faktora koji su među mladim oficirima ubrzali itihadističko organiziranje.", "b56ab15c"]},
"OLAYLAR_EK5:1904-08-29:0":{"b": ["Smrt Murata V", "396659a7"], "d": ["Murat V, koji je 1876. bio na prijestolju oko tri mjeseca i bio svrgnut, nakon pokušaja da se vrati na prijestolje dvadeset osam godina živio je zatočen pod strogim nadzorom i umro od šećerne bolesti. Sahranjen je u turbetu Džedid Havatin kod Nove džamije, uz svoju majku. Ušao je u historiju kao osmanski sultan koji je najkraće bio na prijestolju.", "8558c1b8"]},
"OLAYLAR_EK5:1905-04-01:0":{"b": ["Gubitak Sane u korist imama Jahje", "e7f876cb"], "d": ["Ustanak koji je 1904. pokrenuo zejdijski imam Jahja Hamiduddin završio je u aprilu 1905. padom Sane nakon opsade; grad je izašao iz osmanske uprave, a tokom opsade zavladali su glad i epidemije. Brdoviti reljef Jemena, dužina linija opskrbe i lokalni legitimitet zejdijskog imamata činili su ovdašnju osmansku vlast od samog nastanka krhkom. Grad će pet mjeseci kasnije uz teške gubitke biti vraćen, ali se jemensko pitanje neće zatvoriti sve do 1918.", "702b0ff5"]},
"OLAYLAR_EK5:1905-07-21:0":{"b": ["Jildiski atentat: bombaški napad na Abdul-Hamida II", "1ee2e1a6"], "d": ["Organizacija Dašnakcutjun izvela je atentat aktiviranjem fijakera s tempiranom bombom kod kola sultana koji je izlazio sa svečanog odlaska na džumu; to što je Abdul-Hamid zbog razgovora sa šejhul-islamom zakasnio nekoliko minuta spasilo mu je život. U eksploziji je poginulo dvadeset šest ljudi, a više od pedeset ih je ranjeno. Događaj je još pooštrio sultanovu opsesiju sigurnošću i apsolutističku upravu zasnovanu na mreži doušnika; bio je i tema pjesme Tevfika Fikreta 'Trenutak zakašnjenja'.", "d4f10280"]},
"OLAYLAR_EK5:1905-09-01:0":{"b": ["Povratak Sane: gušenje ustanka imama Jahje", "dec3b8f9"], "d": ["Ustanak započet 1904. pod vodstvom zejdijskog imama Jahje završio je u aprilu 1905. padom Sane, a u gradu su zavladali glad i epidemije. Pojačane vojske pod zapovjedništvom Ali Riza-paše i Ahmed Fejzi-paše, akcijom vođenom od 15. jula do 1. septembra 1905, koju su podržale i snage u Taizu, uz teške gubitke povratile su grad, a ustanak je ugušen. Jemenski pohod donio je osmanskoj vojsci desetine hiljada gubitaka i golemo finansijsko breme; među oficirima u Rumeliji strah od 'progonstva u Jemen' bio je na čelu pritužbi koje su hranile itihadističko organiziranje.", "667bb98c"]},
"OLAYLAR_EK5:1908-12-17:0":{"b": ["Sastanak prvog Medžlis-i Mebusana Druge ustavne monarhije", "e7fd2716"], "d": ["Skupština, nastala na dvostepenim izborima održanim nakon tridesetogodišnje pauze, otvorena je 17. decembra 1908. sultanovim govorom, a za predsjednika je izabran vođa mladoturskog pokreta Ahmed Riza-beg. Skupština sastavljena od turskih, arapskih, albanskih, grčkih, armenskih i jevrejskih poslanika bila je posljednji veliki pokušaj ideala osmanizma. Međutim, nezavisnost Bugarske, aneksija Bosne i objava Krete o pripajanju Grčkoj zasjenile su taj optimizam i prije nego što je skupština otvorena.", "b408f232"]},
"OLAYLAR_EK5:1909-04-27:0":{"b": ["Hareket ordusu i svrgavanje Abdul-Hamida II: stupanje na prijestolje Mehmeda V Rešada", "6a65a704"], "d": ["Hareket ordusu (Akciona armija), koja je krenula iz Soluna zbog incidenta od 31. marta, u noći 22–23. aprila s četiri strane ušla je u Istanbul, a 24. aprila predao se saraj Jildiz. Medžlis-i Umumi-i Milli 27. aprila odlučio je da svrgne Abdul-Hamida II; sultan je poslan u Solun, a na prijestolje je doveden njegov brat Mehmed V Rešad. Tako je okončana tridesettrogodišnja lična uprava, ali je njeno mjesto zauzelo novo doba u kojem je sultan postao simbol, a Komitet jedinstva i napretka vladao uz podršku vojske.", "496ff2f2"]},
"OLAYLAR_EK5:1910-04-01:0":{"b": ["Albanski ustanak: oružani otpor na Kosovu i u Skadru", "93ed30c6"], "d": ["Centralistička poreska politika itihadističke vlade, kampanja oduzimanja oružja i rasprava o latinskom pismu digle su na ustanak albanska plemena, koja su dotad smatrana među državi najodanijim elementima. Iako je vojska pod zapovjedništvom Mahmud Ševket-paše oštro ugušila ustanak, nemir se ponovo rasplamsao 1911. i 1912. Ti ustanci iscrpili su osmansku vojsku uoči Balkanskog rata i ubrzali rođenje albanskog nacionalnog pokreta.", "18d0ffb5"]},
"OLAYLAR_EK5:1912-10-18:0":{"b": ["Ušijski mir: prepuštanje Tripolija i Bengazija Italiji", "4ffa1fd2"], "d": ["Visoka porta, ne mogavši se pred ratnim pripremama balkanskih država odvažiti na sukob na dva fronta, potpisala je u švicarskom gradiću Ouchyju tajni mir s Italijom i napustila Tripolitaniju i Bengazi. Tako je Osmanska država izgubila posljednji posjed u Africi; zauzvrat je obećan povrat Rodosa i Dvanaest otoka koje je Italija okupirala, ali to obećanje nikada nije ispunjeno. Kad je ugovor potpisan, Balkanski rat već je bio počeo. Ovim događajem pod italijansku upravu prešli su Murzuk (Fezan), Gat, Sebha, Ubari, Traghan, Zawila i El-Katrun (Fezan, sandžak Tripoliskog vilajeta).", "5896634d"]},
"OLAYLAR_EK5:1912-10-21:0":{"b": ["Grčka okupacija Lemnosa", "9555af1d"], "d": ["U Prvom balkanskom ratu grčka flota okupirala je Lemnos; luka Mudros na otoku postala je baza za blokadu Dardanela. Otok je u Lausannei (24. jula 1923) ostavljen Grčkoj.", "61677826"]},
"OLAYLAR_EK5:1912-10-30:0":{"b": ["Grčka okupacija Tasosa", "6c03c7f0"], "d": ["U Prvom balkanskom ratu Grčka je okupirala Tasos i Samotraku.", "b0695c7a"]},
"OLAYLAR_EK5:1912-11-01:0":{"b": ["Grčka okupacija Samotrake", "911e82a3"], "d": ["U Prvom balkanskom ratu Grčka je okupirala Samotraku.", "0e592cf7"]},
"OLAYLAR_EK5:1912-11-21:0":{"b": ["Grčka okupacija Lezbosa (Mitilene)", "6b2b07ba"], "d": ["Grčka flota iskrcala se na Lezbos; otok su krajem Prvog balkanskog rata zauzele grčka vojska i flota. Londonska konferencija (maj 1913) potvrdila je to stanje.", "a07eeadb"]},
"OLAYLAR_EK5:1912-11-25:0":{"b": ["Grčko iskrcavanje na Hios", "901c6539"], "d": ["Na Hios, bombardiran 7. aprila 1912. u Prvom balkanskom ratu, Grci su izvršili iskrcavanje; osmanska posada predala se 3. januara 1913. Otok je Lozanskim ugovorom (24. jula 1923) ostavljen Grčkoj.", "d9fc9f4b"]},
"OLAYLAR_EK5:1913-06-11:0":{"b": ["Ubistvo velikog vezira Mahmud Ševket-paše u atentatu u Istanbulu", "68e60e63"], "d": ["Mahmud Ševket-paša, postavljen za velikog vezira nakon upada na Visoku portu, na putu u Ministarstvo rata ubijen je pucnjevima na kola kod Čaršikapija. Komitet jedinstva i napretka, svalivši atentat na opoziciju, pokrenuo je širok val hapšenja i pogubljenja; Stranka slobode i sporazuma faktički je likvidirana. Ovim događajem konačno je uspostavljena jednopartijska diktatura itihadista zasnovana na trojici Enver-Talat-Džemal.", "203085f0"]},
"OLAYLAR_EK5:1913-06-29:0":{"b": ["Početak Drugog balkanskog rata: saveznička svađa oko podjele", "48d088a2"], "d": ["Balkanski saveznici, koji nisu mogli podijeliti zemlje oduzete Osmanlijama Londonskim ugovorom, sukobili su se među sobom; napadom Bugarske na srpske i grčke položaje počeo je drugi rat. Kad su i Rumunija i Crna Gora stupile u rat protiv Bugarske, bugarska vojska se urušila. Osmanska država, iskoristivši tu priliku, prešla je liniju Midija–Enez povučenu Londonskim ugovorom i povratila Istočnu Trakiju zajedno s Edirnama.", "33183400"]},
"OLAYLAR_EK5:1913-09-29:0":{"b": ["Istanbulski mir: mir s Bugarskom i potvrda Edirna", "c8c18b2d"], "d": ["Ugovor potpisan između Osmanske države i Bugarske nakon Drugog balkanskog rata, prihvatajući rijeku Maricu kao granicu, pravno je potvrdio da Edirne, Kirklareli, Didimotihon i Istočna Trakija ostaju Osmanlijama. Aleksandrupolis (Dedeagač) ostavljen je Bugarskoj (a Kavala je nakon bugarske okupacije u jesen 1912. u julu 1913. prešla Grčkoj i potvrđena kao grčka Bukureštanskim mirom od 10. augusta 1913), te su uređeni uzajamna razmjena stanovništva dviju zemalja i prava muslimana u Bugarskoj. Jedini dio teritorija koji se mogao povratiti iz balkanske katastrofe jamči upravo ovaj tekst. Ostala mjesta pripojena istog datuma: Komotini (Gümüldžina).", "1fe8a2f6"]},
"OLAYLAR_EK5:1913-11-01:0":{"b": ["Povratak Tenedosa i Imbrosa — Atinski mir", "ec084d09"], "d": ["Od sjevernoegejskih otoka koje je Grčka okupirala u Balkanskom ratu, Tenedos i Imbros, koji drže ulaz u moreuz, u pregovorima o Atinskom miru smatrani su neophodnima za odbranu Čanakkalea i vraćeni su Osmanlijama. Ostali otoci ostali su Grčkoj. Ta dva otoka postala su posljednje zemlje koje je Carstvo držalo u Egeju i u Lausannei su također ostavljene Turskoj.", "bc1961ea"]},
"OLAYLAR_EK5:1913-11-14:0":{"b": ["Atinski mir: mir s Grčkom i prijenos Soluna i Janjine", "8e94def7"], "d": ["Ugovor potpisan između Osmanske države i Grčke zvanično je priznao prelazak Soluna, Janjine i Južne Makedonije, izgubljenih u Balkanskom ratu, Grčkoj te su napuštena osmanska prava na Kreti. Detaljno su uređena vjerska i imovinska prava muslimana koji su ostali u Grčkoj, status vakufa i imenovanje muftija. Status egejskih otoka ostao je neriješen i ostao trajan izvor napetosti između dviju država.", "a5ae7115"]},
"OLAYLAR_EK5:1914-08-02:0":{"b": ["Potpisivanje tajnog osmansko-njemačkog ugovora o savezu u Istanbulu", "0472efb3"], "d": ["Čim je u Evropi izbio rat, u konaku velikog vezira Said Halim-paše potpisan je tajni ugovor o savezu između Osmanske države i Njemačke; tekst je predviđao da, ako Rusija stupi u rat protiv Njemačke, i Osmanlije stanu na stranu Njemačke. Ugovor je skriven čak i od kabineta, znale su ga samo četiri osobe. Tri mjeseca kasnije prepadom na Crnom moru Osmanska država faktički će biti uvučena u rat, a sudbina carstva bit će vezana za ovaj dokument.", "063ef809"]},
"OLAYLAR_EK5:1914-09-09:0":{"b": ["Jednostrano ukidanje kapitulacija", "ec773d18"], "d": ["Osmanska vlada, u trenutku kad je Evropa bila zauzeta ratom, objavila je da od 1. oktobra 1914. jednostrano ukida kapitulacije, koje su strancima davale sudske, finansijske i carinske povlastice. Okončanje tog četiri stoljeća starog povlasničkog poretka u zemlji je dočekano s velikim zanosom nezavisnosti, a u Istanbulu su održane proslave. Sve države, uključujući saveznicu Njemačku, protestirale su protiv odluke; kapitulacije će konačno otići u historiju tek 1923. u Lausannei.", "b30c11aa"]},
"OLAYLAR_EK5:1914-10-29:0":{"b": ["Prepad na Crnom moru: osmanska flota bombardira ruske luke", "8ad4ef61"], "d": ["Goeben i Breslau (Yavuz i Midilli), koji su pobjegli iz Njemačke i kao 'kupljeni' pridruženi osmanskoj floti, isplovili su pod zapovjedništvom admirala Souchona na Crno more, topovima tukli ruske luke i potopili brodove. Ta naredba, koju je Enver-paša dao krijući od kabineta, faktički je okončala neutralnost. Za sedmicu dana Rusija, Engleska i Francuska objavile su rat, a Osmanska država nepovratno je ušla u Prvi svjetski rat.", "bdd1c93a"]},
"OLAYLAR_EK5:1914-11-06:0":{"b": ["Britansko-indijske snage zauzimaju Fao — otvaranje iračkog fronta", "08663813"], "d": ["Ujutro, dan nakon što su države Antante objavile rat Osmanskoj državi, britansko-indijska brigada koja je čekala u Bahreinu iskrcala se u Fao na ušću Šat al-Araba. Mala osmanska jedinica u ruševnoj tvrđavi Fao povukla se pod vatrom ratnih brodova, a stanica indijske telegrafske linije pala je u britanske ruke. Tako je otvoren irački front.", "7da97cb0"]},
"OLAYLAR_EK5:1914-11-14:0":{"b": ["Proglašenje Velikog džihada: čitanje fetve o džihadu u Fatihovoj džamiji", "2a6174e8"], "d": ["Pet fetvi šejhul-islama Urguplu Hajri-efendije pročitano je u Fatihovoj džamiji u ime halife-sultana, i svi muslimani pozvani su na džihad protiv sila Antante. Taj potez, na koji je Njemačka polagala velike nade, imao je cilj podići muslimane u britanskim i francuskim kolonijama. Očekivani opći ustanak nije se dogodio; naprotiv, dvije godine kasnije ustanak mekanskog emira šerifa Huseina uz britansku podršku gorko je pokazao granice političkog uticaja hilafeta.", "e5a86763"]},
"OLAYLAR_EK5:1914-12-09:0":{"b": ["Predaja Kurne Britancima", "621d36b0"], "d": ["Snage basranskog valije Subhi-bega, koji se nakon pada Basre povukao u Kurnu na sastavu Tigrisa i Eufrata, nakon borbi 4–8. decembra predale su se ujutro 9. decembra 1914.", "ff45626a"]},
"OLAYLAR_EK5:1914-12-22:0":{"b": ["Sarikamiška operacija: katastrofa na kavkaskom frontu", "5cbde7f0"], "d": ["Enver-paša, s ciljem da povrati Kars, Ardahan i Batum, izgubljene 1878, i digne Turke na Kavkazu, gurnuo je Treću armiju u manevar opkoljavanja ruskih snaga zimi preko planina Allahuekber. Zbog nedovoljne zimske opreme, iscrpljene opskrbe i mećave na minus trideset stepeni armija se istopila i prije nego što je stupila u bitku; desetine hiljada vojnika smrzle su se na smrt. Operacija je postala jedna od najtežih osmanskih katastrofa u ratu i ostavila istočni front dvije godine nezaštićenim.", "f5289317"]},
"OLAYLAR_EK5:1915-01-14:0":{"b": ["Prvi pohod na Kanal: napad na Suez preko Sinajske pustinje", "02dd72f5"], "d": ["Zapovjednik Četvrte armije Džemal-paša, s ciljem da oslobodi Egipat od britanske okupacije i zatvori Sueski kanal za plovidbu, organizirao je napad preko Sinajske pustinje. Iako su osmanske jedinice stigle do istočne obale kanala, a dio ih uspio prijeći na drugu stranu, zbog britanske nadmoći i izostanka očekivanog ustanka egipatskog naroda povukle su se. Operacija nije postigla cilj, ali je, prisilivši Englesku da u Egiptu drži velike snage, ostvarila posredan strateški učinak.", "d9d0152c"]},
"OLAYLAR_EK5:1915-05-27:0":{"b": ["Donošenje Zakona o upućivanju i naseljavanju (deportaciji)", "2f2bc22c"], "d": ["Nakon ustanka u Vanu i ruskog napredovanja vlada je donijela privremeni zakon koji je dopuštao da vojni zapovjednici premjeste u druge oblasti stanovništvo za koje se smatralo da narušava sigurnost u pozadini fronta, a sultan ga je potvrdio 27. maja 1915. Kao rezultat primjene veći dio armenskog stanovništva istočnih i južnih anadolskih vilajeta upućen je prema Siriji i Mosulu; tokom transporta zbog bolesti, gladi i napada došlo je do vrlo velikih ljudskih gubitaka. Ta odluka ostala je najteže i do danas najspornije pitanje posljednjih godina Osmanlija.", "e8af8dee"]},
"OLAYLAR_EK5:1916-08-07:0":{"b": ["Osmanske jedinice povratile Muš od ruske okupacije", "fb1be113"], "d": ["Šest mjeseci nakon prve ruske okupacije Muša osmanski 16. korpus ušao je u gradić u protunapadu na pravcu Bitlis–Muš.", "c235eed5"]},
"OLAYLAR_EK5:1916-08-25:0":{"b": ["Muš ponovo prešao u ruske ruke", "43ad8a03"], "d": ["Pred ruskim protunapadom osmanski odred ispraznio je Muš; gradić je između 22. i 25. augusta 1916. ponovo pao pod rusku okupaciju i ostao u njihovim rukama do proljeća 1917.", "db39e054"]},
"OLAYLAR_EK5:1917-05-01:0":{"b": ["Muš konačno oslobođen od ruske okupacije", "f0e89703"], "d": ["Muš, koji je u Prvom svjetskom ratu pao pod rusku okupaciju, osmanske su snage 1. maja 1917. konačno povratile.", "f2406306"]},
"OLAYLAR_EK5:1918-02-10:0":{"b": ["Smrt Abdul-Hamida II u saraju Bejlerbeji", "c9662582"], "d": ["Abdul-Hamid II, svrgnut 1909, najprije poslan u Solun, a nakon gubitka grada u Balkanskom ratu doveden u Istanbul i držan pod nadzorom u saraju Bejlerbeji, umro je. Tokom trideset tri godine vladavine nastojao je držati državu daleko od ratova i dobiti na vremenu, ali se pamtio i po apsolutističkoj upravi. Njegov pogreb uz veliko mnoštvo obavljen je u turbetu Mahmuda I na Divanyoluu; njegova smrt poklopila se s ratnom godinom u kojoj je poredak koji je uspostavio već odavno bio likvidiran.", "241489b4"]},
"OLAYLAR_EK5:1918-03-03:0":{"b": ["Brest-litovski mir: povratak Karsa, Ardahana i Batuma", "da82636f"], "d": ["Ugovor potpisan između Rusije, koja se nakon boljševičke revolucije povukla iz rata, i Centralnih sila zatvorio je istočni front i Osmanskoj državi vratio Kars, Ardahan i Batum (Elvije-i Selase), izgubljene Berlinskim ugovorom 1878. Bio je to jedini teritorijalni dobitak u osmanskoj historiji stečen nakon četrdeset godina pauze. Međutim, nakon Mudroskog primirja oblast će ponovo biti izgubljena, a konačno rješenje doći će Karskim ugovorom 1921.", "f6f15123"]},
"OLAYLAR_EK5:1918-03-28:0":{"b": ["Osmanske jedinice ušle u Artvin", "ca7d1778"], "d": ["Osmanske jedinice, koje su 25. marta prešle granicu iz 1914, krenule su na Elvije-i Selase, koje je Brest-Litovsk vratio na granicu prije 1878, i ušle u Artvin 28. marta 1918. Artvin je kao dio Batumskog sandžaka 1878. ostavljen Rusiji; članak TDV-a o Artvinu povratak bilježi samo kao 'mart 1918', a dan daje Mustafa Sarı.", "7c7f5573"]},
"OLAYLAR_EK5:1918-04-03:0":{"b": ["Ardahan prešao u ruke turske vojske", "7fd9e3db"], "d": ["U akciji za Elvije-i Selase osmanska vojska nakon Artvina zauzela je 3. aprila 1918. Ardahan; Ardahan je pao u ratu 1877–78, godine 1877, i 1878. ostavljen Rusiji. Kars će biti zauzet mjesec dana kasnije, 25. aprila.", "76d4ba84"]},
"OLAYLAR_EK5:1918-04-14:0":{"b": ["Povratak Batuma", "d37a1a0d"], "d": ["Osmanska vojska, koja je nakon povlačenja Rusije iz rata Brest-litovskim mirom napredovala na istok, četrdeset godina kasnije povratila je luku Batum, izgubljenu 1878. Ta luka na istočnom kraju Crnog mora bila je morski izlaz bakinske nafte. Dobitak je trajao samo sedam mjeseci; nakon Mudroskog primirja oblast će biti ispražnjena.", "877ec7ee"]},
"OLAYLAR_EK5:1918-04-25:0":{"b": ["Elvije-i Selase: Kars ulazi pod osmansku upravu", "02cbf0b3"], "d": ["U Brest-Litovsku je dogovoren povrat triju sandžaka izgubljenih Berlinskim ugovorom 1878. — Karsa, Ardahana i Batuma; osmanska vojska ušla je u Ardahan 3. aprila, u Batum 14. aprila, a u Kars 25. aprila 1918. i uprava je faktički uspostavljena. Te zemlje, nazivane 'Elvije-i Selase' (Tri sandžaka), smatrane su nadoknadom gubitka koji je trajao od rata 1877–78. Nakon primirja ponovo će biti izgubljene, a Turskoj će konačno pripasti tek Karskim ugovorom 1921.", "83a69417"]},
"OLAYLAR_EK5:1918-05-20:0":{"b": ["Zauzet Igdir — napredovanje dolinom Araksa", "87ebf4d3"], "d": ["U okviru ofanzive započete u februaru 1918. turske jedinice porazile su armenske jedinice kod Sardarapata sjeverno od Araksa i 20. maja 1918. zauzele Igdir. Igdir nije spadao u Elvije-i Selase, nego je bio kadiluk Surmalu Erivanske gubernije; nakon otprilike 180 godina u toj oblasti uspostavljena je prva osmanska uprava.", "f50c4b56"]},
"OLAYLAR_EK5:1918-07-03:0":{"b": ["Smrt Mehmeda V Rešada i stupanje na prijestolje Mehmeda VI Vahdeddina", "d302ba07"], "d": ["Mehmed V Rešad, čija je devetogodišnja vladavina protekla u tripoliskom, balkanskom i svjetskom ratu, umro je u najkritičnijem periodu rata, a na prijestolje je pod imenom Mehmed VI stupio njegov brat Vahdeddin. Novi sultan pokušao se osloboditi tutorstva itihadističkog kadra; četiri mjeseca kasnije, kad je potpisano primirje, morat će voditi likvidaciju carstva. Bio je trideset šesti i posljednji sultan dinastije Osmanlija.", "2d9306b3"]},
"OLAYLAR_EK5:1918-11-13:0":{"b": ["Dolazak flote Antante pred Istanbul i faktička okupacija grada", "d10cb14d"], "d": ["Nakon Mudroskog primirja saveznička flota od više od šezdeset jedinica, sastavljena od britanskih, francuskih, italijanskih i grčkih brodova, usidrila se pred Dolmabahčeom, a Istanbul je faktički okupiran. Nakon četiri stotine šezdeset pet godina prijestolnica je prvi put prešla pod nadzor stranih vojnika. Riječi 'Otići će onako kako su i došli', za koje se prenosi da ih je istog dana izgovorio Mustafa Kemal-paša, sišavši na Hajdarpaši i vidjevši prizor, postat će jedna od simboličnih rečenica Narodne borbe.", "30db4974"]},
"OLAYLAR_EK5:1918-12-04:0":{"b": ["Povlačenje u oblasti Araksa: Igdir ispražnjen", "57572ab4"], "d": ["U skladu s odredbom Mudroskog primirja o povlačenju iza granice iz 1914, Jakup Ševki-paša naredbom od 21. novembra naredio je da se jedinice izvan brest-litovske granice povuku do 4. decembra; Igdir i okolina tada su potpuno ispražnjeni. Zatim su Armenci krajem decembra 1918. srušili Araks-tursku vladu.", "68b8ff9a"]},
"OLAYLAR_EK5:1918-12-17:0":{"b": ["Englezi se smjestili u Artvinu", "e2cb3153"], "d": ["Budući da je Mudroskim primirjem od 30. oktobra 1918. bilo uslovljeno povlačenje osmanske vojske iza granice iz 1914, Artvin je ispražnjen i 17. decembra 1918. okupirali su ga Britanci. Prema članku TDV-a o Artvinu britanska okupacija trajala je do aprila 1920.", "5b9a237d"]},
"OLAYLAR_EK5:1918-12-24:0":{"b": ["Britanska uprava u Batumu nakon Mudrosa", "9dd768fc"], "d": ["Prema Mudroskom primirju od 30. oktobra 1918. Osmanska država morala se povući iz Batuma; grad su 24. decembra 1918. zaposjele britanske jedinice. Batum, koji je u aprilu 1918. postao sjedište samostalnog sandžaka, od tada do jula 1920. ostao je pod britanskim nadzorom.", "d172259b"]},
"OLAYLAR_EK5:1919-04-20:0":{"b": ["Ardahan prešao pod gruzijsku vlast", "97cf47f6"], "d": ["Ardahan, ispražnjen nakon Mudrosa, gruzijske snage okupirale su 20. aprila 1919, u danima kada su Englezi raspustili Vladu Jugozapadnog Kavkaza. Gruzijska vlast trajat će do 23. februara 1921.", "6027a645"]},
"OLAYLAR_EK5:1919-04-30:0":{"b": ["Preston predao upravu Karsa armenskom guverneru", "efa81cb0"], "d": ["Britanski zapovjednik Preston, koji je 12–13. aprila 1919. raspustio Vladu Jugozapadnog Kavkaza, 30. aprila 1919. ukinuo je privremenu vijećnu vladu i upravu grada predao Armencu Karganovu, postavljenom za guvernera Karsa; u Karsu je počelo razdoblje armenske uprave, koje je trajalo do pobjede Kazima Karabekira 30. oktobra 1920.", "ffa3989a"]},
"OLAYLAR_EK5:1919-07-23:0":{"b": ["Erzurumski kongres: odluka istočnih vilajeta o nacionalnom otporu", "41ef0457"], "d": ["Kongres koji je sazvalo Društvo za odbranu prava Istočne Anadolije, odgođen zbog britanskog pritiska, otvoren je s pedeset šest delegata, a za predsjednika je izabran Mustafa Kemal-paša, koji je dao ostavku na vojnu službu. Kongres je proglasio da je domovina unutar nacionalnih granica cjelina, da se mandat i protektorat ne mogu prihvatiti te da će narod, u slučaju raspada vlade, sam uzeti sudbinu u svoje ruke. Te odluke će šest mjeseci kasnije činiti jezgro teksta Nacionalnog pakta.", "925ca450"]},
"OLAYLAR_EK5:1919-09-04:0":{"b": ["Sivaski kongres: ujedinjenje nacionalnog otpora pod jednim krovom", "0e9ad36b"], "d": ["Kongres, koji je počeo s radom 4. septembra 1919. u Sivaskoj gimnaziji (Sivas Sultanisi), ujedinio je društva za odbranu prava sa svih strana zemlje pod imenom Društvo za odbranu prava Anadolije i Rumelije i izabrao Predstavnički odbor. Prijedlog o američkom mandatu odbačen je nakon dugih rasprava. Deklaracijom objavljenom 11. septembra Narodna borba postala je legitimni politički pokret s jednim središtem i počela je otvorena borba za moć s istanbulskom vladom.", "9e4ba0a0"]},
"OLAYLAR_EK5:1919-10-22:0":{"b": ["Amasijski protokol: razgovori istanbulske vlade s Predstavničkim odborom", "40e6a6ab"], "d": ["Nakon pada Damat Ferida i formiranja vlade Ali Riza-paše, ministar mornarice Salih-paša poslan je u Amasiju na razgovore s Predstavničkim odborom. Postignutim protokolima istanbulska vlada faktički je priznala postojanje anadolskog pokreta; prihvaćeni su sazivanje Medžlis-i Mebusana, slobodno održavanje izbora i očuvanje nacionalnih granica. To je prvi zvanični politički dobitak Narodne borbe nasuprot Istanbulu.", "721d202a"]},
"OLAYLAR_EK5:1920-01-28:0":{"b": ["Prihvatanje Nacionalnog pakta (Misak-i Milli) u posljednjoj osmanskoj skupštini", "6322865e"], "d": ["Tekst Nacionalne zakletve (Ahd-i Milli), koji je u posljednjem osmanskom Medžlis-i Mebusanu potpisao 121 poslanik, uslovljavao je nedjeljivu cjelovitost zemalja unutar mudroske linije u kojima živi muslimansko-turska većina, plebiscit u arapskim vilajetima i Zapadnoj Trakiji, ukidanje kapitulacija i potpunu političko-finansijsku nezavisnost. Tekst je 17. februara 1920. jednoglasno usvojen i objavljen svijetu. Ta deklaracija bila je i politički program Narodne borbe i karta granica koje će se braniti u Lausannei; postala je neposredan uzrok zvanične okupacije Istanbula od sila Antante 16. marta.", "576d2af5"]},
"OLAYLAR_EK5:1920-04-01:0":{"b": ["Pri povlačenju Britanaca Artvin ostao Gruziji", "6d086b06"], "d": ["Prema članku TDV-a o Artvinu britanska okupacija trajala je do aprila 1920; povlačeći se, Britanci su grad ostavili Gruziji. Artvin je u gruzijskim rukama ostao do ultimatuma TBMM od 23. februara 1921.", "20ff63b0"]},
"OLAYLAR_EK5:1920-07-07:0":{"b": ["Batum predan gruzijskoj upravi", "6523d095"], "d": ["Zvanična primopredaja Batuma od Britanaca Gruzijcima obavljena je 7. jula 1920. (članak TDV-a o Batumu navodi samo 'juli 1920'). Ankarska vlada protestirala je 25. jula, nazivajući predaju 'okupacijom'.", "99c9bfc8"]},
"OLAYLAR_EK5:1920-12-03:0":{"b": ["Ugovor u Gjumriju: prvi međunarodni ugovor vlade TBMM", "9232c690"], "d": ["Kad je vojska istočnog fronta pod zapovjedništvom Kazima Karabekira povratila Sarikamiš i Kars, Armenija je zatražila mir i ugovorom potpisanim u Gjumriju prihvatila da ne priznaje Sèvres i da se odriče teritorijalnih zahtjeva na istoku. Taj prvi ugovor koji je potpisala ankarska vlada postao je prvi međunarodni dokument koji je faktički odbacio Sèvres i otvorio TBMM-u put ka pravnom priznanju. Tako je osigurana istočna granica i postalo je moguće prebaciti snage na zapadni front.", "c41c725d"]},
"OLAYLAR_EK5:1921-01-10:0":{"b": ["Prva bitka kod Inönüa: prva pobjeda regularne vojske", "4add3719"], "d": ["Novoformirana regularna vojska zaustavila je na položajima kod Inönüa grčke snage koje su napredovale iz pravca Burse i primorala ih na povlačenje. Taj uspjeh, vojno ograničenog obima, po političkim posljedicama bio je vrlo velik: ankarska vlada pozvana je na Londonsku konferenciju, otvoren je put Moskovskom ugovoru sa Sovjetskom Rusijom i usvojen je Zakon o ustavnom ustrojstvu (Teškilat-i Esasijje). Tom pobjedom učvrstilo se i povjerenje domaće javnosti u regularnu vojsku.", "13509273"]},
"OLAYLAR_EK5:1921-04-01:0":{"b": ["Druga bitka kod Inönüa: grčki napad slomljen drugi put", "a974521c"], "d": ["Grčka vojska, koja na Londonskoj konferenciji nije postigla rezultat, krenula je u novi napad iz pravaca Burse i Ušaka, ali je opet zaustavljena na grebenima Inönüa i morala se povući. Nakon te pobjede napisan je telegram Mustafa Kemal-paše Ismet-paši: 'Vi ste tamo pobijedili ne samo neprijatelja nego i zlu sudbinu naroda'. Bitka je podigla međunarodni ugled Narodne borbe i ubrzala proces povlačenja Italije iz Anadolije.", "639e964d"]},
"OLAYLAR_EK5:1921-10-20:0":{"b": ["Ankarski sporazum: mir s Francuskom i zatvaranje južnog fronta", "35fc32db"], "d": ["Sporazumom potpisanim u Ankari s Francuskom nakon pobjede na Sakarji okončan je rat na južnom frontu; francuske snage ispraznile su Čukurovu i jugoistok, uključujući Adanu, Antep, Maraš i Urfu, i povukle se na sirijsku granicu. Tako je jedna od država Antante faktički priznala ankarsku vladu i otvorila prvu pukotinu na sevrskom frontu. Oružje preuzeto iz ispražnjenih područja i oslobođene jedinice odigrali su ključnu ulogu u pripremi Velike ofanzive.", "7e088769"]},
"OLAYLAR_EK5:1922-10-11:0":{"b": ["Mudanjsko primirje: prijenos Istanbula i moreuza bez rata", "ac0d9baf"], "d": ["Konferencija sazvana u Mudanji nakon što se turska vojska nakon Velike ofanzive u Čanakkaleu i Izmitu našla licem u lice s britanskim snagama završila je primirjem nakon jedanaestodnevnih teških pregovora. Dogovoreno je da Grčka u roku od petnaest dana isprazni Istočnu Trakiju do Marice i preda je turskoj upravi te da se Istanbul i moreuzi predaju mirovnim ugovorom. Tako je oružana faza Narodne borbe završena diplomatskom pobjedom stečenom bez ijednog ispaljenog metka i otvorena su vrata Lausannee.", "79b94dfb"]},
"OLAYLAR_EK5:1922-11-17:0":{"b": ["Odlazak Mehmeda VI Vahdeddina iz Istanbula i izbor Abdul-Medžid-efendije za halifu", "8ab0e847"], "d": ["Posljednji sultan Mehmed VI Vahdeddin, čiji je položaj nakon ukidanja sultanata postao sporan, u petak ujutro 17. novembra 1922. napustio je Istanbul britanskim oklopnjačom Malaya i otišao na Maltu. TBMM je dva dana kasnije, 19. novembra, za halifu bez političkih ovlaštenja izabrao Abdul-Medžid-efendiju. Tako je faktički okončana šest stotina dvadeset tri godine duga vladavina osmanske dinastije; hilafet će, pak, simbolično trajati još petnaest mjeseci. Vahdeddin, koji je prešao na Maltu, a zatim u Italiju, nastanio se u Villa Nobel u San Remu; njegovi zahtjevi za prijem u neku muslimansku zemlju ostali su bez rezultata i ondje je umro 16. maja 1926, ponavljajući da se nikada nije odrekao prava na sultanat i hilafet.", "86831a04"]},
"OLAYLAR_EK5:1926-05-16:0":{"b": ["Smrt posljednjeg sultana Mehmeda VI Vahdeddina u San Remu", "7149ed0e"], "d": ["Posljednji osmanski sultan Mehmed Vahdeddin, koji se nakon odlaska iz Istanbula nastanio u italijanskom gradu San Remu, umro je 16. maja 1926. ne saznavši da se sastao kongres o hilafetu (13. maja 1926), kojem je poručio da se nikada nije odrekao prava na sultanat i hilafet. Bio je u teškoj novčanoj oskudici; trgovcima San Rema dugovao je 60.000 lira, a povjerioci koji su čuli za njegovu smrt dali su zaplijeniti namještaj njegove kuće.", "0864312a"]},
"OLAYLAR_EK6:1325-01-01:0":{"b": ["Konuralpovo osvajanje oblasti Bolua — Mudurnu, Konurapa i Bolu", "e245cd27"], "d": ["Konuralp, jedan od zapovjednika Orhan Gazija, krenuo je prema brdovitoj oblasti istočno od Sakarje i pripojio Mudurnu, Konurapu i oblast Bolua osmanskoj upravi; gradić u Düzce-ravnici nazvan je po njemu. Tačan datum osvajanja nije poznat; priča se oslanja na predaju Ašik-paša-zadea. Oblast je tada bila krajiško područje koje je prelazilo iz ruke u ruku između Džandarogulla i Bizanta; osvajanje je Osmanlije prvi put približilo zapadnoj obali Crnog mora. Nakon Ankarske bitke oblast će opet prijeći Džandarogullima, ali će u doba Mehmeda II Osvajača biti konačno vraćena.", "d7b58190"]},
"OLAYLAR_EK6:1334-01-01:0":{"b": ["Zauzimanje bizantskih gradića južno od Mramornog mora — Mihaliç, Kirmasti, Gölyazı", "9c61b8d4"], "d": ["Nakon zauzimanja Nikeje i Izmita, gradići koje je Bizant držao zapadno od burske ravnice jedan po jedan ušli su pod osmansku upravu. Gölyazı oko jezera Uluabat te Kirmasti i Mihaliç uz potok Susurluk upotpunili su koridor koji južnu obalu Mramornog mora povezuje sa zemljama Karesija. Ti su se gradići dugo bez opsade predavali zbog presijecanja njihove okoline; tako se bizantsko prisustvo u oblasti stisnulo na Gemlički zaljev.", "bd729343"]},
"OLAYLAR_EK6:1395-01-01:0":{"b": ["Korint prešao Morejskoj despotovini", "392495eb"], "d": ["Korint, koji je od 1358. bio leno firentinske porodice Acciajuoli u sklopu Ahajske kneževine, 1395. prešao je u ruke bizantskog despota Moreje Teodora. Grad je od tada do osmanskog osvajanja ostao pod upravom despotovine.", "1803a03a"]},
"OLAYLAR_EK6:1427-06-01:0":{"b": ["Aneksija Bejluka Hadžiemirogulla — Ordu i Ünye", "c064f07f"], "d": ["Turkmenski bejluk, koji je Bajram-beg osnovao oko Ordua, a njegov sin Hadži Emir proširio 1350-ih, bio je mala, ali strateška obalna država sa središtem u današnjem Eskipazaru: jedino nezavisno područje vlasti između Samsuna i Trabzona. Emir Sulejman 1398. je u džaničkoj akciji Bajazida I Munje iskazao odanost, a nakon Ankarske bitke bejluk je ponovo bio slobodan. U doba Murata II, istih godina kada su likvidirani Tadžeddinogulli, zemlje bejluka neposredno su pripojene osmanskoj upravi, a crnomorska obala od Samsuna do Giresuna objedinjena je pod jednom rukom.", "d5caa358"]},
"OLAYLAR_EK6:1458-08-06:0":{"b": ["Osvajanje Korinta", "87a2bc59"], "d": ["U morejskom pohodu Mehmeda II Osvajača tvrđava Akrokorint opsjedana je tri mjeseca i na kraju preuzeta mirnim putem. Tako je Korintska prevlaka, smatrana vratima Moreje, prešla Osmanlijama.", "b2be3a05"]},
"OLAYLAR_EK6:1499-01-01:0":{"b": ["Pripajanje Crne Gore osmanskoj upravi — Cetinje", "7fdb7cc8"], "d": ["Kad je dinastija Crnojevića, koja je vladala Zetom, 1496. napustila vlast, brdovita oblast Crne Gore, zaleđe Skadra, stavljena je pod neposrednu osmansku upravu i najprije ustrojena kao zaseban sandžak, a zatim kao dio Skadarskog sandžaka. Cetinjski manastir ostavljen je kao vjersko središte oblasti. Zbog surovosti reljefa uprava ovdje nikada nije funkcionirala tako čvrsto kao u ravnicama; dva stoljeća kasnije vladičanska uprava rođena iz istog manastira bit će jezgro faktičke nezavisnosti.", "e8356eb2"]},
"OLAYLAR_EK6:1534-06-23:0":{"b": ["Tvrđava Bajazit prihvatila osmansku vlast u pohodu na dva Iraka", "f29e2e17"], "d": ["Kad je veliki vezir Ibrahim-paša u pohodu na dva Iraka stigao u okolinu Bingöla, tvrđave Van, Toprakkale, Avnik i Bajazit, zajedno s mnogim kurdskim plemenima te oblasti, pristale su ući pod osmansku vlast. Bajazit je 1514. u Selimovom pohodu pripojen Osmanlijama, ali kad se vojska vratila, Safavidi su povratili oblast.", "14640206"]},
"OLAYLAR_EK6:1535-06-01:0":{"b": ["Tabriz ponovo prešao Safavidima — povratak s pohoda na dva Iraka", "80b8b761"], "d": ["U pohodu na dva Iraka vojska je ušla u Tabriz, ali budući da je pravi cilj bio Bagdad, u gradu nije ostavljena stalna posada. Dok se vojska, koja je zimu provela u Bagdadu, vraćala na zapad, šah Tahmasp ponovo je ušao u ispražnjeni Azerbejdžan i povratio Tabriz. To je bio ponavljani obrazac osmansko-safavidskih ratova: Tabriz je pet puta zauzet i nijednom od tih pet puta nije zadržan; grad će tek 1585. dobiti dugotrajnu osmansku posadu.", "f60ea64f"]},
"OLAYLAR_EK6:1535-09-22:0":{"b": ["Van i Erciş pali u Tahmaspove ruke (osmansko držanje okončano 1534–35.)", "cb93d561"], "d": ["U oblasti koja je Van 1534. predala osmanskoj vlasti Ulama-paša odolijevao je safavidskoj opsadi u Vanskoj tvrđavi; tvrđava je prešla u safavidske ruke, a safavidske snage koje su opsjedale Erciş povukle su se zbog osmanske pomoći. Kad je Sulejman Zakonodavac stigao u Ahlat (23. septembra 1535), Van je već bio u Tahmaspovim rukama. Van je ostao safavidski do 1548.", "eb576b34"]},
"OLAYLAR_EK6:1547-01-01:0":{"b": ["Prelazak Bajazitskog sandžaka pod safavidsku vlast (Van i Erciş već su 1535. bili safavidski)", "806a2cf1"], "d": ["Bajazitski sandžak na sredini osmansko-safavidske granice ponovo je prešao u iranske ruke (Kaya 2017 to spominje kao 'zajedno s Vanom i Erdžišem'; međutim, Van i Erciş su se prema Karataşu 2025. i TDV-u 22. septembra 1535. vratili Safavidima — vidi prethodni zapis); pri toj promjeni vlasti neka mjesta sandžaka opustošena su. Sandžak je do posljednje četvrtine 16. stoljeća više puta prelazio iz ruke u ruku između dviju država.", "28cb6e07"]},
"OLAYLAR_EK6:1553-08-01:0":{"b": ["Povratak Bajazitskog sandžaka Osmanlijama za nahičevanskog pohoda", "cf0171fa"], "d": ["Za trećeg iranskog (nahičevanskog) pohoda Sulejmana Zakonodavca Bajazitski sandžak ponovo je stavljen pod osmansku upravu. U pohodu 1554. Bajazit je bio važna baza za vojsku; sandžak je 1578. konačno ušao pod osmansku vlast.", "a6c619eb"]},
"OLAYLAR_EK6:1604-06-08:0":{"b": ["Gubitak Erivana u korist šaha Abasa", "34413cf2"], "d": ["U godinama kad su dželalijski ustanci paralizirali Anadoliju i istočni front ostao nezaštićen, šah Abas, koji je svoju vojsku preuredio po evropskom uzoru, prešao je u napad. Erivanska tvrđava, koju je 1583. dao sagraditi Ferhad-paša, predala se nakon sedmomjesečne opsade. Pukla je prva karika kavkaske linije dobivene Ferhad-pašinim mirom, a u iduće tri godine bit će izgubljen cijeli Južni Kavkaz.", "b5f54d9c"]},
"OLAYLAR_EK6:1606-01-01:0":{"b": ["Gubitak Tbilisija i Gandže", "3fb51753"], "d": ["Nakon pada Erivana safavidska vojska napredovala je dolinom Kure; Gandža, središte Karabaha, i Tbilisi, glavni grad Gruzije, jedan za drugim su izgubljeni. Osmanska država istovremeno je na austrijskom frontu vodila trinaestogodišnji dugi rat i bavila se dželalijama u Anadoliji; nije bilo snage koja bi se uputila na istok. Tako je faktički okončan poredak širokih kavkaskih ejaleta uspostavljen Ferhad-pašinim mirom 1590.", "c80d75b7"]},
"OLAYLAR_EK6:1607-01-01:0":{"b": ["Gubitak Širvana — Šamahi, Baku i Derbent", "81beab11"], "d": ["Ejalet Širvan na obali Kaspijskog jezera, osvojen pohodima Ozdemiroglu Osman-paše 1578–1585, kao glavni izvor trgovine svilom donosio je osmanskim finansijama značajan prihod. Safavidska akcija prema sjeveru redom je zauzela Šamahi, Baku i Derbent i likvidirala taj ejalet. Gubitak nije bio samo teritorijalni: i put kojim je iranska svila preko Osmanlija tekla u Evropu izašao je ispod kontrole, a safavidska država počela je prodavati svilu preko Indijskog okeana.", "f85d7f97"]},
"OLAYLAR_EK6:1629-01-01:0":{"b": ["Gubitak Taiza", "65f20d53"], "d": ["Osmanlije su 1038. (1629), zajedno s vlašću nad Jemenom prepuštenom kasimskoj upravi u Sani, napustile i Taiz — prvi veliki korak procesa u kojem su zejdijski imami povratili unutrašnji Jemen.", "72344627"]},
"OLAYLAR_EK6:1635-01-01:0":{"b": ["Gubitak Jemena — vlast kasimskih imama", "49e83e3c"], "d": ["Jemen je od 1538. bio osmanski ejalet, ali otpor zejdijskih imama nikada nije prestao. Ustanak koji je pokrenuo imam Kasim u doba njegovog sina el-Muejjeda Muhammeda proširio se po cijeloj zemlji, a osmanske posade redom su opsjedane. U godinama kad se Murat IV usredsredio na Bagdad i Erivan nije se moglo poslati pojačanje; Taiz je izgubljen 1629, a Moka je ispražnjena u posljednjoj fazi istog sloma 22. oktobra 1635. Godine 1635. i posljednje jedinice u Sani i Zebidu napustile su Jemen. Tako je istočna obala Crvenog mora ostala izvan carstva dvjesto trideset sedam godina i mogla se vratiti tek 1872. Lehedž (el-Havta) je, prema Islamskoj enciklopediji TDV-a, do 1635. bio u osmanskim rukama; od tada su ondje djelovali zejdijski imami.", "e966b559"]},
"OLAYLAR_EK6:1635-10-22:0":{"b": ["Evakuacija Moke", "c6b3061a"], "d": ["Mustafa-beg je 10. džumadel-ula 1045. (22. oktobra 1635) s preostalom snagom i oružjem ispraznio Moku; zatim je Hasan b. Kasim, sin imama Kasima, postavio svoje ljude u Zebidu i Moki i uspostavio kasimski nadzor i na obali Tihame.", "04e81711"]},
"OLAYLAR_EK6:1670-01-01:0":{"b": ["Gubitak Lahse u korist Emirata Benu Halid", "a9b6131a"], "d": ["Lahsa je bila ejalet osnovan 1550. da zapadnu obalu Basranskog zaljeva zatvori Portugalcima, ali je bila veoma daleko od Istanbula, na kraju jedinog pustinjskog puta. U godinama kad je opsada Krete trošila resurse, pleme Benu Halid u toj oblasti pod vodstvom Barraka b. Gurejra istjeralo je osmansku posadu i uspostavilo vlastiti emirat. Zapadna obala zaljeva vijek i po ostala je u plemenskim emiratima; 1795. prijeći će Saudijcima, a 1871. ponovo Osmanlijama.", "f3749775"]},
"OLAYLAR_EK6:1684-09-29:0":{"b": ["Gubitak Preveze i Vonitse u korist Venecije — otvaranje epirske obale", "1201204c"], "d": ["Venecija, koja je pristupila Svetoj ligi, prije početka morejskog pohoda zauzela je dvije tvrđave koje drže ulaz u Ambrakijski zaljev: Prevezu i Vonitsu na suprotnoj obali. Istog ljeta pala je i Lefkada (Aja Mavra). Ta tri položaja omogućila su floti da se iz Jonskog mora sigurno uvuče u unutrašnjost Grčke i postala baza morejske akcije koja će početi iduće godine. Preveza i Vonitsa i u Požarevcu su ostavljene Veneciji; pod osmansku upravu vratit će se tek 1798.", "1de80a4b"]},
"OLAYLAR_EK6:1685-10-12:0":{"b": ["Gubitak Solnoka — raspadanje linije Tise", "51c2c8ef"], "d": ["Nakon pada Ujvara u augustu habsburška vojska okrenula se na jug i zauzela mostobran na Tisi, Solnok. Grad je bio jedini siguran prijelaz između Budima i Erdelja; njegov gubitak značio je da se osmanske tvrđave u istočnoj polovini Ugarske odvajaju jedna od druge. Iduće godine u opsadi Budima presudno je bilo to što je put opskrbe bio presječen.", "a0595e94"]},
"OLAYLAR_EK6:1686-07-10:0":{"b": ["Gubitak Modona u korist Venecije", "114c9cc0"], "d": ["Modon na jugozapadnom kraju Moreje bio je luka koju je Venecija izgubila tri stoljeća ranije i nazivala 'jednim od dva oka države'. Tvrđava opsjednuta nakon pada Korona preuzeta je istovremenim granatiranjem s kopna i s mora. Morosinijeva morejska akcija tako je zauzela cijelu zapadnu obalu poluotoka i otvorila put ka unutrašnjosti.", "df990436"]},
"OLAYLAR_EK6:1686-10-20:0":{"b": ["Gubitak Pečuha", "99d54cf4"], "d": ["Nakon pada Budima u septembru habsburške snage spustile su se na jug zapadno od Dunava i zauzele Pečuh, osmanski od doba Sulejmana Zakonodavca. Grad, koji se pamti po džamiji Gazi Kasim-paše, bio je jedno od najrazvijenijih sandžačkih središta Budimskog ejaleta. Njegov gubitak značio je otvaranje puta prema mohačkoj ravnici; iduće godine upravo ovdje dogodit će se poraz u Drugoj bitki kod Mohača.", "10e39af1"]},
"OLAYLAR_EK6:1686-10-23:0":{"b": ["Gubitak Segedina", "9fbee1b2"], "d": ["Segedin na sastavu rijeka Tise i Moriša bio je južna vrata Panonske ravnice i držao je put prema Temišvarskom ejaletu. Tvrđava, opsjednuta nakon pada Budima i Pečuha iste jeseni, ubrzo se predala. Gubitak triju tvrđava u jednom godišnjem dobu bio je znak da se osmanska upravna struktura u Ugarskoj, uspostavljena od 1541, počinje urušavati. Atlas istog dana i Sentu na Tisi smatra pređenom od Osmanlija na habsburšku stranu (dan predaje specifičan za Sentu nije pročitan u izvoru, dan je preuzet od Segedina; TDV zenta: od oktobra 1686. počeli su sukobi između Osmanlija i saveznika pod habsburškim vodstvom — deklarirana približnost).", "2450ee08"]},
"OLAYLAR_EK6:1687-08-01:0":{"b": ["Gubitak Patrasa (Baljabadra) — sjeverna vrata Moreje", "b9cff63c"], "d": ["Patras na ulazu u Korintski zaljev bio je luka koja nadzire prolaz između Moreje i Rumelije. Kad je venecijanska vojska zauzela grad, i tvrđave na obje obale zaljeva pale su jedna za drugom, a poluotok je potpuno odsječen s kopna. Na kraju te akcije cijela Moreja prešla je Veneciji; oblast će do 1715. biti upravljana pod imenom 'Regno di Morea'.", "3b3ca389"]},
"OLAYLAR_EK6:1687-08-01:1":{"b": ["Prepuštanje Korinta Veneciji", "9a25b6b9"], "d": ["Nakon pada Patrasa Korint je mirnim putem prepušten Venecijancima, a muslimansko stanovništvo napustilo je grad. U augustu 1687. Morosinijeva vojska okupljala se u Korintu za pohod na Atinu.", "d92bcf7d"]},
"OLAYLAR_EK6:1687-12-17:0":{"b": ["Gubitak Jegra", "983391aa"], "d": ["Jegar je zauzet 1596. u pohodu u kojem je lično učestvovao Mehmed III i bio je središte ejaleta nazvanog po njemu. Ta posljednja velika osmanska tvrđava u Sjevernoj Ugarskoj, nakon poraza u Drugoj bitki kod Mohača potpuno opkoljena, godinu dana se opirala i predala se zbog gladi. Njenim gubitkom sjeverno krilo Osmanske države u Ugarskoj u cijelosti je likvidirano.", "ced01ee7"]},
"OLAYLAR_EK6:1688-05-19:0":{"b": ["Gubitak Stolnog Biograda — krunidbenog grada ugarskih kraljeva", "c6147255"], "d": ["Grad u kojem su se ugarski kraljevi stoljećima krunili i sahranjivali zauzeo je 1543. Sulejman Zakonodavac i bio je jedno od najvažnijih sandžačkih središta Budimskog ejaleta. Otprilike dvije godine nakon pada Budima tvrđava, potpuno odsječena od okoline, predala se. Tim gubitkom osmansko prisustvo zapadno od Dunava stisnulo se na okolinu Srijema i Osijeka.", "245ff91b"]},
"OLAYLAR_EK6:1689-02-03:0":{"b": ["Gubitak Sigeta", "834910a7"], "d": ["Siget je bio tvrđava kod koje je sultan Sulejman Zakonodavac u svom trinaestom i posljednjem pohodu 1566. umro dok je opsada trajala; zato je u osmanskom pamćenju imao simbolično mjesto. Sto dvadeset tri godine kasnije, nakon pada svih okolnih tvrđava, i tvrđava zaštićena močvarama se predala. Turbe u kojem su sahranjeni unutrašnji organi Sulejmana Zakonodavca i gradić oko njega srušeni su nakon prelaska pod habsburšku upravu. Ostalo naselje koje je istog datuma u atlasu prešlo od Osmanlija Habsburgovcima: Barcs — slijedi lanac matičnog središta Sigeta (Bánlaky 0017/1449; deklarirana približnost).", "12bc4465"]},
"OLAYLAR_EK6:1692-06-05:0":{"b": ["Gubitak Varada", "6cce360d"], "d": ["Varad je bio ključna tvrđava prema Erdelju, koju je 1660. zauzeo Mehmed-paša Ćuprilić i učinio je središtem ejaleta nazvanog po njoj. Tvrđava, koja je nakon poraza kod Slankamena ostala potpuno sama, predala se zbog gladi nakon gotovo dvogodišnje blokade. Njenim gubitkom faktički je okončan osmanski uticaj nad Erdeljom, a habsburška vlast učvrstila se istočno od Tise.", "72d9fcc0"]},
"OLAYLAR_EK6:1693-05-27:0":{"b": ["Gubitak Janove — zatvaranje puta za Erdelj", "4b5e30d8"], "d": ["Janova, zauzeta 1658, bila je tvrđava koja je držala vezu između Varada i Temišvara. Kad je neposredno nakon pada Varada odsječena od okoline, i ona je izgubljena. Tako je Temišvarski ejalet potpuno odsječen sa sjevera i do Karlovačkog mira opstao je kao jedina ugarska zemlja koja je ostala u osmanskim rukama.", "67168a2e"]},
"OLAYLAR_EK6:1697-01-01:0":{"b": ["Uspostava vladičanske uprave u Crnoj Gori — faktičko odvajanje Cetinja", "a924b778"], "d": ["U godinama kad je rat Svete lige oslabio osmanski nadzor na Balkanu, mitropolija na čelu Cetinjskog manastira postala je u porodici Petrovića položaj koji se prenosio s koljena na koljeno, a oblast je faktički stekla zasebnu upravu. Zahvaljujući nepristupačnosti planina ta vladičanska država dva stoljeća opstajala je ni potpuno nezavisna ni potpuno podložna; pravno će njena nezavisnost biti priznata tek Berlinskim ugovorom 1878.", "104e26b1"]},
"OLAYLAR_EK6:1715-06-01:0":{"b": ["Povratak Korinta", "26f53e3a"], "d": ["Prva velika stanica morejskog pohoda damat Ali-paše bio je Korint; Osmanlije su u junu 1715. povratile grad od Venecijanaca i odatle napredovale prema ostatku poluotoka.", "82e2e719"]},
"OLAYLAR_EK6:1730-08-12:0":{"b": ["Nadirov napad: gubitak Tabriza, Nahičevana, Hamadana, Kermanšaha, Marage i Kasr-i Širina", "d95efd59"], "d": ["Zapadnoiranski gradovi, zauzeti 1723–1727. korištenjem sloma safavidske države, redom su izgubljeni napadom Nadir-kana, koji je faktički preuzeo vlast u Iranu. U Azerbejdžanu su i Ardabil i Halhal prešli u Nadirove ruke. Gubitak Hamadana, Kermanšaha i Kasr-i Širina snažno je odjeknuo u Istanbulu; to što vojska nije krenula u pohod, nego je čekala u Üsküdaru, i pokušaj da se gubitak zataška bili su jedan od neposrednih uzroka ustanka Patrone Halila, koji je izbio šest sedmica kasnije. Atlas i Kotur, koji slijedi lanac Hoja, smatra da je tog dana prešao od Osmanlija Safavidima (Uluerler 2015, Turkish Studies 10/5, str. 6; dan specifičan za Kotur nije naveden u izvoru — deklarirana približnost).", "412bd324"]},
"OLAYLAR_EK6:1735-06-19:0":{"b": ["Poraz kod Baghavarda (Arpačaj) — gubitak Kavkaza u korist Nadir-kana", "4262f54c"], "d": ["Kavkaski ejaleti, zauzeti 1723–1725. korištenjem sloma safavidske države, mogli su se zadržati deset godina. Nadir-kan, koji je faktički preuzeo vlast u Iranu, kod Baghavarda blizu Erivana teško je porazio osmansku vojsku; serdar Abdullah-paša Ćuprilić poginuo je na bojnom polju. Nakon poraza Erivan, Tbilisi, Gandža i Širvan ispražnjeni su u roku od nekoliko mjeseci. Istočna granica vratila se na liniju Kasr-i Širina iz 1639, što će biti potvrđeno 1746.", "f123b2d9"]},
"OLAYLAR_EK6:1770-09-27:0":{"b": ["Gubitak Bendera u korist Rusa", "0daca453"], "d": ["Nakon poraza na Kagulskom polju osmanska vojska povukla se južno od Dunava, a tvrđave između Moldavije i Očakova ostale su same. Bender, koji drži prijelaz rijeke Turle (Dnjestra), zauzet je jurišem nakon dvomjesečne opsade; grad je opljačkan. Gubitak tvrđave prekinuo je srednju kariku odbrambene linije sjevernog Crnog mora, a za njim su pali i Akerman i Kilija. U Küčük Kajnardži Bender će biti vraćen, ali će 1806. biti još jednom izgubljen.", "483d1fad"]},
"OLAYLAR_EK6:1795-04-01:0":{"b": ["Ulazak emirata Sabah u Kuvajtu pod osmansko pokroviteljstvo", "3584dba0"], "d": ["Prema članku TDV-a o Kuvajtu, pristanište je početkom 18. stoljeća osnovalo pleme Utub koje je došlo iz Nedžda, a porodica Sabah preuzela je upravu pred kraj stoljeća. Istih godina kad je Lahsa prešla Saudijcima, emirat, kojem pred vehabijskim pritiskom nije ostao drugi izbor nego osloniti se na Basru, stupio je pod osmansko pokroviteljstvo. Ta veza ozvaničit će se 1871. Midhat-pašinim uređenjem Basre, i Kuvajt će se smatrati jednim od triju kadiluka Basranskog sandžaka; i kasnija iračka teritorijalna pretenzija oslanja se na taj zapis.", "c084f05f"]},
"OLAYLAR_EK6:1806-01-01:0":{"b": ["Gubitak Meke u korist vehabija", "2da23acd"], "d": ["Vehabijski pokret, rođen u Nedždu, u doba Sauda b. Abdulaziza okrenuo se Hidžazu; nakon Taifa i Medine i Meka je po drugi put zauzeta — mekanski emir šerif Galib predao je grad vehabijama pod uslovom da ostane na emirskom položaju. Turbeta su srušena, a put hadžijskih karavana iz Damaska i Kaira presječen; i surra koju je sultan svake godine slao u Haremejn prekinuta je tih godina — jedini izuzetak te dodjele, koja je neprekidno trajala do 1915, jeste razdoblje vehabijske vlasti. Budući da je naslov zaštitnika Haremejna bio jedan od temeljnih oslonaca sultanovog legitimiteta, taj gubitak, više od teritorijalnog gubitka, bio je težak politički udarac; povratak će trajati sedam godina i postat će moguć s vojskom Mehmed Ali-paše Kavalalija.", "888df9e3"]},
"OLAYLAR_EK6:1806-05-27:0":{"b": ["Kraj Dubrovačke Republike — francuska okupacija", "f8e27bf1"], "d": ["Francuzi, koji su se Campoformijskim mirom (1797) smjestili na dalmatinskoj obali, 27. maja 1806. zauzeli su Dubrovnik i okončali malu trgovačku republiku. Tako je okončan tri i po stoljeća dug vazalni status Dubrovnika, koji je od 1458. plaćajući harač Osmanlijama čuvao autonomiju i trgovačke povlastice; grad i otok Mljet republike na karti prelaze pod neposrednu francusku upravu.", "720631c0"]},
"OLAYLAR_EK6:1810-07-11:0":{"b": ["Gubitak Suhuma u korist Rusa — otvaranje istočne obale Crnog mora", "adc96bd4"], "d": ["U osmansko-ruskom ratu 1806–1812. ruska flota uputila se prema istočnoj obali Crnog mora i zauzela Suhum-kale, na kojem je u Abhaziji počivala osmanska vlast. Tvrđava je bila središte veza s kavkaskim plemenima i obalne trgovine. Njenim gubitkom Rusija se prvi put trajno učvrstila na istočnoj obali Crnog mora; osmanski uticaj na Kavkazu stisnuo se na okolinu Anape i Potija.", "77af92b7"]},
"OLAYLAR_EK6:1819-05-10:0":{"b": ["Prepuštanje Parge osmanskoj upravi", "66e0cc5d"], "d": ["Parga je od 1401. bila u venecijanskim rukama i nikada nije bila pod osmanskom upravom; nakon pada Venecije prelazila je redom Francuskoj i Engleskoj. Članak TDV-a o Ali-paši Tepelenskom ovako sažima stanje: grad se predao Englezima, a Ali-pašinoj upravi prepušten je tek 1819. Prijenos je rezultirao iseljenjem velikog dijela stanovništva na Jonske otoke. Tako je i posljednji iz trojke Preveza–Parga–Vonitsa, ostavljene Veneciji u Požarevcu, pripojen carstvu; Parga će devedeset četiri godine ostati osmanska.", "555a1119"]},
"OLAYLAR_EK6:1821-01-01:0":{"b": ["Argos prešao u ruke grčkih ustanika", "be66a696"], "d": ["U prvim mjesecima morejskog ustanka Argos i okolina izašli su ispod osmanske uprave i prešli u ruke grčkih ustanika; grad će u maju 1821. biti poprište osmanske protuakcije.", "c3ea2041"]},
"OLAYLAR_EK6:1821-05-05:0":{"b": ["Ahmed Kihaja zauzeo Argos, grad opljačkan i spaljen", "d6d3ac7b"], "d": ["Snage Ahmed Kihaje porazile su Grke u Argosu, opljačkale i spalile grad; grad se nakratko vratio pod osmanski nadzor.", "316a51a8"]},
"OLAYLAR_EK6:1821-05-15:0":{"b": ["Ahmed Kihaja se u Argosu spojio s muslimanima Tripolice i krenuo prema Tripolici", "9d679fd5"], "d": ["Ahmed Kihaja se u Argosu spojio s muslimanima Tripolice i krenuo prema Tripolici; Argos je ponovo prešao pod nadzor grčkih ustanika.", "596502da"]},
"OLAYLAR_EK6:1822-01-01:0":{"b": ["Korint prešao grčkim ustanicima", "892dcdc6"], "d": ["Tokom grčkog rata za nezavisnost Akrokorint je prešao u ruke ustanika, a zapovjednik tvrđave Kamil-beg zarobljen je.", "a7cb2c26"]},
"OLAYLAR_EK6:1822-07-24:0":{"b": ["Dramali Mahmud-paša postavio štab u Argosu", "c79abbfb"], "d": ["Vojska Dramali Mahmud-paše ušla je u argoško polje, a paša je postavio štab u gradiću Argosu; grad je ponovo prešao pod osmanski nadzor.", "d931b635"]},
"OLAYLAR_EK6:1822-08-06:0":{"b": ["Dramali Mahmud-paša počeo se povlačiti iz Argosa", "5e5afb74"], "d": ["Dramali Mahmud-paša, prisiljen na povlačenje prije nego što su prošle dvije sedmice od okupacije Argosa, počeo je prvu diviziju svoje vojske povlačiti prema Korintu; Argos je ponovo prešao u ruke grčkih ustanika.", "9c49ab0c"]},
"OLAYLAR_EK6:1822-12-12:0":{"b": ["Gubitak Nauplije (Anabolu) u korist ustanika", "1a67fa50"], "d": ["Anabolu, luka s najjačim utvrđenjima u Moreji, predala se zbog gladi nakon blokade duže od godinu dana. Tvrđava je od početka ustanka bila posljednje veliko uporište osmanske kontrole na poluotoku; njenim gubitkom cijela Moreja prešla je u ruke ustanika. Grad će ubrzo postati prvi glavni grad nove grčke države.", "f5a972d7"]},
"OLAYLAR_EK6:1829-04-30:0":{"b": ["Prelazak Nafpakta (Lepanta) pod grčku upravu", "c9d19d4b"], "d": ["Nafpaktos (Lepanto) na sjevernoj obali Korintskog zaljeva, koji je do grčkog ustanka bio u osmanskim rukama, izgubljen je u aprilu 1829. i ušao pod grčku upravu; ime gradića promijenjeno je u antičko Nafpaktos. Muslimansko i jevrejsko stanovništvo grada potpuno je nestalo, a mjesto se pretvorilo u mali gradić.", "b354fb47"]},
"OLAYLAR_EK6:1830-07-05:0":{"b": ["Francuska okupacija Alžira — kraj tri stoljeća starog odžaka", "0be8f568"], "d": ["Pod izgovorom incidenta s lepezom, nastalog iz spora o dugovima, Francuska je tri godine blokirala alžirsku obalu, a zatim iskrcala vojsku kod Sidi Ferrucha. Na kraju trosedmične akcije Husein-dej se predao i okončan je osmanski alžirski odžak, koji je trajao od 1516. Okupacija se nije ograničila na prijestolnicu; istog ljeta izgubljeni su i Tlemcen, Cherchell i Médéa u unutrašnjosti. Da cijela obala dođe pod francuski nadzor trajat će još dvadeset četiri godine.", "a19df96b"]},
"OLAYLAR_EK6:1831-01-01:0":{"b": ["Predaja Negroponta (Eubeje) Grčkoj — zajedno s otokom (Karistos, Oreoi)", "7b524aa4"], "d": ["Negropont (Eubeja), poprište žestokih sukoba tokom cijelog grčkog rata za nezavisnost, ali koji je ostao u osmanskim rukama, nakon stupanja mirovnog ugovora na snagu predat je 1831. Grcima. Muslimansko stanovništvo grada, od 1470. važne pomorske baze, prodavši svu imovinu po vrlo niskim cijenama, masovno se iselilo na osmanske zemlje; grad je dugo ostao prazan, a njemački putopisac Fallmerayer 1842. nazvao ga je gradom duhova.", "313e4745"]},
"OLAYLAR_EK6:1831-01-04:0":{"b": ["Francuska okupacija Orana", "a8415d66"], "d": ["Oran, koji je Španija 1792. predala bez borbe, bio je najveća luka na zapadu Alžira. Šest mjeseci nakon pada prijestolnice francuske jedinice ušle su u grad. Zapadna akcija koja je odavde pokrenuta ubrzo će se suočiti s petnaestogodišnjim otporom emira Abdelkadera.", "e1913ae8"]},
"OLAYLAR_EK6:1832-03-01:0":{"b": ["Okupacija Annabe (Bône)", "21f37fb1"], "d": ["Annaba, luka istočnog Alžira blizu tuniske granice, zauzeta je od francuskih snaga i pretvorena u bazu za marš na Konstantin. Grad je istovremeno bio i najbliža afrička luka nasuprot otoku Sardiniji.", "1ca5b213"]},
"OLAYLAR_EK6:1833-04-12:0":{"b": ["Prepuštanje Atine novoj grčkoj državi (dan kada su bavarske jedinice preuzele Akropolu)", "deee4d37"], "d": ["Atina, osmanska od 1456, tokom grčkog rata za nezavisnost nekoliko je puta mijenjala gospodara, a posada na Akropoli 1827. ponovo je prešla pod osmanski nadzor. Budući da je ostala sjeverno od granice povučene Londonskim protokolom, grad je predat novom kraljevstvu, a posada je ispraznila Akropolu. Dan u atlasu je dan kada su bavarske jedinice preuzele Akropolu; stvarni izlazak osmanske posade dogodio se nekoliko dana kasnije (St Clair, Who Saved the Parthenon?, Open Book Publishers, 2022, pogl. 13; Finlay, Journals and Letters, sv. I, str. 67). Iduće godine Atina je umjesto Nauplije proglašena glavnim gradom Grčke.", "378db620"]},
"OLAYLAR_EK6:1833-09-29:0":{"b": ["Okupacija Bedžaje (Bougie)", "a8927e00"], "d": ["Luka Bedžaja, gdje se kabilijske planine otvaraju prema moru, bila je posljednja nezavisna karika obalne linije između Alžira i Annabe. Zauzeta je uz podršku pomorske artiljerije; ali brdovita unutrašnjost iza nje neće još trideset godina doći pod francuski nadzor. Te obalne okupacije čine godinu po godinu topljenje osmanskog Alžira na karti.", "af6938db"]},
"OLAYLAR_EK6:1838-10-13:0":{"b": ["Okupacija Sétifa", "2073731a"], "d": ["Nakon pada Konstantina godinu ranije francuske snage popele su se na visoravan, zauzele stari rimski grad Sétif i ondje uspostavile trajnu posadu. Sétif je bio tačka u kojoj se ukrštaju karavanski putevi između obale i Sahare; njegova okupacija pokazala je da Francuska više ne nadzire samo luke, nego počinje nadzirati i unutrašnju trgovačku mrežu.", "c20b8b14"]},
"OLAYLAR_EK6:1844-03-04:0":{"b": ["Okupacija Biskre — gubitak vrata Sahare", "d895cad0"], "d": ["Biskra je bila vrata prema Sahari u južnom podnožju planina Atlas i središte oaza datulinih palmi. Njenim zauzimanjem u godinama kad se otpor emira Abdelkadera počeo lomiti francuski nadzor prvi put je stigao do sjevernog ruba pustinje. Nakon toga slijedit će pustinjska akcija koja napreduje oazu po oazu.", "46486fff"]},
"OLAYLAR_EK6:1854-12-02:0":{"b": ["Okupacija Touggourta — gubitak cijelog Alžira", "33c056e2"], "d": ["Zauzimanjem Touggourta, oaznog grada na sjeveru Sahare, okupacija započeta 1830. dovršena je u sjevernoj polovini današnjeg Alžira. Osmanska država tih je godina u Krimskom ratu ratovala na istoj strani s Francuskom; iako nikada zvanično nije napustila pravnu pretenziju na Alžir, faktički nije mogla učiniti nijedan korak. Jedina zemlja koja je ostala u Sjevernoj Africi bio je Tripoli.", "0eaa89a0"]},
"OLAYLAR_EK6:1883-01-19:0":{"b": ["Pad El-Obeida — prelazak Kordofana u ruke Mahdijevih snaga", "58299f62"], "d": ["Pokret koji je pokrenuo Muhammed Ahmed, proglasivši se mahdijem, brzo se širio protiv egipatske uprave u Sudanu. Središte Kordofana El-Obeid palo je nakon četveromjesečne opsade i postalo prijestolnica ustanka; riznica i skladišta oružja u gradu omogućili su pokretu da se pretvori u vojsku. Sudan je pravno još bio teritorij egipatskog hedivata vezanog za Osmanlije, pa gubitak na karti odlazi s trupa carstva.", "200e1799"]},
"OLAYLAR_EK6:1885-01-26:0":{"b": ["Pad Kartuma — gubitak cijelog Sudana", "d4b98464"], "d": ["Nakon desetomjesečne opsade Mahdijeve snage ušle su u Kartum, na sastavu Plavog i Bijelog Nila; guverner grada Gordon ubijen je, a britanska kolona poslana u pomoć zakasnila je dva dana. Od tada je cijeli Sudan, uključujući Sennar, Dongolu i Kordofan, četrnaest godina ostao pod upravom Mahdijske države. Oblast će tek 1899, s potpuno prekinutom osmanskom vezom, ući pod zajedničku britansko-egipatsku upravu.", "39a0a2c0"]},
"OLAYLAR_EK6:1885-02-05:0":{"b": ["Italijanska okupacija Masawe — gubitak zapadne obale Crvenog mora", "c333b95b"], "d": ["Luku Masawu, središte Habeškog ejaleta, okupirala je Italija koristeći pometnju u kojoj je Mahdijev ustanak zahvatio Sudan; to je činilo jezgro italijanske Eritreje. Suakin na sjeveru i arhipelag Dahlak na pučini izgubljeni su u istom procesu. Tako je okončana osmanska vlast na zapadnoj obali Crvenog mora, koja je trajala od doba Selima I Javuza, a more je sada postalo voda kojoj su obje obale strane.", "8cf1ab7a"]},
"OLAYLAR_EK6:1912-05-04:0":{"b": ["Italijanska okupacija Rodosa", "e08662c5"], "d": ["Italija, želeći primorati Osmansku državu da sjedne za pregovarački sto u ratu za Tripolitaniju, prenijela je rat u Sredozemlje i iskrcala vojsku na Rodos. Otok je preuzet za nekoliko dana. Tako je Rodos, koji je Sulejman Zakonodavac 1522. zauzeo dugom opsadom i držao tri stotine devedeset godina, prestao biti najveća otočna baza carstva u istočnom Sredozemlju; iako se u Ušijskom miru smatrao privremenom okupacijom, više se nikada nije mogao vratiti.", "f3823a2e"]},
"OLAYLAR_EK6:1912-05-12:0":{"b": ["Italijanska okupacija Dodekaneza", "200aacf2"], "d": ["U roku od sedmicu dana od zauzimanja Rodosa italijanska flota okupirala je i okolne otoke; taj arhipelag kasnije će dobiti ime 'Dodekanez' (Dvanaest otoka). Većina otoka bila je nekoliko milja od anadolske obale i nadzirala jugoistočni prolaz Egeja. Okupacija se u Ušijskom miru smatrala privremenom u zamjenu za napuštanje Tripolitanije, ali Italija nikada nije ispraznila otoke; 1947. bit će predani Grčkoj.", "01ceef5f"]},
"OLAYLAR_EK6:1912-05-20:0":{"b": ["Okupacija Kosa", "ab246c62"], "d": ["Kos, posljednja karika akcije na Dodekanezu, bio je plodan i napučen otok tik preko puta poluotoka Bodrum. Okupacijom su svi otoci u jugoistočnom uglu Egeja došli pod italijanski nadzor, a jugozapadna obala Anadolije cijelom dužinom bila je okružena stranim lancem otoka.", "5a6552a9"]},
"OLAYLAR_EK6:1912-07-17:0":{"b": ["Proglašenje nezavisnosti Nikarije", "c4452033"], "d": ["Na malom otoku Nikariji, između Samosa i Hiosa, narod se u neizvjesnosti stvorenoj italijanskim okupacijama pobunio, istjerao osmansku žandarmeriju s otoka i proglasio 'slobodnu državu' koja je sa svojom zastavom, markama i skupštinom trajala pet mjeseci. U novembru 1912. otok se pripojio Grčkoj. Uprkos njegovoj malenosti, taj je događaj jasan pokazatelj kako se na Egeju raspadala centralna uprava.", "bf892a96"]},
"OLAYLAR_EK6:1912-11-11:0":{"b": ["Izlazak Samosa ispod osmanske uprave", "3a862f2b"], "d": ["Samos je od 1832. bio autonomna kneževina koja je plaćala porez Osmanlijama i kojom je upravljao beg imenovan iz Istanbula. U praznini nastaloj zbog rata za Tripolitaniju pokret za ujedinjenje na otoku preuzeo je upravu, a poredak autonomne kneževine faktički je okončan; otok je iste godine proglasio pripajanje Grčkoj. Taj otok, udaljen dva kilometra od anadolske obale, postao je jedna od prvih izgubljenih zemalja u Egeju.", "3b6eafda"]},
"OLAYLAR_EK6:1913-03-06:0":{"b": ["Pad Janjine — gubitak Epira i Parge", "d42fce18"], "d": ["Janjina, opsjednuta pet mjeseci u Balkanskom ratu, predala se nakon pada položaja kod Bizanija; zajedno s gradom cijeli Epir prešao je Grčkoj. I Parga, vezana za Janjinski sandžak, tada je izgubljena, čime je okončana devedesetčetverogodišnja osmanska uprava. Gubitak Janjine značio je zatvaranje posljednjeg prozora carstva prema Jadranu.", "faa4893b"]},
"OLAYLAR_EK6:1913-03-26:0":{"b": ["Pad Edirna u bugarske ruke", "459d2e56"], "d": ["Nakon opsade od pet i po mjeseci Edirne, kojem su ponestali municija i namirnice, predalo se; Šukri-paša pao je u zarobljeništvo. Pad grada, osmanskog od 1361. i prijestolnice devedeset dvije godine, smatran je najtežim udarcem Balkanskog rata. Edirne će četiri mjeseca kasnije, u Drugom balkanskom ratu, biti povraćeno korištenjem sloma Bugarske na drugim frontovima.", "4b63fb0d"]},
"OLAYLAR_EK6:1916-07-27:0":{"b": ["Gubitak Janbua u korist snaga šerifa Huseina", "e291c816"], "d": ["Ustanak koji je šerif Husein pokrenuo u junu proširio se na obalu Crvenog mora; Janbu, medinska luka, uz podršku britanske flote prešao je u ruke ustanika. Luka je postala glavna kapija dotoka oružja i novca izvana u ustanak. Tako je snagama Fahreddin-paše u Medini presječena veza s morem, a grad je ostao sam na kraju Hidžaške željeznice.", "83cc4dbb"]},
"OLAYLAR_EK6:1917-11-07:0":{"b": ["Treća bitka za Gazu — gubitak Gaze i Han Junisa", "c142a069"], "d": ["Nakon dva neuspjela pokušaja Allenby je u trećem napadu probio front zaobišavši kod Bir es-Sebe i linija Gaze, držana šest mjeseci, urušila se. Gaza i Han Junis južno od nje ispražnjeni su istog dana. Taj proboj bio je početak raspadanja palestinskog fronta; Jeruzalem će pasti pet sedmica kasnije.", "a6efff96"]},
"OLAYLAR_EK6:1920-05-27:0":{"b": ["Okupacija Komotinija — gubitak Zapadne Trakije", "904d813c"], "d": ["Zapadna Trakija, koja je nakon Mudrosa najprije došla pod nadzor jedinica Antante, odlukom konferencije u San Remu prepuštena je Grčkoj, a grčka vojska ušla je u Komotini. Oblast, 1913. povraćena od Bugarske, bila je posljednja zemlja koju je carstvo izgubilo u Rumeliji. Status turskog stanovništva u oblasti bit će tri godine kasnije uređen u Lausannei režimom manjina. Ovom okupacijom Grčkoj su prešli kadiluci Zapadne Trakije Komotini, Ksanti, Aleksandrupolis (Dedeagač) i Sufli.", "ef0aeba3"]},
"OLAYLAR_EK7:1466-01-01:0":{"b": ["Epidemija kuge u Istanbulu i preseljenje saraja u Edirne", "70c7a163"], "d": ["Prema članku o Istanbulu u Islamskoj enciklopediji TDV-a, brzo i gusto naseljavanje grada povremeno je pripremalo tlo za širenje epidemija; tokom kuge 1466. saraj i državni velikodostojnici privremeno su se povukli u Edirne. Stanovništvo grada u takvim epidemijama pretrpjelo je ozbiljne gubitke.", "7b20238c"]},
"OLAYLAR_EK7:1470-06-01:0":{"b": ["Početak nastave u medresama Sahn-i Seman", "021f2a83"], "d": ["Prema članku o Sahn-i Semanu u Islamskoj enciklopediji TDV-a, ovih osam medresa, osnovanih u okviru Fatihovog kompleksa (külliye), zamišljeno je kao najviša obrazovna ustanova toga doba i činile su vrh osmanske ilmijske hijerarhije. Muderrisluk i diplomiranje na njima u kasnijim su se stoljećima smatrali najuglednijom stepenicom karijere kadije i muderrisa.", "c6fdcefc"]},
"OLAYLAR_EK7:1478-01-01:0":{"b": ["Dovršetak Topkapi saraja (Saraj-i Džedid)", "d2db6323"], "d": ["Prema članku o Topkapi saraju u Islamskoj enciklopediji TDV-a, izvori tog doba razilaze se o datumima početka i završetka gradnje; prema datumu 883 (1478) na natpisu Bab-i Humajuna, gradnja, vjerovatno započeta 1465. po naredbi Mehmeda II Osvajača, do te je godine uglavnom bila dovršena i saraj je zamijenio državno središte u starom saraju. Tako se sultan preselio u novu rezidenciju, koja će tri stoljeća biti upravno i ceremonijalno srce države.", "5dfffded"]},
"OLAYLAR_EK7:1481-05-22:0":{"b": ["Stupanje Bajazida II na prijestolje u Istanbulu", "9b686d04"], "d": ["Prema članku o Bajazidu II u Islamskoj enciklopediji TDV-a, šehzada Bajazid, sandžakbeg Amasije, na vijest o očevoj smrti brzo je stigao u Istanbul i stupio na prijestolje; uz podršku janjičara ostavio je za sobom brata Džema koji je krenuo iz Konje. Pri stupanju na prijestolje janjičarima je podijeljen uobičajeni džulus-bakšiš. Ta smjena na prijestolju zapalila je i fitilj borbe dvojice braće.", "7ea657ef"]},
"OLAYLAR_EK7:1481-05-28:0":{"b": ["Džem-sultan se u Bursi proglasio sultanom", "b355168a"], "d": ["Prema članku o Džem-sultanu u Islamskoj enciklopediji TDV-a, Džem, koji je preko Karamana stigao u Bursu, zauzeo je grad, proglasio se sultanom i dao učiti hutbu u svoje ime. Ta kratkotrajna vladavina okončana je kad su snage koje je poslao njegov stariji brat Bajazid II porazile Džema kod Jenišehira. Nakon poraza Džem je morao pobjeći prema Egiptu.", "18506663"]},
"OLAYLAR_EK7:1482-11-18:0":{"b": ["Pogubljenje Gedik Ahmed-paše", "6d75a58c"], "d": ["Prema članku o Gedik Ahmed-paši u Islamskoj enciklopediji TDV-a, paša poznat po pohodu na Otranto i po dužnosti velikog vezira pogubljen je u Edirnama po naredbi Bajazida II zbog svog držanja u pitanju Džem-sultana i zabrinutosti zbog njegovog uticaja. Smrt jednog od najiskusnijih zapovjednika doba Mehmeda II Osvajača snažno je odjeknula u saraju.", "59d06e3a"]},
"OLAYLAR_EK7:1493-01-01:0":{"b": ["Osnivanje prve štamparije u Istanbulu", "04475930"], "d": ["Prema članku o štampariji u Islamskoj enciklopediji TDV-a, jevrejski useljenici iz Španije, braća David i Samuel ibn Nahmias, osnovali su u Istanbulu prvu štampariju koja je štampala hebrejskim slovima. To je zabilježeno kao prvi štamparski poduhvat koji je djelovao na osmanskim zemljama; štampanje turskog arapskim pismom, pak, postat će moguće mnogo kasnije, u XVIII stoljeću.", "118df98b"]},
"OLAYLAR_EK7:1509-09-14:0":{"b": ["Zemljotres 'Mali sudnji dan' u Istanbulu", "53e3b1d6"], "d": ["Prema članku o Istanbulu u Islamskoj enciklopediji TDV-a, snažni zemljotres koji je pogodio grad u narodu je toga doba pamćen kao 'Mali sudnji dan' (Küčük Kijamet); nastala je teška šteta na zidinama, džamijama i mnogim zgradama, a bilo je i mnogo ljudskih žrtava. Po naredbi Bajazida II u gradu je pokrenuta opsežna akcija obnove i izgradnje.", "47093985"]},
"OLAYLAR_EK7:1511-04-01:0":{"b": ["Početak ustanka Šahkulua", "3d9a4a90"], "d": ["Prema članku o Šahkulu Baba Tekeliju u Islamskoj enciklopediji TDV-a, Šahkulu, kojeg je hranila safavidska propaganda, okupio je u oblasti Teke široku turkmensku masu i pokrenuo veliki ustanak vjersko-društvenog karaktera. Ustanak, kao jedna od najozbiljnijih unutrašnjih sigurnosnih kriza toga doba, duboko je uzdrmao centralni autoritet države.", "3e064ec6"]},
"OLAYLAR_EK7:1512-06-10:0":{"b": ["Smrt Bajazida II na putu u Didimotihon", "c46e98c9"], "d": ["Nekadašnji sultan, koji je nakon odricanja od prijestolja napustio Istanbul da ode u svoj rodni grad Didimotihon, putujući u nosiljci koja je dnevno prelazila samo 5–6 km, pozlio mu je u selu Abalar kod Çorlua i umro je 25. rebiul-evvela 918. (10. juna 1512). Islamska enciklopedija TDV-a uzrok smrti smatra veoma sumnjivim; prema nekim domaćim i stranim izvorima razmatra se mogućnost da je otrovan. Tako je nakon tridesetjednogodišnje vladavine umro osmi sultan iz loze Osman Gazija.", "4a316f9a"]},
"OLAYLAR_EK7:1513-04-24:0":{"b": ["Pogubljenje šehzade Ahmeda po naredbi Selima I Javuza", "65abb2f2"], "d": ["Prema članku o Selimu I u Islamskoj enciklopediji TDV-a, šehzada Ahmed, miljenik oca Bajazida II i glavni suparnik za prijestolje, u borbi u koju je ušao nakon stupanja na prijestolje brata Selima poražen je na Jenišehirskom polju i, bježeći s bojnog polja, uhvaćen i ubijen. Ovim događajem Selim je uglavnom okončao suparništvo za prijestolje među braćom i bratićima.", "6cef6bf2"]},
"OLAYLAR_EK7:1523-06-27:0":{"b": ["Ibrahim-paša imenovan velikim vezirom", "9c94c1e3"], "d": ["Prema članku o Ibrahim-paši Makbulu u Islamskoj enciklopediji TDV-a, Ibrahim-paša, koji je s dužnosti has odabaše uzdignut na zvanje rumelijskog beglerbega i istog dana na položaj velikog vezira, postao je veliki vezir 13. šabana 929. (27. juna 1523). Bilo je to bez presedana imenovanje, pri kojem se iz dvorske službe neposredno prelazilo na položaj velikog vezira i koje je pokazivalo izvanrednu Ibrahim-pašinu bliskost sa Sulejmanom Zakonodavcem.", "d8908e00"]},
"OLAYLAR_EK7:1534-04-06:0":{"b": ["Barbaros Hajreddin-paša imenovan kapudan-pašom", "a0ff6bab"], "d": ["Prema članku o Barbaros Hajreddin-paši u Islamskoj enciklopediji TDV-a, Hajreddin-paša, poznat po uspjesima u Alžiru, pozvan je 6. aprila 1534. u Istanbul i postavljen za kapudan-pašu i beglerbega Džezair-i Bahr-i Sefida. To imenovanje smatra se početkom preustroja osmanske flote i institucionalizacije pomorske moći u Sredozemlju.", "73332d17"]},
"OLAYLAR_EK7:1544-12-02:0":{"b": ["Rustem-paša prvi put postao veliki vezir", "ddfcc014"], "d": ["Prema članku o Rustem-paši u Islamskoj enciklopediji TDV-a, nakon smjene Hadum Sulejman-paše zbog spora s jednim vezirom, Rustem-paša je 17. ramazana 951. (2. decembra 1544) postavljen za velikog vezira. Rustem-paša, čija je bliskost sa sarajem porasla brakom s Mihrimah-sultanijom, na toj je dužnosti postao jedan od najuticajnijih državnika doba Sulejmana Zakonodavca.", "05215a80"]},
"OLAYLAR_EK7:1545-10-01:0":{"b": ["Ebussuud-efendija postao šejhul-islam", "11ed04f8"], "d": ["Prema članku o Ebussuud-efendiji u Islamskoj enciklopediji TDV-a, Ebussuud-efendija, koji je osam godina bio rumelijski kazasker, u šabanu 952. (oktobar 1545) doveden je na položaj šejhul-islama i na toj dužnosti ostao dvadeset osam godina i jedanaest mjeseci. Ebussuud-efendija, poznat po fetvama kojima je kanunname Sulejmana Zakonodavca uskladio sa šerijatskim pravom, imao je presudnu ulogu u oblikovanju pravnih i obrazovnih ustanova svoga doba.", "bc622e58"]},
"OLAYLAR_EK7:1546-07-05:0":{"b": ["Umro Barbaros Hajreddin-paša", "3378a0bf"], "d": ["Prema članku o Barbaros Hajreddin-paši u Islamskoj enciklopediji TDV-a, nakon kratke bolesti umro je u Istanbulu 6. džumadel-ula 953. (5. jula 1546). Smrt Barbarosa, sahranjenog u turbetu uz medresu koju je sam sagradio u Beşiktaşu, doživljena je kao zatvaranje jednog doba u sredozemnoj nadmoći koju je uspostavila osmanska flota.", "c2863ce0"]},
"OLAYLAR_EK7:1550-06-01:0":{"b": ["Počela gradnja Sulejmanije džamije i kompleksa", "101ec36f"], "d": ["Prema članku o Sulejmanija džamiji i kompleksu u Islamskoj enciklopediji TDV-a, kompleks čiji su temelji položeni 1550. pod glavnim arhitektom Mimarom Sinanom zamišljen je kao veliki društveni kompleks koji uz džamiju obuhvata medrese, bolnicu (daruššifa), imaret i biblioteku. Gradnja je bila jedan od najvećih graditeljskih programa koji simboliziraju moć vladavine Sulejmana Zakonodavca i izgradnju Istanbula.", "cbcd3e9d"]},
"OLAYLAR_EK7:1552-06-01:0":{"b": ["U Istanbulu i okolini počeo novi val kuge", "547d6bf6"], "d": ["Prema članku o kugi (taun) u Islamskoj enciklopediji TDV-a, jedna od epidemija 16. stoljeća koje su pogodile islamski svijet trajala je 1552–1566. i bila je naročito snažna u Istanbulu, Anadoliji, Rumeliji, Egiptu i Sjevernoj Africi. Sve širi trgovački putevi i sve veća pokretljivost stanovništva navode se među faktorima koji su u doba najveće moći carstva olakšali širenje epidemija.", "a755c417"]},
"OLAYLAR_EK7:1553-10-05:0":{"b": ["Kara Ahmed-paša imenovan velikim vezirom", "a7d7748e"], "d": ["Prema članku o Kara Ahmed-paši u Islamskoj enciklopediji TDV-a, Kara Ahmed-paša, koji je služio kao drugi vezir, nakon iznenadne smjene tadašnjeg velikog vezira uzdignut je 27. ševvala 960. (5. oktobra 1553) na položaj velikog vezira. Ta promjena upućuje na razdoblje u kojem su se, istih dana kad i pogubljenje šehzade Mustafe, ravnoteže moći unutar saraja brzo mijenjale.", "40fe9b6d"]},
"OLAYLAR_EK7:1553-12-01:0":{"b": ["Pogubljen kapudan-paša Piri Reis", "3b2ad7a0"], "d": ["Prema članku o Piri Reisu u Islamskoj enciklopediji TDV-a, kad su u Egipat stigle optužbe da je, dižući opsadu Hormuza, za mito opljačkao imovinu muslimana i napustio svoju vojsku na bojnom polju, slavni pomorac i kartograf pogubljen je u Kairu krajem 960. (krajem 1553). Smrt Piri Reisa, čija je imovina zaplijenjena, ocjenjuje se kao posljedica suparništva među pašama u pomorskoj politici toga doba u Basri i na Indijskom okeanu.", "c410d0ce"]},
"OLAYLAR_EK:1300-01-01:0":{"b": ["Zauzimanje Köprühisara i priprema za osnivanje Yenişehira", "39abff03"], "d": ["Padom tvrđava na prijevoju između Burse i Iznika položen je temelj isturenog stožera koji će oba grada staviti pod opsadu.", "72fa9808"]},
"OLAYLAR_EK:1301-01-01:0":{"b": ["Osnivanje Yenişehira", "d3275837"], "d": ["Radi vođenja opsada Burse i Iznika osnovano je prvo uređeno osmansko naselje s garnizonom; ovdje je rođen Orhan-gazi.", "39c98a4b"]},
"OLAYLAR_EK:1302-08-01:0":{"b": ["Prva opsada Iznika i osvajanje Marmaracıka", "cdca2349"], "d": ["Iznik je prvi put opsjednut, ali nije osvojen (konačno osvajanje 1331); tom prilikom zauzeta je obližnja tvrđava Marmaracık.", "31c4c65f"]},
"OLAYLAR_EK:1305-06-01:0":{"b": ["Pohod katalonskih četa u Anadoliju", "4fd940d5"], "d": ["Katalonska družina, koju je Bizant unajmio da zaustavi tursko napredovanje, postigla je privremene uspjehe, ali se nije mogla trajno održati; njenim povlačenjem ubrzalo se napredovanje pograničnih bejluka.", "89381e71"]},
"OLAYLAR_EK:1313-01-01:0":{"b": ["Köse Mihal prima islam i pridružuje se Osmanlijama", "ca0d86e1"], "d": ["Köse Mihal, tekfur Harmankaye, sa svojom tvrđavom i ljudima prešao je na islam i pridružio se Osman-gaziji; postao je prvi osmanski zapovjednik bizantskog porijekla.", "327b4cdc"]},
"OLAYLAR_EK:1320-01-01:0":{"b": ["Orhan-beg preuzima faktičku upravu", "6dadbefc"], "d": ["Zbog starosti i bolesti Osman-gazije faktičko vođenje opsade Burse i pohoda prešlo je na njegovog sina Orhan-bega (službeno stupanje na prijestolje bilo je 1326).", "280c6e0d"]},
"OLAYLAR_EK:1321-04-01:0":{"b": ["Zauzimanje Mudanye", "0a623368"], "d": ["Zauzimanjem Mudanye, luke Burse, presječena je veza grada s morem; opsada Burse ušla je u fazu gušenja.", "c13020d5"]},
"OLAYLAR_EK:1324-01-01:0":{"b": ["Akyazı i otok İmralı prelaze u osmanske ruke (datum nema u izvoru)", "380c60ce"], "d": ["Akyazı je u doba Osman-bega (u godinama nakon pohoda 1305) bio meta osmanskih upada; godina konačnog zauzimanja nije poznata. Kad je otok İmralı zauzet, ne navodi nijedan izvor. Granica iz 1324. na karti je privremena oznaka.", "69782c1e"]},
"OLAYLAR_EK:1326-01-01:0":{"b": ["Akča Kodža zauzeo Kandıru i okolicu", "341bb97e"], "d": ["Akča Kodža, jedan od graničnih begova Orhan-gazije, dok je iz svog stožera zapadno od jezera Sapanca upadao u izmitski kraj, oko 1326. zauzeo je Kandıru i njenu okolicu. Izmit je još bio u bizantskim rukama; grad će pasti tek 1337.", "ed042ad1"]},
"OLAYLAR_EK:1326-01-01:1":{"b": ["Pripajanje Yalove i Karamürsela", "133cb07a"], "d": ["Yalova i okolica na južnoj obali Izmitskog zaljeva te su godine prešle u turske ruke; obalni pojas Orhan-beg dao je kao timar Karamürsel-gaziji.", "592a86bc"]},
"OLAYLAR_EK:1328-01-01:0":{"b": ["Akča Kodža zauzeo Aydos i tvrđavu Samandıra", "ce4daa8a"], "d": ["Nakon zauzimanja Kandıre Akča Kodža je, zajedno s Konuralpom i Gazi Abdurrahmanom, zauzeo tvrđavu Aydos kod Kartala, a zatim tvrđavu Samandıra sjeverno od nje; područje Samandıre dato mu je kao posjed. Akča Kodža umro je 1328. kod Kandıre; pograničnu oblast dobio je princ Murat.", "f2ef1bde"]},
"OLAYLAR_EK:1330-01-01:0":{"b": ["Savez Osmanlija, Aydına i Saruhana", "9df6bb74"], "d": ["Tri bejluka zajednički su djelovala protiv Bizanta; flota Umur-bega Aydınoğlua upadima na obale Trakije iscrpljivala je Bizant na drugom frontu.", "32ca49ea"]},
"OLAYLAR_EK:1334-01-01:0":{"b": ["Osvajanje Gemlika (Kiosa)", "66fc4bcd"], "d": ["Obalni grad Gemlik (Kios) u Gemličkom zaljevu, koji se otvara prema Mramornom moru, prešao je u osmanske ruke. Kad se Bursa predala 1326, gradski tekfur poslan je s porodicom u Gemlik; dakle, Gemlik je 1326. još bio u bizantskim rukama. Za Armutlu nije pronađen zaseban datum; vezan je za lanac Gemlika.", "27ef02f4"]},
"OLAYLAR_EK:1346-06-01:0":{"b": ["Brak Orhan-gazije i Teodore: savez s Bizantom", "9b67a590"], "d": ["Orhan-gazi, koji je u bizantskoj borbi za prijestolje podržavao Kantakuzena, oženio se njegovom kćerkom Teodorom; taj je savez omogućio osmanskim snagama da izbliza upoznaju Rumeliju.", "4f8f52d9"]},
"OLAYLAR_EK:1354-08-01:0":{"b": ["Zauzimanje Ankare", "49bf1f6d"], "d": ["Ankara pod upravom ahija došla je pod osmansku upravu; otvoren je put u srednju Anadoliju. Ostala mjesta pripojena istog datuma: Sivrihisar, Çankırı.", "eec5d13e"]},
"OLAYLAR_EK:1357-01-01:0":{"b": ["Napredovanje u Trakiji u doba Sulejman-paše: Malkara, İpsala i Tekirdağ", "fb31cf02"], "d": ["Nakon uspostavljanja mostobrana u Galipolju Sulejman-paša, krećući s poluotoka na sjever, korak po korak zauzeo je ravnicu između obale Mramornog mora i ušća Marice. Malkara, İpsala i Rodosçuk (Tekirdağ) tako su činili neprekinut koridor koji povezuje Galipolje s dolinom Marice. Bez tog koridora nije se moglo krenuti na Edirne; napredovanje koje je 1357. zastalo iznenadnom smrću princa nastavit će Lala Šahin i Hadži Ilbej.", "721cac95"]},
"OLAYLAR_EK:1357-08-01:0":{"b": ["Otmica princa Halila", "b52ac3d7"], "d": ["Orhan-gazijinog mlađeg sina Halila oteli su gusari iz Foče (Foça); kriza oko otkupa godinama je opterećivala osmansko-bizantske odnose.", "812e3cb6"]},
"OLAYLAR_EK:1360-01-01:0":{"b": ["Presijecanje puteva pomoći Edirni: tvrđave Çorlu, Lüleburgaz, Babaeski i Keşan", "8e8ad485"], "d": ["Princ Murat, koji je nakon izbavljenja Halila ponovo započeo osvajačke operacije, poslao je akindžije sve pred Istanbul da bi Edirnu izolirao od moguće pomoći izvana. Zauzete su tvrđave Çorlu, Lüleburgaz i Babaeski na putu Istanbul–Edirne te Keşan na raskršću puteva južne Trakije. Predaja Edirne uslijedila je nakon što je taj opsadni obruč zatvoren.", "fb171002"]},
"OLAYLAR_EK:1361-01-01:0":{"b": ["Zauzimanje Didimotike — otvaranje doline Marice", "b59aee83"], "d": ["Zauzeta je Didimotika, ključna tvrđava doline Marice; tako je otvoren put ka osvajanju Edirne. Bez dovršenja koridora od Galipolja prema sjeveru nije se moglo krenuti na Edirne, pa tvrđava u redoslijedu rumelijskih osvajanja dolazi prije Edirne. Grad je neko vrijeme bio rumelijski stožer sultana. Snage koje su zauzele Didimotiku zatim su, s malim tvrđavama poput Pythiona (Kuleli Burgaz), stavile pod nadzor cijeli srednji tok Marice.", "88f995b6"]},
"OLAYLAR_EK:1366-08-01:0":{"b": ["Gubitak Galipolja (savojski krstaški pohod)", "00e7e415"], "d": ["Flota Amadea Savojskog, rođaka bizantskog cara, zauzela je Galipolje i predala ga Bizantu; osmanskim mostobranom u Rumeliji deset godina upravljalo se s druge strane moreuza. Ostala naselja izgubljena istog datuma: Çimpe.", "b0c24ccd"]},
"OLAYLAR_EK:1371-09-26:0":{"b": ["Bitka kod Černomena (Çirmen) — nadzor nad dolinom Marice", "cd738d8d"], "d": ["Vojska srpskih velikaša razbijena je u noćnom napadu; srpski i bugarski lokalni velikaši u Makedoniji i Rodopima počeli su jedan po jedan plaćati harač Osmanlijama — nije to bilo izravno osvajanje, nego početak vala vazalizacije. U osmanskoj predaji ova se bitka pripovijeda i pod imenom «Sırpsındığı», s godinom 1364, kao noćni napad Hadži Ilbeja na krstašku vojsku koja je došla povratiti Edirnu; TDV navodi da je ta godina pogrešna i da se obje pripovijesti odnose na istu bitku.", "7b2779cd"]},
"OLAYLAR_EK:1372-06-01:0":{"b": ["Osvajanje Plovdiva i Stare Zagore", "e780c9ae"], "d": ["Zauzeti su Plovdiv u gornjem toku Marice i Stara Zagora sjeverno od njega; Bugarsko carstvo obavezano je na harač. Pravac Pazardžik–Ihtiman između Plovdiva i Sofije ostao je u rukama lokalnih velikaša koji su nakon Černomena postali vazali. Ostala naselja izgubljena istog datuma: Haskovo, Klokotnica.", "019bac28"]},
"OLAYLAR_EK:1373-05-01:0":{"b": ["Vazalni Bizant: Ivan V u vojsci Murata I (posljedica pobjede kod Černomena 1371)", "13ffe568"], "d": ["Prema TDV-u, nakon pobjede kod Černomena (na Marici) 26. septembra 1371. Bizantsko Carstvo priznalo je osmansko vrhovništvo i, prihvativši plaćanje harača i službu u osmanskoj vojsci, palo na položaj vazalne države. Car Ivan V se po toj obavezi 1373. pridružio vojsci Murata I; njegov sin Andronik IV, kojeg je tada ostavio u Istanbulu, zajedno s princem Savči-begom u Bursi podigao je ustanak protiv očeva.", "3fe5b636"]},
"OLAYLAR_EK:1376-09-01:0":{"b": ["Povratak Galipolja", "5f96c0a5"], "d": ["Andronik IV, koji je u bizantskoj borbi za prijestolje dobio osmansku podršku, zauzvrat je vratio Galipolje; most između Rumelije i Anadolije ponovo je uspostavljen. Ostala mjesta pripojena istog datuma: Çimpe.", "fc79cd5d"]},
"OLAYLAR_EK:1381-01-01:0":{"b": ["Germijanski miraz: pripojenje Kütahye", "d6a6fe61"], "d": ["Pri udaji Devletšah-hatun, kćeri Sulejman-šaha Germijanskog, za Bajazida Munje, Kütahya, Simav, Tavşanlı i Eğrigöz prešli su kao miraz Osmanlijama — klasičan primjer širenja bez rata. Ostala mjesta pripojena istog datuma: Afyon.", "3321bbba"]},
"OLAYLAR_EK:1381-06-01:0":{"b": ["Kupovina Hamidske oblasti: pripojenje Isparte", "4a1b6047"], "d": ["Husein-beg Hamidoglu dio svog bejluka (Akşehir–Beyşehir–Isparta) prodao je Muratu I za gotovinu; ostatak Hamidske oblasti Munja će anektirati 1391. Ostala naselja izgubljena istog datuma: İshaklı.", "3930685b"]},
"OLAYLAR_EK:1383-09-19:0":{"b": ["Osvajanje Sereza", "d4d28b60"], "d": ["Zauzet je Serez, ključ istočne Makedonije; Solun je ušao u opsadni obruč. Pravac Ćustendil–Petrič–Nevrokop–Drama između Sofije i Sereza tada još nije bio izravno pripojen; redom je od 1370-ih do 1383. bio vazalan, a nakon 1383. prešao pod izravnu upravu. Ostala naselja izgubljena istog datuma: Gevgelija, Kilkis (Avrathisar).", "69be987a"]},
"OLAYLAR_EK:1385-09-01:0":{"b": ["Osvajanje Sofije", "96d5f01f"], "d": ["Zapadni prijevoji Balkanskih planina stavljeni su pod nadzor; budući da je Serez tada već od 1383. bio u rukama, zemlje u Trakiji i Makedoniji činile su neprekinutu cjelinu.", "f358b568"]},
"OLAYLAR_EK:1386-01-01:0":{"b": ["Osvajanje Niša", "77f5d632"], "d": ["Zauzimanjem Niša, ključa doline Morave, Srpska despotovina došla je pod izravnu prijetnju.", "15f52aaf"]},
"OLAYLAR_EK:1387-04-09:0":{"b": ["Prva predaja Soluna", "96010ee9"], "d": ["Nakon duge blokade grad se predao (1403. bit će vraćen Bizantu, a 1430. konačno osvojen). Ostala mjesta pripojena istog datuma: Kavala. Ostala naselja izgubljena istog datuma: Lagkadas (Lanzaka), Pravište (Eleftheroupoli).", "834119a2"]},
"OLAYLAR_EK:1387-06-08:0":{"b": ["Osmansko-đenovljanska ahdnama — obnova ugovora iz 1352", "be11d17a"], "d": ["S đenovljanskim poslanicima iz Pere obnovljen je trgovački sporazum iz 1352, naslijeđen iz vremena Orhan-gazije; ponovo su utvrđeni porezi između dviju država, postupak sa zarobljenicima i slobodna trgovina. Smatra se prvom službeno poznatom ahdnamom o prijateljstvu i trgovini između Osmanlija i Đenovljana — nije to bio vojni savez, nego isključivo trgovački sporazum.", "46b0f65b"]},
"OLAYLAR_EK:1388-01-01:0":{"b": ["Bugarski pohod Čandarli Ali-paše: zauzimanje Šumena i Rusea", "2781c3a9"], "d": ["Tvrđave Bugarskog carstva duž Dunava zauzete su u jednom pohodu; ne treba ga miješati s porazom doživljenim iste godine kod Bileće u Bosni — ovo je bio istovremeni uspjeh na drugom frontu. Tarnovo i Vidin bili su posljednja bugarska središta koja su se još držala.", "d6eaf4cd"]},
"OLAYLAR_EK:1388-08-27:0":{"b": ["Poraz kod Bileće", "89ba0a64"], "d": ["Akindžijski odred usmjeren na Bosnu upao je u zasjedu kod Bileće i uništen je; ta prva velika nevolja na Balkanu ohrabrila je savez koji je vodio ka Kosovu.", "9960a7a5"]},
"OLAYLAR_EK:1390-01-01:0":{"b": ["Aneksija zapadnoanadolskih bejluka: Saruhan, Aydın, Menteše", "dcc33b71"], "d": ["Tri bejluka pripojena su odjednom: Manisa, središte Saruhanovića; Aydın, središte Aydınovića (uključujući i gornju tvrđavu Izmira, dok su luka/donja tvrđava još bile kod vitezova svetog Ivana — do 1402); Muğla–Milas, središte Mentešovića, uključujući obalni pojas Datça–Bodrum–Marmaris–Fethiye. Egejske obale prvi put su se ujedinile pod jednom rukom. Ostala mjesta pripojena istog datuma: Söke.", "7f3094f2"]},
"OLAYLAR_EK:1392-01-01:0":{"b": ["Aneksija Teke oblasti: pripojenje Antalye", "fdbeee5c"], "d": ["Oblast Teke na obali Sredozemlja pripojena je osmanskim zemljama. Tekeovići su ogranak koji se odvojio od Hamidovića: Felekuddin Dundar-beg Antalyu koju je osvojio ostavio je svom bratu Junus-begu i oko 1321. nastao je zaseban bejluk. Zato se Antalya i okolica na karti nakon 1321. ne prikazuju bojom Hamidovića, nego bojom Tekeovića. Bejluk je ponovo uspostavljen nakon bitke kod Ankare i konačno likvidiran tek 1423.", "09a83d97"]},
"OLAYLAR_EK:1392-01-06:0":{"b": ["Osvajanje Skoplja", "9e5a1af5"], "d": ["Zauzeto je središte vardarske Makedonije; Skoplje je postalo jedno od glavnih pograničnih središta Rumelije.", "8722b1dd"]},
"OLAYLAR_EK:1392-11-01:0":{"b": ["Aneksija Kastamonua", "876330ba"], "d": ["Likvidiran je kastamonski ogranak Džandarovića; sinopski ogranak nastavio je kao vazal. Ostala mjesta pripojena istog datuma: Bartın, Safranbolu, Akçakoca, Devrek, Eflani, Karadeniz Ereğli, Tosya.", "c1158ca8"]},
"OLAYLAR_EK:1393-06-17:0":{"b": ["Pad Tarnova — aneksija Bugarske", "ff666977"], "d": ["Pala je prijestolnica Bugarskog carstva; Bugarska je došla pod izravnu osmansku upravu. Ostala mjesta pripojena istog datuma: Pleven, Loveč, Gabrovo.", "c2c12ea0"]},
"OLAYLAR_EK:1393-06-17:1":{"b": ["Tvrđava Loveč (Lofça) prešla Osmanlijama", "a55e87a0"], "d": ["Loveč, jedna od tvrđava bugarskog cara Ivana Šišmana, u pohodu 1393, kad je palo Tarnovo, pripojen je osmanskim zemljama zajedno s ostalim Šišmanovim oblastima. Izvor ne govori sa sigurnošću: «pretpostavlja se» da je osvajanje bilo te godine.", "9430a123"]},
"OLAYLAR_EK:1393-09-01:0":{"b": ["Pripojenje Dobrudže", "478e36f2"], "d": ["Pripojene su dobrudžanske zemlje koje se protežu do delte Dunava. Ostala mjesta pripojena istog datuma: Silistra, Konstanca, Babadag, Balčik, Hârșova, Tulča, Mangalia, Isaccea, Tutrakan, Măcin, Küçük Kaynarca (Kjučuk-Kajnardža).", "84901de2"]},
"OLAYLAR_EK:1394-01-01:0":{"b": ["Silazak u Tesaliju", "8bec60dd"], "d": ["Tesalijska ravnica sa središtem u Larisi došla je pod osmansku upravu. Ostala mjesta pripojena istog datuma: Trikala, Lamija.", "d9f2128c"]},
"OLAYLAR_EK:1394-10-10:0":{"b": ["Bitka na Rovinama — pohod na Vlašku", "343ae7a9"], "d": ["Nakon krvave bitke neizvjesnog ishoda s vlaškim vojvodom Mirčom, Vlaška je pristala plaćati harač Osmanlijama; sjeverno od Dunava uspostavljen je vazalni poredak.", "dd69200f"]},
"OLAYLAR_EK:1395-01-01:0":{"b": ["Osvajanje Nikopolja", "b9791717"], "d": ["Nakon bitke na Rovinama protiv Vlaha 1395, Bajazid Munja zauzeo je tvrđavu Nikopolj na obali Dunava; neke anonimne bugarske hronike navode da je do osvajanja došlo 3. juna 1395. Datum osvajanja u izvorima nije jedinstven: natuknica Bitka kod Nikopolja u TDV Islamskoj enciklopediji piše da je Bajazid zauzeo Silistru i Nikopolj u jednom dunavskom pohodu 1394. Tvrđava će biti opsjednuta u glasovitom krstaškom pohodu 1396, ali neće pasti. Ostala mjesta pripojena istog datuma: Ohrid.", "bc450a9f"]},
"OLAYLAR_EK:1395-06-03:0":{"b": ["Tvrđava Nikopolj prešla Osmanlijama", "327012c9"], "d": ["Nakon prepada na Rovinama Bajazid Munja zauzeo je Nikopolj; uklonjen je bugarski car Ivan Šišman, koji je ondje boravio kao osmanski vazal. U atlasu je Nikopolj od tog dana upisan kao prelazak od Bugarskog carstva Osmanlijama.", "6e7d5207"]},
"OLAYLAR_EK:1395-08-01:0":{"b": ["Izgradnja Anadolu Hisara", "aa259b00"], "d": ["Radi potpore blokadi Istanbula na anadolskoj strani Bosfora sagrađen je Güzelce Hisar (Anadolu Hisar) — prvi trajni korak ka nadzoru nad moreuzom.", "a1b2f889"]},
"OLAYLAR_EK:1396-10-01:0":{"b": ["Aneksija Vidina", "ee1ae44b"], "d": ["Nakon pobjede kod Nikopolja anektirana je i posljednja bugarska kneževina, Vidin.", "28f4258d"]},
"OLAYLAR_EK:1397-07-01:0":{"b": ["Prva aneksija Karamana", "3cf07876"], "d": ["Pobjedom kod Akčaja zemlje Karamanovića prvi put su pripojene Osmanlijama (u doba Fetreta bit će ponovo uspostavljene).", "788bdca3"]},
"OLAYLAR_EK:1398-07-01:0":{"b": ["Pripojenje obala Džanika: Samsun", "af9c40fa"], "d": ["U praznini nastaloj kad je Kadi Burhanuddin pao u zarobljeništvo Ak-Kojunlua Karajuluk Osman-bega, Bajazid Munja najprije je pod osmansku upravu stavio oblast Džanik na obali Crnog mora. Samsun i okolica tako su postali prva crnomorska luka dinastije. Unutrašnji pravac Sivas–Tokat–Kayseri bit će pripojen dvije sedmice kasnije, faktičkim raspadom države Kadi Burhanuddina.", "4b2f9a80"]},
"OLAYLAR_EK:1399-09-01:0":{"b": ["Zauzimanje Malatye", "7cb6ae16"], "d": ["Zauzeta je Malatya na memlučkoj granici — jedan od koraka koji su pojačali napetost s Timurom.", "3b7ba002"]},
"OLAYLAR_EK:1400-01-01:0":{"b": ["Timur zauzeo Malatyu i prepustio je Karajuluk Osmanu — kad se Timur povukao, Dulkadirovići su je povratili", "ad2ce7d8"], "d": ["Bajazid Munja Malatyu koju je zauzeo 1399. prepustio je Nasreddinu Mehmedu Dulkadirogluu i vratio se u Bursu. Timur, koji je 1400. ušao u Anadoliju, najprije je zauzeo Sivas i Elbistan, a zatim Malatyu; grad i okolica su opljačkani, a uprava prepuštena Karajuluk Osmanu koji je bio uz Timura. Kad je Timur napustio to područje, Malatyom su ponovo zavladali Dulkadirovići; tako je osmanska vlast okončana prije bitke kod Ankare.", "5889cce9"]},
"OLAYLAR_EK:1403-06-01:0":{"b": ["Ugovor Sulejmana Čelebije s Bizantom: povratak Soluna", "cc503cc2"], "d": ["Sulejman Čelebi, koji je u doba Fetreta vladao Rumelijom, sporazumom s Bizantom i latinskim državama prepustio je Bizantu Solun i crnomorske obale do Mesemvrije (TDV fetret-devri: Galipoljski ugovor, februar 1403) — na karti İğneada, Rezovo i Ahtopol prelaze Bizantu; na karti Solun toga datuma izlazi iz osmanskih ruku.", "ac791637"]},
"OLAYLAR_EK:1416-05-29:0":{"b": ["Pomorski poraz kod Galipolja (Venecija)", "b71d4d68"], "d": ["Venecijanska flota teško je porazila osmansku flotu pred Galipoljem; to je bio događaj koji je pokazao granice rane osmanske mornarice.", "7166c255"]},
"OLAYLAR_EK:1421-08-15:0":{"b": ["Ustanak Lažnog Mustafe (Düzmece Mustafa)", "0ec43138"], "d": ["Mustafa Čelebi, koji je tvrdio da je Munjin sin, uz bizantsku podršku proglasio je svoju vlast u Rumeliji; Murat II je 1422. ugušio ustanak i dao pogubiti suparnika.", "9bae8d0d"]},
"OLAYLAR_EK:1422-06-10:0":{"b": ["Opsada Istanbula Murata II", "4b9d9fba"], "d": ["U odgovor na bizantsku podršku Lažnom Mustafi Murat II opsjeo je Istanbul; opsada je podignuta kad je njegov brat Mustafa Mali potaknut na ustanak u Anadoliji.", "bc254acf"]},
"OLAYLAR_EK:1423-09-14:0":{"b": ["Predaja Soluna Veneciji", "bfa6c4a0"], "d": ["Bizantski namjesnik pod osmanskim pritiskom predao je grad Veneciji; počelo je osmansko-venecijansko nadmetanje koje će trajati sedam godina.", "da60fe5f"]},
"OLAYLAR_EK:1425-06-01:0":{"b": ["Ponovna aneksija zapadnoanadolskih bejluka: Menteše i Aydın", "aca30a48"], "d": ["Dva egejska bejluka, obnovljena u doba Fetreta, u vrijeme Murata II konačno su pripojena osmanskim zemljama. Prema TDV-ovoj natuknici Mentešovići, Murat II je 827. (1424) zauzeo oblast Menteše i dao zatvoriti dvojicu braće na čelu bejluka. Prema natuknici Aydınovići, anadolski beglerbeg Hamza-beg dao je uhvatiti Džunejd-bega, koji je ponovo otkazao poslušnost, i pogubiti ga s porodicom (829/1425-26), te je oblast Aydın prešla Osmanlijama. Vitezovi svetog Ivana, koji su od 1344. držali lučku tvrđavu Izmira, izgubili su je 1402. od Timura, pa se područje vratilo pod nadzor Aydınovića; ovom aneksijom i ona je pripojena Osmanlijama. Oblast Teke (Antalya) nije predmet ove stavke: Tekeovići su posebno likvidirani 1423. Germijan će biti pripojen oporukom 1429.", "92fa8d97"]},
"OLAYLAR_EK:1429-01-01:0":{"b": ["Aneksija Germijana oporukom", "9eb86b77"], "d": ["Germijanski beg Jakub II, koji je umro bez djece, oporukom je ostavio svoju zemlju Osmanlijama — udžbenički primjer aneksije bez rata. Ostala mjesta pripojena istog datuma: Karahisar-i Sahib (Afyon).", "9173c7b2"]},
"OLAYLAR_EK:1430-03-29:0":{"b": ["Konačno osvajanje Soluna", "bc021768"], "d": ["Grad pod venecijanskom upravom zauzet je jurišem; druga velika luka Rumelije konačno je postala osmanska. Ostala mjesta pripojena istog datuma: Kasandra.", "8853e257"]},
"OLAYLAR_EK:1430-10-09:0":{"b": ["Predaja Janjine", "ee45cb52"], "d": ["Janjina, središte Epira, predala se ugovorom.", "1aad46c0"]},
"OLAYLAR_EK:1439-08-27:0":{"b": ["Prvo zauzimanje Smedereva", "c11ca17d"], "d": ["Nakon tromjesečne opsade zauzeta je prijestolnica Srpske despotovine i Srbija je prvi put anektirana (vratit će se Edirnsko-segedinskim mirom 1444).", "3dc4dfe5"]},
"OLAYLAR_EK:1440-04-01:0":{"b": ["Opsada Beograda (neuspješna)", "3e05f425"], "d": ["Prva velika šestomjesečna opsada Beograda ostala je bez rezultata; tvrđava je osamdeset godina ostala brava pred osmanskim napredovanjem.", "2a88be8a"]},
"OLAYLAR_EK:1443-11-24:0":{"b": ["Poraz kod Zlatice (İzladi) — 'Duga vojna'", "97df1466"], "d": ["Vojska koju je Hunyadi usred zime uveo na Balkan prošla je Niš i Sofiju i došla do Zlatice; osmanska odbrana jedva se održala. To ozračje poraza dovelo je Edirnsko-segedinski mir na pregovarački stol.", "cf103982"]},
"OLAYLAR_EK:1444-06-12:0":{"b": ["Edirnsko-segedinski mir", "0aa4e0de"], "d": ["Desetogodišnji mir: Srpska despotovina je vraćena, Dunav prihvaćen kao granica. To što je ugovor za nekoliko mjeseci prekršen na poticaj papinstva dovelo je do katastrofe kod Varne.", "46b3ced6"]},
"OLAYLAR_EK:1444-08-15:0":{"b": ["Povratak Smedereva i srpskih tvrđava Srbiji", "cda3cf9e"], "d": ["Provedena je odredba Edirnsko-segedinskog mira: Murat II je 15. augusta 1444. Đurđu Brankoviću vratio Smederevo s dvadeset četiri važne tvrđave i s ostalim okupiranim srpskim zemljama (TDV semendire); Niš (TDV nis), Kruševac (Alacahisar; TDV alacahisar), Pirot (Şehirköy; TDV sehirkoy) i Priština (TDV pristine) također su prepušteni Srbima. Vidin, budući da nije bio srpska zemlja, nije ušao u povrat — to je izvor sjeverozapadnog teritorijalnog gubitka koji se na karti vidi oko vremena pobjede kod Varne; nekoliko mjeseci kasnije, s porazom kod Varne, ugovor će ionako postati nevažeći.", "19c68a1f"]},
"OLAYLAR_EK:1452-08-31:0":{"b": ["Dovršen Rumeli Hisar — 'Boğazkesen' (Presjekač moreuza)", "480e8a76"], "d": ["Tvrđavom, dovršenom izvanredno brzom gradnjom koja je prema izvorima trajala četiri-pet mjeseci, nadzor nad Bosforom potpuno je prešao Osmanlijama; zatvoren je put pomoći Istanbulu s Crnog mora. Smatra se faktički prvim korakom opsade.", "1d84cd36"]},
"OLAYLAR_EK:1453-04-06:0":{"b": ["Počela opsada Istanbula", "8af50742"], "d": ["Vojska se rasporedila pred bedemima; u opsadi koja će trajati 54 dana golemi topovi prvi su put sistematski korišteni protiv bedema jedne prijestolnice.", "6d71da31"]},
"OLAYLAR_EK:1453-04-22:0":{"b": ["Brodovi kopnom spušteni u Zlatni rog", "4f2ba07c"], "d": ["Od flote koja nije mogla ući u lancem zatvoreni Zlatni rog oko 70 brodova prevučeno je na namazanim saonicama preko brda Galate i za jednu noć spušteno u Zlatni rog; odbrana je podijeljena na dva fronta.", "2eb65d41"]},
"OLAYLAR_EK:1456-06-04:0":{"b": ["Osvajanje Atine", "4f0f1bb2"], "d": ["Atinsko vojvodstvo prestalo je postojati; na Akropolju je razvijena osmanska zastava. Ostala mjesta pripojena istog datuma: Teba, Livadia.", "a912625d"]},
"OLAYLAR_EK:1459-06-20:0":{"b": ["Aneksija Srbije (pad Smedereva)", "75fd0a62"], "d": ["Predalo se Smederevo, prijestolnica Srpske despotovine; Srbija je postala osmanski sandžak.", "29bd2888"]},
"OLAYLAR_EK:1460-05-29:0":{"b": ["Osvajanje Moreje", "7d5a3c18"], "d": ["Morejska despotovina je likvidirana; poluotok (osim venecijanskih tvrđava) došao je pod osmansku upravu.", "14aba74c"]},
"OLAYLAR_EK:1461-06-01:0":{"b": ["Pripojenje Sinopa", "e03c2739"], "d": ["Sinop Džandarovića predao se bez borbe; otvoren je put za pohod na Trabzon. Ostala mjesta pripojena istog datuma: Kastamonu, Bartın, Safranbolu. TDV-ova natuknica Džandarovići među zemljama bejluka Džandarovića anektiranim 1461. spominje i Bolu, Eflani i Tosyu; u atlasu su i ta tri mjesta od tog dana upisana kao prelazak od Džandarovića Osmanlijama. Ostala naselja izgubljena istog datuma: Karadeniz Ereğli, Devrek, Akçakoca (zemlja Džandarovića).", "9ead5a1c"]},
"OLAYLAR_EK:1463-06-01:0":{"b": ["Pad Bosanskog kraljevstva — Osvajačev pohod na Bosnu", "5362e3f2"], "d": ["Kad je posljednji bosanski kralj Stjepan Tomašević (1461-1463), oslanjajući se na podršku Zapada, odbio platiti harač, smatrano je da je prestao biti vazalni vladar, i vojska pod komandom sultana Mehmeda Osvajača u jednom je pohodu likvidirala Bosansko kraljevstvo. Kralj je uhvaćen i pogubljen, kraljevstvo je nestalo i na tom je području osnovan Bosanski sandžak. Ali pad kraljevstva nije isto što i osvajanje Bosne. Osmanska uprava u ravnici postojala je već petnaest godina — Hodidjed i Sarajevsko polje zauzeti su 1448, a Isa-begovo krajište uspostavljeno je usred kraljevstva. Osvajanje nije završilo ni 1463: Foča je zauzeta 1465, Livno 1469, Hercegovačko vojvodstvo 1483, Srebrenička banovina 1512, a Jajce i Banja Luka na sjeveru tek nakon Mohača, 1528 — Mađari su nakon 1463. na sjeveru Bosne uspostavili banovinu koja se održala šezdeset pet godina. Mjesto koje toga datuma izravno mijenja vlasnika je Travnik; Jajce pak toga datuma nije prešlo Osmanlijama, nego Ugarskoj.", "5ac16344"]},
"OLAYLAR_EK:1468-01-01:0":{"b": ["Konačna aneksija Karamana", "f1dcecaa"], "d": ["Središnje zemlje Karamanovića konačno su pripojene; unutrašnji sukobi trajali su do 1470-ih. Ostala mjesta pripojena istog datuma: Niğde, Mostar, Beyşehir.", "da6cfd4c"]},
"OLAYLAR_EK:1470-07-12:0":{"b": ["Osvajanje Eubeje (Eğriboz)", "5c97daf3"], "d": ["Pala je Eubeja, glavno venecijansko uporište na Egeju.", "189cc474"]},
"OLAYLAR_EK:1471-01-01:0":{"b": ["Aneksija Alanye, Anamura i Silifkea (İçel)", "a0b9d461"], "d": ["Obalni pojas İçela vezan za Karamanoviće (cijela obala Sredozemlja između Antalye i Mersina) pripojen je pomorskim pohodom Gedik Ahmed-paše; Alanya je bila važna zbog strateškog brodogradilišta naslijeđenog iz seldžučkog doba.", "8302df58"]},
"OLAYLAR_EK:1478-01-15:0":{"b": ["Pripojenje Novgoroda Moskvi", "bed87170"], "d": ["Veliki knez Ivan III uklonio je simbolično zvono novgorodske narodne skupštine (veče), lokalne upravitelje zamijenio vlastitim namjesnicima i grad faktički pripojio Moskvi; Novgorod je prestao biti nezavisna republika. Novgorodska zemlja protezala se od Baltičkog do Bijelog mora i do Urala. U atlasu je Novgorod od tog dana upisan kao prelazak od Novgorodske Republike Moskvi.", "65b660e7"]},
"OLAYLAR_EK:1479-01-25:0":{"b": ["Istanbulski mir — Albanija i Skadar", "b09652f7"], "d": ["Okončan je šesnaestogodišnji osmansko-venecijanski rat; Skadar i albanske obale ostali su Osmanlijama. Ostala mjesta pripojena istog datuma: Limni, Samos, Agios Efstratios (Bozbaba).", "bc2aebf2"]},
"OLAYLAR_EK:1480-08-11:0":{"b": ["Iskrcavanje kod Otranta", "7916b89d"], "d": ["Osmanske snage koje su se iskrcale na obalu Apulije opsjele su i zauzele tvrđavu Otranto; budući da se u grad ušlo borbom, dio uglednika koji su pružali otpor pogubljen je, a dio zarobljen. Crkvena tradicija poginule spominje kao 'otrantske mučenike', njih oko 800; TDV preuveličavanje tog broja pripisuje crkvenoj propagandi. Zadržani su samo tvrđava na vrhu poluotoka Salento i uska okolica; ostale zemlje Napuljskog kraljevstva na pravcu Taranto–Brindisi–Lecce nisu izgubljene — taj mostobran prema Italiji trajat će godinu dana.", "0e1004b8"]},
"OLAYLAR_EK:1481-09-10:0":{"b": ["Evakuacija Otranta", "37371bb0"], "d": ["Nakon smrti sultana Mehmeda Osvajača (3. maja 1481) garnizon Otranta, kojem više nije preostala nada u nova pojačanja, pred opsadom napuljskog prijestolonasljednika Alfonsa evakuirao je tvrđavu po sporazumu; tako je jedini osmanski mostobran u Italiji izgubljen godinu dana kasnije.", "961ef9c3"]},
"OLAYLAR_EK:1500-08-09:0":{"b": ["Osvajanje Modona i Korona", "38b608c4"], "d": ["Zauzeti su Modon i Koron, 'dva oka' Venecije u Moreji.", "a11c09d0"]},
"OLAYLAR_EK:1501-08-17:0":{"b": ["Osvajanje Drača", "1f231b98"], "d": ["Tokom osmansko-venecijanskog rata 1499-1503, snage pod komandom Mehmed-bega zauzele su Drač, posljednju veliku venecijansku albansku luku na Jadranu. Nakon Skadra (1479) i Vlore (1417), ovim je osvajanjem cijeli albanski obalni pojas došao pod osmanski nadzor.", "ad635bca"]},
"OLAYLAR_EK:1515-09-15:0":{"b": ["Pripojenje istočne Anadolije", "e0cb8f8f"], "d": ["Nakon Čaldirana pripojeni su Diyarbakır i okolica; kurdski bejluci posredstvom Idrisa Bitlisija vezani su za Osmanlije.", "025d3ddc"]},
"OLAYLAR_EK:1526-07-27:0":{"b": ["Osvajanje tvrđave Varadin (Petrovaradin)", "abf392a5"], "d": ["Vojska koja je krenula na Mohački pohod prešla je iz Beograda na ugarsko tlo; najprije su zauzeta predgrađa Varadina, a nakon četrnaestodnevne opsade pala je i tvrđava. Zakonodavac je naredio da se sela na putu ne pale, jer su se ta mjesta već smatrala osmanskom zemljom.", "60a4ae4e"]},
"OLAYLAR_EK:1526-09-01:0":{"b": ["Predaja Budima nakon Mohača — dva kralja za ugarsko prijestolje", "9d3568a0"], "d": ["Osmanskoj vojsci koja je nakon pobjede kod Mohača krenula na Budim ključevi grada predati su sultanu 11. septembra 1526; međutim, Zakonodavac nije zadržao Budim i povukao je vojsku. U Ugarskoj koja je ostala bez kralja plemići su izabrali dva zasebna kralja: 10. novembra 1526. Ivana Zapolju (János Szapolyai), a 17. decembra 1526. Ferdinanda I Habsburškog. Ferdinand je zauzeo Budim u augustu 1527. Zapoljino useljenje u Budim kao kralja pod osmanskom zaštitom uslijedit će pohodom 1529. (v. stavku za 1529), a izravna osmanska uprava uspostavit će se 1541.", "d68817d3"]},
"OLAYLAR_EK:1526-11-10:0":{"b": ["Ivan Zapolja izabran za ugarskog kralja — Osmanlije mu priznale kraljevstvo uz uvjet vazalnosti", "32bc6baf"], "d": ["Na ugarsko prijestolje, upražnjeno smrću kralja kod Mohača, dio plemstva izabrao je erdeljskog vojvodu Ivana Zapolju; Zapolja je okrunjen u Stolnom Biogradu. Osmanlije, koje su ispraznile Budim, da bi to područje zadržale kao tampon, priznale su Zapoljino kraljevstvo uz uvjet da im bude vazalno. Na karti mjesta vezana za Zapolju od toga datuma prikazuju se kao vazalna Osmanlijama.", "1d697cbd"]},
"OLAYLAR_EK:1526-12-17:0":{"b": ["Ferdinand I proglašen ugarskim kraljem — zapadna i sjeverna Ugarska habsburškoj kruni", "b3910a2f"], "d": ["Habsburški nadvojvoda Ferdinand, pozivajući se na brak svoje sestre s Lajošem II, polagao je pravo na ugarsko prijestolje i dio plemstva proglasio ga je kraljem. Ugarska se tako podijelila između dva kralja; zapadni i sjeverni dio priznao je Ferdinanda. Hrvatsko plemstvo zasebno ga je izabralo početkom 1527.", "1484af4c"]},
"OLAYLAR_EK:1530-01-01:0":{"b": ["Sukob dvaju kraljeva: Ostrogon pod habsburškom zaštitom, Segedin Zapolji", "da92dee5"], "d": ["Ostrogon, koji je od 1526. prelazio između dva kralja, došao je pod habsburšku zaštitu nakon što je nadbiskup s arhivom i riznicom prešao na sjever. Od iste godine do 1541. Segedin je ostao pod Zapoljinom vlašću.", "4317e319"]},
"OLAYLAR_EK:1532-01-01:0":{"b": ["Stanovnici Pečuha prešli na Zapoljinu stranu", "3fc4e7f2"], "d": ["Pečuh, koji je 1528. dobio povlastice od Ferdinanda, uskoro je prešao na Zapoljinu stranu; kralj Ivan neko je vrijeme 1533. boravio u gradu. Padom Budima 1541. grad se ponovo vratio na Ferdinandovu stranu.", "af03d9f3"]},
"OLAYLAR_EK:1551-08-15:0":{"b": ["Osvajanje Tripolija", "8c659986"], "d": ["Tripoli je oduzet vitezovima svetog Ivana; srednja obala sjeverne Afrike postala je osmanska. Ostala mjesta pripojena istog datuma: Misrata.", "f3a5310d"]},
"OLAYLAR_EK:1552-07-27:0":{"b": ["Osvajanje Temišvara", "e9fd4995"], "d": ["Zauzeta je oblast Banata i osnovan Temišvarski beglerbegluk.", "1b99085d"]},
"OLAYLAR_EK:1574-08-25:0":{"b": ["Konačno osvajanje Tunisa", "7bbd11bc"], "d": ["Tunis pod španjolsko-hafsidskim nadzorom konačno je došao pod osmansku upravu; upotpunjena je sjevernoafrička linija. Ostala mjesta pripojena istog datuma: Kairuan, Gabes, Sfax.", "a92c818a"]},
"OLAYLAR_EK:1600-10-20:0":{"b": ["Osvajanje Kaniže", "0c7b6aa3"], "d": ["U Dugom ratu zauzeta je Kaniža; sljedeće godine odbrana Tirjaki Hasan-paše postala je epska.", "12042d94"]},
"OLAYLAR_EK:1663-04-13:0":{"b": ["Počeo pohod na Nove Zamke (Uyvar) — Fazil Ahmed-paša krenuo iz Edirne na Austriju", "306a86db"], "d": ["Nakon što je Austrija napala Erdelj i zauzela tvrđave Székelyhíd i Koložvar, Istanbul je odlučio krenuti u pohod na Habsburgovce. Veliki vezir Köprülüzade Fazil Ahmed-paša krenuo je iz Edirne 13. aprila 1663. U Beograd je stigao austrijski zahtjev za mir, ali su na dva razgovora u Osijeku odbijeni osmanski uvjeti. I na vijećanju u Budimu kao cilj su određeni Nove Zamke.", "f77c2f04"]},
"OLAYLAR_EK:1663-09-24:0":{"b": ["Osvajanje Novih Zamkova (Uyvar)", "ce289470"], "d": ["Zauzeti su Nove Zamke, ključna tvrđava sjeverne Ugarske; izreka 'jak kao Turčin pred Novim Zamkama' ušla je u evropske jezike. Nakon Novih Zamkova i Nitra i Levice predale su se nakon kratkog otpora; obje je u proljeće 1664. povratio De Souches.", "80ef48fc"]},
"OLAYLAR_EK:1715-07-01:0":{"b": ["Povratak Moreje", "9b6460f1"], "d": ["Moreja, koja je Karlovačkim mirom prepuštena Veneciji, vraćena je u jednom pohodu. Ostala mjesta pripojena istog datuma: Patras, Lepant (İnebahtı).", "56dc13ce"]},
"OLAYLAR_EK:1717-08-18:0":{"b": ["Drugi gubitak Beograda — opsada princa Eugena", "6a194354"], "d": ["Nakon poraza kod Varadina i gubitka Temišvara princ Eugen opsjeo je Beograd; kad je poražena i vojska za pomoć koja je došla spasiti grad, tvrđava se predala. Grad, povraćen 1690. a nakon Karlovaca zadržan, tako je ponovo izgubljen i srušena je dunavska odbrambena linija. Beograd će se moći povratiti tek dvadeset dvije godine kasnije, Beogradskim mirom 1739. Ostala naselja izgubljena istog datuma: Smederevo. Atlas, osim toga, područja Grocke (Hisarcık) i Jagodine toga dana upisuje Habsburgovcima (regionalni datum; datum na razini mjesta nema u izvoru, deklarirana približnost); Mehadia pak prelazi Habsburgovcima s datumom 27. augusta 1717. (Bánlaky 0019/1715).", "83c63cd6"]},
"OLAYLAR_EK:1788-12-17:0":{"b": ["Pad Očakova (Özi)", "90a67a6c"], "d": ["Očakov, ključna tvrđava sjeverno od Crnog mora, pao je u ruske ruke u krvavom jurišu; gradsko stanovništvo posječeno je sabljom.", "9d37026c"]},
"OLAYLAR_EK:1812-05-28:0":{"b": ["Bukureštanski mir — gubitak Besarabije", "932da4d6"], "d": ["Ugovorom koji je okončao rusko-turski rat 1806-1812. područje istočno od Pruta (Besarabija) prepušteno je Rusiji. Ostala naselja izgubljena istog datuma: Akkerman, Kilija, Hotin, Bender, Izmail. Atlas, osim toga, i Kišinjev (Chișinău), Bălți, Kahul i Orhei unutar Besarabije smatra mjestima koja su istog dana iz Moldavije (osmanskog vazala) prešla Rusiji. I Soroka prelazi Rusiji istog dana.", "b5921c60"]},
"OLAYLAR_EK:1829-09-14:0":{"b": ["Jedrenski mir", "b3a8fe4c"], "d": ["Na kraju rata u kojem je ruska vojska ušla u Edirne izgubljena je delta Dunava; autonomija/nezavisnost Grčke faktički je prihvaćena. Ostala naselja izgubljena istog datuma: Brăila, Anapa, Ahalcihe. Iako je ugovorom teritorij vraćen, okupacija nije odmah okončana: Vlaška i Moldavija te Silistra ostale su kao zalog pod ruskom upravom do isplate ratne odštete — to je razlog što se ta mjesta na karti i nakon 1829. vide pod okupacijom. Ovim je ugovorom okončano i osmansko pravo na Čerkesiju (Majkop) i čerkesku obalu (Soči, Tuapse); obala je kasnije prešla Rusiji (Soči i Tuapse 1838).", "5666619b"]},
"OLAYLAR_EK:1830-10-17:0":{"b": ["Ferman o autonomiji Srbije — nasljedna kneževina i uvjet garnizona", "6a5d901d"], "d": ["Hatt-i humajunom izdatim na osnovu odredbe Jedrenskog mira o Srbiji Miloš Obrenović priznat je za nasljednog kneza, a Srbija je postala autonomna kneževina, slobodna u unutrašnjim poslovima i vanjski vezana za Osmansko Carstvo. Odredbe: kneževsko dostojanstvo prelazit će s oca na sina, godišnji porez plaćat će se u paušalnom iznosu, srpska skupština uspostavit će vlastitu unutrašnju upravu, crkva će biti autonomna; zauzvrat će u tvrđavama Beograd, Smederevo, Šabac, Böğürdelen i Fethülislam ostati osmanski garnizoni. Ta dvojna struktura trajala je do povlačenja garnizona 1867. Na karti se grad Beograd toga datuma pridružuje autonomnoj Srbiji; tvrđava Kalemegdan do 1867. prikazuje se s osmanskim garnizonom.", "b71abc85"]},
"OLAYLAR_EK:1878-06-04:0":{"b": ["Kipar prepušten engleskoj upravi", "423da3ee"], "d": ["U zamjenu za savez protiv ruske prijetnje uprava nad Kiprom predata je Engleskoj; pravno je ostao osmanski teritorij. Ostala naselja izgubljena istog datuma: Nikozija, Famagusta, Kirenija, Limasol, Larnaka (Tuzla), Pafos, Morphou (Güzelyurt), Akrotiri, Episkopi, Dhekelia; to jest cijeli otok.", "d1abea1c"]},
"OLAYLAR_EK:1881-07-02:0":{"b": ["Tesalija prepuštena Grčkoj", "ac614d24"], "d": ["Prema odlukama Berlinskog kongresa Tesalija i okolica Arte predate su Grčkoj. Ostala naselja izgubljena istog datuma: Arta, Larisa, Trikala, Lamija. Ovom predajom Grčkoj su prešli i Volos, Kalambaka i Karditsa (Tesalija).", "9fc28546"]},
"OLAYLAR_EK:1885-09-18:0":{"b": ["Pripojenje Istočne Rumelije Bugarskoj", "ee43f137"], "d": ["Autonomni vilajet Istočna Rumelija pučem je pripojen Bugarskoj; Porta je prihvatila svršen čin. Tim ujedinjenjem cijela Istočna Rumelija (Stara Zagora, Pazardžik, Sliven, Haskovo, Burgas, Aitos, Elhovo) prešla je Kneževini Bugarskoj.", "7fe3cc42"]},
"OLAYLAR_EK:1897-05-17:0":{"b": ["Bitka kod Domokosa", "9c6f29a5"], "d": ["U grčko-turskom ratu 1897. vojska je kod Domokosa izvojevala odlučnu pobjedu; pod diplomatskim pritiskom teritorijalni dobitak ostao je ograničen.", "aff8be0b"]},
"OLAYLAR_EK:1898-12-22:0":{"b": ["Autonomija Krete", "2e764881"], "d": ["Iako je grčko-turski rat završio osmanskom pobjedom, Engleska, Rusija, Francuska i Italija 18. decembra 1897. proglasile su autonomiju Krete; otok je trebao biti neutralan i autonoman vilajet pod osmanskim suverenitetom. Nakon 6. novembra 1898. u Kandiji i Kisamu turska zastava više se nije isticala; stupanjem na dužnost princa Georga, sina grčkog kralja, kao visokog komesara 22. decembra 1898. Kreta je faktički izašla iz osmanske uprave (službeno se odvojila 1913). Ostala naselja izgubljena istog datuma: Kandija (Kreta), Hanja.", "bc35b2a6"]},
"OLAYLAR_EK:1908-10-05:0":{"b": ["Nezavisnost Bugarske i aneksija Bosne", "393feaa4"], "d": ["U zbrci mešrutijeta Bugarska je proglasila nezavisnost, a Austro-Ugarska anektirala Bosnu i Hercegovinu. Tim proglašenjem sve zemlje Kneževine Bugarske (Varna, Šumen, Ruse, Burgas, Sliven i dr.) postale su nezavisno Kraljevstvo Bugarska.", "b7f0bb26"]},
"OLAYLAR_EK:1913-07-21:0":{"b": ["Povratak Edirne", "536e5599"], "d": ["U Drugom balkanskom ratu vojska je prešla Maricu i bez borbe povratila Edirne. Ostala mjesta pripojena istog datuma: Kırklareli, Tekirdağ.", "e5420880"]},
"OLAYLAR_EK:1916-04-29:0":{"b": ["Pobjeda kod Kut al-Amare", "98b972bc"], "d": ["Komandant engleske divizije opkoljene u Kutu predao se s 13 hiljada vojnika — jedna od najvećih osmanskih pobjeda u Prvom svjetskom ratu.", "20105888"]},
"OLAYLAR_EK:1917-03-11:0":{"b": ["Gubitak Bagdada", "2c18a816"], "d": ["Osmanski Bagdad, star 383 godine, prešao je u ruke engleske vojske. Ostala naselja izgubljena istog datuma: Kerbela, Kizilrubat.", "880969bf"]},
"OLAYLAR_EK:1917-12-09:0":{"b": ["Gubitak Jerusalema", "94067617"], "d": ["Osmanski Jerusalem, star 401 godinu, predat je bez odbrane.", "f2738a38"]},
"OLAYLAR_EK:1918-10-01:0":{"b": ["Gubitak Damaska", "ed177b68"], "d": ["Slomom palestinskog fronta Damask je evakuiran; četiri stoljeća osmanske uprave u Siriji okončana su. Ostala naselja izgubljena istog datuma: Hama, Homs.", "ff6aea3f"]},
"OLAYLAR_EK:1919-01-10:0":{"b": ["Predaja Medine", "76b505f6"], "d": ["72 dana nakon primirja otpor 'Pustinjskog tigra' Fahreddin-paše okončan je sultanovom voljom; posljednja osmanska jedinica u Hidžazu položila je oružje.", "06b180d9"]},
"OLAYLAR_EK:1919-05-15:0":{"b": ["Okupacija Izmira", "e32e5e77"], "d": ["Grčka vojska iskrcala se u Izmiru; otpor koji je počeo prvim metkom zapalio je fitilj Narodnooslobodilačke borbe. Aydın je pak okupiran 27. maja 1919. (zasebna stavka).", "4cc27e6b"]},
"OLAYLAR_EK:1920-03-16:0":{"b": ["Službena okupacija Istanbula", "a8e98ada"], "d": ["Snage Antante službeno su okupirale Istanbul, Zastupnički dom je raspušten; zastupnici su se uputili u Ankaru.", "09ed005b"]},
"OLAYLAR_FRANSA_KONTROL_1027:1284-01-01:0":{"b": ["Grofovija Champagne vezana je za francusku krunu brakom Ivane I s Filipom IV: Troyes (zajedno s Meauxom)", "cae2654d"], "d": ["Brakom šampanjske grofice i navarske kraljice Ivane I s francuskim prijestolonasljednikom Filipom (IV) (1284.) Troyes, glavni grad Champagne, ušao je u kraljevske zemlje; za Meaux Treccani navodi da je iste godine (1284.) 'prešao francuskom kralju'. Zvanična aneksija grofovije bila je 1314., stupanjem Luja X na prijestolje (titula t).", "03072856"]},
"OLAYLAR_FRANSA_KONTROL_1027:1305-01-01:0":{"b": ["Flandrijski grof prepustio je Valonsku Flandriju (Lille, Douai, Béthune) francuskom kralju Filipu IV: Lille", "a4746f27"], "d": ["'Francuski' (valonski) dio Grofovije Flandrije — kaštelanije Douai, Béthune i Lille — dat je 1305. francuskom kralju (konačna predaja 1320.); 1369. ih je brakom dobio burgundski vojvoda.", "fa06bb72"]},
"OLAYLAR_FRANSA_KONTROL_1027:1312-01-01:0":{"b": ["U Lyonu je uspostavljeno vrhovništvo francuskog kralja: Filip IV (Lijepi) Vienneskim ugovorom preuzeo je Lyon, carski feud", "60ea68d8"], "d": ["U Lyonu, koji je od 1032. bio feud njemačkog cara, a stvarnu moć dijelili su nadbiskup i grofovi Foreza, 1312. uspostavljeno je vrhovništvo francuskog kralja Filipa IV; od tog datuma grad se smatra francuskim.", "74a8638d"]},
"OLAYLAR_FRANSA_KONTROL_1027:1314-11-29:0":{"b": ["Umro je Filip IV; francuski kralj postao je Luj X (Hutin)", "10fd76ef"], "d": ["Filip IV umro je 29. novembra 1314.; na francusko prijestolje stupio je njegov sin Luj X (već od 1305. kralj Navare).", "3aa6f8e3"]},
"OLAYLAR_FRANSA_KONTROL_1027:1317-01-09:0":{"b": ["Filip V okrunjen je u Reimsu (nakon smrti Luja X bio je regent, a nakon smrti nećaka Ivana I proglasio se kraljem)", "3b50d3fc"], "d": ["Luj X umro je 5. jula 1316.; regent Filip V proglasio se kraljem nakon posthumno rođenog sina Ivana I, koji je umro 4 dana nakon rođenja, i okrunio se u Reimsu 9. januara 1317. Dan proglašenja nije naveden u izvoru; atlas uzima dan krunidbe.", "5e0b5084"]},
"OLAYLAR_FRANSA_KONTROL_1027:1322-01-03:0":{"b": ["Umro je Filip V; francuski kralj postao je Karlo IV", "a0b9abda"], "d": ["Filip V umro je u Longchampu u noći 2. januara 1322.; na prijestolje je stupio njegov brat Karlo IV.", "a4efde24"]},
"OLAYLAR_FRANSA_KONTROL_1027:1328-05-29:0":{"b": ["Filip VI (Valois) okrunjen je u Reimsu: počela je dinastija Valois", "a9595d82"], "d": ["Kada je Karlo IV u februaru 1328. umro bez muškog nasljednika, Filip de Valois postao je regent; 29. maja 1328. okrunio se u Reimsu i započeo dinastiju Valois. Pretenzija engleskog kralja Edvarda III po majčinoj liniji jedna je od iskri Stogodišnjeg rata.", "aca69718"]},
"OLAYLAR_FRANSA_KONTROL_1027:1348-06-09:0":{"b": ["Napuljska kraljica Ivana prodala je Avignon papi Klementu VI", "ecd3d028"], "d": ["U svojstvu grofice Provanse, napuljska kraljica Ivana 9. juna 1348. prodala je grad Avignon papi Klementu VI za 80.000 florina; grad je do 1791. ostao papinska eksklava. Zapis o naselju već je sadržavao tu granicu; natuknica je nedostajala.", "682eb4f6"]},
"OLAYLAR_FRANSA_KONTROL_1027:1349-04-18:0":{"b": ["Filip VI otkupio je Montpellier od kralja Majorke", "05d06418"], "d": ["Prodaja prava kralja Majorke Jakova III na Montpellier francuskom kralju Filipu VI potvrđena je 18. aprila 1349.; Montpellier je prešao francuskoj kruni.", "302b9de1"]},
"OLAYLAR_FRANSA_KONTROL_1027:1349-07-16:0":{"b": ["Humbert II prenio je Dauphiné na unuka francuskog kralja: Grenoble", "a8d8a248"], "d": ["Između Humberta II i francuskog kralja 30. marta 1349. sklopljen je ugovor u Romansu; 16. jula 1349. u Lyonu je ispravom 'Transport du Dauphiné à la France' zemlja i titula Dauphinéa prepuštena Karlu (unuku francuskog kralja Filipa VI). Od tog trenutka 'Dauphin' je titula prijestolonasljednika Francuske.", "c129d1f5"]},
"OLAYLAR_FRANSA_KONTROL_1027:1350-08-22:0":{"b": ["Umro je Filip VI; francuski kralj postao je Ivan II (Dobri)", "3eb96ab5"], "d": ["Filip VI umro je 22. augusta 1350. u Nogent-le-Roiju; na prijestolje je stupio njegov sin Ivan II.", "ed19aa83"]},
"OLAYLAR_FRANSA_KONTROL_1027:1360-10-24:0":{"b": ["Ugovor u Calaisu: potvrđeni su uslovi iz Brétignyja, Poitou i Akvitanija prepušteni Engleskoj: Poitiers", "8e13271f"], "d": ["Preliminarni sporazum iz Brétignyja od 8. maja 1360. potvrđen je u Calaisu 24. oktobra 1360.: Poitou, Saintonge, Aunis, Agenais, Périgord, Limousin, Quercy, Angoumois i Rouergue prepušteni su Engleskoj. Limoges, La Rochelle i Poitiers u atlasu tog dana prelaze Engleskoj.", "278ddde1"]},
"OLAYLAR_FRANSA_KONTROL_1027:1388-09-28:0":{"b": ["Nica se predala savojskom grofu Amedeu VII ('dédition' Nice Savoji)", "3af46844"], "d": ["Za vrijeme nasljednog spora anžujskih nasljednika Provanse, Nica i okolina (Grofovija Nica) 28. septembra 1388. došle su pod vlast savojskog grofa Amedea VII; Nica je do 1860. (osim francuskih okupacija) ostala u dinastiji Savoja/Sardinije. Atlas je tu granicu već sadržavao; natuknica je nedostajala.", "04a5e558"]},
"OLAYLAR_FRANSA_KONTROL_1027:1420-05-21:0":{"b": ["Ugovor u Troyesu: Henrik V postao je regent i nasljednik Francuske, Champagne je došla pod englesko-burgundsku upravu: Troyes", "21c6f014"], "d": ["Ugovor potpisan u Troyesu 21. maja 1420. između Karla VI i engleskog kralja Henrika V učinio je Henrika V regentom Francuske i nasljednikom prijestolja; dofen Karlo (Karlo VII) isključen je iz naslijeđa. Ugovorom se ne ustupa teritorija; Champagne (Troyes, Reims) od tog datuma do 1429. ostala je pod englesko-burgundskom upravom ('lankasterska Francuska') i atlas tu upravu boji identitetom Engleske.", "e9351409"]},
"OLAYLAR_FRANSA_KONTROL_1027:1420-05-21:1":{"b": ["Ugovor u Troyesu: Henrik V postao je regent i nasljednik Francuske, Champagne je došla pod englesko-burgundsku upravu: Reims", "5d0dea46"], "d": ["Ugovor potpisan u Troyesu 21. maja 1420. između Karla VI i engleskog kralja Henrika V učinio je Henrika V regentom Francuske i nasljednikom prijestolja; dofen Karlo (Karlo VII) isključen je iz naslijeđa. Ugovorom se ne ustupa teritorija; Champagne (Troyes, Reims) od tog datuma do 1429. ostala je pod englesko-burgundskom upravom ('lankasterska Francuska') i atlas tu upravu boji identitetom Engleske.", "e9351409"]},
"OLAYLAR_FRANSA_KONTROL_1027:1420-12-01:0":{"b": ["Henrik V ušao je u Pariz: počeo je englesko-burgundski režim", "126d50cb"], "d": ["Nakon ugovora u Troyesu (21. maja 1420.), u decembru 1420. Pariz je došao pod englesko-burgundsku vlast; gradom se do aprila 1436. upravljalo u ime Henrika VI. Ostala naselja izgubljena istog datuma: Sèvres, Fontainebleau, Saint-Germain-en-Laye, Versailles, Neuilly-sur-Seine (okolina Pariza).", "0fb14bbf"]},
"OLAYLAR_FRANSA_KONTROL_1027:1422-10-21:0":{"b": ["Umro je Karlo VI; Karlo VII proglašen je za francuskog kralja", "7aeefd1a"], "d": ["Karlo VI umro je 21. oktobra 1422.; uprkos ugovoru u Troyesu, Karlo VII proglasio se kraljem (oblast Bourgesa); Pariz je ostao pod englesko-burgundskom kontrolom.", "da118a77"]},
"OLAYLAR_FRANSA_KONTROL_1027:1435-09-21:0":{"b": ["Ugovor u Arrasu: gradovi na Sommi i Mâconnais prepušteni Burgundiji: Amiens", "8e68bd94"], "d": ["Ugovor u Arrasu potpisan 21. septembra 1435. između Karla VII i burgundskog vojvode Filipa Dobrog odvojio je Burgundiju od saveza s Englezima. Zauzvrat su gradovi na Sommi (uključujući Amiens), Mâcon i Mâconnais te Auxerre i Auxerrois prepušteni Vojvodstvu Burgundiji (gradovi na Sommi uz uslov da se mogu otkupiti).", "4ab2b326"]},
"OLAYLAR_FRANSA_KONTROL_1027:1435-09-21:1":{"b": ["Ugovor u Arrasu: gradovi na Sommi i Mâconnais prepušteni Burgundiji: Mâcon", "3d7aa44d"], "d": ["Ugovor u Arrasu potpisan 21. septembra 1435. između Karla VII i burgundskog vojvode Filipa Dobrog odvojio je Burgundiju od saveza s Englezima. Zauzvrat su gradovi na Sommi (uključujući Amiens), Mâcon i Mâconnais te Auxerre i Auxerrois prepušteni Vojvodstvu Burgundiji (gradovi na Sommi uz uslov da se mogu otkupiti).", "4ab2b326"]},
"OLAYLAR_FRANSA_KONTROL_1027:1436-04-13:0":{"b": ["Pariz se predao francuskom kralju Karlu VII", "f3d92546"], "d": ["Nakon ugovora u Arrasu (1435.), stanovnici Pariza 13. aprila 1436. otvorili su kapije zapovjednicima Karla VII; engleska uprava je prestala.", "79a422fe"]},
"OLAYLAR_FRANSA_KONTROL_1027:1450-04-15:0":{"b": ["Bitka kod Formignyja: francuska vojska porazila je englesku, ubrzano je vraćanje Normandije", "77d20042"], "d": ["Dana 15. aprila 1450. kod Formignyja francuska vojska porazila je englesku pomoćnu vojsku; pali su Caen i Cherbourg, a Normandija se vratila pod francusku kontrolu.", "0287dae5"]},
"OLAYLAR_FRANSA_KONTROL_1027:1477-01-01:0":{"b": ["Luj XI preuzeo je Artois (Arras) iz burgundskog naslijeđa", "da697a1e"], "d": ["Smrću Karla Smjelog kod Nancyja (5. januara 1477.) francuski kralj Luj XI zauzeo je Artois; Arras, koji se opirao, zauzet je na juriš i zidine su mu porušene. Ugovorom u Arrasu (23. decembra 1482.) Artois je kao miraz Margarete ostao Francuskoj; Senliskim mirom 1493. vratio se Habsburgovcima.", "7867c9fc"]},
"OLAYLAR_FRANSA_KONTROL_1027:1481-12-11:0":{"b": ["Smrću Karla III Provansa je, prema njegovoj oporuci, prešla francuskom kralju Luju XI: Aix-en-Provence", "dc558e2c"], "d": ["Karlo III, posljednji grof Provanse iz kuće Anžu, sastavio je oporuku u Marseilleu 10. decembra 1481. i umro 11. decembra 1481.; Grofovija Provansa prešla je u ruke francuskog kralja. Pripojenje je pravno utvrđeno 1486. (pristanak Staleža Provanse).", "42fad3ff"]},
"OLAYLAR_FRANSA_KONTROL_1027:1481-12-11:1":{"b": ["Smrću Karla III Provansa je, prema njegovoj oporuci, prešla francuskom kralju Luju XI: Marseille", "bd072b2d"], "d": ["Oporuka je sastavljena u Marseilleu (10. decembra 1481.); smrću Karla (11. decembra) Provansa, a s njom i Marseille, prešli su francuskoj kruni.", "3baf7804"]},
"OLAYLAR_FRANSA_KONTROL_1027:1481-12-11:2":{"b": ["Smrću Karla III Provansa je, prema njegovoj oporuci, prešla francuskom kralju Luju XI: Arles", "de44f23c"], "d": ["Arles je od 1251. bio u rukama provansalskih grofova (Anžu); prelaskom grofovije francuskoj kruni (11. decembra 1481.) postao je francuski.", "b58a0e54"]},
"OLAYLAR_FRANSA_KONTROL_1027:1481-12-11:3":{"b": ["Smrću Karla III Provansa je, prema njegovoj oporuci, prešla francuskom kralju Luju XI: Toulon", "7a8c1f9a"], "d": ["Provansalska luka Toulon postala je francuska prelaskom grofovije francuskoj kruni (11. decembra 1481.); za Toulon nema zasebnog izvora, matično središte je Aix-en-Provence (DEKLARIRANA PRIBLIŽNOST).", "11d22f4b"]},
"OLAYLAR_FRANSA_KONTROL_1027:1493-01-01:0":{"b": ["Senliski mir: Arras (Artois) vraćen Habsburgovcu Maksimilijanu", "040b03f8"], "d": ["Senliski mir (1493.) između Karla VIII i Maksimilijana I dao je Artois i Arras Habsburgovcima.", "2e7e96b7"]},
"OLAYLAR_FRANSA_KONTROL_1027:1498-04-07:0":{"b": ["Umro je Karlo VIII; francuski kralj postao je Luj XII", "560db6d5"], "d": ["Karlo VIII umro je 7. aprila 1498. u Amboiseu; na prijestolje je stupio njegov rođak, vojvoda od Orléansa Luj XII.", "24214314"]},
"OLAYLAR_FRANSA_KONTROL_1027:1552-01-01:0":{"b": ["Pohod Henrika II na Tri biskupije: Toul je pripojen Francuskoj", "5d7053ac"], "d": ["Toul, kojim su upravljali biskupi-grofovi i koji je bio vezan za Njemačko Carstvo, pripojen je Francuskoj 1552. (zajedno s Metzom i Verdunom — Tri biskupije); pravno je potvrđeno Vestfalskim mirom 1648. Dan za Metz (18. april 1552.) u atlasu je zaseban; za Toul dan nije naveden u izvoru.", "5cdb37db"]},
"OLAYLAR_FRANSA_KONTROL_1027:1559-07-10:0":{"b": ["Umro je Henrik II; francuski kralj postao je Franjo II", "88a1a26e"], "d": ["Henrik II umro je 10. jula 1559.; na prijestolje je stupio njegov 15-godišnji sin Franjo II (utjecaj kuće Guise).", "746455f8"]},
"OLAYLAR_FRANSA_KONTROL_1027:1560-12-05:0":{"b": ["Umro je Franjo II; francuski kralj postao je Karlo IX", "16566c2b"], "d": ["Franjo II umro je 5. decembra 1560.; na prijestolje je stupio njegov brat Karlo IX (10 godina), a majka Katarina de Médicis postala je regentica.", "0139a790"]},
"OLAYLAR_FRANSA_KONTROL_1027:1574-05-30:0":{"b": ["Umro je Karlo IX; francuski kralj postao je Henrik III (dok je bio kralj Poljske)", "f86885f1"], "d": ["Karlo IX umro je 30. maja 1574.; njegov brat Henrik de Valois, koji je bio kralj Poljske, postao je nasljednik francuskog prijestolja i u septembru 1574. vratio se u Francusku.", "f3fea374"]},
"OLAYLAR_FRANSA_KONTROL_1027:1589-08-01:0":{"b": ["Henrik III na samrtnoj postelji priznao je Henrika Navarskog (Henrika IV) za nasljednika: počinje dinastija Bourbon", "328bca08"], "d": ["Henrik III, na kojeg je izvršen atentat, kao posljednji kralj loze Valois svečano je 1. augusta 1589. priznao Henrika Navarskog za nasljednika; njegovom smrću (2. augusta) dinastija Bourbon preuzela je francusko prijestolje.", "df18d0c2"]},
"OLAYLAR_FRANSA_KONTROL_1027:1610-05-14:0":{"b": ["Vladavina Henrika IV završila je; Luj XIII postao je kralj", "dfe5892c"], "d": ["Henrik IV ubijen je u atentatu u Parizu 14. maja 1610.; kralj je postao njegov sin Luj XIII. (Kraj vladavine u Treccaniju: «Regnò fino al 14 maggio 1610».)", "86a0f811"]},
"OLAYLAR_FRANSA_KONTROL_1027:1643-05-14:0":{"b": ["Umro je Luj XIII; petogodišnji Luj XIV postao je kralj (regentstvo: Ana Austrijska, Mazarin)", "2ac0d106"], "d": ["Luj XIII umro je 14. maja 1643. u Saint-Germain-en-Layeu; njegov sin Luj XIV istog je dana stupio na prijestolje.", "6a173c34"]},
"OLAYLAR_FRANSA_KONTROL_1027:1659-11-07:0":{"b": ["Pirinejski mir: Roussillon i Artois prešli Francuskoj: Perpignan", "7c9041e1"], "d": ["Pirinejski mir, potpisan 7. novembra 1659. između Francuske i Španije na Fazanskom otoku (île des Faisans) na rijeci Bidasoi, prepustio je Francuskoj Roussillon i Sjevernu Cerdagnu te Artois. Perpignan je od 1642., a Arras od 1640. bio faktički pod francuskom okupacijom; atlas prijelom suvereniteta bilježi na dan mira.", "82ee6b22"]},
"OLAYLAR_FRANSA_KONTROL_1027:1659-11-07:1":{"b": ["Pirinejski mir: Roussillon i Artois prešli Francuskoj: Arras", "ef09e034"], "d": ["Pirinejski mir, potpisan 7. novembra 1659. između Francuske i Španije na Fazanskom otoku (île des Faisans) na rijeci Bidasoi, prepustio je Francuskoj Roussillon i Sjevernu Cerdagnu te Artois. Perpignan je od 1642., a Arras od 1640. bio faktički pod francuskom okupacijom; atlas prijelom suvereniteta bilježi na dan mira.", "82ee6b22"]},
"OLAYLAR_FRANSA_KONTROL_1027:1681-09-30:0":{"b": ["Strasbourg je kapitulirao pred vojskom Luja XIV: pripojen je Francuskoj", "3c3c1cc6"], "d": ["U okviru politike reunion Louvoisova vojska opsjela je Strasbourg; grad je 30. septembra 1681. potpisao uslove predaje (akt o kapitulaciji u Illkirchu); 3. oktobra uslijedila je ratifikacija, a 23. oktobra 1681. svečani ulazak Luja XIV. Grad je pripojen Francuskoj, a gradska autonomija uništena.", "4f2a5014"]},
"OLAYLAR_FRANSA_KONTROL_1027:1791-09-14:0":{"b": ["Ustavotvorna skupština potvrdila je pripojenje Avignona i Comtat Venaissina Francuskoj", "d15fe246"], "d": ["Nakon protjerivanja papinog vicelegata iz Avignona (12. juna 1790.), Ustavotvorna skupština razmotrila je zahtjev za pripojenje; ono je potvrđeno 14. septembra 1791. Pio VI uložio je prigovor 5. novembra 1791.; članom 6. Tolentinskog ugovora (19. februara 1797.) papinstvo se odreklo Avignona i Comtata.", "a422cae7"]},
"OLAYLAR_FRANSA_KONTROL_1027:1793-01-03:0":{"b": ["Monako je pod imenom Fort-Hercule pripojen Francuskoj Republici", "1b846e31"], "d": ["Pripojenjem Monaka revolucionarnoj Francuskoj prekinuta je vlast Grimaldija; kneževina je do 1814. bila dio Francuske (Fort-Hercule).", "c3f4c386"]},
"OLAYLAR_FRANSA_KONTROL_1027:1795-07-22:0":{"b": ["Bazelski mir: Španija je istočni dio Hispaniole (Santo Domingo) prepustila Francuskoj: Santo Domingo", "25497735"], "d": ["Mirom potpisanim 22. jula 1795. u Bazelu između Španije i Francuske Republike, u zamjenu za ukidanje francuske okupacije na Pirinejima, španski dio otoka Hispaniole (Santo Domingo, Santiago de los Caballeros, Higüey) prepušten je Francuskoj.", "d1c0a4ab"]},
"OLAYLAR_FRANSA_KONTROL_1027:1798-03-15:0":{"b": ["Republika Mulhouse pripojena je Francuskoj Republici (Réunion)", "0c2b4f8a"], "d": ["Republika Mulhouse, od 1515. saveznica Švicarske konfederacije, nakon Bazelskog mira (1795.) dobrovoljno je pristupila Francuskoj; ujedinjenje je ostvareno 1798. (Réunion).", "e775b26b"]},
"OLAYLAR_FRANSA_KONTROL_1027:1814-05-30:0":{"b": ["Pariški mir: Monako se vratio pod vlast Grimaldija", "f3011157"], "d": ["Pariškim mirom od 30. maja 1814. Grimaldijima su vraćena prava; Monako je izašao iz francuske aneksije (sardinski protektorat 1815–1861. zasebna je stvar i u ovom zapisu nije obrađen). Tim se mirom i Menton (Kneževina Monako) vratio pod vlast Grimaldija.", "91de9178"]},
"OLAYLAR_FRANSA_KONTROL_1027:1861-02-02:0":{"b": ["Francusko-monačanski ugovor: Monako se za 4 miliona franaka odrekao prava na Menton (i Roquebrune); Menton je prešao Francuskoj", "ffa21e54"], "d": ["Nakon što je Pijemont-Sardinija 1860. zajedno s Nicom predala Francuskoj, knez Monaka prenio je na Francusku suverena prava u Mentonu i Roquebruneu. Menton je od 1848. bio slobodan grad pod sardinskom zaštitom.", "0aff978e"]},
"OLAYLAR_FRANSA_KONTROL_1027:1918-11-17:0":{"b": ["Francuske jedinice ušle su u Mulhouse: počeo je povratak Alzasa", "a56edca7"], "d": ["Šest dana nakon primirja (11. novembra 1918.) francuske jedinice ušle su u Mulhouse. Član 51. Versajskog ugovora smatra da povratak Alzasa-Lorene pod francuski suverenitet ima retroaktivno dejstvo od 11. novembra 1918.; potpisivanje je bilo 28. juna 1919., stupanje na snagu 10. januara 1920.", "204a7d28"]},
"OLAYLAR_FRANSA_KONTROL_1027:1918-11-18:0":{"b": ["Francuske jedinice ušle su u Colmar", "dabdf81a"], "d": ["Colmar je 18. novembra 1918. dočekao francuske jedinice; Alzas se vraćao pod francusku upravu (pravna retroaktivnost od 11. novembra 1918., čl. 51. Versajskog ugovora).", "04dcdb67"]},
"OLAYLAR_FRANSA_KONTROL_1027:1918-11-19:0":{"b": ["Francuska 28. pješadijska divizija ušla je u Metz", "c37a5b99"], "d": ["Francuska 28. pješadijska divizija ušla je u Metz 19. novembra 1918.; Mozel se vratio pod francusku upravu.", "aa57e100"]},
"OLAYLAR_FRANSA_KONTROL_1027:1918-11-21:0":{"b": ["Francuske jedinice ušle su u Strasbourg (zvanična svečanost 22. novembra)", "92b3cc2e"], "d": ["Nakon 47 godina njemačke uprave, prve francuske jedinice ušle su u Strasbourg 21. novembra 1918.; zvanična svečanost ulaska održana je sljedećeg dana.", "22f53345"]},
"OLAYLAR_FRANSA_KONTROL_1027:1940-08-02:0":{"b": ["Wagner i Bürckel postali su šefovi civilne uprave Alzasa i Lorene: oblast je faktički pripojena Reichu", "0e36dc11"], "d": ["Nakon poraza Francuske, Alzas i Mozel su bez ugovora faktički pripojeni Njemačkoj: Alzas je dat civilnoj upravi badenskog gaulajtera Wagnera, a Mozel gaulajtera Saar-Pfalza Bürckela (Mozel je 30. novembra 1940. pripojen Gau Westmark). Tekst primirja nema odredbu o aneksiji; pravno francuski suverenitet traje (Ordonnance od 9. augusta 1944.). Tim imenovanjima Metz (Mozel), Colmar i Mulhouse (Alzas) faktički su prešli pod njemačku civilnu upravu.", "01aeb601"]},
"OLAYLAR_FRANSA_KONTROL_1027:1944-11-20:0":{"b": ["Oslobođen je Mulhouse", "151f48e4"], "d": ["Francuska 1. armija (de Lattre) oslobodila je Mulhouse u novembru 1944.", "78fba884"]},
"OLAYLAR_FRANSA_KONTROL_1027:1944-11-22:0":{"b": ["Oslobođen je Metz (tvrđave su se opirale do decembra)", "17049694"], "d": ["Američka 3. armija oslobodila je Metz 22. novembra 1944.; okolne tvrđave opirale su se do decembra.", "4566f454"]},
"OLAYLAR_FRANSA_KONTROL_1027:1944-11-23:0":{"b": ["Leclercova 2. oklopna divizija oslobodila je Strasbourg", "7b399aa3"], "d": ["2. oklopna divizija pod komandom Leclerca ušla je 23. novembra 1944. u Strasbourg; prestala je njemačka uprava u glavnom gradu Alzasa (faktička aneksija od 1940.).", "4f1f13e2"]},
"OLAYLAR_FRANSA_KONTROL_1027:1945-02-02:0":{"b": ["Oslobođen je Colmar (Colmarski džep očišćen 9. februara)", "41a297f7"], "d": ["Colmar je oslobođen 2. februara 1945.; Colmarski džep potpuno je očišćen 9. februara 1945.", "3cc05417"]},
"OLAYLAR_H7_ASAMA:1529-05-10:0":{"b": ["Sulejman Zakonodavac kreće u pohod na Beč — ponovo počeo rat s Habsburgovcima", "f7afd2a9"], "d": ["Nakon Mohača mađarsko prijestolje podijeljeno je nadvoje, a Ferdinand je 1527. zauzeo Budim i izbacio Zapolju iz prijestolnice. Da bi podržao Zapolju i zaustavio habsburško napredovanje, padišah je četvrti put krenuo u pohod; prije pohoda veliki vezir Ibrahim-paša dobio je titulu seraskera i beglerbegluk Rumelije i s njim je izrađen cijeli plan. Obilne kiše na putu usporavale su napredovanje vojske; pohod se nastavio zauzimanjem Budima i njegovim predajom Zapolji te opsadom Beča.", "4d80633a"]},
"OLAYLAR_H7_ASAMA:1562-05-05:0":{"b": ["Obnova mira s Habsburgovcima — kraj rata za Erdelj i Temišvar", "97071975"], "d": ["Rat koji je počeo prelaskom Erdelja Ferdinandu 1551. i nastavio se pohodima poput osvajanja Temišvara i opsade Jegra, zatvoren je odlukom o nastavku mira s Habsburgovcima. Sporazum je uzajamno obnavljao ranije obaveze dviju strana; ali nije donio rješenje za nemire u pograničju, a nakon Ferdinandove smrti 1564. događaji u Erdelju ponovo su se umnožili.", "04cfeca8"]},
"OLAYLAR_H7_ASAMA:1566-05-01:0":{"b": ["Posljednji pohod Sulejmana Zakonodavca — izlazak iz Istanbula s ciljem Sigeta i Jegra", "31277d21"], "d": ["Nakon Ferdinandove smrti 1564. i stupanja Maksimilijana II na prijestolje umnožili su se sukobi na erdeljskoj granici. U pohodu koji je stari padišah planirao s Mehmed-pašom Sokolovićem ciljevi su bili tvrđave Siget i Jegar, a i caru je trebalo zaprijetiti. Pomolivši se u turbetu Ejuba sultana, s velikom je svečanošću napustio Istanbul; 15. maja stigao je u Edirne, a pedesetog dana od polaska u Beograd. To je bio njegov posljednji odlazak iz prijestolnice koju više neće vidjeti.", "c601608a"]},
"OLAYLAR_H7_ASAMA:1568-02-17:0":{"b": ["Jedrenski mir — kraj ratnog stanja s Habsburgovcima", "d08883e3"], "d": ["Pred Selimom II, koji je nakon sigetskog pohoda zimovao u Jedrenu, nalazili su se habsburški, safavidski, poljski, francuski i mletački poslanici. Odlučeno je da se nastavi mir sa Safavidima; potpisan je ugovor kojim je okončano ratno stanje s Habsburgovcima. U tim poslovima velik je bio uticaj velikog vezira Mehmed-paše Sokolovića.", "27b65c0e"]},
"OLAYLAR_H7_ASAMA:1578-01-02:0":{"b": ["Odluka o pohodu na Iran — protiv Safavida uzdrmanih Tahmaspovom smrću imenovana dva serdara", "1f09b186"], "d": ["Nakon što je šah Tahmasp I 1576. otrovan na kraju sukoba među dinastijom i državnim velikodostojnicima, Safavidi su zapali u velik metež; to je stanje odredilo smjer pohoda koji će se pokrenuti. Lala Mustafa-paša zadužen je da u Iran uđe od Erzuruma, a Kodža Sinan-paša od Bagdada. Kada se pojačao sukob dvojice vezira, umiješao se Sokollu: Sinan-paša je smijenjen, a Lala Mustafa-paša zadužen za osvajanje Širvana preko Gruzije. Ta odluka otvorila je osmansko-safavidski rat 1578-1590.", "3157145f"]},
"OLAYLAR_H7_ASAMA:1604-06-15:0":{"b": ["Cigalazade Sinan-paša krenuo u pohod na Iran", "1e90763e"], "d": ["Dok je trajao rat na dva fronta, s Iranom i Austrijom, šah Abas je opsadom zauzeo Erivan, ušao u Kars, ali je zaustavljen pred Ahiskom. Cigalazade Sinan-paša, imenovan serdarom Istoka, krenuo je iz Istanbula sa zakašnjenjem i 8. novembra stigao pred Kars. Iako su okolnosti bile povoljne, nije krenuo na šaha, nego je prezimio u Vanu, a zbog šahovog napada prešao u Erzurum; jedna ratna sezona prošla je uzalud.", "d155e6f3"]},
"OLAYLAR_H7_ASAMA:1605-11-06:0":{"b": ["Poraz Cigalazade Sinan-paše blizu jezera Urmija (Sufijan)", "7438fec4"], "d": ["Sinan-pašin položaj, dok je u ratnoj sezoni 1605. marširao da povrati Tabriz, uzdrman je kada je beglerbeg Erzuruma Köse Sefer-paša djelovao odvojeno od glavne vojske i pao u zarobljeništvo. Iznenadni prepad šaha Abasa nanio je vojsci težak poraz kod jezera Urmija; Sinan-paša se povukao najprije u Van, pa u Diyarbekir. Što je dao pogubiti beglerbega Alepa Džanbolatoglu Husein-pašu jer je zakasnio s pomoći, potpalilo je veliki ustanak u Anadoliji; nakon Sinan-pašine smrti šah Abas zauzeo je Gandžu, Širvan i Šemahu.", "8e130829"]},
"OLAYLAR_H7_ASAMA:1610-03-26:0":{"b": ["Tabriski pohod Kujudžu Murat-paše — na Ačičaju nije došlo do sukoba", "3c0a0a5d"], "d": ["Veliki vezir Kujudžu Murat-paša, koji je ugušio dželalijske ustanke i uspostavio mir u Anadoliji, krenuo je preko Erzuruma, Hasankalea, Čaldirana i Hoja na šaha Abasa, za kojeg se saznalo da ga čeka u Tabrizu. Dvije vojske suočile su se kod Ačičaja sjeverno od Tabriza, ali do bitke nije došlo; dopisivanje je nastavljeno. Zbog približavanja zime i oskudice municije i hrane paša se preko Ahlata, Vana i Bitlisa povukao u Diyarbekir, a iduće ljeto, dok je pripremao novi pohod, ondje je umro (5. augusta 1611).", "289fa3b6"]},
"OLAYLAR_H7_ASAMA:1615-04-23:0":{"b": ["Osmansko-safavidski rat ponovo počeo — veliki vezir Öküz Mehmed-paša krenuo na istočni pohod", "ef32fa31"], "d": ["Budući da od İncili Mustafe-čauša, poslanog kao poslanik u Iran nakon Nasuh-pašinog ugovora 1612, nije bilo vijesti, veliki vezir Mehmed-paša zadužen je za istočni pohod, dovršio pripreme i prešao u Uskudar. Upravo kad je kretao, stigla je vijest da su İncili-čauš i iranski poslanik Burun Kasim-han sa sporazumom i darovima stigli u Van, ali pohod nije odgođen. Veliki vezir je zimovao u Alepu.", "5c279a1a"]},
"OLAYLAR_H7_ASAMA:1616-09-12:0":{"b": ["Opsada Erivana — nakon pedeset pet dana podignuta bez ishoda", "64a4ecb6"], "d": ["Veliki vezir, koji je u aprilu 1616. s velikom vojskom krenuo iz Alepa, stigao je preko Erzuruma i Karsa pred Erivan. U uvjerenju da će se tvrđava lako predati, teški topovi nisu doneseni; opsada je uz nestašicu opreme trajala pedeset pet dana. Zbog pogibije janjičarskog age Muslu-age i Tekeli Mehmed-paše kao šehida, nevoljnosti vojske i odmicanja sezone opsada je podignuta, a vojska se povukla u Erzurum. Mehmed-paša smijenjen je u novembru 1616, a na njegovo mjesto došao je Halil-paša.", "823b20af"]},
"OLAYLAR_H7_ASAMA:1618-09-10:0":{"b": ["Poraz kod Seraba (Pul-i Šikeste) — iranski pohod Halil-paše", "d323ed03"], "d": ["Halil-paša, serdar umjesto Öküz Mehmed-paše, 1618. ponovo je krenuo na Iran. Bitka kod Pul-i Šikestea, između Tabriza i Ardebila, završila se porazom osmanske vojske. Nakon tog poraza, koji se u izvorima naziva i bitkom kod Seraba, istog mjeseca potpisan je Serabski ugovor.", "f2c187de"]},
"OLAYLAR_H7_ASAMA:1625-11-13:0":{"b": ["Opsada Bagdada Hafiz Ahmed-paše — trajala sedam mjeseci i dvadeset dana, bez ishoda", "764acb0a"], "d": ["Osmanlije, koje su 1623. izgubile Bagdad, krenule su pod komandom velikog vezira i serdara Hafiz Ahmed-paše da povrate grad. Budući da na vijeću sazvanom u Kirkuku prijedlog da se najprije zauzmu klanci nije prihvaćen, vojska je direktno opsjela Bagdad. Paša je lično ulazio u rovove; premda se sedamdeset drugog dana kroz dignutu minu ušlo u grad, vojnici su odbijeni. Kada je u martu 1626. šah Abas stigao u pomoć s 30.000 ljudi, vojska se našla između dvije vatre; u šahovom jurišu 7. juna pretrpljeni su teški gubici. Kada je ponestalo hrane, a vrućina i groznica desetkovale vojsku, opsada je podignuta i vojska se povukla u Diyarbekir.", "350e3f52"]},
"OLAYLAR_H7_ASAMA:1630-10-06:0":{"b": ["Opsada Bagdada Husrev-paše — podignuta nakon trideset devet dana", "18de5581"], "d": ["Veliki vezir Husrev-paša, koji je nakon pobjede kod Mehribana (5. maja 1630) ušao u Hamadan i spalio i razorio grad, umjesto da krene na Kazvin, odlukom ratnog vijeća sazvanog u Dergezinu vratio se glavnom cilju, Bagdadu. Vojska je početkom augusta stigla u okolinu Bagdada i 6. oktobra opsjela grad. U ispadu iranskog garnizona 26. oktobra i u općem jurišu 9. novembra pretrpljeni su veliki gubici; i ova druga opsada nakon gubitka Bagdada podignuta je bez ishoda. Vojska se povukla u Mosul.", "4b3ed1a0"]},
"OLAYLAR_H7_ASAMA:1700-01-01:0":{"b": ["Lepanto prema Karlovačkom miru vraćen Osmanlijama", "9ca4f9dd"], "d": ["Lepanto, koji se u ratovima 1683-1699. dugo opirao i u julu 1687. s okolnim tvrđavama pao u ruke Venecije, ostao je u mletačkim rukama do godinu dana nakon Karlovačkog mira, a zatim se vratio Osmanlijama. Tvrđava na ulazu u Korintski zaljev tako je petnaest godina prije Moreje došla pod osmansku upravu.", "782654b8"]},
"OLAYLAR_H7_ASAMA:1733-07-19:0":{"b": ["Topal Osman-paša porazio Nadira kod Dudžuma — opsada Bagdada podignuta", "7ae1fc9e"], "d": ["Protiv Nadira, koji je u januaru 1733. opsjedao Bagdad, vojska pod komandom Topal Osman-paše, poslana u pomoć Bagdadu, razbila je Nadirove snage kod Dudžuma blizu Samare; ranjeni Nadir povukao se u Hamadan, a opsada koja je trajala mjesecima podignuta je. Ali pobjeda je bila kratkog vijeka: Nadir je krajem iste godine ponovo ušao u Irak i kod Akderbenda sjeverno od Kirkuka porazio osmanske snage; Topal Osman-paša poginuo je u tim borbama i pokopan je u Kirkuku.", "6444aec6"]},
"OLAYLAR_H7_ASAMA:1743-02-25:0":{"b": ["Irački pohod Nadir-šaha — počeo posljednji osmansko-iranski rat, pao Kirkuk", "ba014bf5"], "d": ["Nadir-šah, koji je osamnaest mjeseci proveo u Dagestanu i Gruziji i čiji je zahtjev da se džaferijski mezheb prizna kao peti mezheb Osmanlije odbile, pokrenuo je 1743. novi pohod protiv Osmanlija i s velikom vojskom ušao u Kirkuk. Isti uspjeh nije postigao kod Mosula; morao je podići opsadu. Ovaj rat posljednji je osmansko-iranski rat, koji se završio Ugovorom u Kerdenu 1746.", "5515afec"]},
"OLAYLAR_H7_ASAMA:1744-07-29:0":{"b": ["Nadir-šahova opsada Karsa — trajala dva mjeseca, bez ishoda", "a3ea61d9"], "d": ["Safavidski princ Safi Mirza, koji je našao utočište kod Osmanlija, polagao je pravo na iransko prijestolje; prema planu, serasker Karsa trebao ga je preko Tabriza odvesti u Isfahan i postaviti na prijestolje, a Osmanlije su protiv Irana otvorile tri fronta. Nadir-šah je zato krenuo na Kars i opsjeo tvrđavu. Dvomjesečna opsada nije donijela ishod.", "42fc48b5"]},
"OLAYLAR_H7_ASAMA:1745-08-21:0":{"b": ["Poraz kod Kagaverda — rasula se vojska Jegen Mehmed-paše", "7caf6f22"], "d": ["Godinu nakon opsade Karsa Nadir-šah je kod Kagaverda porazio osmanske snage pod komandom Jegen Mehmed-paše. Zatim se vratio u Isfahan. Odustajanje od insistiranja na priznanju džaferijskog mezheba iduće je godine otvorilo put Ugovoru u Kerdenu.", "3992b8ed"]},
"OLAYLAR_ILIRYA0072:1779-01-01:0":{"b": ["Saudijsko-vehabijske snage zauzele emirat Hail — upravljala je porodica Ibn Ali iz plemena Abde", "2d29ceb9"], "d": ["Kad su snage prve saudijske države zauzele emirat Hail, upravu grada držala je porodica Ibn Ali iz roda Abde plemena Šammar. Ta porodica upravljala je Hailom do 1835, kad je emirat preuzeo Abdullah b. Rašid; dinastija Rašidida nastala je tek tada. U atlasu je Hail do 1836. dosad izgledao bez gospodara, iako izvor za 1820. po imenu navodi emira grada.", "bc2aa4ea"]},
"OLAYLAR_ILIRYA0072:1806-01-01:0":{"b": ["Kvarnerski otoci prelaze Napoleonovoj Kraljevini Italiji, a Boka kotorska pod rusku upravu", "c5e411c8"], "d": ["Nakon Požunskog mira Kvarnerski otoci — za razliku od Dalmacije — nisu neposredno vezani za Francusku, nego za Napoleonovu Kraljevinu Italiju; u Ilirske provincije ušli su tek 1809. U Boki kotorskoj, pak, okončana je austrijska uprava i 1806–1807. uspostavljena ruska uprava; Boka je Francuskoj prešla tek 1807. Ta dva razlikovanja ne mogu se obuhvatiti jednim jedinstvenim 'francuskim' prozorom atlasa.", "ec06d97d"]},
"OLAYLAR_ILIRYA0072:1806-02-01:0":{"b": ["Prelazak Dalmacije pod francusku upravu — primjena Požunskog (bratislavskog) mira", "00bfe4f6"], "d": ["Požunski (Bratislava/Pressburg) mir od 26. decembra 1805. primorao je Austriju da se odrekne Istre, Dalmacije i svih jadranskih otoka. Francuska je u februaru 1806. faktički preuzela upravu; Zadar je ostao sjedište generalnog providura, a tu je dužnost 1806–1810. obavljao Venecijanac Vicenzo Dandolo. Dalmacija je nakon Schönbrunnskog mira 1809. pripojena Ilirskim provincijama. Tako je okončana prva austrijska uprava, koja je trajala od 1797 — u atlasu je to razdoblje dosad izgledalo kao neprekinuto austrijsko.", "b8a55f1c"]},
"OLAYLAR_ILIRYA0072:1813-01-01:0":{"b": ["Austrija vraća Ilirske provincije i Dalmaciju — kraj Napoleonove uprave", "1b2ac942"], "d": ["Krajem 1813. habsburške jedinice vratile su područje južno od Save i ponovo je uspostavljena stara granična organizacija; austrijska vojska ušla je u Istru u oktobru 1813. Karlovac je od tada postao dio austrijskog Kraljevstva Ilirije. I razdoblje francuske uprave u Dalmaciji zatvoreno je 1813. Pripadnost oblasti Austriji zvanično je potvrđena odlukama Pariškog mira 1814. i Bečkog kongresa 1815. Ovom akcijom Villach, Tarvis, Gorica, Gradisca i Pula (Ilirske provincije) vratili su se Austriji krajem 1813.", "bf1e49a8"]},
"OLAYLAR_KI117:1684-08-24:0":{"b": ["Jazlovec prelazi u poljske ruke", "c86581e5"], "d": ["Za vrijeme Sobieskog pohoda na Moldaviju poljska vojska je nakon dvodnevne opsade povratila Jazlovec, koji je od 1672. bio u osmanskim rukama. Tako je počelo raspadanje Kamjaneckog sandžaka.", "98482094"]},
"OLAYLAR_KI117:1684-11-03:0":{"b": ["Povratak Pešte Osmanlijama", "13914c49"], "d": ["Pešta, u koju su habsburške jedinice ušle u junu 1684., nakon neuspjeha opsade Budima početkom novembra 1684. ponovo se vratila pod osmansku kontrolu; Habsburgovci će u Peštu konačno ući 1686.", "41164adc"]},
"OLAYLAR_KI117:1686-01-01:0":{"b": ["Osmanlije evakuiraju tvrđavu Međibož", "2c4b5a7f"], "d": ["Tvrđavu Međibož u Podoliji Osmanlije su napustile 1686.; pri povlačenju pokušale su je dići u zrak. Time je prestala otprilike osmogodišnja osmanska vlast.", "27fe058d"]},
"OLAYLAR_KI117:1686-06-17:0":{"b": ["Habsburška konjica ušla je u Peštu — priprema za opsadu Budima", "c9d23487"], "d": ["Prethodnica habsburške vojske koja se pripremala za opsadu Budima, bavarska konjica, ušla je u Peštu, koju je osmanski garnizon napustio; istočna obala Dunava konačno je prešla pod habsburšku kontrolu. Sam Budim past će 2. septembra.", "9329e3b2"]},
"OLAYLAR_KI117:1686-10-01:0":{"b": ["Mohač prelazi pod habsburšku kontrolu", "f022d9c0"], "d": ["U habsburškom napredovanju južno od Dunava nakon pada Budima, Mohač je u jesen 1686. prešao pod kontrolu saveznika; sljedećeg ljeta vojska će kod Haršanja (1687) pokušati pružiti otpor na toj liniji.", "06cb2407"]},
"OLAYLAR_KI117:1687-07-01:0":{"b": ["Lepanto (İnebahtı) prelazi Veneciji", "8daedb90"], "d": ["Nakon pada Patrasa, Osmanlije su napustile i Lepanto na ulazu u Korintski zaljev, koji je prešao pod mletačku kontrolu; bit će vraćen Karlovačkim mirom 1699.", "2b368884"]},
"OLAYLAR_KI117:1689-09-11:0":{"b": ["Baden je stigao u Jagodinu — moravski koridor ušao je u austrijsku liniju", "a6459b85"], "d": ["Nakon poraza kod Batočine (30. augusta) osmanska vojska povukla se na jug; Baden je 11. septembra 1689. stigao u Jagodinu i podigao most preko Morave. Austrijska linija protezala se preko Jagodine–Ćuprije–Paraćina do Niša; Alaca-Hisar (Kruševac) ostao je izvan linije.", "9badb3bd"]},
"OLAYLAR_KI117:1690-08-29:0":{"b": ["Dursun Mehmed-paša ušao je u Vidin — dunavska obala opet u osmanskim rukama", "2b4d5344"], "d": ["U protuofanzivi Fazil Mustafa-paše kopnena vojska karamanskog mutesarifa Dursun Mehmed-paše i dunavska flota Mezomorta Husejin-paše povratile su Vidin od Austrije.", "d76ac495"]},
"OLAYLAR_KI117:1690-09-01:0":{"b": ["Rumelijski paša ušao je u tvrđavu Oršavu", "3884232b"], "d": ["Kada se austrijska vojska krajem augusta 1690. povukla iz Srbije, rumelijski paša ponovo je zauzeo Oršavu; dunavska obala Banata vratila se pod osmansku kontrolu.", "541ca167"]},
"OLAYLAR_KI117:1690-09-17:0":{"b": ["Tvrđave Valona i Kanina pale su u ruke Venecije", "51bf7b50"], "d": ["Dok je osmanska protuofanziva trajala u Srbiji, mletačka flota i snage zauzele su na albanskoj obali Valonu i Kaninu; u martu 1691. dvije će tvrđave biti porušene i napuštene.", "238bd38c"]},
"OLAYLAR_KI117:1691-03-15:0":{"b": ["Venecija je porušila tvrđave zauzete u Albaniji i povukla se", "378490dd"], "d": ["Mlečani, koji su 17. septembra 1690. zauzeli Valonu i Kaninu, sredinom marta 1691. porušili su tvrđave i povukli se; južna Albanija vratila se pod osmansku kontrolu.", "aa90ce2d"]},
"OLAYLAR_KI117:1695-01-01:0":{"b": ["Kizikermen prelazi u ruske ruke", "2b90f9af"], "d": ["U operaciji na dnjeparskoj liniji, istovremenoj s ruskim pohodom na Azov, Šeremetjev i Mazepa zauzeli su Kizikermen; tvrđava je do Istanbulskog mira 1700. ostala u ruskim rukama.", "c310dfdd"]},
"OLAYLAR_KI117:1695-01-12:0":{"b": ["Gyula se predaje Habsburgovcima", "e378c570"], "d": ["Opsjednuta Gyula potpisala je 21. decembra 1694. kapitulaciju; 12. januara 1695. garnizon je izašao i ušle su habsburške jedinice. Tvrđava je do Karlovačkog mira (1699) bila u habsburškim, a ne osmanskim rukama.", "5e4c275b"]},
"OLAYLAR_KI117:1699-09-22:0":{"b": ["Kamjanec se predaje Poljskoj", "05950f7a"], "d": ["Prema odredbama Karlovačkog mira od 26. januara 1699., evakuacija Podolije završena je u septembru; ključevi Kamjaneca predani su poljskoj komisiji 22. septembra 1699. Prelazak sandžaka, zajedno s potčinjenim tvrđavama (Bar, Međibož, Jazlovec), pod Poljsku faktički se ostvario tog dana.", "15c85c1d"]},
"OLAYLAR_KURULUS_GERI_1021:0630-01-11:0":{"b": ["Meka osvojena: grad prešao Medinskoj državi", "8435e73c"], "d": ["Poslanik je osvojio Meku (20. ramazan 8 / 11. januar 630).", "865a73bd"]},
"OLAYLAR_KURULUS_GERI_1021:0632-06-08:0":{"b": ["Poslanikova smrt: Meka vezana za rašidunske halife", "b65e8cd1"], "d": ["Hazreti Muhamed preselio je 13. rebiul-evvela 11 / 8. juna 632; Meka je došla pod upravu rašidunskih halifa.", "99716bea"]},
"OLAYLAR_KURULUS_GERI_1021:0638-01-01:0":{"b": ["Osnovana Kufa", "617d0f35"], "d": ["Kufa je kao garnizonski grad osnovana uglavnom 17. (638) godine; postala je središte Rašidunskog hilafeta u Iraku (dan nepoznat).", "abaf8837"]},
"OLAYLAR_KURULUS_GERI_1021:0661-07-29:0":{"b": ["Hasan b. Ali prepustio hilafet Muaviji; Muavija primio prisegu u Kufi, Kufa prešla pod umajadsku vlast", "cc9c9de4"], "d": ["Hasan b. Ali, koji je postao halifa nakon što je hazreti Alija u džamiji u Kufi pao kao šehid od ruke Ibn Muldžema (januar 661), prepustio je hilafet Muaviji; Muavija je došao u Kufu i primio prisegu naroda (25. rebiul-evvel 41 / 29. juli 661). Rašidunsko doba se zatvorilo, grad je prešao pod umajadsku upravu (zubejridski međuperiod 680-691. nije posebno upisan u zapis).", "6cadb24f"]},
"OLAYLAR_KURULUS_GERI_1021:0661-07-29:1":{"b": ["Muavija primio prisegu: Meka došla pod umajadsku vlast", "d6dcc232"], "d": ["Muavija je primio prisegu 25. rebiul-evvela 41 / 29. jula 661; Meka je vezana za umajadske namjesnike (dan specifičan za Meku ne postoji, dan države).", "16cecb18"]},
"OLAYLAR_KURULUS_GERI_1021:0670-01-01:0":{"b": ["Osnovan Kajrevan (Ukba b. Nafi, umajadski)", "7409e9ae"], "d": ["Umajadski namjesnik Ukba b. Nafi osnovao je 670. Kajrevan kao bazu Ifrikije.", "b2240f4e"]},
"OLAYLAR_KURULUS_GERI_1021:0683-11-27:0":{"b": ["Ibn Zubejr proglasio hilafet u Meki: Meka izašla iz umajadske vlasti", "9e31ca5c"], "d": ["Vijest o Jezidovoj smrti stigla je u Meku (27. novembra 683); Abdullah b. Zubejr proglasio je hilafet sa središtem u Meki (64/683).", "212a96b5"]},
"OLAYLAR_KURULUS_GERI_1021:0692-10-01:0":{"b": ["Hadždžadž zauzeo Meku: grad ponovo došao pod umajadsku vlast", "48dd6e68"], "d": ["Na kraju opsade Hadždžadža b. Jusufa Meka je 14. džumadel-ula 73 / 1. oktobra 692. ponovo došla pod umajadsku vlast.", "25eedec5"]},
"OLAYLAR_KURULUS_GERI_1021:0745-01-01:0":{"b": ["Abdurrahman b. Habib se pobunio: Kajrevan izašao iz umajadske uprave", "4c7a0da0"], "d": ["Pobunom Abdurrahmana b. Habiba 745. Kajrevan je izašao iz umajadskog namjesništva; do 761. habibidsko/haridžitsko međurazdoblje (deklarirana praznina vlasnika).", "69dac839"]},
"OLAYLAR_KURULUS_GERI_1021:0749-09-02:0":{"b": ["Abasidska vojska zauzela Kufu", "0191709e"], "d": ["Abasidska vojska uzela je Kufu 14. muharrema 132 (2. septembra 749); grad je prešao s Umajada na Abaside.", "998fc494"]},
"OLAYLAR_KURULUS_GERI_1021:0750-08-05:0":{"b": ["Umajadska država prestala: Meka prešla pod abasidsku vlast", "382e4d6e"], "d": ["Posljednji umajadski halifa Mervan II ubijen je 26. zul-hidždže 132 / 5. augusta 750; Meka je ušla u abasidsko namjesništvo Harameyna (dan specifičan za Meku ne postoji — dan kraja države, deklarirana približnost).", "710c6ec7"]},
"OLAYLAR_KURULUS_GERI_1021:0761-01-01:0":{"b": ["Muhamed b. Ešas, imenovan od Abasida, zauzeo Kajrevan", "71af9f79"], "d": ["Muhamed b. Ešas 144. (761) godine zauzeo je Kajrevan u ime Abasida.", "a71fe419"]},
"OLAYLAR_KURULUS_GERI_1021:0762-01-01:0":{"b": ["Halifa Mensur počeo gradnju Bagdada (Medinetu s-selam)", "844a94d5"], "d": ["Radovi na gradu osnovanom na obali Tigrisa počeli su 762; postao je stalna prijestolnica Abasida (dan nepoznat, potvrđena samo godina).", "750c6eb1"]},
"OLAYLAR_KURULUS_GERI_1021:0800-01-01:0":{"b": ["Ibrahim b. Aglab postao namjesnik: Aglabidi u Kajrevanu", "f7279ba9"], "d": ["Harun er-Rašid imenovao je Ibrahima b. Aglaba namjesnikom Ifrikije; Aglabidi (800-909) učinili su Kajrevan prijestolnicom.", "3b6e9426"]},
"OLAYLAR_KURULUS_GERI_1021:0909-01-01:0":{"b": ["Fatimije zauzele Kajrevan; Aglabidi prestali", "021693e0"], "d": ["Godine 909. Zijadetullah III pobjegao je u Egipat; Kajrevan je prešao Fatimijama.", "a6422efd"]},
"OLAYLAR_KURULUS_GERI_1021:0945-12-19:0":{"b": ["Buvejhid Ahmed (Muizzuddevle) ušao u Bagdad; grad prešao pod buvejhidsku vlast", "31accd4a"], "d": ["Ahmed je 11. džumadel-ula 334 (19. decembra 945) ušao u Bagdad; halifa Mustekfi imenovao ga je emirom emira, a grad je prešao pod vlast Buvejhida (i Kufa je došla pod buvejhidsku vlast 945-1055; dan za Kufu preuzet je od susjednog Bagdada).", "11f31be7"]},
"OLAYLAR_KURULUS_GERI_1021:0969-01-01:0":{"b": ["U Meki učena hutba u ime Fatimija (358/969)", "3f069fea"], "d": ["Mekanski emir Džafer b. Muhamed dao je da se hutba uči u ime Fatimija (358/969, preciznost do godine); Fatimije kao vrhovna država.", "2256892c"]},
"OLAYLAR_KURULUS_GERI_1021:0972-10-02:0":{"b": ["Ziridi u Kajrevanu (Buluggin b. Ziri namjesnik Ifrikije)", "5494e662"], "d": ["Buluggin b. Ziri upravljao je Ifrikijom u ime fatimijskog halife; Ziridi (972-1057) vladaju Kajrevanom (TDV daje godinu, dan je iz f zapisa države).", "ffcba4c5"]},
"OLAYLAR_KURULUS_GERI_1021:1057-01-01:0":{"b": ["Hilalska pljačka: Muizz b. Badis povukao se u Mahdiju, ziridska vlast u Kajrevanu završena", "4dbbdff5"], "d": ["Oko 449. (1057) Hilali su opljačkali Kajrevan; Ziridi su se povukli u Mahdiju; do 1229. vlasnik grada u izvorima se ne može pratiti godinu po godinu (deklarirana praznina).", "8bebfdc7"]},
"OLAYLAR_KURULUS_GERI_1021:1085-05-25:0":{"b": ["Alfonso VI ušao u Toledo: grad prešao pod kastiljsku vlast", "3b72bb5f"], "d": ["Treccani: 25. maja 1085. Alfonso VI ušao je u Toledo; grad je dvije godine kasnije postao prijestolnica Kastilje (TDV tuleytula daje samo godinu: 478/1085; u repu hronologije zasebno je upisan dan predaje 8. maja 1085).", "fa2c9677"]},
"OLAYLAR_LAB19_2S_P5:1918-02-16:0":{"b": ["Litvansko vijeće (Taryba) potpisalo je u Vilniusu akt o nezavisnosti", "230ccf8d"], "d": ["U Litvaniji, koja je od 1915. bila pod njemačkom okupacijom, Litvansko vijeće, koje je djelovalo pod nadzorom njemačke vojske, potpisalo je u Vilniusu akt o nezavisnosti. Njemačka je taj korak podsticala za vrijeme pregovora u Brest-Litovsku; stvarni suverenitet došao je tek s njemačkim povlačenjem u novembru 1918. Naselja koja su se istog datuma pridružila novoj državi: Kaunas, Šiauliai.", "529d9290"]},
"OLAYLAR_LAB19_2S_P5:1918-10-07:0":{"b": ["Iskrcavanje francuskih snaga u Bejrutu — početak francuske uprave na libanskoj obali", "7fb62c6f"], "d": ["S povlačenjem osmanskih snaga iz Sirije, francuske pomorske i kopnene jedinice zauzele su Bejrut 7. oktobra 1918., na osnovu britansko-francuskog modus vivendi od 30. septembra 1918. Obalni pojas — Bejrut, Sidon, Tir i, tokom oktobra, Tripoli (Libanski) — te Libanska planina (Deir el-Kamar) prepušteni su francuskoj vojnoj upravi pod nazivom Zapadna zona Uprave okupiranih neprijateljskih teritorija (OETA West), uspostavljene 23. oktobra. Ostala naselja izgubljena istog datuma: Tir, Deir el-Kamar.", "706a7f2c"]},
"OLAYLAR_LAB19_2S_P6:1037-01-01:0":{"b": ["Hamama je istjerao Temima iz Fesa: Emirat Magrava vratio se u Fes", "1d208deb"], "d": ["Nakon što su Benu Ifren 1033. oduzeli Fes magravskom emiru Hamami, Hamama se povukao u Udždu i Tenes, a četiri godine kasnije istjerao je emira Benu Ifrena Temima iz Fesa; Fes je ostao u sastavu Emirata Magrava do osvajanja od strane Almoravida 1070.", "0c4f2f3a"]},
"OLAYLAR_LAB19_2S_P6:1169-01-01:0":{"b": ["Kayseri i Zamanti oduzeti su Danišmendima i pripojeni seldžučkim posjedima", "ef7556eb"], "d": ["Kilič Arslan II oduzeo je Kayseri i Zamanti Danišmendu Zunnunu i pripojio ih posjedima anadolskih Seldžuka.", "29bdf0d1"]},
"OLAYLAR_LAB19_2S_P6:1175-01-01:0":{"b": ["Sivas, Tokat i Niksar oduzeti su Danišmendima i pripojeni seldžučkim posjedima", "e4e4c038"], "d": ["Kilič Arslan II zauzeo je u ljeto 1175. danišmendske posjede, uključujući Sivas, Niksar, Komanu i Tokat; sivaski ogranak Danišmenda prestao je postojati.", "feecde45"]},
"OLAYLAR_LAB19_2S_P6:1178-10-25:0":{"b": ["Kilič Arslan II zauzeo je Malatyu: prestao je postojati malatyanski ogranak Danišmenda", "b1662c9e"], "d": ["Kilič Arslan II je nakon četveromjesečne opsade 11. džumadel-ula 574. (25. oktobra 1178.) zauzeo Malatyu i dokrajčio taj ogranak dinastije Danišmenda.", "9b20f183"]},
"OLAYLAR_LAB19_2S_P6:1244-07-11:0":{"b": ["Horezmijci su ušli u Jerusalem: Jerusalem je izašao iz ruku krstaša", "97cdc2e1"], "d": ["Horezmijske jedinice, koje su palile i pustošile okolinu Damaska, ušle su 11. jula 1244. u Jerusalem; grad je izašao iz ruku krstaša. U oktobru iste godine, u bici kod Gaze, egipatski Ejubidi, uz podršku Horezmijaca, porazili su sirijske Ejubide i njihove saveznike krstaše, te je Jerusalem konačno došao pod vlast egipatskih Ejubida.", "d90527b2"]},
"OLAYLAR_LAB19_2S_P6:1643-01-01:0":{"b": ["Jarubije su povratile Suhar od Portugalaca", "8e9b38d1"], "d": ["Nasir ibn Muršid, vođa omanske dinastije Jarubija, povratio je 1643. Suhar od Portugalaca.", "17402e41"]},
"OLAYLAR_LAB19_2S_P6:1650-01-01:0":{"b": ["Jarubije su povratile Maskat od Portugalaca", "afeaa6dd"], "d": ["Nasir ibn Muršid, vođa omanske dinastije Jarubija, povratio je 1650. Maskat od Portugalaca; ta omanska luka, koju je Portugal držao od 1507., prešla je Jarubijama.", "a68e0b2b"]},
"OLAYLAR_LAB19_2S_P6:1829-05-14:0":{"b": ["Osmanski garnizoni napustili su Missolonghi i Anatoliko", "60ac1fdf"], "d": ["Nakon predaje Lepanta 30. aprila 1829., garnizoni Missolonghija i Anatolika napustili su 14. maja 1829. gradove i predali ih grčkim snagama.", "49fa6f9b"]},
"OLAYLAR_LAB19_2S_P6:1841-05-30:0":{"b": ["Francuska vojska ušla je u Maskaru: palo je Abdulkadirovo središte u unutrašnjosti Alžira", "f7bbe843"], "d": ["Francuska vojska pod komandom maršala Bugeauda ušla je u pohodu 1841., nakon Takdemta, 30. maja u Maskaru; Abdulkadir nije ozbiljno pokušao braniti grad.", "68dd3e47"]},
"OLAYLAR_LAB19_2S_P6:1844-05-08:0":{"b": ["Francuske jedinice ušle su u Dellys i ostavile garnizon", "2a98a144"], "d": ["Francuske jedinice pod komandom maršala Bugeauda ušle su u Dellys 8. maja 1844.; u gradu su ostavile garnizon od dvjesto pedeset ljudi, a 11. maja nastavile su put prema Bordj-Mnaïelu.", "b469cbc0"]},
"OLAYLAR_LAB19_2S_P6:1916-06-16:0":{"b": ["Džidda je pala u ruke pobunjeničkih snaga šerifa Husejna", "36c7eb82"], "d": ["U pobuni koju je šerif Husejn pokrenuo u Mekki u junu 1916., Džidda je 16. juna pala u ruke pobunjenika.", "3f61e26f"]},
"OLAYLAR_LAB19_2S_P6:1916-09-17:0":{"b": ["Taif je pao u ruke šerifa Husejna", "4b420ead"], "d": ["Snage šerifa Husejna, koji se za vrijeme Prvog svjetskog rata pobunio protiv osmanske vlasti, zauzele su Taif 17. septembra 1916.; grad je ostao pod hašemitskom upravom do povlačenja Osmanlija iz Hidžaza 30. oktobra 1918.", "a0ba88b4"]},
"OLAYLAR_LAB19_2S_P6:1918-10-25:0":{"b": ["Osmanske snage napustile su Kirkuk uveče, ušla je britanska Lewinova kolona", "4e8e0d56"], "d": ["Osmanske snage u Kirkuku držale su 25. oktobra 1918. svoj položaj do večeri, a zatim su se počele povlačiti u pravcu Altun-Köprüa; britanska kolona generala Lewina zauzela je nakon mraka Kirkuk i liniju sjeverno od njega.", "28bed7ca"]},
"OLAYLAR_LAB19_2S_P6:1918-10-31:0":{"b": ["Britanska Lewinova kolona zauzela je Altun-Köprü bez otpora", "4e54f6b8"], "d": ["Ujutro 31. oktobra 1918. britanska kolona generala Lewina zauzela je Altun-Köprü ne naišavši na otpor; osmanske snage povlačile su se u pravcu Mosula.", "1e23aefa"]},
"OLAYLAR_LAB19_2S_P6:1919-02-01:0":{"b": ["U Asiru je nakon osmanskog povlačenja vlast porodice Aiz zamijenio Muhammed ibn Ali al-Idrisi", "f3f129c8"], "d": ["Kada su se osmanske snage povukle iz Asira između oktobra 1918. i februara 1919., u tom kraju nastala je praznina vlasti; najprije je vlast preuzela stara porodica Aiz, ali je odmah potom tim krajem zavladao Muhammed ibn Ali al-Idrisi.", "e4292793"]},
"OLAYLAR_LAB19_2S_P6:1920-02-02:0":{"b": ["Tartuski mir: Sovjetska Rusija priznala je nezavisnost Estonije, Petseri je ostao u Estoniji", "65ad6147"], "d": ["Mirom kojim je okončan Estonski rat za nezavisnost Sovjetska Rusija priznala je nezavisnost Estonije. Povučena granica prolazila je nešto istočnije od današnje i na jugoistoku je Petseri (Pečori) ostavila u Estoniji.", "96a8a8b0"]},
"OLAYLAR_LAB19_2S_P6:1922-01-01:0":{"b": ["Saudijci su u Asiru, u Abhi, proglasili svoju vlast: završila je Idrisijeva vlast", "16f33b66"], "d": ["Saudijski emir Abdulaziz poslao je sina Fejsala u oblast Asir i proglasio vlast nad Abhom; time je prestala vlast Muhammeda ibn Alija al-Idrisija u Asiru.", "a28adf26"]},
"OLAYLAR_LAB19_2S_P6:1936-07-18:0":{"b": ["Pobuna u Sevilli, Valladolidu i Burgosu: gradovi su prešli u ruke nacionalista", "04ee444e"], "d": ["Vojna pobuna kojom je počeo Španski građanski rat izbila je 18. jula 1936. na Kanarskim otocima, u Sevilli, Valladolidu i Burgosu. Gran Enciclopèdia Catalana navodi Sevillu kao 'bazu pobune u Andaluziji'. Ti gradovi su pobunom prešli pod nacionalističku upravu (protivničku Španskoj Republici).", "0edcbde9"]},
"OLAYLAR_LAB19_2S_P6:1936-07-19:0":{"b": ["Pobuna u Zaragozi, Pamploni, Oviedu, Salamanci i Palmi: gradovi su prešli u ruke nacionalista", "1610d143"], "d": ["Vojna pobuna izbila je 19. jula 1936. u Zaragozi, Pamploni, Vitoriji, Oviedu, Salamanci i Palmi (Mallorca). Gran Enciclopèdia Catalana te gradove ubraja među pobune od 19. jula. Mallorca (Palma) od tog datuma prelazi pod nacionalističku upravu.", "287e0df5"]},
"OLAYLAR_LAB19_2S_P6:1938-10-10:0":{"b": ["Arbitražna odluka o Chacu: veći dio Chaco Boreala dodijeljen je Paragvaju", "ecf3de14"], "d": ["Arbitražni odbor sastavljen od predstavnika Argentine, Brazila, Čilea, SAD-a, Perua i Urugvaja objavio je 10. oktobra 1938. odluku kojom je, u skladu s Mirovnim ugovorom od 21. jula 1938., određena bolivijsko-paragvajska granica. Veći dio spornog Chaco Boreala pripao je Paragvaju; Bolivija je dobila uzak izlaz na rijeku Paragvaj.", "5b2f0579"]},
"OLAYLAR_LAB19_2S_P6:1939-03-30:0":{"b": ["Nacionalističke jedinice ušle su u Valenciju", "6faa6441"], "d": ["Nacionalističke jedinice ušle su u Madrid 28. marta 1939., a u Valenciju 30. marta. Tako je pao i posljednji veliki grad republikanskog fronta; rat je zvanično završen dva dana kasnije, 1. aprila 1939.", "ae0c6ab4"]},
"OLAYLAR_LAB19_2S_P6:1941-08-29:0":{"b": ["Njemačka komanda uspostavila je Vladu narodnog spasa na čelu s Nedićem", "b0c34dad"], "d": ["U Srbiji pod njemačkom okupacijom 29. augusta 1941. uspostavljena je Vlada narodnog spasa na čelu s Milanom Nedićem. Vlada je bila kolaboracionistička uprava potčinjena njemačkoj vojnoj komandi; Beograd se od tog datuma smatra glavnim gradom Nedićeve Srbije.", "f25ea523"]},
"OLAYLAR_LAB19_2S_P6:1944-10-06:0":{"b": ["Nedić je napustio Beograd; kolaboracionistička vlada faktički je prestala postojati", "a56652e3"], "d": ["Milan Nedić napustio je Beograd i teritoriju Srbije 6. oktobra 1944.; Ivan Petković, imenovan za predsjednika vlade, tu dužnost faktički nikada nije preuzeo. Grad je ostao pod njemačkim vojnim nadzorom do 20. oktobra 1944., kada su ga oslobodili partizani.", "bcd6274d"]},
"OLAYLAR_LAB19_2S_P6:1944-10-20:0":{"b": ["Narodnooslobodilačka vojska Jugoslavije i Crvena armija oslobodile su Beograd", "bf067abe"], "d": ["Jedinice Narodnooslobodilačke vojske Jugoslavije uz podršku Crvene armije oslobodile su 20. oktobra 1944. Beograd od njemačke okupacije. Grad je prešao pod partizansku upravu; Nedićeva Srbija faktički se raspala dvije sedmice ranije.", "5114a3cc"]},
"OLAYLAR_LAB19_2S_P6:1945-02-14:0":{"b": ["Jugoslavenski partizani zauzeli su Mostar: u Hercegovini se urušila kontrola Nezavisne Države Hrvatske", "1e551550"], "d": ["Jedinice Narodnooslobodilačke vojske Jugoslavije zauzele su Mostar u februaru 1945.; zauzimanjem Drežnice 16. februara završena je Mostarska operacija i veći dio Hercegovine prešao je u ruke partizana.", "8bd01f9f"]},
"OLAYLAR_LAB19_2S_P6:1945-05-09:0":{"b": ["Slovenski partizani oslobodili su Ljubljanu", "fe8463ad"], "d": ["Jedinice 29. divizije i 7. korpusa Slovenske partizanske vojske ušle su 9. maja 1945. u Ljubljanu i oslobodile grad. Time je prestala uprava njemačke Operativne zone Jadransko primorje (OZAK).", "b41462f0"]},
"OLAYLAR_LAB19_BOS_1119:1446-01-01:0":{"b": ["Dirija je prvi put data Maniju ibn Rebiji: početak naselja Dirija", "17298eb7"], "d": ["Prema izvorima, Dirija je prvi put osnovana 850. (1446-47): Hadžer el-Jemama ibn Dir dao je obližnje Asibu i Mulejjebid svom rođaku Maniju ibn Rebiji.", "16e25bc0"]},
"OLAYLAR_LAB19_BOS_1119:1470-01-01:0":{"b": ["Bengazi se ponovo pojavio kao naselje (procjena)", "a54842f9"], "d": ["Procjenjuje se da se Bengazi, napušten u kasnom bizantijskom razdoblju, ponovo pojavio kao naselje oko 1470. godine.", "e6454ed3"]},
"OLAYLAR_LAB19_BOS_1119:1551-01-01:0":{"b": ["U pohodu na Tripoli 1551. oblast Berka došla je pod osmansku vlast", "e2d7e52c"], "d": ["Za vrijeme pohoda na Tripoli 1551. oblast Berka došla je pod osmansku vlast.", "a4de9dc5"]},
"OLAYLAR_LAB19_BOS_1119:1578-01-01:0":{"b": ["Bengazi je konačno pripojen osmanskoj upravi", "d50b0ffb"], "d": ["Nakon što je Berka 1551. došla pod osmansku vlast, Bengazi je 1578. konačno pripojen osmanskoj upravi; potom je kao sandžak Tripolitanskog ejaleta u XVII. stoljeću ostao pod upravom dejeva, a u XVIII. stoljeću porodice Karamanli.", "e56ee4c8"]},
"OLAYLAR_LAB19_BOS_1119:1688-01-01:0":{"b": ["Rijad pod upravom porodice Ebu Zera iz plemena Benu Hanife", "021a6f1c"], "d": ["Rijad je od 1099. (1688.) bio pod upravom porodice Ebu Zera iz plemena Benu Hanife; susjedni Emirat Dirija prešao je Saudijcima.", "ba2e75f1"]},
"OLAYLAR_LAB19_BOS_1119:1726-01-01:0":{"b": ["Muhammed ibn Suud počeo je vladati u Diriji kao nezavisni emir", "e76002ec"], "d": ["Muhammed ibn Suud, potomak Manija ibn Rebije, emir po kojem je današnja saudijska dinastija dobila ime, počeo je 1726. nezavisno vladati Dirijom i njenom okolinom.", "2dadd98a"]},
"OLAYLAR_LAB19_BOS_1119:1744-01-01:0":{"b": ["Muhammed ibn Abdulvehhab protjeran je iz Ujejne i došao u Diriju kod Muhammeda ibn Suuda: temelj vehabijsko-saudijskog saveza", "8fba33c0"], "d": ["Godine 1744. Muhammed ibn Abdulvehhab, koji je u Ujejni bio pod zaštitom Osmana ibn Ahmeda Al Muammera, poglavara Temima, protjeran je iz grada i došao u Diriju kod Muhammeda ibn Suuda; njih dvojica stvorila su vjersko-političku silu.", "0af60871"]},
"OLAYLAR_LAB19_BOS_1119:1746-01-01:0":{"b": ["Počela je borba rijadskog emira Dehhama ibn Devvasa i saudijskih snaga, s trideset pet sukoba", "46db3863"], "d": ["Rijadski emir Dehham ibn Devvas i snage vezane za porodicu Suud sukobili su se trideset pet puta između 1746. i 1773.; na kraju borbe Rijad je pao u ruke Saudijaca.", "12494f64"]},
"OLAYLAR_LAB19_BOS_1119:1765-09-16:0":{"b": ["Muhammed ibn Suud umro je u Diriji i ondje je ukopan", "8ebaece4"], "d": ["Muhammed ibn Suud, osnivač saudijske dinastije, umro je u Diriji 30. rebiul-evvela 1179. (16. septembra 1765.) i ondje je ukopan.", "1d6dea75"]},
"OLAYLAR_LAB19_BOS_1119_D:1665-01-01:0":{"b": ["Kozački ataman Černigovski podigao je tvrđavu Albazin", "a7dab4cf"], "d": ["Tvrđavu Albazin podigao je 1665. kozački ataman N. R. Černigovski na mjestu utvrđenih zimovališta koja je 1651. razorio Habarovljev odred; zimovališta su se uzdizala na zemljištu gradića Jakse u posjedima daurskog kneza Albazija.", "4699838b"]},
"OLAYLAR_LAB19_BOS_1119_D:1685-06-01:0":{"b": ["Tvrđava Albazin izgorjela je i razorena je u junu 1685. nakon prve mandžurske opsade", "a6af183c"], "d": ["Tvrđava Albazin uništena je u požaru u junu 1685. nakon prve opsade mandžurskih snaga; tvrđava je 1685-1686. ponovo izgrađena na istom mjestu.", "109536af"]},
"OLAYLAR_LAB19_BOS_1119_D:1739-01-01:0":{"b": ["Demidovljevi ljudi počeli su graditi topionicu bakra na ušću Barnaula", "4ed15cec"], "d": ["Demidovljevi ljudi pojavili su se u jesen 1739. na ušću rijeke Barnaul i počeli graditi topionicu bakra; uz topionicu je nastalo tvorničko naselje.", "53596692"]},
"OLAYLAR_LAB19_BOS_1119_E:1718-01-01:0":{"b": ["Osnovana je tvrđava Semipalatinsk (Irtiška linija)", "3ba4dbbc"], "d": ["Na ruskoj Irtiškoj utvrdnoj liniji 1718. osnovana je tvrđava Semipalatinsk; iste godine u blizini je osnovana i tvrđava Dolonskaja.", "05ac7e1e"]},
"OLAYLAR_LAB19_BOS_1119_E:1720-01-01:0":{"b": ["Major Liharev podigao je tvrđavu Ust-Kamenogorsk na ušću Ulbe u Irtiš", "3cbb514d"], "d": ["Major Liharev je 1720. na ušću rijeke Ulbe u Irtiš podigao tvrđavu Ust-Kamenogorsk; tvrđava je postala dio Irtiške utvrdne linije.", "739f9c8e"]},
"OLAYLAR_LAB19_BOS_1119_F:1680-08-10:0":{"b": ["Počela je Pueblo pobuna: Taos, Picuris i druga pueblo sela udarili su na Špance i svećenike", "b22c32c9"], "d": ["Pueblo sela u Novom Meksiku zajednički su se digla 10. augusta 1680.: u Santa Clari ubijeni su španski vojnici, u Jemezu je, po primjeru Taosa i Picurisa, upućen poziv na ubijanje svećenika i Španaca; ustanak je doveo do toga da guverner Otermín evakuira Santa Fe.", "eb1a3ce7"]},
"OLAYLAR_LAB19_BOS_1119_F:1680-08-21:0":{"b": ["Guverner Otermín napustio je Santa Fe i krenuo prema Isleti", "61a1cd02"], "d": ["Nakon devetodnevne opsade guverner Antonio de Otermín je 21. augusta 1680. naredio napuštanje Santa Fea i istog jutra poveo španske stanovnike na put prema Isleti; Santa Fe je pao u ruke pobunjeničkih pueblo snaga.", "a5c086d3"]},
"OLAYLAR_LAB19_BOS_1119_SIBIRYA:1630-01-01:0":{"b": ["Osnovan je Kirenski ostrog: ruski kozački ostrog za nametanje jasaka Tunguzima", "03d599c0"], "d": ["Ruski kozaci su 1630. na obali Lene osnovali Kirenski ostrog (iste godine kao i Ilimski, Bratski 1631.); ostrog je osnovan radi pokoravanja Tunguza.", "94e94865"]},
"OLAYLAR_LAB19_BOS_1119_SIBIRYA:1709-06-29:0":{"b": ["Na sastavu rijeka Bije i Katuna izgrađen je prvi Bikatunski ostrog (kasniji Bijsk)", "2fbcd72e"], "d": ["Ruski kozaci su 1709. na sastavu rijeka Bije i Katuna podigli prvi Bikatunski ostrog (prethodnika kasnije tvrđave Bijsk); ostrog je na jugozapadnoj granici Kuznječkog ujezda otvorio novu fazu ruske kolonizacije usmjerene prema Altaju.", "fed7b8d1"]},
"OLAYLAR_LAB19_BOS_1119_SIBIRYA:1710-01-01:0":{"b": ["Džungarski odred pod komandom zajsana Duhara spalio je prvi Bikatunski ostrog", "8c2510ca"], "d": ["Prvi Bikatunski ostrog spalio je godinu dana nakon osnivanja (1710.) džungarski odred pod komandom zajsana Duhara.", "7a8fc48f"]},
"OLAYLAR_LAB19_BOS_1119_SIBIRYA:1803-01-01:0":{"b": ["Irkutska gubernija je podijeljena: nastao je Kirenski ujezd", "40f81910"], "d": ["Godine 1803. Irkutska gubernija podijeljena je na Irkutski, Nižnjeudinski, Verhnjeudinski, Kirenski, Nerčinski i Jakutski ujezd; Kirenska jedinica potom je kao okrug trajala do kraja 19. stoljeća.", "e10043ad"]},
"OLAYLAR_LAB19_DUZELTME_1120:1814-05-01:0":{"b": ["Francuski garnizon Nieuwpoorta povukao se početkom maja 1814.: u Zapadnoj Flandriji prestala je francuska uprava", "3b3be3fa"], "d": ["Nakon primirja od 12. aprila 1814. Oostende, Diksmuide, Nieuwpoort i Ypres ostali su u francuskim rukama; ostatak departmana Lys (Zapadna Flandrija) Francuzi su napustili početkom maja, prije Prvog pariskog mira (30. maja 1814.). Oblast je do 1. augusta 1814. ostala potčinjena Generalnom guvernatorstvu Belgije.", "3484e0d8"]},
"OLAYLAR_LAB19_DUZELTME_1120:1821-03-05:0":{"b": ["Melik pokrajine Berber predao se Ismail-paši", "d1e6e36b"], "d": ["Vojska Ismail-paše, sina Mehmed Ali-paše, ušla je 3. marta 1821. u pokrajinu Berber; 5. marta melik Nasiruddin, koji je boravio u središtu pokrajine, šejhovi i uglednici dočekali su Ismail-pašu i pokorili mu se.", "380181bd"]},
"OLAYLAR_LAB19_DUZELTME_1120:1918-09-23:0":{"b": ["Osmanski garnizon napustio je Maan, Arapska vojska zauzela je grad", "40f0e4b1"], "d": ["Prema Allenbyjevom izvještaju, jedinice osmanskog II. korpusa koje su se povlačile iz Hidžaza napustile su Maan 23. septembra 1918., a grad je zauzela Arapska vojska; Arapska vojska gonila je zaštitnicu garnizona koji se povlačio sve do Džerduna.", "752cf8c4"]},
"OLAYLAR_LAB19_MOCHE_1120:0850-01-01:0":{"b": ["Kraj kulture Moche (oko 850. n. e.): raspala se država Moche sa središtem u Huacas de Moche", "e8cad6b1"], "d": ["Arheolozi sjeverne obale uglavnom smještaju kraj kulture Moche oko 850. n. e.; novi radiokarbonski datumi pokazuju da naselje u Huacas de Moche seže u 9. stoljeće i kasnije, a s tekstilnim nalazima u Huaca del Sol i u 10. stoljeće, ali da se kultura u tom procesu znatno promijenila.", "a4aab3f8"]},
"OLAYLAR_MISIR1801:1801-05-14:0":{"b": ["Damijeta uzeta od Francuza — ispražnjena tvrđava Lesbe", "06b1e7b0"], "d": ["U Damijetu je poslana snaga pod komandom Ibrahim-paše iz vojske velikog vezira. Ujutro 14. maja, dok je bio pripremljen juriš na tvrđavu Lesbe, koja je štitila Damijetu, vidjelo se da su je Francuzi ispraznili i da se garnizon povukao; zauzete su i dvije male tvrđave vezane za nju. Damijeta je nakon Rašida, koji je pao u aprilu, bila drugi grad na ušću Nila koji je izašao iz francuske kontrole.", "2eb4936c"]},
"OLAYLAR_MISIR1801:1801-06-27:0":{"b": ["Preuzimanje Kaira od Francuza — Belliardova kapitulacija", "7a11bb5e"], "d": ["Tokom zajedničke operacije osmanskih i britanskih snaga usmjerene na Egipat zapovjednik francuskih snaga u Kairu general Belliard potpisao je kapitulaciju. S Kairom je iz francuske kontrole izašao i Suez, koji su Francuzi zauzeli u novembru 1798. Zatvaranje okupacije dovršit će se dva mjeseca kasnije u Aleksandriji, a evakuacija iz zemlje trajat će do oktobra.", "e8dac3f4"]},
"OLAYLAR_MISIR1801:1801-08-31:0":{"b": ["Preuzimanje Aleksandrije od Francuza — Menouova kapitulacija", "cd50663c"], "d": ["Glavnokomandujući Istočne armije general Menou 17. augusta opsjednut je u Aleksandriji; 21. augusta Englezi su zauzeli tvrđavu Marabout blizu grada, a 31. augusta Menou je potpisao kapitulaciju vojske. Povratak francuskih jedinica u Francusku počeo je 2. septembra. Tako je okupacija, koja je počela iskrcavanjem u Aleksandriju u junu 1798, okončana u gradu u kojem je i počela.", "22e807c1"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:0763-01-01:0":{"b": ["Napuljski vojvoda Stefan II okrenuo se od Konstantinopolja prema Rimu: vojvodstvo se faktički osamostalilo", "5a181f23"], "d": ["Napuljsko vojvodstvo, vezano za Bizant, u doba Stefana II 763. okrenulo se papi i faktički postalo autonomno (prvi vojvoda Basilije postavljen je 661.).", "4202f3af"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1059-01-01:0":{"b": ["Cosenza je iz Bizanta prešla Normanima: Vojvodstvo Apulija i Kalabrija", "80b85c65"], "d": ["Vojvodstvo Roberta Guiscarda (1059.) obuhvatilo je Kalabriju; Cosenza je iz Bizanta prešla normanskom vojvodstvu (dan osvajanja specifičan za grad nije pročitan, na nivou godine).", "97fda44a"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1059-01-01:1":{"b": ["Reggio Calabria je iz Bizanta prešao Normanima: Vojvodstvo Apulija i Kalabrija", "221f6474"], "d": ["Vojvodstvo Roberta Guiscarda (1059.) obuhvatilo je Kalabriju; Reggio je iz Bizanta prešao normanskom vojvodstvu (dan osvajanja specifičan za grad nije pročitan, na nivou godine).", "31927a9e"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1071-01-01:0":{"b": ["Brindisi je iz Bizanta prešao Normanima: Vojvodstvo Apulija", "52c14154"], "d": ["Normanskim osvajanjem Barija 1071. pala je posljednja bizantijska tvrđava u Italiji; Brindisi je, vezan za niz Barija, pripojen Vojvodstvu Apuliji (rečenica s datumom specifična za grad nije pronađena).", "db68d985"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1071-01-01:1":{"b": ["Lecce je iz Bizanta prešao Normanima: Vojvodstvo Apulija", "73da4722"], "d": ["Normanskim osvajanjem Barija 1071. pala je posljednja bizantijska tvrđava u Italiji; Lecce je, vezan za niz Barija, pripojen Vojvodstvu Apuliji (rečenica s datumom specifična za grad nije pronađena).", "e11ac323"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1099-01-01:0":{"b": ["U Genovi je osnovana Compagna Communis: grad je prešao na komunalnu upravu", "1cc30776"], "d": ["Genovski uglednici osnovali su Compagnu Communis i organizirali gradsku upravu kao komunu; to je početak Genovske Republike.", "952b5184"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1128-01-01:0":{"b": ["Taranto je iz Vojvodstva Apulije prešao Kraljevini Siciliji (Ruggero II)", "3ecf982e"], "d": ["Ruggero II je 1128. zauzeo Vojvodstvo Apuliju i kneževinu Boemunda II Taranto/Otranto/Brindisi (maj-juni 1128., sekundarni izvor); istog dana kao i nizovi Barija i Salerna.", "b52e2957"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1128-01-01:1":{"b": ["Brindisi je iz Vojvodstva Apulije prešao Kraljevini Siciliji (Ruggero II)", "6519178f"], "d": ["Ruggero II je 1128. uzeo Brindisi iz kneževine Taranto Boemunda II (sekundarni izvor); istog dana kao i nizovi Barija i Salerna.", "7adade28"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1128-01-01:2":{"b": ["Lecce je iz Vojvodstva Apulije prešao Kraljevini Siciliji (Ruggero II; matično središte Bari)", "22cdacd2"], "d": ["Lecce je, pripojenjem Vojvodstva Apulije Kraljevini Siciliji (1128.), promijenio vlasnika vezan za niz Barija; rečenica s datumom specifična za grad nije pronađena.", "9c938986"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1128-01-01:3":{"b": ["Cosenza je iz Vojvodstva Apulije i Kalabrije prešla Kraljevini Siciliji (Ruggero II)", "75da9e9c"], "d": ["Kalabrija je, prelaskom Vojvodstva Apulije i Kalabrije Rogeru II (1128.), postala dio Kraljevine Sicilije; rečenica s datumom specifična za grad nije pronađena (matično središte: niz Barija/Melfija).", "e8b41ab1"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1128-01-01:4":{"b": ["Reggio Calabria je iz Vojvodstva Apulije i Kalabrije prešao Kraljevini Siciliji (Ruggero II)", "37e6922f"], "d": ["Kalabrija je, prelaskom Vojvodstva Apulije i Kalabrije Rogeru II (1128.), postala dio Kraljevine Sicilije; rečenica s datumom specifična za grad nije pronađena (matično središte: niz Barija/Melfija).", "e8b41ab1"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1143-01-01:0":{"b": ["Osnovana je Rimska komuna: obnovljen je senat (renovatio senatus), papinska svjetovna vlast je suspendirana", "b54d2c34"], "d": ["Rimski narod je na Kapitolu ponovo uspostavio komunu i senat; pod utjecajem Arnolda iz Brescie papinska vlast faktički se nije priznavala do 1155. (titula f 1143., Treccani 1144.).", "baeccd38"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1283-01-01:0":{"b": ["Reggio Calabria je od Anžuvinaca prešao Aragonskoj Siciliji (Pedro III iskrcao se u Kalabriji)", "800b47b1"], "d": ["Nakon Sicilijanske večernje (1282.) Reggio je ostao u anžujskim rukama; početkom 1283. aragonski kralj Pedro III iskrcao se u Kalabriji i Reggio je postao aragonska baza rata protiv Anžuvinaca (u julu 1284. Karlo Anžujski opsjedao je grad i nije ga uspio zauzeti). Dan nije naveden u izvoru, na nivou godine.", "6b2afca7"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1302-08-31:0":{"b": ["Mir u Caltabellotti: Reggio Calabria vratio se iz Aragonske Sicilije Anžuvincima (Napulju)", "241c90a7"], "d": ["Mir u Caltabellotti (31. augusta 1302.) donio je to da se Federico III odrekne posjeda u kopnenoj Kalabriji, a da otok ostane aragonskoj grani kao Kraljevina Trinakrija; Reggio je prešao anžujskom Napuljskom Kraljevstvu.", "c2a155cb"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1318-07-25:0":{"b": ["Jacopo I da Carrara izabran je za zaštitnika i namjesnika Padove: Padovanska komuna prešla je jednom senjoru", "b3fc0eae"], "d": ["Padovanska aristokratija izabrala je Jacopa I da Carraru za doživotnog zaštitnika/namjesnika (ubrzo nakon 25. jula 1318.); komuna je prešla jednom senjoru. Dan nije siguran, uzet je prvi dan intervala.", "aa9a4a3f"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1351-05-01:0":{"b": ["Zürich je vječnim savezom pristupio Konfederaciji: postao je peti član uz Luzern, Uri, Schwyz i Unterwalden", "78e9419b"], "d": ["Zürich je 1. maja 1351. sklopio vječni savez s Luzernom, Urijem, Schwyzom i Unterwaldenom i postao član Stare Švicarske konfederacije.", "4646e7ae"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1399-01-01:0":{"b": ["Pisa je prodata Gianu Galeazzu Viscontiju (Gherardo d'Appiano)", "eba05ce2"], "d": ["Signoriju porodice Appiano u Pisi Gherardo je prodao milanskom vojvodi Gianu Galeazzu Viscontiju; Pisa je 1399-1402. bila vezana za Milansko vojvodstvo. Dan nije naveden u izvoru (na nivou godine 1399.).", "705f44b2"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1402-09-03:0":{"b": ["Umro je Gian Galeazzo Visconti: Pisa se odvojila od Milana i ostala nezavisna pod Gabrielom Marijom Viscontijem", "9e80b0ad"], "d": ["Smrću Giana Galeazza (septembar 1402.) Pisa je oporukom prešla njegovom vanbračnom sinu Gabrielu Mariji Viscontiju; Treccani EI i SNS to opisuju kao kratkotrajnu nezavisnost Pise. Gabriele Maria je 27. augusta 1405. prodao svoja prava Firenci, a grad je osvojen u oktobru 1406.", "e34aec85"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1506-11-11:0":{"b": ["Papa Julije II ušao je u Bolognu: senjorstvo Bentivoglija je ukinuto, počela je neposredna papinska uprava", "dc4823a7"], "d": ["Papa Julije II ušao je s vojskom u Bolognu i protjerao Giovannija II Bentivoglija; grad je pripojen Papinskoj Državi.", "9afc6459"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1532-01-01:0":{"b": ["Okončana je komunalna sloboda Ancone: za Klementa VII došla je pod neposrednu papinsku vlast", "d2fbbb8f"], "d": ["Komunalna sloboda Republike Ancone završila je 1532., kada je za Klementa VII došla pod neposrednu vlast papinstva (preciznost do godine; dan/mjesec nisu pročitani).", "518c4913"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1536-05-21:0":{"b": ["Ženeva je glasala za reformaciju: prestala je vlast biskupa i Savoje, rođena je Ženevska Republika", "dcb02e44"], "d": ["Glasanjem Opće skupštine 21. maja 1536. Ženeva je prihvatila reformaciju; grad je ostao nezavisna republika uz Bern, ali nije postao član Konfederacije.", "fd9e9db5"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1540-01-01:0":{"b": ["Okončano je senjorstvo Baglionija: Perugia je došla pod neposrednu papinsku upravu Pavla III", "3c57f2fe"], "d": ["Na kraju Rata za so ukinuto je senjorstvo Baglionija i Pavao III počeo je graditi Rocca Paolinu; prestala je faktička nezavisnost Komune Perugia (preciznost do godine; dan nije pročitan).", "0a01ed80"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1739-10-17:0":{"b": ["Kardinal Alberoni okupirao je San Marino: nametnuta je papinska uprava", "4d3a4296"], "d": ["Ravenski legat, kardinal Giulio Alberoni, vojnom silom je okupirao San Marino i pokušao ga pripojiti Papinskoj Državi; narod se opirao građanskom neposlušnošću.", "79343d06"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1740-02-05:0":{"b": ["Papa Klement XII priznao je prava San Marina: nezavisnost je vraćena", "0783c00e"], "d": ["Na osnovu tajnih predstavki papa je priznao prava San Marina; Alberonijeva okupacija je završena.", "d3268069"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1796-05-15:0":{"b": ["Napoleon je ušao u Milano: prestala je austrijska uprava", "adce9a6c"], "d": ["Bonaparte je nakon prvih pobjeda u italijanskom pohodu 15. maja 1796. ušao u Milano; Lombardija je izašla iz austrijskih ruku.", "2a2ae65e"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1796-06-23:0":{"b": ["Bolonjsko primirje: Bologna i Ferrara prešle su u francuske ruke", "5eed42c8"], "d": ["Papa Pio VI potpisao je primirje u Bologni; legacije Bologna i Ferrara ušle su pod francusku kontrolu i plaćena je teška odšteta.", "4447b7b3"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1796-12-27:0":{"b": ["Proglašena je Cispadanska republika (Modena, Reggio, Bologna, Ferrara)", "f9ee3f5a"], "d": ["Na kongresu u Reggiju ujedinili su se Modena, Reggio, Bologna i Ferrara i proglasili Cispadansku republiku; vojvodstvo Este faktički je prestalo postojati.", "0529810e"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1797-02-02:0":{"b": ["Wurmser je predao Mantovu", "476b954d"], "d": ["Na kraju višemjesečne opsade austrijski zapovjednik Wurmser predao je 2. februara 1797. Mantovu Francuzima.", "68c18933"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1797-02-19:0":{"b": ["Tolentinski mir: papa je Bolognu, Ferraru i Romagnu prepustio Francuskoj", "9868973b"], "d": ["Pio VI sklopio je u Tolentinu mir s Francuskom; Bologna, Ferrara i Romagna (Ravenna, Rimini) prešle su Cispadanskoj republici pod francuskim vodstvom.", "2d453d48"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1797-05-12:0":{"b": ["Mletačka Republika prestala je postojati: Veliko vijeće se samo raspustilo", "a03a1a31"], "d": ["Pod Napoleonovim pritiskom Veliko vijeće se 12. maja 1797. samo raspustilo, dužd Manin podnio je ostavku; počela je francuska okupacija, a daljnja sudbina Veneta određena je u Campo Formiju.", "cd4ad1df"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1797-07-09:0":{"b": ["Cisalpinska republika svečano je osnovana u Milanu: ujedinili su se Lombardija, Mantova, Bergamo, Brescia i cispadanske zemlje", "b8338ba1"], "d": ["Lombardija, Mantova, Bergamo, Brescia, koje je Napoleon osvojio, Cispadanska republika (Modena, Reggio, Bologna, Ferrara) i Romagna ujedinjene su u jednu državu.", "ed1bf80a"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1798-02-15:0":{"b": ["Proglašena je Rimska Republika: papinska uprava je prekinuta", "30145500"], "d": ["Pod Berthierovom okupacijom Rima, na Kapitolu je proglašena Rimska Republika; papa Pio VI poslan je u izgnanstvo.", "99f72dba"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1798-04-26:0":{"b": ["Ženeva je anektirana Francuskoj: Ženevska Republika je prestala postojati, uspostavljen je departman Léman", "cbee4241"], "d": ["Potpisan je ugovor o aneksiji s Francuskom; Ženeva i okolina pridružile su se Francuskoj Republici kao departman Léman.", "3c1c8254"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1798-12-09:0":{"b": ["Pijemont je stavljen pod francusku upravu; Karlo Emanuel IV povukao se na Sardiniju", "d4e022ae"], "d": ["Savojska dinastija u decembru 1798. napustila je kopneni Pijemont i povukla se na otok Sardiniju, a Torino je došao pod francusku kontrolu (zvanična aneksija 11. septembra 1802.).", "dcb442ed"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1799-01-23:0":{"b": ["Proglašena je Partenopejska republika: francuska vojska ušla je u Napulj, mjesto burbonskog kraljevstva preuzela je sestrinska republika", "f657b307"], "d": ["Championnetova vojska zauzela je Napulj; burbonski Ferdinand IV pobjegao je u Palermo. Faktička kontrola republike uglavnom se odnosi na grad Napulj i okolinu (provincija je ostala naklonjena Burbonima).", "9e17f40e"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1799-04-27:0":{"b": ["Nakon Cassana austrijsko-ruska vojska srušila je Cisalpinsku republiku", "5b6ad0d8"], "d": ["Nakon bitke kod Cassana austrijsko-ruske snage ušle su u Lombardiju; Cisalpinska republika se urušila.", "09c16276"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1799-06-13:0":{"b": ["Kardinal Ruffo povratio je Napulj: Partenopejska republika je prestala postojati, vratila se burbonska uprava", "04d437c6"], "d": ["Sanfedistička vojska pod komandom kardinala Ruffa ušla je u Napulj; republikanske tvrđave ubrzo su se predale, a kraljevstvo se vratilo pod burbonsku upravu.", "775b1d4c"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1799-09-30:0":{"b": ["Napuljske jedinice ušle su u Rim: Rimska Republika je prestala postojati, vratila se papinska uprava", "a367ed6a"], "d": ["Napuljske snage zauzele su Rim i Rimska Republika je prestala postojati; faktički povratak papinske uprave dovršen je u julu 1800. ulaskom Pija VII.", "6ee7e336"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1800-06-04:0":{"b": ["Nakon Marenga Napoleon je ponovo uspostavio Cisalpinsku republiku", "c03710d1"], "d": ["Nakon pobjede kod Marenga Napoleon se vratio u Milano i ponovo uspostavio Cisalpinsku republiku (informativni okvir: 2. juni).", "df5345f5"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1802-10-09:0":{"b": ["Umro je parmski vojvoda Ferdinand I: vojvodstvo je prešlo pod francusku upravu", "0e6bc319"], "d": ["Ferdinand, koji je Aranjueskim ugovorom (1801.) prenio vojvodstvo Francuskoj, umro je 9. oktobra 1802.; Parma i Piacenza ušle su pod francusku upravu (zvanična aneksija 1808.).", "5d07614d"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1805-06-04:0":{"b": ["Napoleon je prihvatio aneksiju Ligurije: Genova je pripojena Francuskom Carstvu", "ecc8047e"], "d": ["Ligurski senat potvrdio je aneksiju 25. maja 1805.; Napoleon ju je prihvatio 4. juna 1805. i Ligurska republika je prestala postojati.", "054ecfb4"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1805-12-26:0":{"b": ["Požunski mir: Veneto, Istra i Dalmacija prešli su Kraljevini Italiji", "94ff5a04"], "d": ["Austrija je bivše mletačke posjede (Veneto, Friuli, Istru, Dalmaciju) prepustila Napoleonovoj Kraljevini Italiji.", "5e25f259"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1807-12-10:0":{"b": ["Kraljevina Etrurija prestala je postojati: Toskana je ušla pod francusku okupaciju", "f4c9b9ef"], "d": ["Napoleon je raspustio Kraljevinu Etruriju; kraljica regentica napustila je Firencu, a Toskana je 1808. pripojena Francuskoj kao departmani Arno, Ombrone i Méditerranée.", "d2e2917f"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1808-04-02:0":{"b": ["Napoleon je Marke pripojio Kraljevini Italiji: Ancona je postala središte departmana Metauro", "2314868d"], "d": ["Dekretom br. 158 izdatim u Saint-Cloudu, Marke koje su pripadale Papinskoj Državi dodane su Kraljevini Italiji; dekretom od 20. aprila 1808. uspostavljeni su departmani Metauro (Ancona), Musone (Macerata) i Tronto (Fermo).", "10d2d834"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1809-05-17:0":{"b": ["Napoleon je Papinske zemlje pripojio Francuskom Carstvu", "f4ba4cb8"], "d": ["Rim i preostali dijelovi Papinske Države (uključujući Umbriju) anektirani su Francuskoj; Pio VII je uhapšen. Tim dekretom Perugia (Umbrija) pripojena je Francuskom Carstvu.", "824297f5"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1810-02-28:0":{"b": ["Pariški ugovor: Bavarska je Južni Tirol (Trento) prepustila Napoleonu, oblast je pripojena Kraljevini Italiji", "01762dda"], "d": ["Bavarski kralj predao je Južni Tirol Napoleonu; uspostavljen je departman Alto Adige sa središtem u Trentu i pripojen Kraljevini Italiji (podjela od 9. juna 1810.).", "1ceb45f7"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1813-10-13:0":{"b": ["Austrija se vratila u Trst: prestala je francuska uprava u Ilirskim provincijama", "8d0c9c7d"], "d": ["Austrijske jedinice i britanska flota ušle su u Trst u oktobru 1813.; prema Treccaniju, grad se 13. oktobra 1813. vratio Austriji. Francuski garnizon povukao se u tvrđavu San Giusto, 29. oktobra potpisani su uslovi kapitulacije, a 8. novembra izašao je iz tvrđave. Karta prikazuje povratak grada (13. oktobra).", "a8adb522"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1813-10-15:0":{"b": ["Austrijske jedinice ušle su u Trento: urušio se departman Alto Adige Kraljevine Italije", "1870c11e"], "d": ["Austrijske jedinice pod komandom generala Fennera ušle su u Bolzano 11., a u Trento 15. oktobra 1813.; 10. decembra 1813. uspostavljena je privremena austrijska uprava.", "66916a3e"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1813-12-31:0":{"b": ["Francuski garnizon povukao se iz Ženeve: ponovo je uspostavljena Ženevska Republika", "b06ab617"], "d": ["Približavanjem austrijskih jedinica urušila se francuska uprava; 31. decembra 1813. restaurirana je Ženevska Republika, koja je 1814-1815. pristupila Konfederaciji.", "0fe9a364"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1814-04-11:0":{"b": ["Fontainebleau: Parma i Piacenza dati su Mariji Lujzi", "909f6ba0"], "d": ["Nakon Napoleonove abdikacije Parma, Piacenza i Guastalla dati su njegovoj supruzi Mariji Lujzi (faktički je preuzela upravu 1816.).", "6d19058c"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1814-04-16:0":{"b": ["Eugène je u Mantovi potpisao primirje: Kraljevina Italija se urušila, Austrija je uzela Milano", "f658fa23"], "d": ["Primirjem u Schiarino-Rizzinu faktički je prestala Napoleonova Kraljevina Italija; Lombardija i Veneto ušli su pod austrijsku kontrolu (zvanična predaja Završnim aktom Bečkog kongresa, 9. juna 1815.).", "a0989fbc"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1814-05-20:0":{"b": ["Viktor Emanuel I vratio se u Torino: savojska dinastija je restaurirana", "32499bf1"], "d": ["Prestala je francuska uprava Pijemontom; Viktor Emanuel I vratio se sa Sardinije u Torino i ponovo stavio na snagu ustav iz 1770.", "8db5bb96"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1814-05-24:0":{"b": ["Pio VII vratio se u Rim: ponovo je uspostavljena papinska uprava", "d0b4171c"], "d": ["Nakon petogodišnjeg zarobljeništva papa Pio VII 24. maja 1814. trijumfalno je ušao u Rim; Papinska Država je restaurirana (Legacije su vraćene 1815.).", "d93a4a6c"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1814-07-14:0":{"b": ["Franjo IV preuzeo je upravu kao vojvoda Modene: restaurirano je vojvodstvo Este-Habsburg", "e06a5823"], "d": ["Kada se raspala Napoleonova Kraljevina Italija, Vojvodstvo Modene i Reggija vraćeno je dinastiji Habsburg-Este (Franji IV).", "daa659f4"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1814-09-01:0":{"b": ["Restauriran je veliki vojvoda Toskane Ferdinand III", "f6f21c83"], "d": ["Po završetku Napoleonovog doba Ferdinand III iz dinastije Habsburg-Lorraine ponovo je preuzeo upravu u Toskani (septembar 1814.).", "a310e5c7"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1848-03-22:0":{"b": ["Manin je zauzeo venecijanski Arsenal: proglašena je Republika Sv. Marka", "154bae0a"], "d": ["Pod vodstvom Danielea Manina Venecija se digla protiv austrijske uprave i proglasila Republiku Sv. Marka; austrijske jedinice povukle su se iz grada 26. marta.", "476c31cc"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1849-02-09:0":{"b": ["Proglašena je Rimska Republika: dok je papa pobjegao u Gaetu, Ustavotvorna skupština uspostavila je republiku", "282025d1"], "d": ["Trijumvirat s Mazzinijem na čelu proglasio je republiku u Rimu; papinska uprava je suspendirana.", "03575b62"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1849-07-03:0":{"b": ["Francuska vojska ušla je u Rim: Rimska Republika je prestala postojati, vratila se papinska uprava", "2e5ed341"], "d": ["Francuske ekspedicione snage Oudinota zauzele su Rim; Garibaldi se povukao i republika je pala (Wikipedia 2. juli, većina izvora 3. juli).", "bbaabf25"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1849-08-22:0":{"b": ["Venecija se predala Austriji: Republika Sv. Marka je prestala postojati", "f5e5de33"], "d": ["Nakon opsade, kolere i gladi Manin je predao grad; vratila se austrijska uprava (informativni okvir navodi 27. august).", "70a16b74"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:1943-09-23:0":{"b": ["Mussolini je osnovao Republiku Salò: sjeverna Italija postala je Italijanska socijalna republika pod njemačkim protektoratom", "9248adee"], "d": ["Mussolini, kojeg su Nijemci oslobodili, osnovao je pod njemačkim vojnim nadzorom Italijansku socijalnu republiku (Salò), koja je obuhvatala sjevernu i srednju Italiju; Kraljevina i Badoglijeva vlada ostale su na jugu. Osnivanjem Republike Salò Venecija, Torino, Genova, Verona, Bologna i drugi gradovi sjeverne Italije prešli su Italijanskoj socijalnoj republici.", "d8f8bd9c"]},
"OLAYLAR_NAPOLYON_ITALYA_1028:536-12-09:0":{"b": ["Velizar je ušao u Rim: Rim je iz ostrogotske uprave prešao Bizantu", "f74ca8a4"], "d": ["U Gotskom ratu Velizarova vojska ušla je u Rim 9. decembra 536.; grad je oduzet Ostrogotima i pripojen Bizantu (Totila će ga ponovo uzeti 546.).", "75602e01"]},
"OLAYLAR_OK104:1284-01-01:0":{"b": ["Bizant je od Anžuvinaca povratio Kroju (Akčahisar), Drač i Valonu", "4e1a9810"], "d": ["Drač i Kroju, koje je 1271-1272. uzeo Karlo Anžujski, nakon Karlove smrti ponovo je uzeo bizantijski car Andronik II (TDV Kruya: 'ponovo je uzeo Valonu, Drač i Kroju'). Poznata je samo godina; dan nije potvrđen.", "eef9a5c3"]},
"OLAYLAR_OK104:1304-01-01:0":{"b": ["Filip Tarentski ponovo je stavio Drač (Durrës) pod anžujsku upravu", "be355b48"], "d": ["U Draču, koji je 1284. prešao Bizantu, sin napuljskog kralja Karla II, knez Tarenta Filip, ponovo je 1304. uspostavio anžujsku upravu; ponovo je proglašeno Albansko kraljevstvo (Regnum Albaniae), ali se za Filipova života ograničilo na ovaj grad (Europange: 'The kingdom of Albania was re-established in 1304, when Philip of Taranto was able to restore the Angevin regime in Durazzo'). Godine 1332. njegov sin Robert dao je Drač Ivanu od Gravine u zamjenu za Ahajsku kneževinu; Dračko vojvodstvo ostalo je u anžujskim rukama dok 1368. grad nije zauzeo Karlo Topija. Poznata je samo godina; dan nije potvrđen.", "f918f799"]},
"OLAYLAR_OK104:1344-01-01:0":{"b": ["Srbi su zauzeli Kroju (Akčahisar), Berat i Valonu", "cef4ca73"], "d": ["TDV Kruya: '1344. Srbi su zauzeli Kroju, Berat i Valonu'. TDV, članak o Albaniji, navodi da je Dušan okupirao Albaniju između 1343. i 1346., a da su 1355. raspadom njegovog carstva ojačali lokalni velikaši. Poznata je samo godina; dan nije potvrđen.", "0ab9765f"]},
"OLAYLAR_OK104:1393-05-01:0":{"b": ["Dukagjini prepuštaju Lješ (Alessio) Veneciji", "2cab90db"], "d": ["Paul i Lek Dukagjin, koji su od 1387. držali Lješ (Alessio) kao središte albanske Kneževine Dukagjin, uvidjevši da pred osmanskim pritiskom neće moći braniti tu luku na ušću Drima, prepustili su tvrđavu Veneciji i povukli se u brdski kraj istočno od grada. Grad je nakon toga ostao u mletačkim rukama sve dok ga 1478., za vrijeme pohoda Mehmeda II Osvajača na Skadar, nije zauzeo rumelijski beglerbeg Davud-paša — i to što je Skenderbeg ovdje 1. marta 1444. okupio protivosmanski savez (Lješku ligu, Lidhja e Lezhës) i što je 17. januara 1468. ovdje umro dogodilo se u mletačkoj tvrđavi.", "a7df86bc"]},
"OLAYLAR_OK104:1443-01-01:0":{"b": ["Skenderbeg je zauzeo Kroju (Akčahisar) — počinje albanski otpor", "8f007d17"], "d": ["Nakon poraza kod Izladija (TDV Kruya: 847/1443.) Skenderbeg je zauzeo Kroju. Nakon smrti njegovog oca Gjona Kastriotija 1437. Osmanlije grad nisu dale njemu, nego Hasan-begu, kojeg su postavile. Poznata je samo godina; dan nije potvrđen.", "d5be30c0"]},
"OLAYLAR_OK106:1571-01-01:0":{"b": ["Poljska pomjera liniju na Dnjepru — osnivanje Kremenčuka", "1bc86966"], "d": ["Poljsko-litvanska država osnovala je na prijelazu na srednjem Dnjepru, kuda su prolazili krimski napadi, novi pogranični gradić; dvadeset pet godina kasnije tu je dodata i tvrđava. Tako se poljska linija kontrole spustila do sjevernog ruba Zaporoške stepe i taj riječni prijelaz prvi put je vezan za stalni garnizon neke države. Gradić će u sljedećem stoljeću kao središte kozačkog puka prijeći u poredak Hetmanata.", "4d022f2b"]},
"OLAYLAR_OK106:1616-01-01:0":{"b": ["Pojava Umanja na poljskoj pograničnoj liniji Jedisana", "2e6551ab"], "d": ["Uman se kao naselje na jugoistočnom kraju bratslavskog područja pod poljskom upravom prvi put pominje u dokumentima. Ležao je na putevima kojima je Krimski kanat napadao prema sjeveru; to što se ondje ustalio gradić pokazuje da se prazni stepski pojas između dvije države počeo sužavati sa sjevera. Grad će naredna dva stoljeća ostati najjužnije veliko poljsko naselje na toj liniji.", "7a425b4c"]},
"OLAYLAR_OK106:1638-01-01:0":{"b": ["Pomjeranje moskovske odbrambene linije u stepi — Čugujev", "c68d36d3"], "d": ["Kozački vođa Jakiv Ostrjanin i njegovi ljudi, koji su nakon njegovog ustanka u Poljskoj utočište našli u Moskovskoj državi, osnovali su pogranično naselje uz Donjec. To je bio jedan od prvih velikih skokova prema stepi odbrambene linije koju je Moskva gradila protiv krimskih napada; u narednih pola stoljeća na istoj liniji redom će nastati gradići poput Sumija, Izjuma i Bahmuta. Naselje je do 1765. ostalo središte satnije Harkovskog puka.", "3fdefaaa"]},
"OLAYLAR_OK106:1652-01-01:0":{"b": ["Osnivanje Slobodske Ukrajine — Sumi i pojas stepskih naselja", "ab7abf59"], "d": ["Seljaci i Kozaci iz bilocerkivskog puka na desnoobalnoj Ukrajini osnovali su pod vodstvom pukovnika Herasima Kondratjeva novi gradić uz Psel; četiri godine kasnije moskovski vojvoda utvrdio je tvrđavu. Taj migracijski val početak je poretka Slobodske Ukrajine, koji je praznu stepu na južnoj granici Moskve otvorio za naseljavanje: doseljenicima je davano oslobađanje od poreza, a zauzvrat se od njih očekivala pogranična straža. Sumi je od 1658. do 1765. bio središte puka koji je nosio njegovo ime.", "fc9a8983"]},
"OLAYLAR_OK106:1703-05-17:0":{"b": ["Gradnja Jeni-Kalea — zaključavanje Kerčkog moreuza", "d9067015"], "d": ["Nakon što je 1700. Azov ustupljen Rusiji, jedina vrata Crnog mora prema Azovskom moru pretvorila su se u stratešku graničnu liniju. Osmanska država dala je na lokalitetu Akıntı Burnu, deset kilometara sjeveroistočno od grada Kerča, sagraditi novo utvrđenje i tako prolaz kroz moreuz dovela u domet topova; tvrđava je dobila ime Jeni-Kale (Nova tvrđava). Sedamdeset godina ostala je istočna brava Krima, a članom devetnaest Mira u Küçük Kaynardži 1774. ustupljena je Rusiji zajedno s Kerčom.", "8f8533a1"]},
"OLAYLAR_OK106:1754-01-01:0":{"b": ["Tvrđava Svete Jelisavete — južna granica Rusije doseže liniju osmansko-krimskih napada", "b9097272"], "d": ["Rusija je na zemlji zaporoških Kozaka sagradila novu tvrđavu s imenom Svete Jelisavete. Njena javna svrha bila je zaštita balkanskih doseljenika naseljenih u Novoj Srbiji od osmanskih i krimskih napada; naime, ruska granična linija prvi put se spustila do sred stepe, na puteve napada. Ta isturena postaja postala je dvadeset godina kasnije polazna tačka širenja na sjevernom Crnom moru koje počinje Mirom u Küçük Kaynardži.", "8ac6527e"]},
"OLAYLAR_OK106:1847-05-31:0":{"b": ["II ugovor u Erzurumu — granica na Šatt al-Arabu i ustupanje obale Huzistana", "5d1f9103"], "d": ["Osmansko-iranski granični spor, neriješen više od jednog stoljeća, uređen je nakon dugih pregovora uz britansko i rusko posredovanje drugim ugovorom potpisanim u Erzurumu. Cijeli plovni put Šatt al-Araba ostao je Osmanlijama; zauzvrat su naselja na istočnoj obali rijeke — uključujući luku Muhameru i ostrvo Abadan nasuprot — ostavljena Kadžarima. Tako je obalni pojas Huzistana, koji se od pripojenja Basre 1546. smatrao pod osmanskom upravom, nakon tri stotine godina izgubljen. Mehmed Huršid-paša, član granične komisije osnovane da na terenu utvrdi liniju povučenu ugovorom, obilazio je područje 1848-1852. i napisao Putopis o granicama (Seyâhatnâme-i Hudûd).", "8fe2f887"]},
"OLAYLAR_OK107:1514-09-15:0":{"b": ["Povlačenje iz Tabriza — kraj sedmičnog zaposjedanja i povratak preko Karsa i Bayburta", "fd1542e3"], "d": ["Sultan Selim Javuz, koji je nakon pobjede kod Čaldirana 6. septembra ušao u Tabriz, ostao je u gradu oko sedmicu dana; riznicu šaha Ismaila i dio gradskih zanatlija i učenjaka s porodicama preselio je u Istanbul. Htio je prezimiti u Karabahu i iduće godine nastaviti pohod, ali je zbog protivljenja janjičara od te namisli odustao, pa se vojska vratila preko Karsa i Bayburta. Tako Tabriz nije ostao u osmanskim rukama: Čaldiran je bio pobjeda na bojnom polju, a trajni teritorijalni dobitak došao je iduće godine pohodom na Kemah, Diyarbekir i istočnu Anadoliju.", "9cc5fc19"]},
"OLAYLAR_OK107:1515-09-19:0":{"b": ["Pripojenje Nusaybina, Derika i Silopija Osmanskoj državi — južni krak Diyarbekira", "c3621d22"], "d": ["Nakon preuzimanja Amida i osnivanja beglerbegluka Diyarbekir, kada je Idris Bitlisi pridobio kurdske begove u tom kraju, pod osmansku upravu prešli su i Nusaybin, Derik i Silopi južno od ravnice Mardina. Ta mjesta organizirana su kao središta nahija i kadiluka novog beglerbegluka; neka, poput Cizrea, ostavljena su domaćim begovima sa statusom nasljednih posjeda (yurtluk-ocaklık). Tako je pohod u istočnoj Anadoliji, započet nakon Čaldirana, stigao do Gornje Džezire.", "f975424e"]},
"OLAYLAR_OK109:1918-10-28:0":{"b": ["Proglašenje nezavisnosti Čehoslovačke — prva država nasljednica habsburške baštine", "8f40155f"], "d": ["Kada je Austro-Ugarska izgubila snagu u ratu i usljed štrajkova, demonstracija i ustanaka u zemlji, Narodni odbor je 28. oktobra 1918. proglasio nezavisnost Čehoslovačke. Na osnovu izbornog stanja iz 1911. osnovana je privremena narodna skupština, a 14. novembra 1918. počela je raditi vlada na čijem je čelu kao predsjednik postavljen Masaryk. Nova država svoje mjesto u međunarodnom pravu stekla je Mirom u Saint-Germain-en-Layeu (10. septembra 1919). Na karti se Čehoslovačka pojavljuje 11. novembra 1918; proglašenje nezavisnosti je dvije sedmice ranije. Tim proglašenjem Hradec Králové (Češka), Olomouc i Brno (Moravska) prešli su Čehoslovačkoj.", "74de11eb"]},
"OLAYLAR_OK109:1918-10-29:0":{"b": ["Proglašenje Države Slovenaca, Hrvata i Srba — Hrvatski sabor raskinuo habsburške veze", "2e5ae559"], "d": ["Hrvatski sabor je 29. oktobra 1918. proglasio da su Hrvatska, Slavonija i Dalmacija raskinule sve državnopravne veze s Austro-Ugarskom; istog dana u Ljubljani je proslavljeno osnivanje Države Slovenaca, Hrvata i Srba. U Bosni i Hercegovini austrougarska uprava je 1. novembra 1918. predala vlast vladi Narodnog vijeća. Ta država trajala je dok 1. decembra 1918. u Beogradu nije proglašeno Kraljevstvo Srba, Hrvata i Slovenaca.", "9e0cf3b3"]},
"OLAYLAR_OK109:1918-10-30:0":{"b": ["Osnivanje Republike Austrije — njemačka jezgra habsburške baštine", "1ec8b06f"], "d": ["Nakon što je 29. oktobra u Pragu proglašeno osnivanje Čehoslovačke, a u Zagrebu Države Slovenaca, Hrvata i Srba, i austrijski Nijemci su 30. oktobra osnovali Republiku Austriju. Istog dana Osmanska država potpisivala je Mudroski mir; kraj dvaju carstava pao je u kalendaru jedan uz drugi.", "3772c9f7"]},
"OLAYLAR_OK109:1918-10-31:0":{"b": ["Revolucija astri — Károlyi postao predsjednik vlade, u Mađarskoj počela da se raspada monarhija (narodna republika proglašena 16. novembra)", "d7780d2e"], "d": ["Kada je postao jasan poraz Centralnih sila, u Mađarskoj su ojačala antimonarhistička osjećanja i došlo je do skretanja ulijevo. 31. oktobra 1918, na kraju \\\"revolucije astri\\\", predsjednik vlade postao je grof Mihály Károlyi radikalnih pogleda, zatim je proglašena narodna republika; Károlyi je 11. januara 1919. izabran za redovnog predsjednika republike.", "0a48f4b7"]},
"OLAYLAR_OK109:1918-11-03:0":{"b": ["Primirje u Villi Giusti — Austro-Ugarska položila oružje, Trento i Trst prešli Italiji", "75da65fb"], "d": ["Potpisivanje primirja cara Karla s Italijanima u Villi Giusti 3. novembra 1918. ubrzalo je raspad carstva. TDV taj dan izričito bilježi kao polaganje oružja Austrije: \"Priznavši poraz, Austrija je 3. novembra, a Njemačka 11. novembra položila oružje.\" Na karti Trento i Trst tog dana prelaze od Austrije Italiji — to je prvi prijenos teritorije u raspadu vidljiv na karti. Tim primirjem Brixen, Cortina d'Ampezzo, Gorica i Gradisca južno od linije Brenner–Toblach–Julijske Alpe prešli su pod italijansku okupaciju.", "11a74dbf"]},
"OLAYLAR_OK109:1918-11-11:0":{"b": ["Nezavisnost Poljske — Regentsko vijeće predalo komandu nad vojskom Piłsudskom", "e8b546cf"], "d": ["Józef Piłsudski vratio se u Varšavu 10. novembra 1918. Regentsko vijeće mu je 11. novembra predalo komandu nad vojskom, a nekoliko dana kasnije povjerilo mu i zadatak sastavljanja nacionalne vlade.", "578314ea"]},
"OLAYLAR_OK109:1918-11-14:0":{"b": ["Srpska vojska zauzela Pečuh — počela srpska okupacija Baranje", "68f0695f"], "d": ["Pečuh, strateški važan zbog rudnika uglja, 14. novembra 1918. došao je pod srpsku okupaciju. Srpska okupacija Pečuha i županije Baranje trajala je do augusta 1921.", "7222b6bd"]},
"OLAYLAR_OK109:1918-11-14:1":{"b": ["Srpska vojska zauzela Temišvar — počela srpska vojna uprava u Banatu", "3cc85350"], "d": ["Srpske jedinice zauzele su 14. novembra 1918. Temišvar, raspustile narodnu gardu i preuzele vojnu, a ubrzo i civilnu upravu Banata. Početkom decembra u grad su ušle i francuske jedinice; rumunska uprava uspostavljena je tek u julu-augustu 1919.", "78697a6b"]},
"OLAYLAR_OK109:1918-11-19:0":{"b": ["Srpske jedinice ušle u Szigetvár — okupacija južnog Somogya", "a06b1907"], "d": ["Iz srpske vojske koja je napredovala sjeverno od linije povučene Beogradskim vojnim sporazumom, 220 vojnika pod komandom Obrena Petrovića ušlo je u noći s 18. na 19. u Szigetvár, sreski centar Somogya; tom snagom držana su i sela sreza. Okupacija je trajala do augusta 1921; Trianon je Szigetvár ostavio u Mađarskoj.", "9485d5ab"]},
"OLAYLAR_OK109:1918-12-01:0":{"b": ["Osnivanje Kraljevstva Srba, Hrvata i Slovenaca i Velike Rumunije — istog dana dvije države", "6fd85345"], "d": ["Ujedinjenjem Slavena koji su se raspadom Austro-Ugarske odvojili od carstva sa Srbijom, 1. decembra 1918. osnovano je Kraljevstvo Srba, Hrvata i Slovenaca; oko 250.000 km² teritorije i 12.000.000 stanovnika. Temelj je postavljen Krfskom deklaracijom 20. jula 1917, a skupštine u Podgorici 26. oktobra, u Bosni i Hercegovini 28. oktobra i u Novom Sadu 25. novembra donijele su odluku o pridruživanju. Istog dana, pridruživanjem Transilvanije, Bukovine i Besarabije odlukom njihovih naroda, nastala je Velika Rumunija. Na karti teritorije Kraljevine Srbije prelaze Jugoslaviji. Osnivanjem Kraljevstva sve teritorije Kraljevine Srbije (Niš, Skoplje, Bitola, Ohrid, Priština, Prizren, Peć i dr.) prešle su Kraljevstvu Srba, Hrvata i Slovenaca.", "4fd0ff67"]},
"OLAYLAR_OK109:1918-12-01:1":{"b": ["Rumunska vojska ušla u Brašov i svečano dočekana", "4a917d27"], "d": ["Rumunska vojska ušla je u decembru 1918. u Brašov; rumunski uglednici grada svečano su dočekali vojsku i generala Berthelota.", "96d03f2f"]},
"OLAYLAR_OK109:1918-12-19:0":{"b": ["Italijanska vojska zauzela Knin", "7949dd0f"], "d": ["Italijanska vojska zauzela je Knin 19. decembra 1918. Okupacija je trajala do 4. aprila 1921, kada se italijanska vojska nakon Rapalskog ugovora povukla iz grada.", "f4363313"]},
"OLAYLAR_OK109:1918-12-29:0":{"b": ["Čehoslovačke jedinice zauzele Košice (Kassa)", "0989490f"], "d": ["Kada je 29. decembra 1918. 30. pješadijski puk koji nosi ime Aloisa Jiráseka zauzeo grad, Košice su faktički pripojene Republici Čehoslovačkoj.", "2453b355"]},
"OLAYLAR_OK109:1919-04-20:0":{"b": ["Rumunska vojska ušla u Satu Mare (19. aprila) i Oradeu (20. aprila)", "3ee2bd72"], "d": ["Na Veliku subotu, 19. aprila 1919, u Satu Mare mjesna delegacija na čelu s dr. Ilieom Carolom Barbulom dočekala je na mostu preko Someša prvu patrolu 2. konjičke divizije pod komandom pukovnika Ressela. Sljedećeg dana, 20. aprila 1919, rumunske jedinice pod komandom generala Traiana Moșoiua ušle su u Oradeu.", "9249e364"]},
"OLAYLAR_OK109:1919-06-28:0":{"b": ["Versajski mir — povratak Alzasa i Lorene Francuskoj prešao u pravo", "3babdfcb"], "d": ["Pariška mirovna konferencija sastala se 18. januara 1919, a 28. juna s Njemačkom je potpisan Versajski mir. Član 51 ugovora vratio je pod francuski suverenitet Alzas i Lorenu (Strasbourg, Metz, Colmar, Mulhouse), njemačke od 1871 — ali prijenos nije vezao za dan potpisivanja, nego retroaktivno za primirje od 11. novembra 1918. Isti niz konferencija iznjedrio je Saint-Germain s Austrijom (10. septembra 1919), Neuilly s Bugarskom (27. novembra 1919), Trianon s Mađarskom (4. juna 1920) i Sèvres s Osmanskom državom (10. augusta 1920).", "4ab970de"]},
"OLAYLAR_OK109:1919-07-22:0":{"b": ["Rumunske jedinice stigle u Lugoj (Lugos) — rumunska uprava na istoku Banata", "f65fc73c"], "d": ["Voz s rumunskim jedinicama stigao je u Lugoj 22. jula 1919. u 14 sati; građani su dočekali vojsku na stanici, prefekt Caraș-Severina George Dobrin održao je pozdravni govor, a general Jitianu je odgovorio. U dijelu Banata koji je pripao Rumuniji rumunska uprava uspostavljena je u julu 1919; pravni prijenos obavljen je Trianonskim mirom 1920.", "b228ed28"]},
"OLAYLAR_OK109:1919-08-03:0":{"b": ["Rumunska vojska ušla u Temišvar — u gradu uspostavljena rumunska uprava", "8728e1d1"], "d": ["U Temišvar, u koji su 14. novembra 1918. ušle srpske, a početkom decembra i francuske jedinice, ujutro 3. augusta 1919. ušle su prve jedinice rumunske vojske pod komandom pukovnika Virgila Economua i u gradu je uspostavljena rumunska uprava.", "0b1627d3"]},
"OLAYLAR_OK109:1919-08-12:0":{"b": ["Vojska SHS ušla u Prekmurje — Murska Sobota i Lendava izašle iz mađarske uprave", "21b2ba08"], "d": ["Jedinice Kraljevstva Srba, Hrvata i Slovenaca 12. augusta 1919. ušle su u Prekmurje s one strane Mure; mađarska uprava na tom području završila se tog dana. Pravni prijenos obavljen je Trianonskim mirom 1920.", "3ce8a913"]},
"OLAYLAR_OK109:1919-09-10:0":{"b": ["Mir u Saint-Germainu — smanjenje Austrije prešlo u pravo", "e7b722d5"], "d": ["Nakon rata Austrija je sa saveznicima potpisala Mir u Saint-Germainu. Prema ugovoru Austrija je priznala nezavisnost Mađarske, Čehoslovačke i Jugoslavije; prihvatila je da se bez saglasnosti Lige naroda ne ujedini s Njemačkom, da ukine obaveznu vojnu službu i ograniči vojsku na 30.000 ljudi. To je i dokument kojim je Čehoslovačka stekla svoje mjesto u međunarodnom pravu. Prijenos na karti obavljen je godinu dana ranije; ovaj ugovor ga je potvrdio. Tim ugovorom Lavov, Jazlivec, Karviná te dalmatinska obala i ostrva (Krk, Cres, Lošinj, Rab, Pag, Hvar, Korčula, Vis, Zadar, Šibenik, Knin) prešli su iz austrijskih ruku na raspolaganje Glavnim savezničkim silama; Užhorod i Mukačevo (Potkarpatska Rusija) Čehoslovačkoj.", "b4d5f306"]},
"OLAYLAR_OK109:1919-11-27:0":{"b": ["Mir u Neuillyju — Bugarska izgubila Zapadnu Trakiju i egejsku obalu", "01f2b8c8"], "d": ["Nakon što se rat završio porazom, car Ferdinand bio je prisiljen zatražiti primirje i abdicirati u korist sina Borisa (29. septembra 1918). Mirom u Neuillyju, kojim je rat okončan, Bugarska je pretrpjela strateške teritorijalne gubitke u korist Srba, izgubila cijelu Zapadnu Trakiju, morala ostaviti egejsku obalu Grčkoj i potvrdila odredbe Bukureštanskog mira kojim je Južna Dobrudža data Rumuniji. Na karti odgovarajući prijenos nije na dan ugovora, nego u maju 1920, kada je uprava faktički promijenila ruke: Dedeagač, Soufli, Orestijada i Čirmen 14. maja, a Komotini, Ksanti, Didimotiho i Feres 27. maja prelaze Grčkoj.", "d61eb549"]},
"OLAYLAR_OK109:1920-06-04:0":{"b": ["Trianonski mir — Mađarska izgubila dvije trećine teritorije", "84aff507"], "d": ["Prema Trianonskom miru, potpisanom tri mjeseca nakon što je 1. marta 1920. Horthy postavljen za kraljevskog namjesnika, Mađarska je pretrpjela teške teritorijalne i ljudske gubitke: izvan granica ostale su dvije trećine od 283.000 km² njene teritorije (bez Hrvatske) i šezdeset posto stanovništva, uključujući više od tri miliona Mađara; vojska je smanjena na 35.000 ljudi. Na karti se Mađarsko namjesništvo vidi u tim smanjenim granicama; Erdelj i Gornja Ugarska upravo tog dana prelaze u boju Rumunije i Čehoslovačke. Tim ugovorom Bratislava, Košice, Nitra i Komárom (Gornja Ugarska) pravno su prešli Čehoslovačkoj; Oradea, Satu Mare, Lugoj, Alba Iulia i Brašov (Erdelj i istok Banata) Rumuniji; Subotica, Bečkerek, Bač, Murska Sobota i Čakovec (Bačka, zapad Banata, Prekmurje, Međimurje) Kraljevstvu Srba, Hrvata i Slovenaca.", "f7c54f07"]},
"OLAYLAR_OK109:1920-06-04:1":{"b": ["Banat podijeljen, Temišvar ostavljen Rumuniji (Trianon čl. 27/3 i 45)", "256b4aca"], "d": ["Trianonski mir povukao je mađarsko-rumunsku granicu članom 27/3, a članom 45 Mađarska se u korist Rumunije odrekla svih prava i naslova na bivše monarhijske teritorije s one strane te granice; time je međunarodnim pravom priznato ujedinjenje Erdelja, Banata, Crișane i Maramureša s Rumunijom. Banat je podijeljen između Rumunije i Srbije; grad Temišvar pripojen je Kraljevini Rumuniji. U Temišvaru je rumunska uprava faktički djelovala od 3. augusta 1919; ugovor je to stanje pretočio u pravo.", "5ec9c446"]},
"OLAYLAR_OK109:1921-04-04:0":{"b": ["Italijanska vojska povukla se iz Knina", "a1d2e846"], "d": ["Nakon Rapalskog ugovora italijanska vojska se 4. aprila 1921. povukla iz Knina; okupacija koja je počela 19. decembra 1918. završila se.", "0af4a592"]},
"OLAYLAR_OK109:1921-06-12:0":{"b": ["Italija predala Šibenik Kraljevstvu SHS", "9d07b12a"], "d": ["Italijanska okupacija koja je počela 6. novembra 1918. završila se 12. juna 1921. ceremonijom uz učešće vojnih predstavnika Italije i Kraljevstva SHS.", "3d4d272c"]},
"OLAYLAR_OK109:1921-08-20:0":{"b": ["Srpske jedinice povukle se iz Szigetvára — grad preuzela mađarska žandarmerija", "97781b77"], "d": ["Nakon stupanja Trianona na snagu srpske snage počele su se 17. augusta povlačiti iz Barcsa i Szigetvára i odnijele sve što se moglo odnijeti. 20. augusta oko podne ušle su mađarske žandarmerijske jedinice; poslijepodne su gradsko vijeće i službenici položili zakletvu, a u pet sati u gradskoj vijećnici obavljena je vojna primopredaja.", "1db599da"]},
"OLAYLAR_OK109:1921-08-22:0":{"b": ["Završena srpska okupacija Pečuha — mađarska Nacionalna armija ušla u grad", "f437115a"], "d": ["Srpske jedinice počele su 18. augusta 1921. napuštati područje; 20-21. augusta uprava grada i županije predata je predstavnicima mađarske vlade, a 22. augusta u grad su ušle jedinice mađarske Nacionalne armije.", "0210d518"]},
"OLAYLAR_OK109:1921-11-13:0":{"b": ["Austrijska Bundesheer ušla u Burgenland — teritorija koju je Trianon ostavio Austriji faktički preuzeta", "7bfd6915"], "d": ["Trianonski (1920) i Saint-Germainski (1919) mir ostavili su Austriji pojas zapadne Ugarske u kojem se govorio njemački; prvi pokušaj preuzimanja 28. augusta 1921. propao je zbog otpora mađarskih neregularnih jedinica. Nakon Venecijanskog protokola (13. oktobra 1921) Saveznička generalna komisija je 11. novembra odobrila ulazak Bundesheera, a dva dana kasnije počelo je preuzimanje sjevernog Burgenlanda; južni dio preuzet je 6. decembra 1921, a područje Soprona je plebiscitom ostalo Mađarskoj.", "c78d0f81"]},
"OLAYLAR_ONCE1000_1019:0330-05-11:0":{"b": ["Konstantinopol svečano otvoren; središte carstva faktički pomjereno na istok", "e4d78842"], "d": ["Nova prijestolnica koju je osnovao Konstantin I svečano je otvorena 11. maja 330; prijestolnica Bizantskog (Istočnorimskog) Carstva postao je Konstantinopol.", "482503e4"]},
"OLAYLAR_ONCE1000_1019:0969-07-06:0":{"b": ["Vojskovođa Dževher es-Sikili ušao u Fustat i osvojio Egipat; Ihšididi prestali", "fd0410b1"], "d": ["U ime fatimijskog halife Muizza li-dinillaha Dževher es-Sikili ušao je u Fustat (17. šaban 358 / 6. juli 969); Egipat je prešao s Ihšidida na Fatimije, a područje na kojem će se osnovati Kairo došlo je pod fatimijsku vlast.", "4aee6045"]},
"OLAYLAR_ONCE1000_1019:0990-03-31:0":{"b": ["Ebu Zevvad zauzeo Mosul; osnovana ukajlidska dinastija", "c3032f55"], "d": ["Ukajlid Ebu Zevvad Muhamed b. Musejjeb zauzeo je Mosul (380 / 990); izabran je prvi dan presjeka hidžretske 380. i 990. godine, 31. mart 990 (hidžretsko-gregorijanska tabela, ±1-2 dana), dan nije naveden u izvoru.", "ecd80cfe"]},
"OLAYLAR_ONCE1281_GERIYE:1147-10-24:0":{"b": ["Afonso Henriques zauzeo Lisabon (Ušbunu); grad postao središte nove Kraljevine Portugal", "24fddde8"], "d": ["Ušbuna je uzeta od Almoravida i prešla u ruke Portugala (27. džumadel-ula 542 / 24. oktobar 1147).", "bd3b3add"]},
"OLAYLAR_ONCE1281_GERIYE:1229-12-31:0":{"b": ["Jakov I zauzeo grad Majorku (Medina Majurka)", "47fd675c"], "d": ["Aragonski kralj Jakov I uzeo je grad Majorku od muslimana; Palma je prešla Aragonskoj kruni.", "462f0592"]},
"OLAYLAR_ONCE1281_GERIYE:1238-05-12:0":{"b": ["Muhamed b. Jusuf ibn el-Ahmer osnovao u Granadi Nasridsku državu", "23f66f33"], "d": ["Nasridska država osnovana je sa središtem u Granadi (26. ramazan 635 / 12. maj 1238).", "04a01554"]},
"OLAYLAR_ONCE1281_GERIYE:1238-06-01:0":{"b": ["Sporazum u Stensbyju: Njemački viteški red vratio sjevernu Estoniju (Reval) danskom kralju Valdemaru II", "b64c584d"], "d": ["Sporazumom postignutim u junu 1238. u Stensbyju na Sjællandu Reval i sjeverna Estonija vratili su se pod dansku vlast (dan nije naveden u izvoru).", "e8ad663d"]},
"OLAYLAR_ONCE1281_GERIYE:1238-09-28:0":{"b": ["Ugovor o predaji Valencije: Jakov I zauzeo grad", "977120b3"], "d": ["Balansija (Valencija) 28. septembra 1238. ugovorom o predaji prešla je aragonskom kralju Jakovu I (svečani ulazak 9. oktobra).", "c3465b4f"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1054-11-05:0":{"b": ["Ukajlid Kurejš dao je da se uči hutba u ime Tugrul-bega", "9fb65fc0"], "d": ["Kada je Tugrul-beg zbog pohoda na Bagdad stigao u oblast, ukajlidski emir Kurejš u šabanu 446 / novembru 1054. dao je da se uči hutba u ime Tugrul-bega; nakon ubistva Mervanida Sulejmana, 447/1055. teško je ranjen.", "43df7313"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1064-01-01:0":{"b": ["Sultan Alp-Arslan osvojio je Ani i upravu grada dao Šedadidu Ebu Šudžau Menučihru", "f2c51a49"], "d": ["Alp-Arslan, koji je 456/1064. osvojio Ani, upravu grada dao je Ebu Šudžau Menučihru, sinu Šedadida Ebu'l-Esvara Šavura. Menučihr je svojim zemljama pripojio i Kars te, bojeći se bizantske vojske koja se približavala, dao popraviti zidine oštećene tokom osvajanja; kao seldžučki vazal vladao je u Aniju pedeset četiri godine.", "6ddc5837"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1068-01-01:0":{"b": ["Alp-Arslan je zauzeo Ahisku", "31b9964f"], "d": ["Ahiska (1068), koju je u seldžučko doba zauzeo Alp-Arslan, 1267–1268. došla je pod mongolsku vlast.", "f2d87d84"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1068-01-01:1":{"b": ["Alp-Arslan i njegovi saveznici sravnili su sa zemljom Tbilisi i Kartli", "ff50ab5d"], "d": ["Kralj Bagrat bio je povratio veći dio svojih tvrđava; međutim, Alp-Arslan i njegovi saveznici 1068. sravnili su sa zemljom Tbilisi i Kartli.", "753e1b62"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1073-01-01:0":{"b": ["Filaret je u gradu Hunu (okolica Elbistana) okupio armenske sveštenike, dao izabrati katolikosa i učinio grad sjedištem katolikosata", "66005693"], "d": ["Filaret je, iskoristivši zarobljavanje Romana Diogena u bitki kod Manzikerta 1071, u gradu Hunu okupio armenske sveštenike i dao izabrati katolikosa. Tako je uspostavljeno vjersko središte armenske uprave u okolici Maraša, Elbistana i Malatye, odvojene od Bizanta.", "146d6889"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1076-01-01:0":{"b": ["Sultan Melikšah pohodom na Gruziju stigao je do Kartlija; odgovornost za oblast povjerio je Serhengu Savteginu", "830b979a"], "d": ["Melikšah je s gruzijskim zapovjednikom Juaneom, sinom Liparita, koji mu je ostao vjeran, poduzeo pohod na Gruziju, stigao do Kartlija, vratio se s mnogo zarobljenika i plijena i odgovornost za oblast povjerio Serhengu Savteginu (1076). Kralj Georgije II dobio je ratove protiv Savtegina i povratio neka mjesta.", "8a5912c3"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1078-07-14:0":{"b": ["Melikšah je preko Arasa ušao u Gruziju, opljačkao oblast Somkheth i zarobio Juanea", "e62fd603"], "d": ["Kada je kralj Georgije II porazio Savtegina i povratio neka mjesta, sultan Melikšah ponovo je krenuo u pohod i preko Arasa ušao u Gruziju (471/1078–79); opljačkao je oblast Somkheth, zarobio Juanea, ondje ostavio Savtegina s pojačanjima i vratio se. Emir Ahmed nanio je kralju težak poraz kod Kouela i povratio Kars.", "57f4ff76"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1083-01-01:0":{"b": ["Sulejman-šah I poduzeo je pohod na Čukurovu i osvojio Tarsus, Adanu, Anazarb i Misis", "c443ee8b"], "d": ["Sulejman-šah, koji je 1082. uzeo titulu sultana, iste je godine poduzeo pohod na Čukurovu i osvojio gradove i tvrđave Tarsus, Adanu, Anazarb i Misis (1082–1083); potom je na poziv stanovnika Antiohije sa sinovima Kilidž Arslanom i Davudom krenuo na Antiohiju.", "e617bea2"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1085-01-01:0":{"b": ["Čubuk-beg osvojio je Harput i osnovao bejluk Čubukogullari, koji je obuhvatao okolicu Palua i Čemiškezeka", "1f333d7d"], "d": ["Tokom turskih upada u Anadoliju nakon 1071, Čubuk-beg osvojio je Harput i osnovao bejluk koji je obuhvatao oblasti Palua i Čemiškezeka. Bejluk je trajao kratko; 1110-ih godina Artukid Belek zauzeo je grad.", "5c951bf7"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1085-04-29:0":{"b": ["Sultan Melikšah dao je Bitlis i oblast kao iktu Dilmačoglu Mehmed-begu; počeo je bejluk Dilmačogullari", "7cdcb46f"], "d": ["Nakon što je glavni zapovjednik seldžučke vojske Fahruddevle Ibn Džehir zauzeo Bitlis i oblast, sultan Melikšah dao ju je kao iktu Dilmačoglu Mehmed-begu, koji je učestvovao kod Manzikerta (478/1085). Bejluk je vladao u Bitlisu i Erzenu od 1085. do 1394.", "da296fec"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1085-06-20:0":{"b": ["Muslim b. Kurejš poražen je i ubijen kod Kurzahila u borbi protiv Sulejman-šaha", "fc482adb"], "d": ["Ukajlid Muslim b. Kurejš, koji je htio osnovati jedinstvenu arapsku državu nezavisnu od velikog seldžučkog sultana, kada je dao opljačkati okolicu Antiohije, zaratio je sa Sulejman-šahom; poražen je i ubijen kod mjesta Kurzahil (24. safer 478 / 20. juni 1085) i sahranjen kod Alepskih vrata.", "9f4da840"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1086-01-01:0":{"b": ["Sultan Melikšah došao je s velikom vojskom na Kavkaz i potpuno potčinio oblast", "79dd07e4"], "d": ["Nakon što je kralj Georgije II otišao u Isfahan i priznao Melikšahovo suzerenstvo, Melikšah je 1086. posljednji put s velikom vojskom došao na Kavkaz i potpuno potčinio oblast; Istočna Gruzija dobila je ime 'Didi Turkoba' (Velika turska zemlja).", "a15ba581"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1095-01-01:0":{"b": ["Čaka-bega ubio je zet Kilidž Arslan I na gozbi", "20cdcec9"], "d": ["Ana Komnena, koja bilježi da je Čaka-bega na gozbi ubio zet Kilidž Arslan, datum smrti navodi kao 1097, ali je to, s obzirom na opsadu Malatye 1096. i pad Nikeje 1097, pogrešno; datum smrti trebao bi biti 1095 (u. 488/1095 [?]).", "9a287bc8"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1097-01-01:0":{"b": ["Kilidž Arslan I opsjeo je Malatyu, koju su željeli zauzeti i Danišmendidi; digao je opsadu kada su križari krenuli prema Nikeji", "4f036db3"], "d": ["Kilidž Arslan je zimi 490/1097. krenuo na Malatyu, na koju su bacili oko i Danišmendidi, i neko je vrijeme opsjedao grad; saznavši da su križarske vojske krenule na put, okrenuo se Nikeji, koja je izgubljena (juni 1097).", "4282aef8"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1100-07-01:0":{"b": ["Gumuštegin Gazi upao je u zasjedu antiohijskom knezu Boemundu, zarobio ga i odveo u Niksar, gdje ga je zatvorio", "c43f8a71"], "d": ["Danišmendid Gumuštegin, koji je opsjedao Malatyu, iz zasjede je porazio snage antiohijskog kneza Boemunda koji je došao u pomoć; Boemund je najprije odveden u Sivas, a potom u Niksar i zatvoren. Zbog približavanja urfskog grofa Balduina opsada je dignuta.", "543833c3"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1101-06-23:0":{"b": ["Prema sporazumu križara i cara Aleksija Komnena, Ankara je prepuštena Bizantu", "d64f8668"], "d": ["Tokom Prvog križarskog rata Raimond de Toulouse zauzeo je Ankaru bez ozbiljnog otpora, a Turci u tvrđavi posječeni su mačem; prema sporazumu križara i Aleksija Komnena, grad je 23. juna 1101. prepušten Bizantskom Carstvu. Bizantska uprava trajala je oko dvadeset godina.", "f8a37732"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1101-08-01:0":{"b": ["Gumuštegin, Kilidž Arslan I i Ridvan potukli su kod Merzifona lombardsku križarsku vojsku", "f2703ea8"], "d": ["Lombardski križari, koji su radi oslobađanja Boemunda iz zarobljeništva zauzeli Ankaru i napredovali prema Çankırıju, u augustu 1101. potučeni su kod Merzifona od udružene turske vojske od 20.000 ljudi Gumuštegina, Kilidž Arslana I, alepskog melika Ridvana i haranskog emira Karadže.", "ddaa77e1"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1102-01-01:0":{"b": ["Sokmen je preuzeo Hasankeyf; osnovana je hisnkejfska grana Artukida", "07e6f974"], "d": ["Sokmen, koji je nakon smrti mosulskog emira Kurboge u Mosulu podržavao Musu, na Musino obećanje pomogao mu je da porazi Džokurmuša; nakon Musinog ubistva otišao je u Hasankeyf i preuzeo grad. Tako je osnovana hisnkejfska grana Artukida (1102–1232).", "fccc615e"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1103-01-01:0":{"b": ["Sokmen je zauzeo Mardin nakon smrti svog sinovca Jakutija", "a5099d54"], "d": ["Mardin je bio pod vlašću Sokmenovog sinovca Jakutija; iskoristivši spor izbio nakon njegove smrti, Sokmen je 1103. zauzeo grad i pridružio sebi veliki dio okolice Dijarbekira.", "43484644"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1103-08-01:0":{"b": ["Kilidž Arslan I porazio je Gumuštegina Gazija kod Maraša", "15ec5217"], "d": ["To što je Gumuštegin za otkup oslobodio Boemunda i nezadovoljstvo Kilidž Arslana, koji je tražio udio u otkupnini, zavadili su dva saveznika; Kilidž Arslan kod Maraša nanio je Gumušteginu težak poraz.", "64f2df55"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1104-01-01:0":{"b": ["Gumuštegin Gazi umro je u Sivasu; njegov sin emir Gazi stao je na čelo danišmendidske dinastije", "75915f65"], "d": ["Gumušteginovom smrću Danišmendidi su pretrpjeli veliki potres; Malatya je predata Seldžucima, među članovima dinastije izbile su borbe za prijestolje. Upravu je preuzeo stariji sin, emir Gazi.", "f184fc73"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1104-05-07:0":{"b": ["Sokmen el-Kutbi i Džokurmuš porazili su i zarobili urfskog grofa Balduina du Bourga i Josselina u okolici Harana (Baliha)", "5240d89c"], "d": ["Križarski urfski grof Balduin du Bourg i telbaširski grof Josselin 9. šabana 497 / 7. maja 1104. u bitki kod Harana poraženi su od muslimana i pali u zarobljeništvo. Junak pobjede Sokmen u oktobru iste godine razbolio se i umro.", "3b141414"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1104-10-01:0":{"b": ["Umro je Sokmen; naslijedio ga je sin Ibrahim", "c40e3436"], "d": ["Sokmen, koji se razbolio ubrzo nakon pobjede kod Harana, umro je u oktobru 1104; na čelo hisnkejfske grane došao je sin Ibrahim, a nakon Ibrahimove smrti 1108. artukidski vladar postao je njegov brat Davud.", "3fb73425"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1110-01-01:0":{"b": ["Muhammed Tapar potukao je gruzijske snage i razorio neke gradove", "372cbcc6"], "d": ["Kada je kralj David II s velikom vojskom dobivenom od Kipčaka pokrenuo novi osvajački pohod i stigao do Gandže, seldžučki sultan Muhammed Tapar krenuo je na Gruziju, potukao gruzijske snage i razorio neke gradove (503/1110).", "f381ea2e"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1110-01-01:1":{"b": ["Melikšah (Šahinšah), kojeg je poslao veliki seldžučki sultan Muhammed Tapar, zasjeo je na anadolsko seldžučko prijestolje u Konyi", "b8987991"], "d": ["Nakon smrti Kilidž Arslana I, zbog napada Aleksija Komnena, Muhammed Tapar poslao je u Anadoliju Melikšaha, starijeg sina Kilidž Arslana; Melikšah je došao u Konyu, zasjeo na prijestolje i šest godina se borio s Aleksijem.", "a8488c23"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1111-09-01:0":{"b": ["Sokmen el-Kutbi umro je u Balisu na obali Eufrata; naslijedio ga je sin Zahirudin Ibrahim", "510ea223"], "d": ["Sokmen, koji se pridružio vojsci Mevduda, sina Altuntegina, koju je Muhammed Tapar poslao na križare, kada mu se bolest pogoršala, napustio je vojsku i u septembru 1111. umro u Balisu. Na čelo Ahlatšaha došao je sin Ibrahim i ostao do 1126/1127.", "1ca34ea9"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1112-01-01:0":{"b": ["Artukid Belek učinio je Palu svojim središtem i prisvojio zemlje Čubukogullara", "624ab91f"], "d": ["Kada je 1112. Belek b. Behram zavladao Harputom, Palu je od Čubukogullara prešao harputskoj grani Artukida; Belek ga je učinio prijestolnicom.", "2d7c33df"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1118-01-01:0":{"b": ["David IV počeo je naseljavati u Gruziju 45.000 kipčačkih porodica", "559894b0"], "d": ["David se sporazumio s 45.000 kipčačkih porodica iz stepa Sjevernog Kavkaza i južne Rusije, doveo ih od 1118. u Gruziju i uz njihovu pomoć 1121. okončao seldžučku vlast u Tbilisiju.", "d4bc7246"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1119-01-01:0":{"b": ["Emir Gazi potukao je antiohijskog kneza Rogera i izvršio upad na Antiohiju", "7bd138a2"], "d": ["Emir Gazi u maju 1119. s vojskom od 7000 ljudi izvršio je upad na Antiohiju i potukao antiohijskog kneza Rogera koji je krenuo na njega.", "c575e81b"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1121-08-12:0":{"b": ["Gruzijski kralj David potukao je muslimansku vojsku kod Didgorija; otvoren je put prema Tbilisiju i Aniju", "03b19a6d"], "d": ["Protiv velike vojske koju je gruzijski kralj David (u TDV David II; u gruzijskim izvorima David IV Graditelj) dobio od Kipčaka, vojska koju je poslao irački seldžučki sultan Mahmud — gandžanski melik Tugrul, atabeg Gundogdu, Dubejs b. Sadaka i Artukid Ilgazi te Dilmačoglu Togan Arslan — poražena je 12. augusta 1121. kod Didgorija. Gruzijci su potom zauzeli Tbilisi, koji je stoljećima bio pod islamskom vlašću, i učinili ga prijestolnicom.", "d186cc45"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1122-11-19:0":{"b": ["Umro je Nedžmudin Ilgazi; njegovi sinovi Sulejman vladao je u Majjafarikinu, a Timurtaš u Mardinu", "5e1a6c08"], "d": ["Ilgazi, artukidski vladar Mardina koji je iz Alepa vodio veliku borbu protiv križara, razbolio se tokom pohoda na tvrđavu Zerdena sa sinovcem Belekom i damaščanskim atabegom Tugteginom i umro 19. novembra 1122. Od njegovih sinova Sulejman je vladao u Majjafarikinu, Timurtaš u Mardinu, a njegov sinovac Sulejman u Alepu.", "6f429e0c"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1124-01-01:0":{"b": ["Zauzimanjem okolice Malatye od strane emira Gazija Elbistan je došao pod danišmendidsku upravu", "5be35d74"], "d": ["Elbistan, razoren velikim zemljotresom 1114, došao je pod danišmendidsku upravu kada je 1124. Danišmendid emir Gazi zauzeo okolicu Malatye.", "a81725b1"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1129-01-01:0":{"b": ["Danišmendidi su preuzeli kontrolu nad oblašću Kastamonua", "e1be4a42"], "d": ["Godine 1129. Ankara, Çankırı, Kastamonu i crnomorske obale došli su pod kontrolu emira Gazija; oblast Kastamonua uključena je u danišmendidske granice.", "df047345"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1129-01-01:1":{"b": ["Danišmendidi su preuzeli kontrolu nad Çankırıjem, Kastamonuom i crnomorskim obalama", "db4c771a"], "d": ["Danišmendidi, u doba emira Gazija najmoćnija država u Anadoliji, 1129. preuzeli su kontrolu nad Ankarom, Çankırıjem, Kastamonuom i crnomorskim obalama; veći dio zemalja od Malatye do Sakarye došao je pod danišmendidsku upravu.", "1d1edb93"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1130-01-01:0":{"b": ["Šedadid Fazl IV poginuo je u bitki koju je erzenski emir Kurti pokrenuo da povrati Dvin", "d8a7ad18"], "d": ["Fazl IV, koji je nakon opsade Anija povratio Ani i pripojio svojim zemljama Gandžu i Dvin, poginuo je 524/1130. u bitki koju je erzenski emir Kurti pokrenuo da povrati Dvin; naslijedio ga je brat, ali je njegov sin Mahmud došao u Ani i preuzeo upravu.", "7810bf30"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1131-01-01:0":{"b": ["Saltukid Zijaudin Gazi potukao je gruzijskog kralja Ivanea", "5ba067d6"], "d": ["Zijaudin Gazi, koji je učestvovao u pohodu protiv Gruzijaca kada su oni 1126. prošli İspir i Pasinler i stigli do Oltua, potukao je 1131. kralja Ivanea.", "d91b0282"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1132-01-01:0":{"b": ["Smrću Zijaudina Gazija na čelo saltukidskog bejluka došao je njegov sinovac Izzudin Saltuk II", "726791ef"], "d": ["Zijaudin Gazi, rođak Artukida Timurtaša, umro je 526/1132; na čelo bejluka došao je njegov sinovac Izzudin Saltuk II.", "a7412435"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1134-01-01:0":{"b": ["Umro je emir Gazi; njegov stariji sin melik Muhammed proglašen je vladarom u Malatyi", "1cf04ea6"], "d": ["Emir Gazi (Melik Gazi), najuticajniji vladar Anadolije, umro je 528/1134. Menšur, zlatna palica i darovi koje su poslali abasidski halifa Mustaršid Billah i sultan Sandžar predati su meliku Muhammedu i proglašen je vladarom u Malatyi. Njegova braća Ajnuddevle i Jagan pobunila su se.", "e39192f6"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1142-01-01:0":{"b": ["Sultan Mesud zauzeo je Sivas; Ankaru, Çankırı i Kastamonu oduzeo je Danišmendidima i dao sinu Šahinšahu", "cc439683"], "d": ["Kada su se smrću melika Muhammeda Danišmendidi podijelili na tri grane, anadolski seldžučki sultan Mesud I krenuo je na Sivas, zauzeo grad i svog mlađeg sina Šahinšaha postavio za namjesnika Ankare, Çankırıja i Kastamonua.", "6b775908"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1142-01-01:1":{"b": ["Sultan Mesud oduzeo je Danišmendidima Kastamonu i ostavio ga sinu Šahinšahu", "ae895779"], "d": ["Sultan Mesud, koji je zauzeo Sivas, zajedno s Ankarom i Çankırıjem dao je i Kastamonu u namjesništvo mlađem sinu Šahinšahu.", "f8cfb811"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1142-01-01:2":{"b": ["Sultan Mesud oduzeo je Danišmendidima Çankırı i ostavio ga sinu Šahinšahu", "8047e8a8"], "d": ["Mesud I, iskoristivši danišmendidske borbe za prijestolje, zauzeo je Ankaru, Çankırı i Kastamonu i upravu tih triju gradova ostavio sinu Šahinšahu.", "07d66793"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1143-06-17:0":{"b": ["Sultan Mesud započeo je tromjesečnu opsadu Malatye; kako nije bilo rezultata, digao ju je 14. septembra 1143", "4c2d2d2b"], "d": ["Sultan Mesud, koji je zauzeo Sivas dinastije podijeljene na tri dijela nakon smrti danišmendidskog melika Muhammeda (537/1142), 1. zul-hidždžea 537 / 17. juna 1143. opsjeo je Malatyu; budući da tri mjeseca nije bilo rezultata, 2. rebiul-evvela 538 / 14. septembra 1143. digao je opsadu i vratio se u Konyu.", "2dc53da5"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1143-12-06:0":{"b": ["Melik Muhammed umro je u Kayseriju; Danišmendidi su se podijelili na sivaške, malatijske i kajserijske ogranke", "1ee92ff3"], "d": ["Prema Mihailu Sirijskom, nakon smrti melika Muhammeda, koji je umro u Kayseriju 6. decembra 1143, njegov brat Jagibasan uspostavio je vlast u Sivasu, sin Zunnun u Kayseriju, a Ajnuddevle u Malatyi i Elbistanu; Danišmendidi su se podijelili na tri ogranka i ušli u pogubne međusobne borbe.", "b07a9299"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1144-08-01:0":{"b": ["Umro je hisnkejfski artukidski vladar Davud; naslijedio ga je sin Fahrudin Kara Arslan", "4782f166"], "d": ["Davud, koji je protiv mosulskog atabega Zengija sklopio savez s mardinskim Artukidom Timurtašem, umro je 1. augusta 1144; njegov sin Fahrudin Kara Arslan sporazumio se protiv Zengija s anadolskim seldžučkim sultanom Mesudom I.", "48a2c46f"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1153-03-29:0":{"b": ["Uslijed zavjere koju je skovao anijski emir Fahrudin Šedad, saltukidsku vojsku porazio je gruzijski kralj Demetrije; Izzudin Saltuk pao je u zarobljeništvo", "f936d922"], "d": ["Anijski emir Šedad, koji je zaprosio Saltukovu kćer i bio odbijen, javio je da želi Saltuku prodati grad i stupiti u njegovu službu; kada je Saltuk došao s vojskom, dojavio je to gruzijskom kralju. Saltukidsku vojsku teško je porazio kralj Demetrije, Saltuk je pao u zarobljeništvo i oslobodio se uz otkupninu od 100.000 dinara.", "0d47e21f"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1155-01-01:0":{"b": ["Nakon smrti sultana Mesuda, Jagibasanu, zetu iz roda Danišmendida, dati su Amasya, Ankara i Kapadokija", "295fac37"], "d": ["Kada je nakon Mesudove smrti na prijestolje stupio Kilidž Arslan II (1155), od dvojice Mesudovih zetova iz danišmendidske dinastije, Jagibasanu su dati Amasya, Ankara i Kapadokija, a Zunnunu gradovi Kayseri i Sivas; braća su, polažući pravo na prijestolje, podigla ustanak.", "b6540bd8"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1155-03-07:0":{"b": ["Fahrudin Šedad pao je u gruzijsko zarobljeništvo; u Aniju je, pobunom armenskih monahinja, na njegovo mjesto doveden brat Fazl V", "2e64eb02"], "d": ["Nakon što je gruzijski kralj Demetrije porazio saltukidsku vojsku, armenske monahinje, ogorčene postupkom Fahrudina Šedada, pobunile su se i umjesto Saltuka u Ani dovele njegovog brata Fazla V (550/1155); emirat Fazla V okončan je 1161. predajom Anija gruzijskom kralju.", "56cd50fc"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1161-01-01:0":{"b": ["Gruzijski kralj Georgije zauzeo je Ani", "8081e228"], "d": ["Gruzijski kralj Georgije, koji je 1154. nanio težak poraz saltukidskom vladaru Izzudinu Saltuku, 1161. zauzeo je grad Ani; šedadidski emirat prestao je kada su se vjerski službenici pobunili i predali grad gruzijskom kralju.", "357c7a97"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1161-08-01:0":{"b": ["Ahlatšah Sokmen, Izzudin Saltuk i Devletšah opsjeli su Ani; kada je Saltuk napustio logor, muslimani su poraženi", "d651d8fe"], "d": ["Nakon što je gruzijski kralj Georgije zauzeo Ani, ahlatski šah Sokmen II, Izzudin Saltuk II, beg Erzena i Bitlisa Fahruddevle Devletšah i drugi turski emiri udružili su se i opsjeli grad. Kada je stigao kralj Georgije, Saltuk je napustio logor ne obavijestivši druge begove; muslimani su poraženi, mnogi su ubijeni, a 9000 ljudi palo je u zarobljeništvo.", "2345b0e8"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1162-01-01:0":{"b": ["Gruzijci su zaposjeli Dvin", "e8f2a041"], "d": ["Gruzijci, koji su 1161. zauzeli Ani, iduće su godine zaposjeli Kars i Dvin; potom je zajednički pohod muslimanskih begova 1163. porazio Gruziju.", "b28be1b3"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1162-01-01:1":{"b": ["Gruzijci su zaposjeli Kars i Dvin", "a7388ca5"], "d": ["Gruzijci su godinu nakon zauzimanja Anija 1161. zaposjeli Kars i Dvin; pošto su pobili mnogo muslimana i spalili džamije i kuće, vratili su se u Tbilisi.", "2a892f7b"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1163-01-01:0":{"b": ["Udružena vojska muslimanskih begova porazila je gruzijskog kralja Georgija; Georgije je bio prisiljen vratiti Ani", "346b30b1"], "d": ["Velika vojska, okupljena na poticaj sultana Tugrula i atabega Šemsudina Ildeniza, 558/1163. nanijela je težak poraz gruzijskom kralju Georgiju i Georgije je morao vratiti Ani.", "a59e4ef4"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1163-07-01:0":{"b": ["Saveznička vojska turskih begova porazila je gruzijsku vojsku blizu tvrđave Lukri", "58d3a0d5"], "d": ["Više od 50.000 ratnika, u kojima su bili Ildeniz, Sokmen, Izzudin Saltuk, Ibn Aksunkur i Arslan-šah, provalilo je u Gruziju; u julu 1163. u okolici tvrđave Lukri Gruzijci su poraženi, kralj Georgije pobjegao je ostavivši prtljag i morao vratiti Ani.", "7ac70a0b"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1164-08-04:0":{"b": ["Sivaški melik Jagibasan umro je u Çankırıju; među Danišmendidima počela je nova borba", "59448eb7"], "d": ["Jagibasan, koji je otišao onamo kako bi od seldžučkog melika Çankırıja Šahinšaha dobio pomoć protiv Kilidž Arslana II, umro je 4. augusta 1164. u Çankırıju; sahranjen je u haremu medrese koju je sam sagradio u Niksaru. Tko ga je naslijedio, sporno je.", "0efd18be"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1165-01-01:0":{"b": ["Kilidž Arslan II oduzeo je Danišmendidima okolicu Darende i Gedüka (Şarkışla)", "917ee1e6"], "d": ["Iskoristivši borbe unutar dinastije nakon Jagibasanove smrti, Kilidž Arslan II 1165. pripojio je Elbistan, Darende i oblast Gedüka.", "7f39a47e"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1168-01-01:0":{"b": ["Umro je Izzudin Saltuk II; na prijestolje je stupio njegov sin Nasirudin Muhammed", "40c0ab87"], "d": ["Nakon Izzudina Saltuka, umrlog 563/1168, na saltukidsko prijestolje stupio je njegov sin Nasirudin Muhammed; Velika džamija u Erzurumu 1179. sagrađena je u njegovo ime.", "18b4b682"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1170-09-14:0":{"b": ["Kilidž Arslan II dao je obnoviti Aksaray i pod imenom Daruzzafer pretvorio ga u vojnu bazu", "e0f2e591"], "d": ["Kilidž Arslan II grad Aksaray, koji je 566 (1170–71) dao obnoviti i nazvao Daruzzafer, pretvorio je u vojnu bazu; dao je sagraditi džamije, zavije, medrese i karavansaraj i ondje naselio gazije i učenjake dovedene iz Azerbejdžana.", "0ddd80f6"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1172-01-01:0":{"b": ["Stanovnici Sivasa pobunili su se i ubili Ismaila; uz podršku Nuredina Zengija, Zunnun je u Sivasu stupio na danišmendidsko prijestolje", "ab96caf2"], "d": ["Zbog gladi u Sivasu narod se pobunio protiv Ismaila, koji nije dijelio zalihe iz žitnica; Ismail i njegova žena ubijeni su. Ugledni ljudi grada pozvali su Zunnuna, koji se sklonio kod Nuredina; Zunnun je uz Nuredinovu pomoć 567/1172. stupio u Sivasu na danišmendidsko prijestolje, ali je ubrzo pod pritiskom Kilidž Arslana II pobjegao u Niksar.", "374133e0"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1175-01-01:0":{"b": ["Kilidž Arslan II oduzeo je Danišmendidima Niksar i pripojio ga seldžučkoj vlasti", "e49e3971"], "d": ["Kilidž Arslan II u ljeto 1175. zauzeo je Sivas, Niksar, Komanu, Tokat i druge danišmendidske zemlje; jedno od danišmendidskih središta, Niksar, u čijem se haremu Jagibasanove medrese nalazi njegov grob, palo je u seldžučke ruke.", "aa58d509"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1175-01-01:1":{"b": ["Kilidž Arslan II oduzeo je Tokat iz nestale danišmendidske zemlje i pripojio ga seldžučkoj vlasti", "1894c403"], "d": ["Nakon smrti atabega Nuredina Mahmuda Zengija 569/1174, Kilidž Arslan II, zanemarivši uslove sporazuma, u ljeto 1175. zauzeo je Sivas, Niksar, Komanu, Tokat i druge danišmendidske zemlje; Zunnun i Šahinšah sklonili su se u Bizant, a sivaški ogranak Danišmendida nestao je.", "dbfcc454"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1180-05-28:0":{"b": ["Kilidž Arslan II oduzeo je Bizantu oblast Uluborlua, Kütahye i Dorileja (Eskišehira)", "807be33d"], "d": ["Budući da se car Manuel nije držao uslova sporazuma i nije dao srušiti tvrđavu Dorilej, Kilidž Arslan II 573/1177. dao je opustošiti dolinu Meandra; Uluborlu, Kütahya i Dorilej 576/1180. prešli su pod seldžučku vlast.", "60e80418"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1184-01-01:0":{"b": ["Gruzijski kralj David krenuo je na Erzurum; vratio se zbog otpora stanovništva", "07419985"], "d": ["Gruzijski kralj David krenuo je na Erzurum, porazio Nasirudina Muhammeda i natjerao ga da se povuče u grad; pred hrabrošću i odlučnošću turskog stanovništva opljačkao je okolicu i povukao se (580/1184–85).", "85711193"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1184-04-14:0":{"b": ["Kilidž Arslan II podijelio je zemlju među jedanaest sinova", "b1ee119d"], "d": ["U starosti je Kilidž Arslan II podijelio zemlju među sinovima; Tokat je pripao starijem sinu Ruknudinu Sulejman-šahu. Seldžučka zemlja podijeljena je na jedanaest dijelova.", "09e83cd3"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1185-01-01:0":{"b": ["Namjesnik Isak Duka Komnen pobunio se protiv cara Andronika i proglasio nezavisnost Kipra", "445f5db0"], "d": ["Dok je Kipar bio bizantska provincija, namjesnik Isak Duka Komnen pobunio se protiv cara Andronika Komnena i proglasio nezavisnost, pa je Kipar 1185. izašao iz bizantske vlasti.", "00f3ca97"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1185-07-10:0":{"b": ["Ahlatšah Sokmen II (Šah-i Ermen) umro je tokom opsade Mosula", "f492f6ba"], "d": ["Kada je Salahudin 1185. ponovo opsjeo Mosul, stigla je vijest o smrti njegovog saveznika Sokmena (9. rebiul-ahir 581 / 10. juli 1185). Salahudin se iz pohoda na Ahlat nije vratio praznih ruku, nego je zauzeo Majjafarikin, koji je ostao bez vladara.", "2692f19a"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1190-05-17:0":{"b": ["Križarska vojska pod zapovjedništvom Fridrika Barbarosse porazila je seldžučku vojsku i ušla u Konyu", "f1f901b6"], "d": ["Njemački car Barbarossa, koji je u martu 1190. prešao iz Galipolja u Anadoliju, kod Uluborlua je ušao u seldžučke zemlje i 17. maja 1190. porazio vojsku Kutbudina Melikšaha i drugih seldžučkih melika te ušao u prijestolnicu Konyu, koju je sultan ispraznio.", "0d30744a"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1192-08-26:0":{"b": ["Kilidž Arslan II umro je tokom opsade Aksaraya; naslijedio ga je Kejhusrev I", "083f9fae"], "d": ["Kilidž Arslan II, koji je tokom borbe sa sinovima zajedno s Gijasudinom Kejhusrevom opsjeo Aksaray, razbolio se i 15. šabana 588 / 26. augusta 1192. umro; Kejhusrev je u Konyi stupio na prijestolje.", "1f04ea47"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1193-05-18:0":{"b": ["Ahlatšaha Begtemura ubio je njegov zet Hezar Dinari", "12078a3c"], "d": ["Oko dva i po mjeseca nakon Salahudinove smrti, Sejfudina Begtemura ubio je 18. maja 1193. jedan od njegovih zapovjednika, zet Bedrudin Aksunkur Hezar Dinari. Hezar Dinari zatočio je Begtemurovog sedmogodišnjeg sina i suprugu u tvrđavi u oblasti Erzasa.", "e0117ffd"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1196-11-24:0":{"b": ["Gijasudin Kejhusrev prepustio je prijestolje bratu Ruknudinu Sulejman-šahu i otišao u izgnanstvo", "557c281e"], "d": ["Kejhusrev I, koji se borio s braćom, morao je prepustiti prijestolje Sulejman-šahu II (Ruknudinu) (593/1196) i napustio je Konyu; Sulejman-šah je, preuzevši zemlje braće, uspostavio jedinstvo zemlje.", "129847ea"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1197-01-01:0":{"b": ["Amaury de Lusignan uzeo je titulu kralja Kipra; iste godine križari u Akki priznali su ga i za jeruzalemskog kralja", "c38ed247"], "d": ["Amaury je 1197. uzeo kraljevsku titulu, a iste godine križari u Akki priznali su ga za jeruzalemskog kralja; Kraljevina Kipar postala je pomorska baza križarskog Istoka.", "1d28312c"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1199-01-06:0":{"b": ["Levon je u katedrali u Tarsu primio krunu koju je poslao car Svetog Rimskog Carstva Henrik VI i postao prvi kralj Armenskog Kraljevstva Kilikije", "99ceea3a"], "d": ["Rubenidski princ Levon u katedrali u Tarsu stavio je krunu koju je poslao car Svetog Rimskog Carstva Henrik VI, a posvetio ga je papin predstavnik; rubenidska kneževina pretvorila se u Armensko Kraljevstvo Kilikije.", "05fe804d"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1201-06-23:0":{"b": ["Sulejman-šah II oduzeo je Malatyu od brata Muizzudina Kajser-šaha", "fff1df20"], "d": ["Sulejman-šah, koji je krenuo protiv brata, malatijskog melika Muizzudina Kajser-šaha, koji se opirao da mu bude vazal, 19. ramazana 597 / 23. juna 1201. zauzeo je grad.", "65e22bbb"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1202-01-01:0":{"b": ["Pohod Sulejman-šaha II na Gruziju: Seldžuci, koje su Gruzijci iznenada napali u logoru, pretrpjeli su teške gubitke; zarobljen je mengudžučki beg Erzindžana Behram-šah", "3ee9e922"], "d": ["Sulejman-šah II, koji je 1202. krenuo na Gruzijce koji su napadali turske zemlje, dok se odmarao u logoru doživio je gruzijski prepad i pretrpio teške gubitke; među zarobljenicima bio je i mengudžučki beg Erzindžana Behram-šah.", "4151b3d2"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1202-06-25:0":{"b": ["Sulejman-šah II dokrajčio je saltukidsku dinastiju i dao Erzurum kao iktu bratu Tugrul-šahu", "37a63791"], "d": ["Anadolski seldžučki sultan Sulejman-šah II, koji je tokom pohoda na Gruziju došao u Erzurum, zatočio je Melikšaha, ukinuo saltukidski bejluk (2. ševval 598 / 25. juni 1202) i dao Erzurum bratu Mugisudinu Tugrul-šahu, meliku Elbistana. Saltukidske zemlje ostale su u rukama Tugrul-šaha do 1225.", "6d717627"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1204-01-01:0":{"b": ["Umro je Sulejman-šah II; na prijestolje je stupio njegov maloljetni sin Kilidž Arslan III", "838d74dd"], "d": ["Sulejman-šah II nije postigao rezultat u pohodu na Gruziju 1202, a 1204. je umro na putu dok je išao u drugi pohod na Gruziju (600/1204). Naslijedio ga je maloljetni sin Kilidž Arslan III; tokom njegove sedmo- do osmomjesečne vladavine osvojena je oblast Isparte.", "6d8da37d"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1204-08-29:0":{"b": ["Gruzijci su izvršili upad u Azerbejdžan i ušli u zemlju Ahlatšaha, opljačkali okolicu Manzikerta i Erdžiša", "beb13519"], "d": ["Gruzijci su 601/1204–05. nakon uspješnog upada u Azerbejdžan ušli u zemlju Ahlatšaha i napredovali do Manzikerta, potom prema Erdžišu, sve paleći i rušeći; vojska im nije izašla u susret.", "5c1e0212"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1205-03-01:0":{"b": ["Gijasudin Kejhusrev I otišao je u Konyu i po drugi put zasjeo na anadolsko seldžučko prijestolje", "f6332e53"], "d": ["Kejhusrev, koji je zbog križarskog zauzimanja Carigrada (april 1204) morao otići u tvrđavu svog tasta u trapezuntskoj oblasti, za vrijeme maloljetnosti Kilidž Arslana III došao je u grad i po drugi put zasjeo na prijestolje (redžeb 601 / mart 1205).", "831b9889"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1207-01-01:0":{"b": ["Kejhusrev I zauzeo je oblast Denizlija", "47cabadd"], "d": ["U vrijeme drugog sultanata Gijasudina Kejhusreva I (1205–1211) zauzete su oblasti Denizlija i Antalije (603/1207); Antalija je zauzeta 5. marta 1207.", "190b906c"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1211-06-01:0":{"b": ["U bitki s bizantskom vojskom kod Alaşehira poginuo je Kejhusrev I; i bizantska vojska pretrpjela je teške gubitke", "fdac0ce7"], "d": ["Kejhusrev je poginuo u bitki s bizantskom vojskom kod Alaşehira; i bizantska vojska pretrpjela je vrlo teške gubitke. Njegovo tijelo najprije je sahranjeno u Alaşehiru, a potom preneseno u Konyu i položeno u Sultansko turbe uz Alaudinovu džamiju (kraj juna 1211).", "fd58f9bc"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1211-06-15:0":{"b": ["Državni velikodostojnici sastali su se u Konyi i odlučili na seldžučko prijestolje dovesti malatijskog melika Izzudina Kejkavusa; Kejkavus I proglašen je sultanom u Kayseriju", "f80be390"], "d": ["Nakon smrti Kejhusreva I (608/1211), državni velikodostojnici odlučili su na prijestolje dovesti malatijskog melika Izzudina Kejkavusa, kao najstarijeg sina, i poslali glasnika da dođe u Kayseri; njegov brat Alaudin Kejkubad nije priznao njegov sultanat.", "09e0f400"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1212-01-01:0":{"b": ["Kejkubad nije priznao sultanat starijeg brata Kejkavusa I i pobunio se; zatvorio se u tvrđavu Ankare i predao", "13cc17e2"], "d": ["Alaudin Kejkubad, koji se pobunio protiv Izzudina Kejkavusa, nakon očeve smrti proglašenog sultanom u Kayseriju, zajedno s armenskim kraljem Leonom i erzurumskim melikom, amidžom Tugrul-šahom, opsjeo je Kayseri; kako nije postigao rezultat, povukao se u tvrđavu Ankare i, kada su zalihe ponestale, predao se pod uslovom da se ni njemu ni narodu ne nanese zlo (608/1212).", "7b48bb7a"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1220-01-01:0":{"b": ["Izzudin Kejkavus I umro je u Viranšehiru kod Malatye, dok se pripremao za pohod na Alep", "61f16209"], "d": ["Izzudin Kejkavus, koji je krenuo na Alep, gdje je nakon smrti alepskog Ejjubida el-Melikuz-Zahira (1216) na prijestolje stupio njegov maloljetni sin, sklopio je savez s Artukidom Amida Nasirudinom Mahmudom i erbilskim vladarom Kokborijem, a kada je stigao u Malatyu, razbolio se i umro u Viranšehiru kod Malatye (ševval 616 / januar 1220).", "a8264a2f"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1220-01-01:1":{"b": ["Alaudin Kejkubad pušten je iz zatvora i proglašen vladarom u Sivasu", "2e697d48"], "d": ["Nakon smrti Izzudina Kejkavusa I, Kejkubad je pušten iz zatvora i proglašen sultanom u Sivasu (616/1220). Zbog mongolske invazije dao je Konyu, Sivas i Kayseri opasati zidinama.", "c731bdd7"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1220-01-01:2":{"b": ["Mongoli su prvi put potukli Gruzijce", "b869830b"], "d": ["Mongoli su prvi put potukli Gruzijce 1220, a 1231. ušli su u Gruziju.", "7f39fa9d"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1225-01-13:0":{"b": ["Armenski kralj Hetum zatražio je mir od Kejkubada; mir je sklopljen uz godišnji danak od 40.000 zlatnika i vojnu pomoć", "0d137195"], "d": ["Na žalbe trgovaca na Franke i Armence, Kejkubad je 622 (1225) zaratio s Armencima i križarima; armenski kralj Hetum poslao je poslanika i zatražio mir. Kralj je trebao svake godine sultanu plaćati 40.000 zlatnika i, kada sultan zatraži, poslati 1000 konjanika i 500 samostreličara.", "9d0f1a8e"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1228-01-01:0":{"b": ["Alaudin Kejkubad zauzeo je Erzindžan i ukinuo erzindžanski ogranak Mengudžukida", "edfdc566"], "d": ["Kejkubad, koji je krenuo protiv Mengudžukida koji su tražili nezavisnost, 625/1228. pripojio je Erzindžan anadolskim seldžučkim zemljama; meliku Muzaferudinu iz dinastije, gospodaru Şarkîkarahisara, dat je Kırşehir kao ikta, a Efsus s nekim mjestima kao mulk.", "ba31e942"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1228-01-01:1":{"b": ["Okončana je vladavina melika Muzaferudina, vladara şarkîkarahisarskog ogranka Mengudžukida; Kırşehir mu je dat kao ikta", "1ec2fd55"], "d": ["Alaudin Kejkubad 1228. ukinuo je erzindžanski ogranak Mengudžukida; meliku Muzaferudinu iz dinastije, gospodaru Şarkîkarahisara, dat je Kırşehir kao ikta, a mjestašce Efsus s nekim mjestima kao mulk.", "e17ab2ba"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1232-01-01:0":{"b": ["Seldžučke vojske zauzele su neke tvrđave u Gruziji; kraljica Rusudan ponudila je mir i pristala udati kćer Tamaru za Kejhusreva II", "2a057d64"], "d": ["U doba Alaudina Kejkubada I, 1232. su Kemaludin Kamjar i Mubarizudin Čavli poduzeli pohod na Gruziju i zauzeli neke tvrđave; kraljica Rusudan, nemoćna da se odupre seldžučkoj vojsci, ponudila je mir i pristala udati kćer Tamaru za Kejkubadovog sina Gijasudina Kejhusreva II.", "c8ce3253"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1234-01-01:0":{"b": ["Harputski ogranak prešao je u ruke anadolskih Seldžuka", "f2572ad0"], "d": ["Alaudin Kejkubad, radi odbrane od ejjubidskog prodora u Anadoliju, 631/1234. zauzeo je Harput; prestala je vlast harputskog ogranka Artukida (nakon Köse-Daga grad je prešao u ruke Ilhanida).", "b0bea54d"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1236-01-01:0":{"b": ["Mongoli su ponovo zaposjeli Gruziju i gruzijske velikaše poslali u Mongoliju", "245ae81a"], "d": ["Kada su Mongoli 633/1235–36. ponovo zaposjeli Gruziju, gruzijske velikaše poslali su u Mongoliju; oni su ondje ostali godinama. Mongoli su u pohodima koristili mnogo gruzijskih vojnika.", "159ea654"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1237-05-31:0":{"b": ["Alaudin Kejkubad I umro je otrovan mesom divljači; naslijedio ga je sin Gijasudin Kejhusrev II", "5d74714c"], "d": ["Kejkubad, kojim se zaključuje razdoblje uspona Seldžuka, otrovao se mesom divljači koje je jeo na gozbi priređenoj poslanicima za ramazanski bajram i sutradan umro (4. ševval 634 / 31. maj 1237); umjesto prijestolonasljednika Izzudina Kilidž Arslana, nastojanjem državnika na prijestolje je stupio Kejhusrev II.", "7b42c0c6"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1239-01-01:0":{"b": ["Mongolska vojska pod zapovjedništvom Čormagan-nojona tokom pohoda na Gruziju zauzela je i razorila Kars", "f510f715"], "d": ["Godine 636/1239. mongolska vojska pod zapovjedništvom Čormagan-nojona tokom pohoda na Gruziju zauzela je i razorila Kars; grad je do 1336. ostao pod ilhanidskom upravom.", "38d144da"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1242-01-01:0":{"b": ["Mongolski zapovjednik Bajdžu-nojon zauzeo je Erzurum i posjekao njegovo stanovništvo", "118b9e3a"], "d": ["Mongolski zapovjednik u Azerbejdžanu Bajdžu-nojon, iskoristivši slabost Seldžuka uslijed ustanka Babaija, potkraj 1242. zauzeo je Erzurum, posjekao njegovo stanovništvo i vratio se na Mugan da u proljeće ponovo napadne Anadoliju.", "dcfa189c"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1243-01-01:0":{"b": ["Mongoli, koji su nakon Köse-Daga zaposjeli Anadoliju, zauzeli su Amasyu i upravljali njome preko mongolskih namjesnika", "3b39a0ad"], "d": ["Mongoli, koji su nakon bitke kod Köse-Daga 1243. zaposjeli Anadoliju, zauzeli su Amasyu i gradom su počeli upravljati mongolski namjesnici.", "a9d1a1e2"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1243-01-01:1":{"b": ["Nakon poraza kod Köse-Daga, Kayseri je nakon desetodnevnog otpora pao u ruke Mongola", "5600cbe9"], "d": ["Nakon bitke kod Köse-Daga (1243), Kayseri je nakon desetodnevnog otpora pao u ruke Mongola i pretrpio veliko razaranje.", "924187ac"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1243-01-01:2":{"b": ["Kraljica Rusudan pristala je plaćati Mongolima danak i službeno priznala velikog hana za sizerena", "99d19c31"], "d": ["Kraljica Rusudan, shvativši da se ne može nositi s Mongolima, pristala je da im se potčini plaćajući danak i 1243. službeno priznala velikog hana za sizerena. Nakon Rusudanine smrti Mongoli su Kavkaz podijelili na osam pokrajina.", "c61c6116"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1243-01-01:3":{"b": ["Ilhanidi su nakon Köse-Daga Tokatski emirat dali Muinudinu Sulejmanu Pervaneu", "f2938da6"], "d": ["Ilhanidi, koji su nakon bitke kod Köse-Daga zavladali anadolskom seldžučkom državom, Tokatski emirat dali su Muinudinu Sulejmanu Pervaneu; 1276. Tokat je bio pod upravom Nuredina Džibrila.", "d931de12"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1244-01-01:0":{"b": ["Mongolski zapovjednik Jasavur-nojon nakratko je zauzeo Malatyu", "98759910"], "d": ["Mongoli nakon pobjede kod Köse-Daga (1243) nisu postigli rezultat u prvim pokušajima protiv Malatye; Jasavur-nojon 1244. nakratko je zauzeo grad, a 1258. razorio ga je Bajdžu-nojon.", "78c903ae"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1246-01-01:0":{"b": ["Državnici su uluborlutskog melika Izzudina Kejkavusa proglasili sultanom u selu Altuntaš kod Akşehira", "20d6f3e7"], "d": ["Izzudina Kejkavusa, koji je u vrijeme smrti Gijasudina Kejhusreva II bio melik Uluborlua (Borgulua), državnici su proglasili sultanom u selu Altuntaš kod Akşehira (643/1246).", "e7c6a924"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1247-01-01:0":{"b": ["Kralj Hetum I poslao je brata Sempada u Karakorum i s bratom Möngke-kana sklopio savez protiv Memluka", "7413b5e5"], "d": ["Kralj Hetum I, poslavši brata Sempada u Karakorum, započeo je službeni savez s Mongolskim Carstvom.", "769d4bcf"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1251-01-01:0":{"b": ["Nakon stupanja Möngke-kana na prijestolje, dvojica Davida koji su se vratili iz Mongolije zajedno su vladala Gruzijom", "f1640157"], "d": ["Nakon stupanja velikog mongolskog hana Möngkea na prijestolje (1251), dvojica Gruzijaca po imenu David koje je on postavio vratila su se iz Karakoruma u svoju zemlju i zajedno vladala; potom su Batu-kan i Hulagu nastojali uspostaviti vlast u Gruziji.", "96249933"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1255-01-01:0":{"b": ["Kilidž Arslan IV poražen je od Kejkavusa II u bitki kod Ahmedhisara blizu Kayserija", "edac92e9"], "d": ["Nakon smrti Dželaludina Karataja, Kilidž Arslan se u Kayseriju proglasio samostalnim sultanom (652/1254); iduće je godine u bitki kod mjesta Ahmedhisar blizu Kayserija poražen od Kejkavusa.", "d64649d2"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1257-01-01:0":{"b": ["Mongoli pod zapovjedništvom Jašmuta nakon duge opsade zauzeli su Majjafarikin; Mardin se opirao osam mjeseci", "c2328a27"], "d": ["Hulagu je 1257, idući na pohod u Siriju, jedan odred pod zapovjedništvom Jašmuta zadužio da zauzme Mardin i Majjafarikin; Majjafarikin je pao nakon duge opsade, a utvrđeni Mardin izdržao je više od osam mjeseci.", "18f326a7"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1257-03-05:0":{"b": ["Kilidž Arslan IV, doveden iz Burgulua u Konyu, sam je posađen na seldžučko prijestolje", "cb3eced9"], "d": ["Kilidž Arslan IV, koji se nakon poraza kod Sultanhanija (654/1256) nalazio u Burguluu (Uluborluu), doveden je u Konyu i 16. safera 655 / 5. marta 1257. sam posađen na seldžučko prijestolje; kada je Kejkavus II 14. rebiul-ahira 655 / 1. maja 1257. došao u Konyu, poslao je zapovjednika Alija Bahadira na Kilidž Arslana.", "32f17269"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1258-01-08:0":{"b": ["Kejkavus II preuzeo je vlast nad Malatyom, Sivasom, Tokatom i Amasyom; Kilidž Arslan povukao se u Erzindžan", "d4834ad1"], "d": ["Kada je Izzudin Kejkavus uz pomoć slavnih zapovjednika zavladao Malatyom, Sivasom, Tokatom i Amasyom, Kilidž Arslan IV morao se povući u Erzindžan (656/1258); potom je jarlikom Möngke-kana zemlja podijeljena na dva dijela (657/1259).", "5954d32b"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1259-01-01:0":{"b": ["Jarlikom Möngke-kana seldžučka zemlja podijeljena je na dva dijela između Kejkavusa II i Kilidž Arslana IV", "4dacbe83"], "d": ["Nakon Bajdžuovog odlaska iz Anadolije, Kejkavus II ponovo je posađen na prijestolje u Konyi (1. maj 1257); jarlikom Möngke-kana zemlja je podijeljena između Kejkavusa i Kilidž Arslana. Kejkavus, koji nije priznavao mongolsku vlast, 660/1262. sklonio se u Bizant.", "c7df29bf"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1260-01-01:0":{"b": ["Artukidski vladar Mardina Kara Arslan priznao je ilhanidsku vlast", "c6b7b1a6"], "d": ["Mardin je tokom mongolske opsade koja je trajala više od 8 mjeseci pretrpio glad i kugu; Kara Arslan, koji je došao na čelo nakon smrti Nedžmudina Gazija, u zamjenu za vraćanje Dare, Habura, Nusajbina i Resulajna Artukidima priznao je mongolsku vlast, a 659/1261. Hulagu ga je potvrdio kao gospodara Mardina.", "ff8d14de"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1260-01-01:1":{"b": ["Kada su se Mongoli poraženi od Memluka povukli u Iran, Memluci su napali Kilikiju i opustošili zemlju", "505db4aa"], "d": ["Kada su se ilhanidski Mongoli poraženi od Memluka povukli u Perziju, Memluci su napali Kilikiju i opustošili zemlju; to je stvarni početak memlučkih napada.", "89ccf21b"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1266-01-01:0":{"b": ["Muinudin Pervane preko Mongola dao je ubiti Kilidž Arslana IV i na prijestolje doveo njegovog maloljetnog sina Kejhusreva III", "27f0dc7a"], "d": ["Kada je Kilidž Arslan prisiljavan da pristane da mu Sinop bude dat kao mulk, vezir Muinudin Pervane dao ga je preko Mongola ubiti (664/1266) i na njegovo mjesto doveo maloljetnog sina Kejhusreva III; Pervane je postao neprikosnoveni gospodar države.", "4aa91de1"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1266-01-01:1":{"b": ["Bajbars je sišao u Kilikiju i zarobio Leona, sina sisskog kralja Hetuma", "2cefee6a"], "d": ["Memlučki sultan Bajbars 1266. sišao je u Kilikiju i zarobio Leona, sina sisskog kralja Hetuma; prema kasnijem sporazumu, armenski je kralj trebao vratiti zauzete gradove i tvrđave, a Leon je trebao biti pušten (1268. u armenskim rukama ostao je samo Besni).", "e5f53d00"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1266-01-01:2":{"b": ["Han Zlatne Horde Berke stigao je sve do Tbilisija", "23866ba3"], "d": ["Berke-kan 1266. stigao je sve do Tbilisija; unatoč tome, razina blagostanja Gruzije pod ilhanidskom vlašću bila je prilično visoka.", "013e2621"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1268-01-01:0":{"b": ["Atabezi koji su upravljali oblastima Ahiske, Ardahana i Artvina (atabegat Samche/Meshetije) preuzeli su upravu oblasti", "71bb5a86"], "d": ["Atabezi, upravitelji oblasti Ahiske, Ardahana i Artvina od 1268. do 1578, držali su upravu oblasti i u tom su razdoblju bili podložni državama Ilhanata, Kara-Kojunlu i Ak-Kojunlu.", "44bea8bb"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1269-01-01:0":{"b": ["Hetum I odrekao se prijestolja u korist sina Leona II; kraljevstvo je faktički postalo memlučki vazal", "3d94aadc"], "d": ["Hetum I odrekao se prijestolja i ustupio ga sinu Leonu II; Leon II bio je prisiljen plaćati velik godišnji danak i kraljevstvo je faktički postalo memlučki vazal.", "cd7ade63"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1271-01-01:0":{"b": ["Memlučki sultan Bajbars poslao je na Kipar flotu od sedamnaest brodova; zbog oluje napad nije uspio", "cfeb4521"], "d": ["Bajbars je 1271, dok je zauzimao posljednje tvrđave i gradove križara u Palestini i Siriji, poslao na Kipar flotu od sedamnaest brodova, ali je napad zbog nastale oluje ostao neuspješan.", "c0ba5344"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1275-01-01:0":{"b": ["Bejluk Sahib Ataogullari osnovan je u Afyonkarahisaru i okolici", "c909e2f5"], "d": ["Sinovi i unuci anadolskog seldžučkog vezira Sahib Ate osnovali su bejluk u Afyonkarahisaru i okolici (1275–1341).", "26972b2f"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1277-06-04:0":{"b": ["Ilhanidi su otkrili izdaju Muinudina Sulejmana Pervanea i pogubili ga", "9a7cc34e"], "d": ["Abaka-kan, koji je nakon Bajbarsovog odlaska iz Anadolije došao s velikom vojskom, dao je pobiti 200.000 ljudi zbog saradnje s Memlucima; otkrivši i Pervanetovu izdaju, pogubili su ga i anadolskom seldžučkom državom počeli upravljati preko činovnika poslanih iz Tabriza (Pervanetova smrt 676/1277).", "c7bb6ee3"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1280-05-03:0":{"b": ["Mesud II, sin Kejkavusa II, došao je u Sinop i otišao u ilhanidsku prijestolnicu da iziđe pred Abaka-kana", "9b43e13f"], "d": ["Mesud II, sin i prijestolonasljednik Kejkavusa II, 679/1280. došao je u Sinop, potom otišao u ilhanidsku prijestolnicu i izišao pred Abaka-kana; Abaka-kan dao mu je upravu nad Erzurumom, Erzindžanom, Sivasom, Dijarbekirom i Harputom.", "0ddb3753"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1282-04-11:0":{"b": ["Argun-kan proglasio je Mesuda II sultanom i dao ubiti Kejhusreva III", "0afda15b"], "d": ["Nakon što je Ahmed Teguder seldžučke zemlje podijelio između Mesuda II i Kejhusreva III, Argun-kan, koji je izašao kao pobjednik iz borbe za ilhanidsko prijestolje, proglasio je sultanom Mesuda II, koji se nalazio u Tabrizu (681/1282), i dao ubiti Kejhusreva III, koji je čekao u Erzurumu.", "ffa63120"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1284-03-20:0":{"b": ["Mesud II vratio se u Anadoliju i stupio na prijestolje seldžučkog sultana najprije u Kayseriju, a potom u Konyi", "ca5c28f4"], "d": ["Mesud II, uz Argunovo odobrenje, vratio se u Anadoliju i 683/1284. stupio na prijestolje u Kayseriju i Konyi; pod tiranijom mongolskih zapovjednika i namjesnika ostao je 'vladar-sjenka', boreći se s Karamanovićima, Ešrefogullarima i Germijanogullarima.", "c089c457"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1288-11-22:0":{"b": ["Seldžučki vezir Sahib Ata Fahrudin Ali umro je kod Akşehira", "9c7034f1"], "d": ["Sahib Ata, koji je služio Kejkavusu kao namjesnik sultanata (657/1259), 670/1271–72. bio zatočen u tvrđavi Osmandžik, a 674/1275–76. ponovo imenovan vezirom, potkraj 686 / početkom 1288. nakon pohoda sa savezničkom seldžučko-mongolskom vojskom protiv Karamanovića, u selu Nadir kod Akşehira umro je 25. ševvala 687 / 22. novembra 1288. i sahranjen u svom turbetu u Konyi.", "f8bf5f4a"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:0481-01-01:0":{"b": ["Klodvig je naslijedio oca Childerika kao kralj Salijskih Franaka; središte vlasti bio je Tournai", "e4d35fd1"], "d": ["Klodvig je 481, s petnaest godina, naslijedio oca Childerika I kao kralj Salijskih Franaka. U to vrijeme Salijski Franci prodrli su do rijeke Somme, a središte njihove moći bio je Tournai.", "d4c684f8"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:0486-01-01:0":{"b": ["Klodvig u bitki kod Soissonsa pobjeđuje Syagrija; ostatak rimske države južno od Somme prelazi Francima", "afa05aa7"], "d": ["Klodvig je 486. napao rimskog generala Syagrija; Syagrije, poražen u bitki kod Soissonsa, sklonio se kod vizigotskog kralja Alarika II i bio mu izručen. Klodvig je potom preselio rezidenciju u Soissons i dio po dio zauzeo Belgiku II (s prijestolnicom Reimsom).", "f20e6e70"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:0496-12-25:0":{"b": ["Klodviga u Reimsu krsti biskup Remigije (Božić)", "16299c9a"], "d": ["Nakon pobjede nad Alemanima Klodvig je otišao u Reims i na Božić 496. zajedno s tri hiljade Franaka krstio ga je sveti Remigije. Krštenje je katoličkom stanovništvu burgundskog i vizigotskog kraljevstva skrenulo pogled na Klodviga.", "2d58bf65"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:0507-01-01:0":{"b": ["Klodvig kod Vouilléa (blizu Poitiersa) ubija vizigotskog kralja Alarika II; vizigotske zemlje do Pireneja prelaze Francima", "e8ea0c78"], "d": ["Klodvig je nakon što je 506. dovršio pokoravanje Alemana, iduće godine krenuo na vizigotskog kralja Alarika II. Kod Vouilléa blizu Poitiersa vlastitom je rukom ubio Alarika; dio vizigotskog kraljevstva do Pireneja, osim Septimanije, pripojen je franačkoj državi.", "e632a672"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:0511-11-27:0":{"b": ["Klodvig umire; sahranjen je u Parizu, koji je u posljednjim godinama učinio prijestolnicom, a jedinstvo kraljevstva ostaje u merovinškom naslijeđu", "c6c9caa4"], "d": ["Klodvig je posljednje godine proveo u Parizu i učinio ga prijestolnicom kraljevstva; uklonivši male franačke kraljeve u središtima kao što su Cambrai i Köln, postao je jedini kralj svih franačkih plemena. Umro je 511.", "eeb42f8c"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:0756-01-01:0":{"b": ["Pipin III pohodima u Italiju oduzima Langobardima Ravenski egzarhat i daruje ga papi; rađa se Papinska država", "f6bbc975"], "d": ["Pipin III je na poziv pape Stjepana II 754. i 756. poduzeo dva pohoda u Italiju; darovavši papi Ravenski egzarhat, oduzet langobardskom kralju Aistulfu, postao je tvorac papine svjetovne države. Pipin je papi dao titulu 'patricija Rimljana'.", "0e4f19d8"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:0800-12-25:0":{"b": ["Karla Velikog u Rimu u crkvi sv. Petra papa Lav III proglašava i kruni za cara", "3d72f37d"], "d": ["Karlo Veliki otišao je 800. u Rim radi obnove; iduće godine na Božić, dok je ustajao od molitve u crkvi sv. Petra, papa Lav III okrunio ga je i proglasio carem i augustom.", "d6956767"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:0814-01-28:0":{"b": ["Karlo Veliki umire u Aachenu i istog dana sahranjen je u crkvi Gospe Marije", "915d6f61"], "d": ["Karlo Veliki većinu posljednjih godina proveo je u Aachenu (Aixu). Početkom 814. dobio je groznicu i od posljedica upale porebrice umro 28. januara 814. nakon što je primio pričest te je istog dana sahranjen u crkvi Gospe Marije u Aachenu; naslijedio ga je sin Ljudevit Pobožni.", "8ce37094"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:0842-02-14:0":{"b": ["Strazburške zakletve: Karlo Ćelavi i Ljudevit Njemački u Strazburgu polažu zakletvu o savezu", "b462f12a"], "d": ["Godinu dana nakon pobjede kod Fontenoya, Karlo Ćelavi i Ljudevit Njemački učvrstili su savez Strazburškim zakletvama; Karlo je prisegnuo na germanskom jeziku Ljudevitovog naroda, a Ljudevit na romanskom jeziku Karlovih podanika.", "02ceae89"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:0843-08-10:0":{"b": ["Verdunski ugovor: Karolinško Carstvo dijeli se na tri dijela (Zapadna, Srednja i Istočna Franačka)", "1b628d03"], "d": ["Sinovi Ljudevita Pobožnog ugovorom postignutim u Verdunu u augustu 843. podijelili su carstvo: Karlo Ćelavi dobio je zemlje zapadno od linije Meuse–Saône–Rhône (Zapadna Franačka, uključujući Špansku marku), Ljudevit Njemački zemlje istočno od Rajne (Bavarska, Tiringija, Franačka, Saska; također okolicu Speyera, Wormsa i Mainza), a Lotar Italiju, carsku titulu i pojas u dolinama Rajne i Rhône.", "5bda08ed"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:0858-02-13:0":{"b": ["Cináed mac Ailpín umro je u dvoru Forteviot (13. februar)", "d9eee9cb"], "d": ["Prema historijskom popisu kraljeva Albe (Škotske), Chronicle of the Kings of Alba, Cináed mac Ailpín umro je 13. februara u dvoru Forteviot; Annals of Ulster njegovu smrt stavljaju u 858. U atlasu je Forteviot od ovog prvog datiranog svjedočanstva upisan Kraljevini Škotskoj.", "9ad98182"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:0875-12-25:0":{"b": ["Karlo Ćelavi u Rimu prima carsku krunu", "49f42456"], "d": ["Nakon smrti Ljudevita II, Karlo Ćelavi, koji je uz podršku pape Ivana VIII sišao u Italiju, u Paviji je primio italsku kraljevsku, a u Rimu carsku krunu.", "d63d65ae"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:0893-01-28:0":{"b": ["Karlo Prostodušni kruni se za kralja u Reimsu; počinje suparničko kraljevstvo protiv Oda", "ccc4acd5"], "d": ["Karlo III 'Prostodušni' bio je 887. prilikom zbacivanja Karla Debelog isključen zbog mladosti; za vrijeme Odove vladavine, uz priznanje dijela velikaša, okrunjen je u Reimsu 28. januara 893, a savezom s carem natjerao je Oda da mu ustupi dio Neustrije. Odovom smrću 898. postao je gospodar cijelog kraljevstva.", "cd52d1cb"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:0911-01-01:0":{"b": ["Ugovor u Saint-Clair-sur-Epteu: Karlo Prostodušni ustupa Normanima današnju Normandiju", "fd0306b0"], "d": ["Karlo III 911. sklopio je u Saint-Clair-sur-Epteu ugovor s Normanima; dio Normana se pokrstio, a zemlja koja će se kasnije zvati Vojvodstvo Normandija prepuštena im je. Priča o ženidbi Rolla kraljevom sestrom potječe iz Dudonovog pripovijedanja i vrlo je sumnjiva.", "5798ced7"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:0923-06-15:0":{"b": ["Bitka kod Soissonsa: kralj Robert I gine, a za kralja je izabran burgundski vojvoda Raoul", "4430302d"], "d": ["Robert, koji je 922. izabran za kralja protiv Karla Prostodušnog, poginuo je u bitki kod Soissonsa; Robertovi pristaše, koji su pobijedili, za kralja su izabrali burgundskog vojvodu Raoula (Rudolfa). Karlo je, uzdajući se u grofa Vermandoisa Herberta, pao u zarobljeništvo i 929. umro u Péronneu.", "9c2c291f"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:0955-08-10:0":{"b": ["Bitka na Lechu: Otto I stavlja tačku na mađarske upade", "7bd31ba4"], "d": ["Otto je krenuo na Mađare koji su opsjedali Augsburg i velikom pobjedom na Lechu 10. augusta 955. oslobodio Njemačku mađarskih upada; iste godine porazio je i Slavene.", "fbb1b763"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:0962-02-02:0":{"b": ["Otto I prima carsku krunu u Rimu; početak Svetog Rimskog Carstva njemačkog naroda", "24571f97"], "d": ["Otto je na poziv pape Ivana XII za pomoć protiv Berengara prešao u Italiju; nakon dolaska u Paviju na Božić 961, u Rimu je 2. februara 962. primio carsku krunu i potvrdio papinska prava i povlastice. Rimljani su prisegli da će pri izboru pape tražiti carevo odobrenje. Tim datumom prestala je Istočna Franačka (Njemačko kraljevstvo), a umjesto nje nastala je Njemačka (Sveto Rimsko Carstvo): gradovi Istočne Franačke poput Frankfurta, Hamburga i Dorestada (Wijk bij Duurstede) prešli su Njemačkoj (Svetom Rimskom Carstvu).", "eae66234"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:1016-04-23:0":{"b": ["Æthelred II umire; velikaši okupljeni u Southamptonu biraju Cnuta za kralja", "35653e3c"], "d": ["Nakon smrti Æthelreda II 23. aprila 1016, vijeće velikaša u Southamptonu izabralo je Danca Cnuta za kralja; London je pak ostao vjeran Edmundu. U velikoj bitki kod Assanduna pobijedio je Cnut, a nakon Edmundove smrti u novembru 1016. početkom 1017. izabran je za kralja cijele Engleske.", "3a49dfc2"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:1032-01-01:0":{"b": ["Kralj Henrik I daje Burgundsko vojvodstvo bratu Robertu; počinje kapetinško Burgundsko vojvodstvo (prva vojvodska kuća)", "18dcd0ab"], "d": ["Francuski kralj Henrik I 1032. dodijelio je Burgundsko vojvodstvo bratu Robertu; od Roberta je potekla prva kapetinška vojvodska kuća, koja će trajati do 1361.", "cbb03a09"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:1032-01-01:1":{"b": ["Umire Rudolf III, posljednji kralj Burgundskog (Arelatskog) kraljevstva; njegova zemlja pripada Konradu II (njemačkom caru) — Basel ulazi u carske zemlje", "4dc8eb08"], "d": ["Rudolf III (993–1032), posljednji kralj Burgundskog (jurskoburgundskog/arelatskog) kraljevstva, umirući bez nasljednika ostavio je svoje zemlje caru Konradu II. To je naslijeđe izvor carskih prava nad dijelom današnje Švicarske od Jure do Aare, nad Franche-Comtéom, Lyonnaisom, Dauphinéom, Savojom i Provansom, koji se od 13. stoljeća naziva Arelatskim kraljevstvom. Od 888. vlast kraljevstva priznavala se u biskupijama Besançon, Basel, Lozana, Ženeva i Sion.", "54aa5fa8"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:1032-01-01:2":{"b": ["Umire Rudolf III, posljednji kralj Burgundskog (Arelatskog) kraljevstva; njegova zemlja pripada Konradu II (njemačkom caru) — Ženeva ulazi u carske zemlje", "be189789"], "d": ["Rudolf III (993–1032), posljednji kralj Burgundskog (jurskoburgundskog/arelatskog) kraljevstva, umirući bez nasljednika ostavio je svoje zemlje caru Konradu II. To je naslijeđe izvor carskih prava nad dijelom današnje Švicarske od Jure do Aare, nad Franche-Comtéom, Lyonnaisom, Dauphinéom, Savojom i Provansom, koji se od 13. stoljeća naziva Arelatskim kraljevstvom. Od 888. vlast kraljevstva priznavala se u biskupijama Besançon, Basel, Lozana, Ženeva i Sion.", "54aa5fa8"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:1032-01-01:3":{"b": ["Umire Rudolf III, posljednji kralj Burgundskog (Arelatskog) kraljevstva; njegova zemlja pripada Konradu II (njemačkom caru) — Lyon ulazi u carske zemlje", "78601ea1"], "d": ["Rudolf III (993–1032), posljednji kralj Burgundskog (jurskoburgundskog/arelatskog) kraljevstva, umirući bez nasljednika ostavio je svoje zemlje caru Konradu II. To je naslijeđe izvor carskih prava nad dijelom današnje Švicarske od Jure do Aare, nad Franche-Comtéom, Lyonnaisom, Dauphinéom, Savojom i Provansom, koji se od 13. stoljeća naziva Arelatskim kraljevstvom. Od 888. vlast kraljevstva priznavala se u biskupijama Besançon, Basel, Lozana, Ženeva i Sion.", "54aa5fa8"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:1066-01-05:0":{"b": ["Umire Edward Ispovjednik; Harold Godwinson biran je i okrunjen za kralja u Londonu", "3ff7af82"], "d": ["Edward Ispovjednik, koji nije mogao prisustvovati posveti Westminsterske opatije, umro je 5. januara 1066; umirući je za nasljednika predložio Harolda. Harold je odmah izabran i okrunjen; Northumbrija ga je isprva odbacila, ali mu se potom pokorila. Vilim je, pozivajući se na Edwardovu oporuku i Haroldovo obećanje iz oko 1064, zatražio prijestolje i počeo pripremati invaziju.", "c67100ae"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:1066-12-25:0":{"b": ["Normanski vojvoda Vilim kruni se u Westminsteru za kralja Engleske", "92ddd637"], "d": ["Vilim, koji se 28. septembra 1066. iskrcao u Pevenseyu, 14. oktobra u bitki kod Senlaca (Hastingsa) slomio je Harolda; na Božić je okrunjen u Westminsteru. Pokoravanje juga, zapada i sjevera Engleske trajalo je još pet godina.", "78756409"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:1068-01-01:0":{"b": ["Vilim Osvajač poduzima pohod na pobunjeni Exeter", "cc25aa87"], "d": ["Godina 1068. za Vilima je protekla u vojnim pohodima na Exeter i York, gdje su se sklonili Haroldovi pristaše.", "e1fb87c6"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:1069-01-01:0":{"b": ["Sjeverni ustanak: Danci i Englezi zauzimaju York; Vilim opsjeda i povrati grad te opustoši sjever", "c15ad892"], "d": ["Nakon ubistva Roberta de Cominesa u Durhamu, sjever je proglasio Edgara Æthelinga, a danski kralj Sweyn poslao je flotu; Danci i Englezi zauzeli su York, koji su branile dvije normanske tvrđave. Vilim je krenuo na York, potjerao Dance na brodove, blokadom zauzeo grad i opustošio zemlju sve do Durhama; početkom 1070. krenuo je na Chester i dovršio pokoravanje sjevera.", "a4420b47"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:1075-01-01:0":{"b": ["Papa Grgur VII zabranjuje laičku investituru (dodjelu crkvenih zvanja od strane svjetovnjaka) pri imenovanju klera", "bc8488be"], "d": ["Zabrana laičke investiture, objavljena dvije godine nakon Hildebrandovog izbora za papu pod imenom Grgur VII 1073, ugrozila je carevu moć pri crkvenim imenovanjima i bila je početak otvorenog sukoba s Henrikom IV.", "c78da49d"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:1080-03-07:0":{"b": ["Papa Grgur VII po drugi put ekskomunicira Henrika IV i zbacuje ga s prijestolja", "d73a0f3d"], "d": ["Nakon pobjede kod Flarchheima (27. januar 1080), pod pritiskom Sasa i uticajem netačnih vijesti, Grgur VII napustio je politiku čekanja; 7. marta 1080. ponovo je ekskomunicirao Henrika i proglasio ga zbačenim te razriješio podanike zakletve vjernosti. Učinak je bio mnogo slabiji nego 1076; sinod u Brixenu 25. juna 1080. svrgnuo je Grgura.", "518e832b"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:1111-04-13:0":{"b": ["Henrik V prima carsku krunu u Rimu; pitanje investiture privremeno se rješava kompromisom", "f7e1aee5"], "d": ["Henrik V je u februaru 1111. u Sutriju dobio obećanje carske krune u zamjenu za odricanje od investiture; od pape Paskala II iznuđeno je pravo investiture i obećanje krune, a krunidba je obavljena 13. aprila 1111. Nakon što je Henrik napustio Rim, jedan je sabor tu povlasticu proglasio nevažećom.", "5d77b395"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:1152-01-01:0":{"b": ["Henrik (II) ženidbom s Eleonorom stječe Poitou, Guyennu i Gaskonju", "4db69859"], "d": ["Henrik Plantagenet 1150. postao je vojvoda Normandije, a 1151, nakon očeve smrti, grof Anžua; 1152. ženidbom s Eleonorom, koja se razvela od francuskog kralja Louisa VII, stekao je Poitou, Guyennu i Gaskonju — to je južna polovina Anžuvinskog Carstva. Brak je navukao na njega neprijateljstvo Louisa VII, Henrikovog sizerena.", "39880a5d"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:1154-10-25:0":{"b": ["Kralj Stephen umire; Henrik II bez ikakvog otpora stupa na englesko prijestolje", "e1882039"], "d": ["Henrik je 1153. uz pomoć Crkve i pristaša svoje majke Matilde iznudio od Stephena priznanje prava na englesko naslijeđe; kada je Stephen umro 25. oktobra 1154, bez otpora je istakao svoje pravo. Anžuvinsko Carstvo ujedinilo je zemlje od Engleske do Pireneja.", "82a14d22"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:1155-06-18:0":{"b": ["Fridrik I Barbarossa prima carsku krunu u Rimu", "94350025"], "d": ["Fridrik je na prvom pohodu u Italiju, poduzetom 1154, 18. juna 1155. u Rimu primio carsku krunu; zbog nedovoljnih snaga i izbilog neprijateljstva u jesen se vratio u Njemačku.", "ae0ad79e"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:1157-01-01:0":{"b": ["Sabor u Besançonu: burgundsko plemstvo nudi vjernost Fridriku; zaoštrava se sukob pape i cara", "7252823d"], "d": ["Na saboru održanom u oktobru 1157. u Besançonu burgundski plemići prisegli su vjernost Fridriku; zbog hapšenja švedskog nadbiskupa na povratku iz Rima spor pape i cara se proširio.", "7b20ab27"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:1173-01-01:0":{"b": ["Tuluski grof Raymond V polaže vazalnu zakletvu (homagij) Henriku II", "460d9e41"], "d": ["Henrik II, koji je preuzeo Eleonorine zahtjeve na Toulouse, nakon duge borbe 1173. natjerao je tuluskog grofa Raymonda V da mu za Toulouse položi vazalnu zakletvu.", "1727d885"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:1176-05-29:0":{"b": ["Bitka kod Legnana: Lombardski savez pobjeđuje Fridrika I", "b7613445"], "d": ["Protiv Fridrika, koji je 1174. krenuo na peti pohod u Italiju, bio je osnovan Lombardski savez i podignuta tvrđava Alessandria. Budući da saski vojvoda Henrik Lav nije pomogao, Fridrik je 29. maja 1176. poražen kod Legnana; mislilo se da je ranjen i da je poginuo. Povukao se u Paviju i počeo mirovne pregovore s papom Aleksandrom III.", "4d37e6ac"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:1177-01-01:0":{"b": ["Mletački mir: Fridrik Barbarossa i papa Aleksandar III mire se; šestogodišnje primirje s Lombardskim savezom", "041665b3"], "d": ["Nakon Legnana, Fridrik je Mletačkim mirom u augustu 1177. priznao Aleksandra III za pravog papu i oslobodio se ekskomunikacije (u julu 1177. poljubio je papi noge); s Lombardskim savezom sklopljeno je šestogodišnje primirje. Pitanje Matildine ostavštine prepušteno je arbitraži.", "1b138556"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:1183-06-25:0":{"b": ["Mir u Konstanzu: Fridrik sklapa trajan mir s Lombardskim savezom", "91ea5aaf"], "d": ["U junu 1183. u Konstanzu je sklopljen ugovor s Lombardskim savezom (trajni mir koji je zamijenio šestogodišnje primirje iz 1177). U međuvremenu je saski vojvoda Henrik Lav lišen vojvodstva i prognan, a vojvodstvo rascjepkano; 1184. njegov sin Henrik zaručen je s Konstancom, kćerkom sicilijanskog kralja Rogera.", "97ab19ec"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:1201-01-01:0":{"b": ["Kapitulacija u Neussu: Otto IV priznaje papinsku vlast nad papinskim zemljama", "b43b4c91"], "d": ["Njemački car Otto IV kapitulacijom u Neussu 1201. priznao je papinsku vlast nad područjem od Radicofanija do prijelaza kod Ceperana (Ravenski egzarhat, Pentapolis, Anconska marka, biskupija Spoleto, Matildini posjedi, grofovija Brittenoro). Dio tih zemalja stoljećima je ostao samo papinska želja; stvarno pripajanje mjesta poput Ravene, Ancone, Bologne i Ferrare datira u 16. stoljeće.", "e76fd40c"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:1204-01-01:0":{"b": ["Filip August osvaja Normandiju: okončava se unija s Engleskom koja je trajala od 1106; Maine, Touraine, Anžu i Poitou 1204–1205. prelaze Francuskoj", "ad5f7cb2"], "d": ["Nakon što je Ivan bez Zemlje dao ubiti Artura, Filip August 1203–1204. zauzeo je Normandiju (opsada Château-Gaillarda septembar 1203 – april 1204, Rouen 24. juni 1204). Osvajanje Mainea, Tourainea, Anžua i Poitoua 1204. i 1205. bilo je lahko 'gotovo kao šetnja'; samo su tvrđave Loches i Chinon pružale otpor još godinu dana.", "e587727d"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:1204-01-01:1":{"b": ["Touraine (Tours) prelazi francuskoj kruni", "220394a0"], "d": ["Osvajanja Filipa Augusta u dolini Loire 1204–1205. vezala su Maine, Touraine, Anžu i Poitou za francuskog kralja; tvrđave Loches i Chinon pružale su otpor godinu dana.", "c3eaca78"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:1214-01-01:0":{"b": ["Fridrik II daje Rajnski Palatinat Ottu od Wittelsbacha (Palatinska grofovija u dinastiji Wittelsbach)", "5f54fd76"], "d": ["Nakon smrti rajnskog palatinskog grofa Henrika 1214, njemački kralj Fridrik II dao je Palatinat Ottu (zaručenom s Henrikovom sestrom Agnezom), mlađem sinu bavarskog vojvode Ludwiga I. Otkako se Konrad 1155. nastanio u tvrđavi Juttenbühel blizu Heidelberga, ta se okolica smatrala prijestolnicom Palatinata.", "066e8777"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:1218-01-01:0":{"b": ["Simon de Montfort gine opsjedajući Toulouse", "6da05355"], "d": ["Simon de Montfort, zapovjednik Albižanskog križarskog rata, 1215. ušao je u Toulouse, ali je 1218. poginuo opsjedajući grad. Zapovjedništvo križara prešlo je na njegovog sina Amauryja; Raymond VII, sin Raymonda VI, 1222. došao je na čelo grofovije.", "47aa27de"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:1229-01-01:0":{"b": ["Pariški (Meaux-Pariz) ugovor: Raymond VII ustupa francuskoj kruni veći dio svojih feuda", "ef1cb151"], "d": ["Pariškim ugovorom 1229. francuski kralj lišio je tulusku dinastiju većeg dijela feuda; grofovija je preko Raymondove kćeri Jeanne i njenog muža Alfonsa (brata Louisa IX) trebala 1271. prijeći francuskoj kruni.", "7186cd3b"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:1266-07-02:0":{"b": ["Norveški kralj ustupa Škotskoj ostrvo Man i Hebride za 4000 maraka", "e027acbe"], "d": ["Aleksandar III 1261. poslao je u Norvešku poslanike radi ustupanja ostrva, a kada nije uspio, zaratio je; 1263. kod Largsa uništena je norveška flota. Manski kralj Magnus morao je napustiti sva ostrva osim Mana. Norveški kralj 1266. ustupio je ostrva (uključujući Man) Škotskoj za 4000 maraka; škotska uprava na Manu učvrstila se tek 1275. porazom Manjana kod Ronaldswaya.", "fdf0afa6"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:1266-07-02:1":{"b": ["Norveški kralj ustupa Škotskoj Hebride za 4000 maraka: Iona (Hebridi)", "215cac00"], "d": ["Pobjedom Aleksandra III nad norveškom flotom kod Largsa (1263) uzdrmana je norveška vlast nad Hebridima; norveški kralj 1266. ustupio je ostrva Škotskoj za 4000 maraka.", "81cc8cf0"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:1268-10-29:0":{"b": ["Konradin je pogubljen u Napulju: gasi se muška loza Hohenstaufena", "55645d01"], "d": ["Konradin, posljednji predstavnik dinastije Hohenstaufen, nakon poraza kod Tagliacozza (23. august 1268) od anžuvinskog vojvode Karla suđen je u Napulju kao izdajnik i 29. oktobra pogubljen zajedno s prijateljem Fridrikom od Badena (naslovnim vojvodom Austrije). Muška loza Hohenstaufena ugasila se.", "d81af0d1"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:1271-01-01:0":{"b": ["Umiru Alphonse de Poitiers i supruga Jeanne: naslijeđe Tuluske grofovije prelazi francuskoj kruni", "eabc3640"], "d": ["Kada je Raymond VII umro 1249, grofovija je ostala kćeri Joan; Joan je bila udata za Alfonsa, brata Louisa IX. Njihovom smrću 1271. prostrano naslijeđe tuluskih grofova prešlo je francuskoj kruni.", "ee58c39e"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:1276-11-21:0":{"b": ["Bečki mir: češki kralj Otokar II odriče se Austrije, Štajerske, Koruške i Kranjske", "db5c2bc4"], "d": ["Rudolf Habsburški, nakon izbora za kralja (1273), stavio je Otokara pod carsko izopćenje i u junu 1276. zaratio s njim; Rudolf, koji je od Otokara odvojio donjobavarskog vojvodu Henrika, u novembru 1276. natjerao je češkog kralja da se odrekne četiri pokrajine. Otokaru su ponovo dodijeljene kao leno samo Češka i Moravska, njegov sin Vjenceslav zaručen je s Rudolfovom kćerkom; Rudolf je trijumfalno ušao u Beč.", "d79ed14c"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0569-09-04:0":{"b": ["Alboin je ušao u Milano: sjeverna Italija izašla je iz bizantskih ruku", "b6be0ed6"], "d": ["Alboin je 4. septembra 569. ušao u Milano; biskup Honorat pobjegao je u Đenovu. Pavija je pala nakon duge opsade, a dolina rijeke Po uvelike je prešla u ruke Langobarda; Bizant je zadržao samo neke obalne i utvrđene gradove.", "c0d39443"]},
"OLAYLAR_ORTACAG_BEKLEYEN_ACIK:0629-01-01:0":{"b": ["Hazari su zauzeli Tiflis", "d0847d32"], "d": ["Dok su bili podređeni Zapadnim Göktürcima, Hazari su prešli Derbentski prolaz i poduzimali upade u Gruziju i Azerbejdžan; 629. zauzet je Tiflis i pokorene su neke armenske skupine. Glavni grad bio je Balandžar.", "5027db3b"]}
});
